-- Run: mysql -u root -p --default-character-set=utf8mb4 docta_me < server/sql/migrations/insert-med-substance-reference-info.sql

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 4-dihlorbenzil alkohol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (1, 'A local antiseptic for the mouth and throat, used together with amylmetacresol', 'Lokalni antiseptik za usnu duplju i grlo; primjenjuje se zajedno sa amilmetakrezolom', 'Локални антисептик за усну дупљу и грло; примјењује се заједно са амилметакрезолом', 'Антисептик для местного применения в полости рта и горле; применяется вместе с амилметакрезолом', 'Ein örtliches Antiseptikum für Mund und Rachen, angewendet zusammen mit Amylmetacresol', 'Ağız ve boğazda etkili yerel bir antiseptiktir; amilmetakrezol ile birlikte kullanılır', 'Sore, scratchy or red throat in colds and pharyngitis, when a local remedy is enough', 'Bol, grebanje i crvenilo u grlu kod prehlade i faringitisa, kada je dovoljno lokalno sredstvo', 'Бол, гребање и црвенило у грлу код прехладе и фарингитиса, када је довољно локално средство', 'Боль, першение и покраснение в горле при простуде и фарингите, когда достаточно местного средства', 'Halsschmerzen, Kratzen und Rötung im Rachen bei Erkältung und Rachenentzündung, wenn ein örtliches Mittel ausreicht', 'Soğuk algınlığı ve farenjitte boğaz ağrısı, gıcık ve kızarıklık; yerel bir ürünün yeterli olduğu durumlar', 'It acts locally only and does not replace treatment of tonsillitis. See a doctor if the pain is severe, lasts more than a few days or comes with a high fever; age limits apply for children.', 'Djeluje samo lokalno i ne zamjenjuje liječenje angine. Ako je bol jak, traje duže od nekoliko dana ili je praćen visokom temperaturom, obratiti se ljekaru; za djecu važe starosna ograničenja.', 'Дјелује само локално и не замјењује лијечење ангине. Ако је бол јак, траје дуже од неколико дана или је праћен високом температуром, обратити се љекару; за дјецу важе старосна ограничења.', 'Действует только местно и не заменяет лечения ангины. Если боль сильная, держится дольше нескольких дней или сопровождается высокой температурой — к врачу; у детей есть ограничения по возрасту.', 'Wirkt nur örtlich und ersetzt keine Behandlung einer Mandelentzündung. Bei starken Schmerzen, Dauer über einige Tage oder hohem Fieber zum Arzt; für Kinder gelten Altersgrenzen.', 'Yalnızca yerel etki eder, bademcik iltihabının tedavisinin yerini tutmaz. Ağrı şiddetliyse, birkaç günden uzun sürüyorsa veya ateş yüksekse hekime başvurun; çocuklarda yaş sınırı vardır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- acetilcistein
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (6, 'A mucolytic that breaks down thick mucus, so it becomes thinner and easier to cough up.', 'Mukolitik koji razgrađuje gust sekret, pa se lakše iskašljava.', 'Муколитик који разграђује густ секрет, па се лакше искашљава.', 'Муколитик: разрушает связи в густой слизи, поэтому мокрота становится жиже и легче откашливается.', 'Ein Schleimlöser, der zähen Schleim aufbricht, sodass er leichter abgehustet wird.', 'Koyu balgamın yapısını çözerek atılmasını kolaylaştıran bir mukolitiktir.', 'Used for a cough with thick mucus in bronchitis and other airway conditions; nasal forms for a thick blocked nose.', 'Primjenjuje se kod kašlja sa gustim sekretom uz bronhitis i druge bolesti disajnih puteva, nazalni oblici kod guste sekrecije iz nosa.', 'Примјењује се код кашља са густим секретом уз бронхитис и друге болести дисајних путева, назални облици код густе секреције из носа.', 'Применяют при кашле с густой мокротой на фоне бронхита и других болезней дыхательных путей, назальные формы — при густом насморке.', 'Wird bei Husten mit zähem Schleim bei Bronchitis und anderen Atemwegserkrankungen eingesetzt, Nasenformen bei zähem Nasensekret.', 'Bronşit ve diğer solunum yolu hastalıklarında koyu balgamlı öksürükte, burun formları koyu burun akıntısında kullanılır.', 'Available over the counter. In asthma, peptic ulcer disease and in young children, only on a doctor''s advice.', 'Izdaje se bez recepta. Kod astme, čira na želucu i kod male djece samo po savjetu ljekara.', 'Издаје се без рецепта. Код астме, чира на желуцу и код мале дјеце само по савјету љекара.', 'Отпускается без рецепта. При бронхиальной астме, язвенной болезни и у детей раннего возраста — только по назначению врача.', 'Rezeptfrei erhältlich. Bei Asthma, Magengeschwür und bei kleinen Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Astım ve mide ülseri olanlarda ve küçük çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- acetilsalicilna kiselina
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (7, 'A non-steroidal anti-inflammatory salicylate. Cardio forms prevent blood clots, ordinary tablets relieve pain and fever.', 'Nesteroidni antiinflamatorni lijek iz grupe salicilata. Kardio oblici sprječavaju stvaranje ugrušaka, obične tablete smanjuju bol i temperaturu.', 'Нестероидни антиинфламаторни лијек из групе салицилата. Кардио облици спрјечавају стварање угрушака, обичне таблете смањују бол и температуру.', 'Нестероидное противовоспалительное средство из группы салицилатов. Кардиоформы препятствуют образованию тромбов, обычные снимают боль и жар.', 'Ein Salicylat mit entzündungshemmender Wirkung. Kardio-Formen hemmen die Blutgerinnung, normale Tabletten wirken gegen Schmerzen und Fieber.', 'Salisilat grubundan, steroid yapıda olmayan bir antiinflamatuardır. Kardiyo formları pıhtıyı önler, normal tabletleri ağrı ve ateşi azaltır.', 'Cardio forms are taken long term to prevent heart attack and stroke, ordinary tablets are used for headache and fever during colds.', 'Kardio oblici uzimaju se dugotrajno radi prevencije infarkta i moždanog udara, obične tablete kod glavobolje i temperature uz prehladu.', 'Кардио облици узимају се дуготрајно ради превенције инфаркта и можданог удара, обичне таблете код главобоље и температуре уз прехладу.', 'Кардиоформы применяют длительно для профилактики инфаркта и инсульта, обычные таблетки — при головной боли и температуре при простуде.', 'Kardio-Formen werden dauerhaft zur Vorbeugung von Herzinfarkt und Schlaganfall eingesetzt, normale Tabletten bei Kopfschmerzen und Fieber.', 'Kardiyo formları kalp krizi ve inmeden korunmak için uzun süre kullanılır, normal tabletleri baş ağrısı ve ateşte tercih edilir.', 'It irritates the stomach and raises bleeding risk. Not given to children and teenagers with viral infections because of Reye''s syndrome. Cardio use is a doctor''s decision.', 'Nadražuje želudac i povećava rizik od krvarenja. Djeci i adolescentima kod virusnih infekcija se ne daje zbog Rejevog sindroma. Kardio primjenu određuje ljekar.', 'Надражује желудац и повећава ризик од крварења. Дјеци и адолесцентима код вирусних инфекција се не даје због Рејевог синдрома. Кардио примјену одређује љекар.', 'Раздражает желудок и повышает риск кровотечений. Детям и подросткам при вирусных инфекциях не дают из-за риска синдрома Рея. Кардиоформы — по назначению врача.', 'Reizt den Magen und erhöht das Blutungsrisiko. Kindern und Jugendlichen mit Virusinfekten wird es wegen des Reye-Syndroms nicht gegeben. Kardio-Einnahme bestimmt der Arzt.', 'Mideyi tahriş eder ve kanama riskini artırır. Viral enfeksiyonu olan çocuk ve ergenlere Reye sendromu riski nedeniyle verilmez. Kardiyo kullanımına hekim karar verir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- aklidinijum bromid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (17, 'A bronchodilator from the long-acting anticholinergic group.', 'Bronhodilatator iz grupe dugodjelujućih antiholinergika.', 'Бронходилататор из групе дугодјелујућих антихолинергика.', 'Бронхорасширяющее вещество из группы длительно действующих антихолинергических средств.', 'Ein Bronchien erweiternder Wirkstoff aus der Gruppe der lang wirkenden Anticholinergika.', 'Uzun etkili antikolinerjik grubundan bir bronş genişleticidir.', 'Used for long-term control of chronic obstructive pulmonary disease, reducing breathlessness and the number of flare-ups.', 'Koristi se za dugotrajnu kontrolu hronične opstruktivne bolesti pluća, smanjuje nedostatak vazduha i broj pogoršanja.', 'Користи се за дуготрајну контролу хроничне опструктивне болести плућа, смањује недостатак ваздуха и број погоршања.', 'Применяют для длительного контроля хронической обструктивной болезни лёгких: уменьшает одышку и частоту обострений.', 'Dient der Langzeitkontrolle der chronisch obstruktiven Lungenerkrankung: weniger Atemnot und seltenere Verschlechterungen.', 'Kronik obstrüktif akciğer hastalığının uzun süreli kontrolünde kullanılır, nefes darlığını ve alevlenme sayısını azaltır.', 'Prescription only. Not for relieving sudden breathlessness. Dry mouth and throat irritation are possible. It is used with care in glaucoma and prostate problems.', 'Izdaje se samo na recept. Nije za prekid iznenadnog napada gušenja. Mogući su suva usta i nadražaj grla. Kod glaukoma i tegoba sa prostatom koristi se oprezno.', 'Издаје се само на рецепт. Није за прекид изненадног напада гушења. Могући су сува уста и надражај грла. Код глаукома и тегоба са простатом користи се опрезно.', 'Только по рецепту. Не подходит для снятия внезапной одышки. Возможны сухость во рту и раздражение горла. При глаукоме и болезнях простаты — с осторожностью.', 'Nur auf Rezept. Nicht zur Behandlung plötzlicher Atemnot geeignet. Mundtrockenheit und Halsreizung sind möglich. Bei Glaukom und Prostatabeschwerden vorsichtig.', 'Yalnızca reçeteyle verilir. Ani nefes darlığında uygun değildir. Ağız kuruluğu ve boğaz tahrişi olabilir. Glokom ve prostat sorunlarında dikkatle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- alprazolam
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (32, 'A short-acting benzodiazepine with a calming and anti-anxiety effect.', 'Benzodiazepin kratkog djelovanja sa smirujućim i anksiolitičkim efektom.', 'Бензодиазепин кратког дјеловања са смирујућим и анксиолитичким ефектом.', 'Бензодиазепин короткого действия с успокаивающим и противотревожным эффектом.', 'Ein kurz wirksames Benzodiazepin mit beruhigender und angstlösender Wirkung.', 'Sakinleştirici ve kaygı giderici etkisi olan kısa etkili bir benzodiazepindir.', 'Prescribed for anxiety disorders and panic states, usually as a short course under medical supervision.', 'Propisuje se kod anksioznih poremećaja i napada panike, obično kratko i uz nadzor ljekara.', 'Прописује се код анксиозних поремећаја и напада панике, обично кратко и уз надзор љекара.', 'Назначают при тревожных расстройствах и панических состояниях, обычно коротким курсом под наблюдением врача.', 'Wird bei Angststörungen und Panikzuständen verordnet, in der Regel kurzzeitig und unter ärztlicher Aufsicht.', 'Kaygı bozukluklarında ve panik ataklarda, genellikle kısa süreli ve doktor gözetiminde reçete edilir.', 'Prescription only and closely controlled. Causes drowsiness and reduces attention, does not mix with alcohol and is unsafe for driving. Dependence is possible, a doctor plans stopping.', 'Lijek se izdaje samo na poseban recept. Izaziva pospanost i smanjuje pažnju, ne ide uz alkohol i nije bezbjedan za vožnju. Moguća je zavisnost, prekid vodi ljekar.', 'Лијек се издаје само на посебан рецепт. Изазива поспаност и смањује пажњу, не иде уз алкохол и није безбједан за вожњу. Могућа је зависност, прекид води љекар.', 'Рецептурное вещество строгого учёта. Вызывает сонливость и снижает внимание, несовместимо с алкоголем и опасно при вождении. Возможна зависимость, отмену планирует врач.', 'Verschreibungspflichtig und besonders überwacht. Macht müde und mindert die Aufmerksamkeit, verträgt sich nicht mit Alkohol, Fahren ist unsicher. Abhängigkeit möglich, Absetzen plant der Arzt.', 'Sıkı denetime tabi, yalnızca reçeteyle verilen bir maddedir. Uyku hali ve dikkat azalması yapar, alkolle kullanılmaz, araç kullanmak güvenli değildir. Bağımlılık olabilir, bırakmayı doktor planlar.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- amilmetakrezol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (39, 'Amylmetacresol is a local antiseptic for the throat, usually used together with dichlorobenzyl alcohol', 'Amilmetakrezol je lokalni antiseptik za grlo; koristi se obično zajedno sa dihlorbenzil alkoholom', 'Амилметакрезол је локални антисептик за грло; користи се обично заједно са дихлорбензил алкохолом', 'Амилметакрезол — антисептик местного действия для горла; применяется обычно вместе с дихлорбензиловым спиртом', 'Amylmetacresol ist ein örtliches Antiseptikum für den Rachen und wird meist zusammen mit Dichlorbenzylalkohol eingesetzt', 'Amilmetakrezol boğazda yerel etkili bir antiseptiktir; genellikle diklorobenzil alkol ile birlikte kullanılır', 'Sore or scratchy throat and hoarseness in colds and pharyngitis, when a local remedy is enough', 'Bol i grebanje u grlu, promuklost kod prehlade i faringitisa, kada je dovoljno lokalno sredstvo', 'Бол и гребање у грлу, промуклост код прехладе и фарингитиса, када је довољно локално средство', 'Боль и першение в горле, охриплость при простуде и фарингите, когда достаточно местного средства', 'Halsschmerzen, Kratzen und Heiserkeit bei Erkältung und Rachenentzündung, wenn ein örtliches Mittel ausreicht', 'Soğuk algınlığı ve farenjitte boğaz ağrısı, gıcık ve ses kısıklığı; yerel bir ürünün yeterli olduğu durumlar', 'It works only on the throat lining and does not replace treatment of a bacterial infection. See a doctor with high fever, coating on the tonsils or persistent pain; age limits apply for children.', 'Djeluje samo na sluznici grla i ne zamjenjuje liječenje bakterijske infekcije. Kod visoke temperature, naslaga i dugotrajnog bola obratiti se ljekaru; za djecu važe starosna ograničenja.', 'Дјелује само на слузници грла и не замјењује лијечење бактеријске инфекције. Код високе температуре, наслага и дуготрајног бола обратити се љекару; за дјецу важе старосна ограничења.', 'Работает только на слизистой горла и не заменяет лечения бактериальной инфекции. При высокой температуре, налётах и затяжной боли — к врачу; у детей есть ограничения по возрасту.', 'Wirkt nur auf der Rachenschleimhaut und ersetzt keine Behandlung einer bakteriellen Infektion. Bei hohem Fieber, Belägen und anhaltenden Schmerzen zum Arzt; für Kinder gelten Altersgrenzen.', 'Yalnızca boğaz mukozasında etki eder, bakteriyel enfeksiyon tedavisinin yerini tutmaz. Yüksek ateş, bademciklerde plak ve uzayan ağrıda hekime başvurun; çocuklarda yaş sınırı vardır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- amlodipin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (45, 'A long-acting calcium channel blocker, often combined with other blood pressure medicines.', 'Blokator kalcijumskih kanala dugog djelovanja, često i u kombinacijama sa drugim lijekovima za pritisak.', 'Блокатор калцијумских канала дугог дјеловања, често и у комбинацијама са другим лијековима за притисак.', 'Блокатор кальциевых каналов длительного действия, часто применяется в комбинациях с другими средствами от давления.', 'Ein lang wirksamer Kalziumkanalblocker, oft in Kombination mit anderen Blutdruckmitteln.', 'Uzun etkili bir kalsiyum kanal blokeridir, sık olarak diğer tansiyon ilaçlarıyla birleşik preparatlarda bulunur.', 'Prescribed for high blood pressure and for angina, including as part of fixed combination products.', 'Propisuje se kod povišenog krvnog pritiska i kod angine pektoris, uključujući i kombinovane preparate.', 'Прописује се код повишеног крвног притиска и код ангине пекторис, укључујући и комбиноване препарате.', 'Назначают при артериальной гипертензии и при стенокардии, в том числе в составе комбинированных препаратов.', 'Wird bei Bluthochdruck und bei Angina pectoris verordnet, auch als Bestandteil fester Kombinationspräparate.', 'Yüksek tansiyonda ve anjina pektoriste, birleşik preparatlar içinde de reçete edilir.', 'Prescription only. Ankle swelling, headache and flushing are possible. Grapefruit juice increases its effect. A doctor sets the dose, it should not be stopped on your own.', 'Izdaje se samo na recept. Mogući su otoci skočnih zglobova, glavobolja i crvenilo lica. Sok od grejpfruta pojačava djelovanje. Dozu vodi ljekar, ne prekida se samovoljno.', 'Издаје се само на рецепт. Могући су отоци скочних зглобова, главобоља и црвенило лица. Сок од грејпфрута појачава дјеловање. Дозу води љекар, не прекида се самовољно.', 'Только по рецепту. Возможны отёки лодыжек, головная боль и приливы. Грейпфрутовый сок усиливает действие. Дозу подбирает врач, самостоятельно приём не прекращают.', 'Verschreibungspflichtig. Knöchelödeme, Kopfschmerzen und Hitzegefühl sind möglich. Grapefruitsaft verstärkt die Wirkung. Die Dosis führt der Arzt, kein eigenmächtiges Absetzen.', 'Yalnızca reçeteyle verilir. Ayak bileğinde şişme, baş ağrısı ve sıcak basması olabilir. Greyfurt suyu etkisini artırır. Dozu doktor ayarlar, kendiliğinden bırakılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- amoksicilin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (46, 'A broad-spectrum antibiotic from the penicillin group. It is also available combined with clavulanic acid.', 'Antibiotik iz grupe penicilina širokog spektra djelovanja. Postoji i kombinacija sa klavulanskom kiselinom.', 'Антибиотик из групе пеницилина широког спектра дјеловања. Постоји и комбинација са клавуланском киселином.', 'Антибиотик группы пенициллинов с широким спектром действия. Есть комбинация с клавулановой кислотой.', 'Ein Breitbandantibiotikum aus der Penicillingruppe. Auch in Kombination mit Clavulansäure erhältlich.', 'Penisilin grubundan geniş spektrumlu bir antibiyotiktir. Klavulanik asitli kombinasyonu da vardır.', 'Used for bacterial infections of the airways, ear and throat, urinary tract and skin, and in regimens against Helicobacter pylori.', 'Primjenjuje se kod bakterijskih infekcija disajnih puteva, uha i grla, mokraćnih puteva i kože, kao i u terapiji Helicobacter pylori.', 'Примјењује се код бактеријских инфекција дисајних путева, уха и грла, мокраћних путева и коже, као и у терапији Helicobacter pylori.', 'Применяют при бактериальных инфекциях дыхательных путей, уха и горла, мочевых путей и кожи, а также в схемах против Helicobacter pylori.', 'Wird bei bakteriellen Infektionen der Atemwege, von Ohr und Hals, der Harnwege und der Haut sowie gegen Helicobacter pylori eingesetzt.', 'Solunum yolları, kulak ve boğaz, idrar yolları ve deri enfeksiyonlarında, ayrıca Helicobacter pylori tedavisinde kullanılır.', 'Prescription only. It does not work against viral colds. Rash and diarrhoea are possible, and it is not used with penicillin allergy. The course is completed in full.', 'Izdaje se na recept. Ne djeluje na virusne prehlade. Mogući su osip i proliv, ne primjenjuje se kod alergije na peniciline. Terapiju treba završiti do kraja.', 'Издаје се на рецепт. Не дјелује на вирусне прехладе. Могући су осип и пролив, не примјењује се код алергије на пеницилине. Терапију треба завршити до краја.', 'Отпускается по рецепту. Против вирусных простуд не действует. Возможны сыпь и диарея, при аллергии на пенициллины не применяют. Курс важно пройти полностью.', 'Verschreibungspflichtig. Gegen virale Erkältungen wirkt es nicht. Ausschlag und Durchfall sind möglich, bei Penicillinallergie nicht anwenden. Die Therapie wird zu Ende geführt.', 'Yalnızca reçeteyle verilir. Viral soğuk algınlığına etkisizdir. Döküntü ve ishal olabilir, penisilin alerjisinde kullanılmaz. Tedavi sonuna kadar tamamlanır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- amorolfin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (47, 'An antifungal for external use on the nails.', 'Antimikotik za spoljnu primjenu na nokte.', 'Антимикотик за спољну примјену на нокте.', 'Противогрибковое вещество для наружного применения на ногти.', 'Ein Antimykotikum zur äußeren Anwendung an den Nägeln.', 'Tırnaklara dıştan uygulanan bir antifungaldir.', 'Used for fungal infection of finger and toe nails when only a limited part of the nail plate is affected.', 'Primjenjuje se kod gljivične infekcije noktiju na rukama i nogama kada je zahvaćen manji dio ploče nokta.', 'Примјењује се код гљивичне инфекције ноктију на рукама и ногама када је захваћен мањи дио плоче нокта.', 'Применяют при грибковом поражении ногтей на руках и ногах, когда затронута ограниченная часть ногтевой пластины.', 'Wird bei Pilzbefall der Finger- und Fußnägel angewendet, wenn nur ein kleiner Teil der Nagelplatte betroffen ist.', 'El ve ayak tırnaklarında, tırnak plağının sınırlı bir bölümünü tutan mantar enfeksiyonunda kullanılır.', 'Over the counter. Treatment of nails is long, and extensive damage needs a doctor. In pregnancy and for children, only on a doctor''s advice. Avoid contact with the eyes.', 'Izdaje se bez recepta. Liječenje je dugotrajno, a kod opsežne zahvaćenosti potreban je ljekar. U trudnoći i kod djece samo po savjetu ljekara. Izbjegavati kontakt sa očima.', 'Издаје се без рецепта. Лијечење је дуготрајно, а код опсежне захваћености потребан је љекар. У трудноћи и код дјеце само по савјету љекара. Избјегавати контакт са очима.', 'Отпускается без рецепта. Лечение ногтей длительное, при обширном поражении нужен врач. Беременным и детям — по назначению врача. Избегать попадания в глаза.', 'Rezeptfrei. Die Behandlung dauert lange, bei ausgedehntem Befall ist ärztliche Hilfe nötig. In Schwangerschaft und bei Kindern nur ärztlich. Kontakt mit den Augen vermeiden.', 'Reçetesiz satılır. Tedavi uzun sürer, yaygın tutulumda hekime başvurulur. Gebelikte ve çocuklarda hekim önerisiyle kullanılır. Gözle temasından kaçınılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- apiksaban
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (53, 'A direct-acting anticoagulant that blocks clotting factor Xa.', 'Direktni antikoagulans koji blokira faktor zgrušavanja Xa.', 'Директни антикоагуланс који блокира фактор згрушавања Xa.', 'Антикоагулянт прямого действия, блокирует фактор свёртывания Xa.', 'Ein direktes Antikoagulans, das den Gerinnungsfaktor Xa hemmt.', 'Pıhtılaşma faktörü Xa''yı bloke eden doğrudan etkili bir antikoagülandır.', 'Prescribed in atrial fibrillation to prevent stroke, in deep vein thrombosis and pulmonary embolism, and after joint surgery.', 'Propisuje se kod atrijalne fibrilacije radi prevencije moždanog udara, kod duboke venske tromboze i plućne embolije, i poslije operacija zglobova.', 'Прописује се код атријалне фибрилације ради превенције можданог удара, код дубоке венске тромбозе и плућне емболије, и послије операција зглобова.', 'Назначают при мерцательной аритмии для профилактики инсульта, при тромбозе глубоких вен и лёгочной эмболии, а также после операций на суставах.', 'Wird bei Vorhofflimmern zur Schlaganfallvorbeugung, bei tiefer Venenthrombose und Lungenembolie sowie nach Gelenkoperationen verordnet.', 'Atriyal fibrilasyonda inmeyi önlemek için, derin ven trombozu ve akciğer embolisinde, ayrıca eklem ameliyatlarından sonra reçete edilir.', 'Prescription only. It raises the risk of bleeding and stopping it on your own is dangerous. Tell any doctor or dentist that you take it, and be careful with NSAIDs.', 'Izdaje se samo na recept. Povećava rizik od krvarenja, samovoljni prekid je opasan. O uzimanju se obavještavaju ljekar i stomatolog, oprez uz NSAIL.', 'Издаје се само на рецепт. Повећава ризик од крварења, самовољни прекид је опасан. О узимању се обавјештавају љекар и стоматолог, опрез уз NSAIL.', 'Только по рецепту. Повышает риск кровотечений, самостоятельная отмена опасна. О приёме предупреждают врача и стоматолога, осторожно с НПВС и другими разжижающими кровь средствами.', 'Verschreibungspflichtig. Erhöht das Blutungsrisiko, eigenmächtiges Absetzen ist gefährlich. Arzt und Zahnarzt über die Einnahme informieren, Vorsicht bei NSAR.', 'Yalnızca reçeteyle verilir. Kanama riskini artırır, kendi başına bırakmak tehlikelidir. Doktor ve diş hekimi kullanımdan haberdar edilmeli, NSAİİ ile dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- askorbinska kiselina
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (60, 'Ascorbic acid is vitamin C, a water-soluble vitamin, used on its own and in combination cold remedies', 'Askorbinska kiselina je vitamin C, vitamin rastvorljiv u vodi; koristi se samostalno i u kombinovanim preparatima protiv prehlade', 'Аскорбинска киселина је витамин Ц, витамин растворљив у води; користи се самостално и у комбинованим препаратима против прехладе', 'Аскорбиновая кислота — витамин C, водорастворимый витамин; применяется отдельно и в комбинированных средствах от простуды', 'Ascorbinsäure ist Vitamin C, ein wasserlösliches Vitamin, das einzeln und in Kombipräparaten gegen Erkältung vorkommt', 'Askorbik asit, suda çözünen bir vitamin olan C vitaminidir; tek başına ve kombine soğuk algınlığı ürünlerinde bulunur', 'Prevention and correction of vitamin C deficiency, support when needs are increased, and as part of combination cold remedies', 'Prevencija i nadoknada nedostatka vitamina C, podrška kod povećanih potreba, kao i u kombinovanim preparatima protiv prehlade', 'Превенција и надокнада недостатка витамина Ц, подршка код повећаних потреба, као и у комбинованим препаратима против прехладе', 'Профилактика и восполнение недостатка витамина C, поддержка при повышенной потребности, в составе комбинированных средств при простуде', 'Vorbeugung und Ausgleich eines Vitamin-C-Mangels, Unterstützung bei erhöhtem Bedarf sowie als Bestandteil von Erkältungskombinationen', 'C vitamini eksikliğinin önlenmesi ve giderilmesi, ihtiyacın arttığı durumlarda destek, ayrıca kombine soğuk algınlığı ürünlerinde', 'Large amounts irritate the stomach and raise the risk of kidney stones. With kidney stones, kidney disease, in pregnancy and in children use only as advised by a doctor.', 'Veće količine nadražuju želudac i povećavaju rizik od kamena u bubregu. Kod kamena i bolesti bubrega, u trudnoći i kod djece samo po savjetu ljekara.', 'Веће количине надражују желудац и повећавају ризик од камена у бубрегу. Код камена и болести бубрега, у трудноћи и код дјеце само по савјету љекара.', 'Большие количества раздражают желудок и повышают риск камней в почках. При мочекаменной болезни, болезнях почек, беременности и у детей — по назначению врача.', 'Größere Mengen reizen den Magen und erhöhen das Risiko für Nierensteine. Bei Nierensteinen, Nierenerkrankungen, in der Schwangerschaft und bei Kindern nur nach ärztlicher Anweisung.', 'Yüksek miktarlar mideyi tahriş eder ve böbrek taşı riskini artırır. Böbrek taşı ve böbrek hastalığında, gebelikte ve çocuklarda yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- atorvastatin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (65, 'A statin, a medicine that lowers LDL cholesterol in the blood. Combinations with other cholesterol and blood pressure agents exist.', 'Statin, lijek koji snižava LDL holesterol u krvi. Postoje i kombinacije sa drugim lijekovima za masnoće i pritisak.', 'Статин, лијек који снижава LDL холестерол у крви. Постоје и комбинације са другим лијековима за масноће и притисак.', 'Статин — средство, снижающее уровень холестерина LDL в крови. Есть комбинации с другими препаратами от холестерина и давления.', 'Ein Statin, ein Mittel zur Senkung des LDL-Cholesterins im Blut. Es gibt auch Kombinationen mit anderen Lipid- und Blutdruckmitteln.', 'Kandaki LDL kolesterolü düşüren bir statindir. Diğer kolesterol ve tansiyon ilaçlarıyla kombinasyonları da bulunur.', 'Used for high cholesterol and to lower the risk of heart attack and stroke, including in coronary heart disease.', 'Primjenjuje se kod povišenog holesterola i radi smanjenja rizika od infarkta i moždanog udara, kod koronarne bolesti.', 'Примјењује се код повишеног холестерола и ради смањења ризика од инфаркта и можданог удара, код коронарне болести.', 'Применяют при повышенном холестерине и для снижения риска инфаркта и инсульта, в том числе при ишемической болезни сердца.', 'Wird bei erhöhtem Cholesterin und zur Senkung des Herzinfarkt- und Schlaganfallrisikos eingesetzt, auch bei koronarer Herzkrankheit.', 'Yüksek kolesterolde, kalp krizi ve inme riskini azaltmak için, koroner kalp hastalığında da kullanılır.', 'Prescription only and taken long term under medical supervision. Unexplained muscle pain is reported to the doctor. Not used in pregnancy, and liver values are checked by the doctor.', 'Izdaje se na recept i uzima se dugotrajno uz nadzor ljekara. Neobjašnjivi bolovi u mišićima prijavljuju se ljekaru. U trudnoći se ne primjenjuje, prate se nalazi jetre.', 'Издаје се на рецепт и узима се дуготрајно уз надзор љекара. Необјашњиви болови у мишићима пријављују се љекару. У трудноћи се не примјењује, прате се налази јетре.', 'Отпускается по рецепту, принимают длительно под наблюдением врача. О необъяснимой боли в мышцах сообщают врачу. При беременности не применяют, врач следит за показателями печени.', 'Verschreibungspflichtig und langfristig unter ärztlicher Kontrolle. Unerklärliche Muskelschmerzen dem Arzt melden. In der Schwangerschaft nicht anwenden, Leberwerte werden kontrolliert.', 'Yalnızca reçeteyle verilir, hekim gözetiminde uzun süre kullanılır. Açıklanamayan kas ağrıları hekime bildirilir. Gebelikte kullanılmaz, karaciğer değerleri izlenir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- azelastin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (70, 'A locally acting antihistamine. It also comes in a combination with a steroid.', 'Antihistaminik sa lokalnim djelovanjem. Postoji i u kombinaciji sa hormonskim lijekom.', 'Антихистаминик са локалним дјеловањем. Постоји и у комбинацији са хормонским лијеком.', 'Антигистаминное средство местного действия. Входит и в комбинацию с гормональным средством.', 'Ein örtlich wirkendes Antihistaminikum, auch in Kombination mit einem Kortisonpräparat erhältlich.', 'Bölgesel etkili bir antihistaminiktir. Kortizonlu bir ilaçla kombinasyonu da bulunur.', 'Used for allergic rhinitis with sneezing and a blocked nose, and for allergic conjunctivitis.', 'Primjenjuje se kod alergijskog rinitisa sa kijanjem i zapušenim nosom, kao i kod alergijskog konjunktivitisa.', 'Примјењује се код алергијског ринитиса са кијањем и запушеним носом, као и код алергијског коњунктивитиса.', 'Применяют при аллергическом рините с чиханием и заложенностью носа, а также при аллергическом конъюнктивите.', 'Wird bei allergischem Schnupfen mit Niesen und verstopfter Nase sowie bei allergischer Bindehautentzündung angewendet.', 'Hapşırık ve burun tıkanıklığıyla giden alerjik nezlede ve alerjik konjonktivitte kullanılır.', 'Some forms are prescription only, and the combination with a steroid is a doctor''s decision. A bitter taste and nasal irritation are possible.', 'Dio oblika izdaje se na recept, a kombinaciju sa hormonom određuje ljekar. Mogući su gorak ukus i nadražaj sluznice nosa.', 'Дио облика издаје се на рецепт, а комбинацију са хормоном одређује љекар. Могући су горак укус и надражај слузнице носа.', 'Часть форм отпускается по рецепту, комбинация с гормоном — только по назначению врача. Возможны горький привкус и раздражение слизистой носа.', 'Ein Teil der Formen ist verschreibungspflichtig, die Kombination mit Kortison bestimmt der Arzt. Bitterer Geschmack und Nasenreizung sind möglich.', 'Bazı formları reçeteye tabidir, kortizonlu kombinasyona hekim karar verir. Ağızda acı tat ve burun mukozasında tahriş görülebilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- beklometazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (79, 'An inhaled corticosteroid that reduces inflammation in the airways. In Montenegro it is available only in combination products.', 'Inhalacioni kortikosteroid koji smanjuje upalu u disajnim putevima. U Crnoj Gori je dostupan samo u kombinovanim preparatima.', 'Инхалациони кортикостероид који смањује упалу у дисајним путевима. У Црној Гори је доступан само у комбинованим препаратима.', 'Ингаляционный глюкокортикоид, уменьшающий воспаление в дыхательных путях. В Черногории доступен только в комбинированных препаратах.', 'Ein inhalatives Kortison, das Entzündungen in den Atemwegen dämpft. In Montenegro ist es nur in Kombinationspräparaten erhältlich.', 'Solunum yollarındaki iltihabı azaltan inhale bir kortikosteroittir. Karadağ''da yalnızca kombine preparatlarda bulunur.', 'Used as maintenance treatment of asthma and COPD, so that attacks and flare-ups occur less often.', 'Primjenjuje se kao osnovna terapija astme i HOBP, da bi napadi i pogoršanja bili rjeđi.', 'Примјењује се као основна терапија астме и ХОБП, да би напади и погоршања били рјеђи.', 'Применяют как базисное лечение бронхиальной астмы и ХОБЛ, чтобы реже возникали приступы и обострения.', 'Wird als Basistherapie bei Asthma und COPD eingesetzt, damit Anfälle und Verschlechterungen seltener auftreten.', 'Astım ve KOAH''ta temel tedavi olarak, atakların ve alevlenmelerin daha seyrek olması için kullanılır.', 'Prescription only. Rinsing the mouth after inhaling lowers the risk of thrush and hoarseness. It is not a rescue medicine for an attack.', 'Izdaje se na recept. Ispiranje usta poslije inhalacije smanjuje rizik od gljivica i promuklosti. Nije lijek za brzo olakšanje u napadu.', 'Издаје се на рецепт. Испирање уста послије инхалације смањује ризик од гљивица и промуклости. Није лијек за брзо олакшање у нападу.', 'Отпускается по рецепту. Полоскание рта после ингаляции снижает риск молочницы и осиплости. Это не средство скорой помощи при приступе.', 'Verschreibungspflichtig. Mundspülen nach der Inhalation senkt das Risiko für Pilzbefall und Heiserkeit. Es ist kein Notfallmittel im Anfall.', 'Reçeteye tabidir. İnhalasyondan sonra ağzın çalkalanması pamukçuk ve ses kısıklığı riskini azaltır. Atak anında kurtarıcı ilaç değildir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- benfotiamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (81, 'A fat-soluble form of vitamin B1 (thiamine) that is absorbed better than plain thiamine.', 'Oblik vitamina B1 (tiamina) rastvorljiv u mastima, koji se bolje apsorbuje od običnog tiamina.', 'Облик витамина B1 (тиамина) растворљив у мастима, који се боље апсорбује од обичног тиамина.', 'Жирорастворимая форма витамина B1 (тиамина), которая усваивается лучше обычного тиамина.', 'Eine fettlösliche Form von Vitamin B1 (Thiamin), die besser aufgenommen wird als gewöhnliches Thiamin.', 'B1 vitamininin (tiamin) yağda çözünen, sıradan tiamine göre daha iyi emilen bir formudur.', 'Used for vitamin B1 deficiency and in B-complex products for pain and altered sensation linked to nerve damage.', 'Primjenjuje se kod nedostatka vitamina B1 i u preparatima B grupe kod bola i promjena osjeta zbog oštećenja nerava.', 'Примјењује се код недостатка витамина B1 и у препаратима Б групе код бола и промјена осјета због оштећења нерава.', 'Применяют при недостатке витамина B1 и в комплексах группы B при боли и нарушениях чувствительности из-за поражения нервов.', 'Wird bei Vitamin-B1-Mangel und in B-Komplex-Präparaten bei Schmerzen und Missempfindungen durch Nervenschäden verwendet.', 'B1 vitamini eksikliğinde ve sinir hasarına bağlı ağrı ile his değişikliklerinde B grubu preparatlarda kullanılır.', 'Sold without prescription, but numbness, burning or pain in the limbs should first be assessed by a doctor. It does not replace diabetes treatment.', 'Izdaje se bez recepta, ali utrnulost, žarenje ili bol u udovima prvo treba da procijeni ljekar. Ne zamjenjuje liječenje dijabetesa.', 'Издаје се без рецепта, али утрнулост, жарење или бол у удовима прво треба да процијени љекар. Не замјењује лијечење дијабетеса.', 'Отпускается без рецепта, но онемение, жжение или боль в конечностях сначала должен оценить врач. Не заменяет лечение диабета.', 'Rezeptfrei, aber Taubheit, Brennen oder Schmerzen in den Gliedmaßen sollte zuerst ein Arzt abklären. Ersetzt keine Diabetesbehandlung.', 'Reçetesiz satılır, ancak kol ve bacaklarda uyuşma, yanma veya ağrıyı önce doktor değerlendirmelidir. Diyabet tedavisinin yerini tutmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- benralizumab
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (82, 'A monoclonal antibody that reduces eosinophils, the cells driving allergic inflammation in the airways. Given as an injection under the skin.', 'Monoklonsko antitijelo koje smanjuje broj eozinofila, ćelija koje održavaju alergijsku upalu u disajnim putevima. Daje se injekcijom pod kožu.', 'Моноклонско антитијело које смањује број еозинофила, ћелија које одржавају алергијску упалу у дисајним путевима. Даје се ињекцијом под кожу.', 'Моноклональное антитело, снижающее число эозинофилов — клеток, поддерживающих аллергическое воспаление в дыхательных путях. Вводится подкожно.', 'Ein monoklonaler Antikörper, der die Zahl der Eosinophilen senkt, jener Zellen, die die allergische Entzündung der Atemwege unterhalten. Spritze unter die Haut.', 'Hava yollarındaki alerjik iltihabı sürdüren eozinofil hücrelerinin sayısını azaltan monoklonal antikordur. Deri altına enjeksiyonla uygulanır.', 'Used as an add-on to standard therapy in severe eosinophilic asthma that is not controlled by inhalers.', 'Primjenjuje se kao dodatak osnovnoj terapiji kod teške eozinofilne astme koja se ne kontroliše inhalatorima.', 'Примјењује се као додатак основној терапији код тешке еозинофилне астме која се не контролише инхалаторима.', 'Применяют как дополнение к базисной терапии при тяжёлой эозинофильной бронхиальной астме, которая не контролируется ингаляторами.', 'Wird als Zusatz zur Basistherapie bei schwerem eosinophilem Asthma eingesetzt, das mit Inhalatoren nicht kontrolliert ist.', 'İnhalerlerle kontrol altına alınamayan ağır eozinofilik astımda temel tedaviye ek olarak kullanılır.', 'Prescription only; a specialist starts and supervises the treatment. Not for attacks, and inhaled therapy is not stopped. Injection-site reactions and headache are possible.', 'Samo na recept, terapiju uvodi i prati specijalista. Ne koristi se u napadu, a osnovni inhalatori se ne ukidaju. Mogući su reakcija na mjestu uboda i glavobolja.', 'Само на рецепт, терапију уводи и прати специјалиста. Не користи се у нападу, а основни инхалатори се не укидају. Могући су реакција на мјесту убода и главобоља.', 'Только по рецепту, лечение назначает и контролирует специалист. Не применяется при приступе, базисные ингаляторы не отменяют. Возможны реакция в месте укола и головная боль.', 'Nur auf Rezept, Beginn und Kontrolle durch einen Facharzt. Nicht im Anfall, die Basisinhalatoren werden nicht abgesetzt. Reaktionen an der Einstichstelle und Kopfschmerzen möglich.', 'Yalnızca reçeteyle verilir, tedaviyi uzman hekim başlatır ve izler. Atakta kullanılmaz, temel inhaler tedavi kesilmez. Enjeksiyon yerinde tepki ve baş ağrısı olabilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- benzidamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (85, 'A topical non-steroidal anti-inflammatory agent with a local painkilling effect for the mouth and throat.', 'Lokalni nesteroidni antiinflamatorni lijek koji ublažava bol u ustima i grlu.', 'Локални нестероидни антиинфламаторни лијек који ублажава бол у устима и грлу.', 'Местное нестероидное противовоспалительное средство с обезболивающим действием для полости рта и горла.', 'Ein örtlich wirkendes entzündungshemmendes Mittel mit schmerzlindernder Wirkung für Mund und Rachen.', 'Ağız ve boğazda bölgesel etkili, ağrıyı hafifleten antiinflamatuar bir etken maddedir.', 'Used for pain and inflammation of the throat and mouth, including mouth ulcers and the period after dental procedures.', 'Primjenjuje se kod bola i zapaljenja u grlu i usnoj duplji, uključujući stomatitis i period poslije stomatoloških zahvata.', 'Примјењује се код бола и запаљења у грлу и усној дупљи, укључујући стоматитис и период послије стоматолошких захвата.', 'Применяют при боли и воспалении в горле и полости рта, в том числе при стоматите и после стоматологических вмешательств.', 'Wird bei Schmerzen und Entzündungen im Hals und Mund angewendet, auch bei Aphthen und nach zahnärztlichen Eingriffen.', 'Boğaz ve ağız içindeki ağrı ve iltihapta, aft ve diş işlemleri sonrası dönemde kullanılır.', 'Available over the counter. Burning or numbness in the mouth may occur. In small children, sprays and rinses only on a doctor''s advice.', 'Izdaje se bez recepta. Mogući su peckanje i utrnulost u ustima. Kod male djece sprejevi i rastvori samo po savjetu ljekara.', 'Издаје се без рецепта. Могући су пецкање и утрнулост у устима. Код мале дјеце спрејеви и раствори само по савјету љекара.', 'Отпускается без рецепта. Возможны жжение и онемение во рту. У маленьких детей спреи и растворы применяют только по назначению врача.', 'Rezeptfrei erhältlich. Brennen oder Taubheitsgefühl im Mund sind möglich. Bei kleinen Kindern nur nach ärztlicher Anweisung anwenden.', 'Reçetesiz satılır. Ağızda yanma ve uyuşma görülebilir. Küçük çocuklarda sprey ve çözeltiler yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- benzil nikotinat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (86, 'A substance for external use that widens skin vessels and creates a feeling of warmth. It is part of warming topical products.', 'Sredstvo za spoljnu primjenu koje širi krvne sudove kože i daje osjećaj toplote. Ulazi u zagrijavajuće spoljne preparate.', 'Средство за спољну примјену које шири крвне судове коже и даје осјећај топлоте. Улази у загријавајуће спољне препарате.', 'Вещество, расширяющее сосуды кожи и дающее ощущение тепла. Входит в согревающие средства для наружного применения.', 'Ein äußerlich anzuwendender Stoff, der die Hautgefäße erweitert und ein Wärmegefühl erzeugt. Er steckt in wärmenden Mitteln.', 'Deri damarlarını genişleterek sıcaklık hissi veren, dıştan kullanılan bir maddedir. Isıtıcı dış kullanım ürünlerinde bulunur.', 'Used in topical products for muscle and joint pain, bruises and sprains, and to warm up muscles before exercise.', 'Primjenjuje se u spoljnim preparatima kod bolova u mišićima i zglobovima, kod nagnječenja i istegnuća i za zagrijavanje prije napora.', 'Примјењује се у спољним препаратима код болова у мишићима и зглобовима, код нагњечења и истегнућа и за загријавање прије напора.', 'Применяют в составе наружных средств при боли в мышцах и суставах, при ушибах и растяжениях, а также для разогрева перед нагрузкой.', 'Wird in äußerlichen Mitteln bei Muskel- und Gelenkschmerzen, Prellungen und Zerrungen sowie zum Aufwärmen vor Belastung verwendet.', 'Dıştan kullanılan ürünlerde kas ve eklem ağrısında, berelenme ve burkulmalarda, egzersiz öncesi ısınmada kullanılır.', 'Available over the counter. External use only, on unbroken skin. Marked redness and burning are possible, keep it away from eyes and mucous membranes.', 'Izdaje se bez recepta. Samo spolja, na neoštećenu kožu. Mogući su jako crvenilo i žarenje, ne nanosi se na oči i sluznice.', 'Издаје се без рецепта. Само споља, на неоштећену кожу. Могући су јако црвенило и жарење, не наноси се на очи и слузнице.', 'Отпускается без рецепта. Только наружно, на неповреждённую кожу. Возможны сильное покраснение и жжение, в глаза и на слизистые не наносят.', 'Rezeptfrei erhältlich. Nur äußerlich auf unverletzter Haut. Starke Rötung und Brennen sind möglich, nicht in die Augen und auf Schleimhäute bringen.', 'Reçetesiz satılır. Yalnızca sağlam deriye haricen uygulanır. Belirgin kızarıklık ve yanma olabilir, göz ve mukozaya sürülmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- betahistin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (90, 'A medicine that acts on histamine receptors and on blood flow in the inner ear.', 'Lijek koji djeluje na histaminske receptore i na protok krvi u unutrašnjem uhu.', 'Лијек који дјелује на хистаминске рецепторе и на проток крви у унутрашњем уху.', 'Средство, действующее на гистаминовые рецепторы и на кровоток во внутреннем ухе.', 'Ein Arzneimittel, das auf Histaminrezeptoren und die Durchblutung im Innenohr wirkt.', 'Histamin reseptörleri ve iç kulaktaki kan akımı üzerinde etkili bir ilaçtır.', 'Used for vertigo, ringing in the ears and hearing loss in Meniere''s disease and other disorders of the balance organ.', 'Primjenjuje se kod vrtoglavice, zujanja u ušima i slabljenja sluha kod Menijerove bolesti i drugih poremećaja ravnoteže.', 'Примјењује се код вртоглавице, зујања у ушима и слабљења слуха код Менијерове болести и других поремећаја равнотеже.', 'Применяют при головокружении, шуме в ушах и снижении слуха при болезни Меньера и других нарушениях вестибулярного аппарата.', 'Wird bei Schwindel, Ohrgeräuschen und Hörminderung bei Morbus Meniere und anderen Störungen des Gleichgewichtsorgans eingesetzt.', 'Meniere hastalığı ve diğer denge bozukluklarında baş dönmesi, kulak çınlaması ve işitme azalmasında kullanılır.', 'Prescription only. Caution with peptic ulcer disease and asthma. In pregnancy, breastfeeding and in children, only on a doctor''s advice.', 'Izdaje se na recept. Oprez kod čira na želucu i kod astme. U trudnoći, dojenju i kod djece samo po savjetu ljekara.', 'Издаје се на рецепт. Опрез код чира на желуцу и код астме. У трудноћи, дојењу и код дјеце само по савјету љекара.', 'Отпускается по рецепту. Осторожность при язвенной болезни и бронхиальной астме. При беременности, кормлении грудью и у детей — только по назначению врача.', 'Verschreibungspflichtig. Vorsicht bei Magengeschwür und Asthma. In Schwangerschaft und Stillzeit sowie bei Kindern nur nach ärztlicher Anweisung.', 'Reçeteye tabidir. Mide ülseri ve astımda dikkatli olunur. Gebelikte, emzirme döneminde ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- betametazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (91, 'A potent glucocorticoid, in Montenegro also in combinations with an antibiotic or salicylic acid.', 'Jak glukokortikoid, u Crnoj Gori i u kombinacijama sa antibiotikom ili salicilnom kiselinom.', 'Јак глукокортикоид, у Црној Гори и у комбинацијама са антибиотиком или салицилном киселином.', 'Сильный глюкокортикоид, в Черногории в том числе в комбинациях с антибиотиком или салициловой кислотой.', 'Ein starkes Glukokortikoid, in Montenegro auch in Kombination mit einem Antibiotikum oder Salicylsäure.', 'Güçlü bir glukokortikoiddir, Karadağ''da antibiyotikli veya salisilik asitli kombinasyonları da bulunur.', 'Topical forms are used for eczema, psoriasis and other itchy inflammatory skin conditions; injections are prescribed for rheumatic and allergic conditions.', 'Lokalni oblici primjenjuju se kod ekcema, psorijaze i drugih upalnih bolesti kože sa svrabom, a injekcije ljekar propisuje kod reumatskih i alergijskih stanja.', 'Локални облици примјењују се код екцема, псоријазе и других упалних болести коже са сврабом, а ињекције љекар прописује код реуматских и алергијских стања.', 'Наружные формы применяют при экземе, псориазе и других воспалительных болезнях кожи с зудом, инъекции назначает врач при ревматических и аллергических состояниях.', 'Äußerlich bei Ekzem, Schuppenflechte und anderen juckenden Hautentzündungen; Injektionen verordnet der Arzt bei rheumatischen und allergischen Erkrankungen.', 'Dıştan kullanılan formlar egzama, sedef ve kaşıntılı diğer deri iltihaplarında, enjeksiyonlar ise romatizmal ve alerjik durumlarda hekim kararıyla uygulanır.', 'Prescription only. Prolonged use thins the skin; on the face and in children it is used with care. It goes on infected skin only when a doctor prescribes it.', 'Izdaje se samo na recept. Dugotrajna primjena istanjuje kožu, na licu i kod djece koristi se oprezno. Na inficiranu kožu nanosi se samo po preporuci ljekara.', 'Издаје се само на рецепт. Дуготрајна примјена истањује кожу, на лицу и код дјеце користи се опрезно. На инфицирану кожу наноси се само по препоруци љекара.', 'Только по рецепту. Длительное нанесение истончает кожу, на лице и у детей применяют с осторожностью. На инфицированную кожу наносят только по назначению врача.', 'Nur auf Rezept. Längere Anwendung macht die Haut dünner, im Gesicht und bei Kindern nur vorsichtig. Auf infizierte Haut nur nach ärztlicher Anordnung auftragen.', 'Yalnızca reçeteyle verilir. Uzun süreli kullanım deriyi inceltir, yüzde ve çocuklarda dikkatle kullanılır. Enfekte deriye ancak hekim önerisiyle sürülür.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- bilastin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (94, 'A second-generation antihistamine that rarely causes drowsiness.', 'Antihistaminik druge generacije koji gotovo ne izaziva pospanost.', 'Антихистаминик друге генерације који готово не изазива поспаност.', 'Антигистаминное средство второго поколения, которое почти не вызывает сонливости.', 'Ein Antihistaminikum der zweiten Generation, das kaum müde macht.', 'Nadiren uyku hali yapan ikinci kuşak bir antihistaminiktir.', 'Used for allergic rhinitis with sneezing and an itchy nose, and for hives and itching of the skin.', 'Primjenjuje se kod alergijskog rinitisa sa kijanjem i svrabom u nosu, kao i kod koprivnjače i svraba kože.', 'Примјењује се код алергијског ринитиса са кијањем и сврабом у носу, као и код копривњаче и свраба коже.', 'Применяют при аллергическом рините с чиханием и зудом в носу, а также при крапивнице и кожном зуде.', 'Wird bei allergischem Schnupfen mit Niesen und Nasenjucken sowie bei Nesselsucht und Hautjucken angewendet.', 'Hapşırma ve burun kaşıntısıyla giden alerjik nezlede, ayrıca kurdeşen ve deri kaşıntısında kullanılır.', 'In Montenegro it is prescription only. Food and fruit juices reduce its absorption. Drowsiness is rare but worth noting when driving. In children, as a doctor advises.', 'U Crnoj Gori se izdaje na recept. Hrana i voćni sokovi smanjuju apsorpciju. Pospanost je rijetka, ali se uzima u obzir pri vožnji. Djeci po savjetu ljekara.', 'У Црној Гори се издаје на рецепт. Храна и воћни сокови смањују апсорпцију. Поспаност је ријетка, али се узима у обзир при вожњи. Дјеци по савјету љекара.', 'В Черногории отпускается по рецепту. Еда и фруктовые соки снижают всасывание. Сонливость бывает редко, но при вождении её учитывают. Детям — по назначению врача.', 'In Montenegro verschreibungspflichtig. Essen und Fruchtsäfte vermindern die Aufnahme. Müdigkeit ist selten, beim Autofahren aber zu bedenken. Bei Kindern nach ärztlichem Rat.', 'Karadağ''da reçeteye tabidir. Yiyecek ve meyve suları emilimini azaltır. Uyku hali seyrektir ama araç kullanırken dikkate alınır. Çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- bisakodil
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (97, 'A stimulant laxative that increases movement of the large bowel.', 'Stimulativni laksativ koji pojačava pokretljivost debelog crijeva.', 'Стимулативни лаксатив који појачава покретљивост дебелог цријева.', 'Слабительное стимулирующего действия: усиливает моторику толстой кишки.', 'Ein stimulierendes Abführmittel, das die Bewegung des Dickdarms anregt.', 'Kalın bağırsak hareketlerini artıran uyarıcı bir müshildir.', 'Used for constipation and to empty the bowel before endoscopy and X-ray examinations.', 'Primjenjuje se kod zatvora i za pražnjenje crijeva prije endoskopije i rendgenskih pregleda.', 'Примјењује се код затвора и за пражњење цријева прије ендоскопије и рендгенских прегледа.', 'Применяют при запоре, а также для очищения кишечника перед эндоскопией и рентгеновскими исследованиями.', 'Wird bei Verstopfung und zur Darmentleerung vor Endoskopie und Röntgenuntersuchungen eingesetzt.', 'Kabızlıkta ve endoskopi ile röntgen incelemeleri öncesinde bağırsağın boşaltılmasında kullanılır.', 'Available over the counter but meant for short use. With abdominal pain, suspected obstruction or in children, only on a doctor''s advice.', 'Izdaje se bez recepta, ali je namijenjen kratkotrajnoj upotrebi. Kod bolova u trbuhu, sumnje na opstrukciju i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта, али је намијењен краткотрајној употреби. Код болова у трбуху, сумње на опструкцију и код дјеце само по савјету љекара.', 'Отпускается без рецепта, но предназначено для короткого применения. При боли в животе, подозрении на непроходимость и у детей — по назначению врача.', 'Rezeptfrei, aber nur für kurze Anwendung gedacht. Bei Bauchschmerzen, Verdacht auf Darmverschluss und bei Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır ancak kısa süreli kullanım içindir. Karın ağrısında, tıkanıklık şüphesinde ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- bisoprolol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (98, 'A cardioselective beta blocker that slows the pulse and reduces the load on the heart. There are also combinations with a diuretic.', 'Kardioselektivni beta blokator koji usporava puls i smanjuje opterećenje srca. Postoje i kombinacije sa diuretikom.', 'Кардиоселективни бета блокатор који успорава пулс и смањује оптерећење срца. Постоје и комбинације са диуретиком.', 'Кардиоселективный бета-блокатор: урежает пульс и снижает нагрузку на сердце. Есть комбинации с мочегонным.', 'Ein kardioselektiver Betablocker, der den Puls verlangsamt und das Herz entlastet. Auch mit einem Diuretikum kombiniert.', 'Nabzı yavaşlatan ve kalbin yükünü azaltan kardiyoselektif bir beta blokerdir. İdrar söktürücüyle kombinasyonları da vardır.', 'Prescribed for high blood pressure, angina, heart rhythm disorders and chronic heart failure.', 'Propisuje se kod povišenog pritiska, angine pektoris, poremećaja srčanog ritma i hronične srčane slabosti.', 'Прописује се код повишеног притиска, ангине пекторис, поремећаја срчаног ритма и хроничне срчане слабости.', 'Назначают при повышенном давлении, стенокардии, нарушениях сердечного ритма и при хронической сердечной недостаточности.', 'Wird bei Bluthochdruck, Angina pectoris, Herzrhythmusstörungen und chronischer Herzschwäche verordnet.', 'Yüksek tansiyonda, anjina pektoriste, kalp ritim bozukluklarında ve kronik kalp yetmezliğinde reçete edilir.', 'Prescription only. It must not be stopped abruptly, as heart function can worsen. With asthma, a slow pulse or diabetes it needs particular care.', 'Izdaje se samo na recept. Nagli prekid nije dozvoljen jer rad srca može da se pogorša. Kod astme, sporog pulsa i dijabetesa potreban je poseban oprez.', 'Издаје се само на рецепт. Нагли прекид није дозвољен јер рад срца може да се погорша. Код астме, спорог пулса и дијабетеса потребан је посебан опрез.', 'Только по рецепту. Резко прекращать приём нельзя: работа сердца может ухудшиться. При астме, редком пульсе и диабете нужна особая осторожность.', 'Verschreibungspflichtig. Plötzliches Absetzen ist nicht erlaubt, die Herzfunktion kann sich verschlechtern. Bei Asthma, langsamem Puls und Diabetes besondere Vorsicht.', 'Yalnızca reçeteyle verilir. Aniden bırakılmaz, kalbin çalışması kötüleşebilir. Astım, yavaş nabız ve diyabette özel dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- bromheksin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (109, 'A mucolytic that makes mucus less viscous and easier to cough up.', 'Mukolitik koji smanjuje gustinu sekreta i olakšava iskašljavanje.', 'Муколитик који смањује густину секрета и олакшава искашљавање.', 'Муколитик: делает мокроту менее вязкой и облегчает откашливание.', 'Ein Schleimlöser, der zähen Schleim verflüssigt und das Abhusten erleichtert.', 'Balgamın koyuluğunu azaltıp atılmasını kolaylaştıran bir mukolitiktir.', 'Used for a cough with mucus that is hard to bring up in acute and chronic airway conditions.', 'Primjenjuje se kod kašlja sa sekretom koji se teško iskašljava, uz akutne i hronične bolesti disajnih puteva.', 'Примјењује се код кашља са секретом који се тешко искашљава, уз акутне и хроничне болести дисајних путева.', 'Применяют при кашле с трудноотделяемой мокротой на фоне острых и хронических болезней дыхательных путей.', 'Wird bei Husten mit zähem, schwer abzuhustendem Schleim bei akuten und chronischen Atemwegserkrankungen eingesetzt.', 'Akut ve kronik solunum yolu hastalıklarında güç çıkarılan balgamlı öksürükte kullanılır.', 'Available over the counter. It is not combined with cough suppressants. In asthma, ulcer disease and young children, only on a doctor''s advice.', 'Izdaje se bez recepta. Ne kombinuje se sa lijekovima koji potiskuju kašalj. Kod astme, čira i male djece samo po savjetu ljekara.', 'Издаје се без рецепта. Не комбинује се са лијековима који потискују кашаљ. Код астме, чира и мале дјеце само по савјету љекара.', 'Отпускается без рецепта. Не сочетают со средствами, подавляющими кашель. При астме, язве и у детей раннего возраста — по назначению врача.', 'Rezeptfrei erhältlich. Nicht zusammen mit hustenstillenden Mitteln. Bei Asthma, Magengeschwür und kleinen Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Öksürüğü baskılayan ilaçlarla birlikte kullanılmaz. Astım, ülser ve küçük çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- bršljan (hedera helix l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (110, 'Common ivy (Hedera helix) is a medicinal plant, and an expectorant extract is made from its leaves.', 'Bršljan je ljekovita biljka, a iz njegovog lista se dobija ekstrakt sa ekspektorantnim djelovanjem.', 'Бршљан је љековита биљка, а из његовог листа се добија екстракт са експекторантним дјеловањем.', 'Плющ обыкновенный (Hedera helix) — лекарственное растение, из листьев которого получают экстракт с отхаркивающим действием.', 'Efeu (Hedera helix) ist eine Heilpflanze, aus deren Blättern ein schleimlösender Extrakt gewonnen wird.', 'Sarmaşık (Hedera helix) tıbbi bir bitkidir, yapraklarından balgam söktürücü etkili ekstre elde edilir.', 'Used for coughs with thick mucus during colds and bronchitis.', 'Primjenjuje se kod kašlja sa gustim sekretom kod prehlade i bronhitisa.', 'Примјењује се код кашља са густим секретом код прехладе и бронхитиса.', 'Применяют при кашле с трудноотделяемой мокротой при простуде и бронхите.', 'Wird bei Husten mit zähem Schleim bei Erkältung und Bronchitis eingesetzt.', 'Soğuk algınlığı ve bronşitte koyu balgamlı öksürükte kullanılır.', 'Sold without prescription, and syrups may contain sorbitol or alcohol. A long-lasting cough, breathlessness or high fever needs a doctor, children only as advised.', 'Izdaje se bez recepta, a sirupi mogu sadržati sorbitol ili alkohol. Dugotrajan kašalj, nedostatak vazduha ili visoka temperatura traže ljekara, djeci po savjetu ljekara.', 'Издаје се без рецепта, а сирупи могу садржати сорбитол или алкохол. Дуготрајан кашаљ, недостатак ваздуха или висока температура траже љекара, дјеци по савјету љекара.', 'Отпускается без рецепта, сиропы могут содержать сорбит или спирт. При длительном кашле, одышке или высокой температуре нужен врач, детям — по его назначению.', 'Rezeptfrei, Säfte können Sorbit oder Alkohol enthalten. Anhaltender Husten, Atemnot oder hohes Fieber gehören ärztlich abgeklärt, bei Kindern nur nach Anweisung.', 'Reçetesiz satılır, şuruplar sorbitol veya alkol içerebilir. Uzun süren öksürük, nefes darlığı veya yüksek ateşte hekime gidilir, çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- budesonid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (112, 'An inhaled corticosteroid that reduces inflammation in the airways. There are single-substance products and combinations with airway-widening drugs.', 'Inhalacioni kortikosteroid koji smanjuje upalu u disajnim putevima. Postoje preparati sa jednom supstancom i kombinacije sa bronhodilatatorima.', 'Инхалациони кортикостероид који смањује упалу у дисајним путевима. Постоје препарати са једном супстанцом и комбинације са бронходилататорима.', 'Ингаляционный глюкокортикоид, снимающий воспаление в дыхательных путях. Есть препараты с одним веществом и комбинации с бронхорасширяющими.', 'Ein inhalatives Kortison, das Entzündungen in den Atemwegen dämpft. Es gibt Einzelpräparate und Kombinationen mit Bronchienerweiterern.', 'Solunum yollarındaki iltihabı azaltan inhale bir kortikosteroittir. Tek başına ve bronş genişleticilerle kombine preparatları vardır.', 'Used as maintenance treatment of asthma and COPD to reduce inflammation, attacks and the number of flare-ups.', 'Primjenjuje se kao osnovna terapija astme i HOBP, radi smanjenja upale, napada i broja pogoršanja.', 'Примјењује се као основна терапија астме и ХОБП, ради смањења упале, напада и броја погоршања.', 'Применяют как базисное лечение бронхиальной астмы и ХОБЛ, чтобы уменьшить воспаление, приступы и частоту обострений.', 'Wird als Basistherapie bei Asthma und COPD eingesetzt, um Entzündung, Anfälle und die Zahl der Verschlechterungen zu verringern.', 'Astım ve KOAH''ta temel tedavi olarak, iltihabı, atakları ve alevlenme sayısını azaltmak için kullanılır.', 'Prescription only. Rinsing the mouth after inhaling lowers the risk of thrush and hoarseness. Maintenance treatment must not be stopped on your own.', 'Izdaje se na recept. Ispiranje usta poslije inhalacije smanjuje rizik od gljivica i promuklosti. Osnovna terapija se ne prekida samostalno.', 'Издаје се на рецепт. Испирање уста послије инхалације смањује ризик од гљивица и промуклости. Основна терапија се не прекида самостално.', 'Отпускается по рецепту. Полоскание рта после ингаляции снижает риск молочницы и осиплости. Прекращать базисную терапию самостоятельно нельзя.', 'Verschreibungspflichtig. Mundspülen nach der Inhalation senkt das Risiko für Pilzbefall und Heiserkeit. Die Basistherapie nicht eigenmächtig absetzen.', 'Reçeteye tabidir. İnhalasyondan sonra ağzın çalkalanması pamukçuk ve ses kısıklığı riskini azaltır. Temel tedavi kendi başına bırakılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- butamirat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (118, 'A centrally acting cough suppressant that is not an opioid.', 'Lijek protiv kašlja sa centralnim djelovanjem koji ne spada u opioide.', 'Лијек против кашља са централним дјеловањем који не спада у опиоиде.', 'Противокашлевое вещество центрального действия, не относящееся к опиоидам.', 'Ein zentral wirkender Hustenstiller, der nicht zu den Opioiden gehört.', 'Opioid olmayan, merkezi etkili bir öksürük kesicidir.', 'Used for dry irritating cough, including before procedures on the airways.', 'Primjenjuje se kod suvog nadražajnog kašlja, i prije zahvata na disajnim putevima.', 'Примјењује се код сувог надражајног кашља, и прије захвата на дисајним путевима.', 'Применяют при сухом раздражающем кашле, в том числе перед процедурами на дыхательных путях.', 'Wird bei trockenem Reizhusten angewendet, auch vor Eingriffen an den Atemwegen.', 'Kuru ve tahriş edici öksürükte, ayrıca solunum yollarına yapılacak işlemler öncesinde kullanılır.', 'Not combined with medicines that thin mucus. Some forms are prescription only, for children and in pregnancy use is directed by a doctor.', 'Ne kombinuje se sa lijekovima koji razrjeđuju sekret. Pojedini oblici se izdaju na recept, djeci i u trudnoći po nalogu ljekara.', 'Не комбинује се са лијековима који разрјеђују секрет. Поједини облици се издају на рецепт, дјеци и у трудноћи по налогу љекара.', 'Не сочетают со средствами, разжижающими мокроту. Часть форм отпускается по рецепту, детям и беременным — по назначению врача.', 'Nicht mit schleimlösenden Mitteln kombinieren. Manche Formen sind verschreibungspflichtig, bei Kindern und in der Schwangerschaft nur auf ärztliche Anordnung.', 'Balgam söktürücülerle birlikte kullanılmaz. Bazı formları reçeteyle verilir, çocuklarda ve gebelikte doktor kararıyla kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- cetilpiridinijum
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (134, 'A local antiseptic from the quaternary ammonium group for the mouth and throat.', 'Lokalni antiseptik iz grupe kvaternarnih amonijumovih jedinjenja za usta i grlo.', 'Локални антисептик из групе кватернарних амонијумових једињења за уста и грло.', 'Местный антисептик из группы четвертичных аммониевых соединений для полости рта и горла.', 'Ein örtliches Antiseptikum aus der Gruppe der quartären Ammoniumverbindungen für Mund und Rachen.', 'Ağız ve boğaz için kuaterner amonyum bileşiklerinden yerel bir antiseptiktir.', 'Used for sore and scratchy throat and for inflammation of the mouth lining and gums, often together with a local anaesthetic.', 'Primjenjuje se kod bola i grebanja u grlu, upale sluznice usta i desni, često uz lokalni anestetik.', 'Примјењује се код бола и гребања у грлу, упале слузнице уста и десни, често уз локални анестетик.', 'Применяют при боли и першении в горле, воспалении слизистой рта и дёсен, часто вместе с местным обезболивающим.', 'Wird bei Halsschmerzen und Kratzen im Hals sowie bei Entzündungen von Mundschleimhaut und Zahnfleisch angewendet, oft mit einem Lokalanästhetikum.', 'Boğaz ağrısı ve gıcığında, ağız içi ve diş eti iltihabında, çoğu kez yerel bir ağrı kesiciyle birlikte kullanılır.', 'Over the counter. The action stays local: with high fever, coating on the tonsils or pain lasting several days, see a doctor.', 'Izdaje se bez recepta. Djelovanje je samo lokalno: uz visoku temperaturu, naslage i bol duži od nekoliko dana potreban je ljekar.', 'Издаје се без рецепта. Дјеловање је само локално: уз високу температуру, наслаге и бол дужи од неколико дана потребан је љекар.', 'Отпускается без рецепта. Действие только местное: при высокой температуре, налётах и боли дольше нескольких дней нужен врач.', 'Rezeptfrei. Die Wirkung bleibt örtlich: bei hohem Fieber, Belägen und Schmerzen über mehrere Tage zum Arzt.', 'Reçetesiz satılır. Etkisi yalnızca yereldir: yüksek ateş, bademciklerde plak veya birkaç günden uzun ağrıda doktora başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- cijanokobalamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (139, 'Vitamin B12 in the cyanocobalamin form, needed for blood formation and nerve function.', 'Vitamin B12 u obliku cijanokobalamina, potreban za stvaranje krvi i rad nervnog sistema.', 'Витамин B12 у облику цијанокобаламина, потребан за стварање крви и рад нервног система.', 'Витамин B12 в форме цианокобаламина, нужен для кроветворения и работы нервной системы.', 'Vitamin B12 in Form von Cyanocobalamin, nötig für die Blutbildung und die Nervenfunktion.', 'Siyanokobalamin formundaki B12 vitamini, kan yapımı ve sinir sisteminin çalışması için gereklidir.', 'Used for vitamin B12 deficiency and the anaemia it causes, in vegetarian diets, and in B-complex products for nerve problems.', 'Primjenjuje se kod nedostatka vitamina B12 i pripadajuće anemije, kod vegetarijanske ishrane i u preparatima B grupe kod tegoba sa nervima.', 'Примјењује се код недостатка витамина B12 и припадајуће анемије, код вегетаријанске исхране и у препаратима Б групе код тегоба са нервима.', 'Применяют при дефиците витамина B12 и связанной с ним анемии, при вегетарианском питании и в комплексах группы B при проблемах с нервами.', 'Wird bei Vitamin-B12-Mangel und der dadurch bedingten Anämie, bei vegetarischer Ernährung und in B-Komplex-Präparaten verwendet.', 'B12 vitamini eksikliğinde ve buna bağlı kansızlıkta, vejetaryen beslenmede ve sinir şikayetlerinde B grubu preparatlarda kullanılır.', 'Tablets are sold over the counter, injections are prescription only. The cause of deficiency must be found, so long-term use is directed by a doctor.', 'Tablete se izdaju bez recepta, injekcije na recept. Uzrok nedostatka treba utvrditi, pa dugotrajno uzimanje vodi ljekar.', 'Таблете се издају без рецепта, ињекције на рецепт. Узрок недостатка треба утврдити, па дуготрајно узимање води љекар.', 'Таблетки отпускаются без рецепта, инъекции — по назначению врача. Причину дефицита нужно выяснить, поэтому длительный приём ведёт врач.', 'Tabletten sind rezeptfrei, Injektionen verschreibungspflichtig. Die Ursache des Mangels muss geklärt werden, längere Einnahme begleitet der Arzt.', 'Tabletleri reçetesiz, iğneleri reçeteyle verilir. Eksikliğin nedeni araştırılmalıdır, uzun süreli kullanımı doktor yönetir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ciklesonid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (140, 'An inhaled corticosteroid that becomes active in the airways themselves.', 'Inhalacioni kortikosteroid koji postaje aktivan tek u disajnim putevima.', 'Инхалациони кортикостероид који постаје активан тек у дисајним путевима.', 'Ингаляционный глюкокортикоид, который становится активным уже в дыхательных путях.', 'Ein inhalatives Kortison, das erst in den Atemwegen aktiv wird.', 'Etkisi ancak solunum yollarında ortaya çıkan inhale bir kortikosteroittir.', 'Used as maintenance treatment of asthma: it reduces inflammation in the bronchi, attacks and the need for reliever inhalers.', 'Primjenjuje se kao osnovna terapija astme: smanjuje upalu u bronhijama, napade i potrebu za brzodjelujućim inhalatorima.', 'Примјењује се као основна терапија астме: смањује упалу у бронхијама, нападе и потребу за брзодјелујућим инхалаторима.', 'Применяют как базисное лечение бронхиальной астмы: уменьшает воспаление в бронхах, приступы и потребность в быстродействующих ингаляторах.', 'Wird als Basistherapie bei Asthma eingesetzt: Es mindert die Entzündung der Bronchien, Anfälle und den Bedarf an Notfallsprays.', 'Astımda temel tedavi olarak kullanılır: bronşlardaki iltihabı, atakları ve kurtarıcı inhaler ihtiyacını azaltır.', 'Prescription only. It does not relieve an attack that has already started. Oral thrush is less common, but rinsing the mouth after inhaling is still advised.', 'Izdaje se na recept. Ne prekida napad koji je već počeo. Gljivice u ustima su rjeđe, ali se usta poslije inhalacije ipak ispiraju.', 'Издаје се на рецепт. Не прекида напад који је већ почео. Гљивице у устима су рјеђе, али се уста послије инхалације ипак испирају.', 'Отпускается по рецепту. Начавшийся приступ им не снимают. Молочница во рту бывает реже, но рот после ингаляции всё равно прополаскивают.', 'Verschreibungspflichtig. Ein bereits begonnener Anfall lässt sich damit nicht lösen. Mundsoor ist seltener, Mundspülen nach der Inhalation bleibt sinnvoll.', 'Reçeteye tabidir. Başlamış bir atağı gidermez. Ağızda pamukçuk daha seyrek görülür, yine de inhalasyondan sonra ağız çalkalanır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- cinhokain
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (147, 'A local anaesthetic, in Montenegro used in haemorrhoid products together with a wound-healing agent.', 'Lokalni anestetik, u Crnoj Gori se koristi u preparatima za hemoroide zajedno sa sredstvom za zarastanje.', 'Локални анестетик, у Црној Гори се користи у препаратима за хемороиде заједно са средством за зарастање.', 'Местный анестетик, в Черногории применяется в средствах от геморроя вместе с ранозаживляющим веществом.', 'Ein örtliches Betäubungsmittel, in Montenegro in Mitteln gegen Hämorrhoiden mit einem wundheilenden Wirkstoff.', 'Bir lokal anestezik, Karadağ''da yara iyileştirici bir madde ile birlikte hemoroit ürünlerinde bulunur.', 'Used for pain, itching and burning caused by haemorrhoids and anal fissures.', 'Primjenjuje se kod bola, svraba i žarenja zbog hemoroida i analnih fisura.', 'Примјењује се код бола, свраба и жарења због хемороида и аналних фисура.', 'Применяют при боли, зуде и жжении, связанных с геморроем и трещинами заднего прохода.', 'Wird bei Schmerzen, Juckreiz und Brennen durch Hämorrhoiden und Analfissuren angewendet.', 'Hemoroit ve anal fissüre bağlı ağrı, kaşıntı ve yanmada kullanılır.', 'Available without prescription. Not for prolonged use without examination, bleeding during bowel movements needs to be checked. In pregnancy, on a doctor''s advice.', 'Izdaje se bez recepta. Ne koristi se dugo bez pregleda, krv pri pražnjenju crijeva zahtijeva ispitivanje. U trudnoći po savjetu ljekara.', 'Издаје се без рецепта. Не користи се дуго без прегледа, крв при пражњењу цријева захтијева испитивање. У трудноћи по савјету љекара.', 'Отпускается без рецепта. Долго применять без осмотра не следует, кровь при дефекации требует обследования. При беременности — по совету врача.', 'Rezeptfrei erhältlich. Nicht lange ohne Untersuchung anwenden, Blut beim Stuhlgang muss abgeklärt werden. In der Schwangerschaft nach ärztlichem Rat.', 'Reçetesiz satılır. Muayene olmadan uzun süre kullanılmaz, dışkılama sırasındaki kanama araştırılmalıdır. Gebelikte doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- crni sljez (malva sylvestris l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (156, 'Common mallow (Malva sylvestris), a medicinal plant whose flowers contain mucilage that soothes an irritated throat and dry cough.', 'Crni sljez (Malva sylvestris), ljekovita biljka čiji cvijet sadrži sluzi koje umiruju nadraženo grlo i suv kašalj.', 'Црни сљез (Malva sylvestris), љековита биљка чији цвијет садржи слузи које умирују надражено грло и сув кашаљ.', 'Мальва лесная (Malva sylvestris) — лекарственное растение, слизи из его цветков смягчают раздражённое горло и сухой кашель.', 'Wilde Malve (Malva sylvestris), eine Heilpflanze; die Schleimstoffe der Blüten beruhigen gereizten Hals und trockenen Reizhusten.', 'Ebegümeci (Malva sylvestris), çiçeklerindeki müsilaj ile tahriş olmuş boğazı ve kuru öksürüğü yatıştıran tıbbi bir bitkidir.', 'The flower extract is part of herbal cough syrups used for dry, irritating cough and a scratchy throat during colds.', 'Ekstrakt cvijeta ulazi u biljne sirupe protiv kašlja koji se primjenjuju kod suvog, nadražajnog kašlja i grebanja u grlu.', 'Екстракт цвијета улази у биљне сирупе против кашља који се примјењују код сувог, надражајног кашља и гребања у грлу.', 'Экстракт цветков входит в растительные сиропы от кашля, которые применяют при сухом раздражающем кашле и першении в горле при простуде.', 'Der Blütenextrakt steckt in pflanzlichen Hustensäften, die bei trockenem Reizhusten und Halskratzen im Rahmen einer Erkältung verwendet werden.', 'Çiçek ekstresi, soğuk algınlığında kuru ve tahriş edici öksürük ile boğaz kaşıntısında kullanılan bitkisel şuruplarda bulunur.', 'Available without prescription, and syrups may contain sugar or alcohol. A cough lasting over a week, fever or breathlessness needs a doctor; children, only as advised.', 'Izdaje se bez recepta, sirup može sadržati šećer ili alkohol. Kašalj duži od nedjelju dana, temperatura ili gušenje traže pregled, djeci po preporuci ljekara.', 'Издаје се без рецепта, сируп може садржати шећер или алкохол. Кашаљ дужи од недјељу дана, температура или гушење траже преглед, дјеци по препоруци љекара.', 'Отпускается без рецепта, сироп может содержать сахар или спирт. При кашле дольше недели, температуре или одышке нужен врач, детям — по его назначению.', 'Rezeptfrei, Säfte können Zucker oder Alkohol enthalten. Husten über eine Woche, Fieber oder Atemnot gehören zum Arzt, bei Kindern nur nach ärztlichem Rat.', 'Reçetesiz satılır, şurup şeker veya alkol içerebilir. Bir haftadan uzun öksürük, ateş veya nefes darlığında hekime gidilir; çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dabigatran eteksilat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (157, 'A direct anticoagulant that blocks thrombin and reduces blood clotting.', 'Direktni antikoagulans koji blokira trombin i smanjuje zgrušavanje krvi.', 'Директни антикоагуланс који блокира тромбин и смањује згрушавање крви.', 'Антикоагулянт прямого действия: блокирует тромбин и снижает свёртываемость крови.', 'Ein direkt wirkendes Antikoagulans, das Thrombin hemmt und die Blutgerinnung senkt.', 'Trombini bloke ederek kanın pıhtılaşmasını azaltan, doğrudan etkili bir antikoagülandır.', 'Used to prevent stroke in atrial fibrillation and for deep vein thrombosis and pulmonary embolism.', 'Primjenjuje se za prevenciju moždanog udara kod atrijalne fibrilacije, kod duboke venske tromboze i plućne embolije.', 'Примјењује се за превенцију можданог удара код атријалне фибрилације, код дубоке венске тромбозе и плућне емболије.', 'Применяют для профилактики инсульта при фибрилляции предсердий, при тромбозе глубоких вен и тромбоэмболии лёгочной артерии.', 'Wird zur Schlaganfallvorbeugung bei Vorhofflimmern sowie bei tiefer Venenthrombose und Lungenembolie eingesetzt.', 'Atriyal fibrilasyonda inmeden korunmada, derin ven trombozunda ve akciğer embolisinde kullanılır.', 'Prescription only. It raises bleeding risk and must not be stopped on your own. Bleeding and planned surgery are reported to a doctor. Care is needed with NSAIDs.', 'Izdaje se samo na recept. Povećava rizik od krvarenja, terapija se ne prekida samostalno. Krvarenja i planirane operacije javljaju se ljekaru. Oprez uz NSAIL.', 'Издаје се само на рецепт. Повећава ризик од крварења, терапија се не прекида самостално. Крварења и планиране операције јављају се љекару. Опрез уз NSAIL.', 'Только по рецепту. Повышает риск кровотечений, самостоятельная отмена опасна. О кровотечениях и предстоящих операциях сообщают врачу. С НПВС сочетают осторожно.', 'Verschreibungspflichtig. Erhöht das Blutungsrisiko, eigenmächtiges Absetzen ist gefährlich. Blutungen und geplante Eingriffe dem Arzt melden. Vorsicht mit NSAR.', 'Yalnızca reçeteyle verilir. Kanama riskini artırır, kendi başına bırakılmaz. Kanamalar ve planlanan ameliyatlar hekime bildirilir. NSAİİ ile birlikte dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dapagliflozin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (161, 'A glucose-lowering medicine from the SGLT2 inhibitor group that removes some glucose in the urine. Combinations with metformin exist.', 'Lijek za snižavanje šećera iz grupe SGLT2 inhibitora, izbacuje dio glukoze mokraćom. Postoje i kombinacije sa metforminom.', 'Лијек за снижавање шећера из групе SGLT2 инхибитора, избацује дио глукозе мокраћом. Постоје и комбинације са метформином.', 'Сахароснижающее средство из группы ингибиторов SGLT2, выводит часть глюкозы с мочой. Есть комбинации с метформином.', 'Ein Mittel zur Blutzuckersenkung aus der Gruppe der SGLT2-Hemmer, das Glukose über den Urin ausscheidet. Auch mit Metformin kombiniert.', 'SGLT2 inhibitörleri grubundan, glukozun bir kısmını idrarla atan kan şekeri düşürücü bir ilaçtır. Metforminli kombinasyonları vardır.', 'Used in type two diabetes and also in chronic heart failure and chronic kidney disease.', 'Primjenjuje se kod dijabetesa tipa dva, kao i kod hronične srčane slabosti i hronične bolesti bubrega.', 'Примјењује се код дијабетеса типа два, као и код хроничне срчане слабости и хроничне болести бубрега.', 'Применяют при диабете второго типа, а также при хронической сердечной недостаточности и хронической болезни почек.', 'Wird bei Typ-zwei-Diabetes sowie bei chronischer Herzschwäche und chronischer Nierenerkrankung eingesetzt.', 'Tip iki diyabette, ayrıca kronik kalp yetmezliği ve kronik böbrek hastalığında kullanılır.', 'Prescription only. It raises the risk of fungal and urinary infections and of dehydration. Not used in pregnancy. Signs of ketoacidosis need urgent medical care.', 'Izdaje se na recept. Povećava rizik od gljivičnih i mokraćnih infekcija i od dehidracije. U trudnoći se ne primjenjuje. Znaci ketoacidoze traže hitnu pomoć.', 'Издаје се на рецепт. Повећава ризик од гљивичних и мокраћних инфекција и од дехидрације. У трудноћи се не примјењује. Знаци кетоацидозе траже хитну помоћ.', 'Отпускается по рецепту. Повышает риск грибковых и мочевых инфекций и обезвоживания. При беременности не применяют. Признаки кетоацидоза требуют срочной помощи.', 'Verschreibungspflichtig. Es erhöht das Risiko für Pilz- und Harnwegsinfektionen sowie für Austrocknung. In der Schwangerschaft nicht anwenden. Zeichen einer Ketoazidose sind ein Notfall.', 'Yalnızca reçeteyle verilir. Mantar ve idrar yolu enfeksiyonu ile sıvı kaybı riskini artırır. Gebelikte kullanılmaz. Ketoasidoz belirtileri acil değerlendirme gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- deflazakort
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (169, 'A systemic glucocorticoid with anti-inflammatory and immune-suppressing action.', 'Sistemski glukokortikoid sa protivupalnim i imunosupresivnim djelovanjem.', 'Системски глукокортикоид са противупалним и имуносупресивним дјеловањем.', 'Системный глюкокортикоид с противовоспалительным и подавляющим иммунитет действием.', 'Ein systemisches Glukokortikoid mit entzündungshemmender und immundämpfender Wirkung.', 'İltihabı baskılayan ve bağışıklığı azaltan sistemik bir glukokortikoittir.', 'Prescribed for rheumatic, autoimmune and severe allergic diseases, and for certain muscle disorders.', 'Propisuje se kod reumatskih, autoimunih i teških alergijskih bolesti, kao i kod pojedinih bolesti mišića.', 'Прописује се код реуматских, аутоимуних и тешких алергијских болести, као и код појединих болести мишића.', 'Назначают при ревматических, аутоиммунных и тяжёлых аллергических заболеваниях, а также при некоторых болезнях мышц.', 'Wird bei rheumatischen, autoimmunen und schweren allergischen Erkrankungen sowie bei bestimmten Muskelerkrankungen verordnet.', 'Romatizmal, otoimmün ve ağır alerjik hastalıklarda, ayrıca bazı kas hastalıklarında reçete edilir.', 'Prescription only. Long use affects bones, weight, blood pressure and blood sugar. It must not be stopped abruptly, a doctor tapers it gradually.', 'Izdaje se samo na recept. Duga primjena utiče na kosti, težinu, pritisak i šećer u krvi. Nagli prekid nije dozvoljen, ukidanje ljekar vodi postepeno.', 'Издаје се само на рецепт. Дуга примјена утиче на кости, тежину, притисак и шећер у крви. Нагли прекид није дозвољен, укидање љекар води постепено.', 'Только по рецепту. Длительный приём влияет на кости, вес, давление и уровень сахара в крови. Резко прекращать нельзя, отмену врач проводит постепенно.', 'Verschreibungspflichtig. Längere Einnahme wirkt auf Knochen, Gewicht, Blutdruck und Blutzucker. Kein plötzliches Absetzen, der Arzt schleicht es aus.', 'Yalnızca reçeteyle verilir. Uzun kullanım kemikleri, kiloyu, tansiyonu ve kan şekerini etkiler. Aniden bırakılmaz, hekim kademeli olarak azaltır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- deksametazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (170, 'A corticosteroid with strong anti-inflammatory and anti-allergic action.', 'Kortikosteroid sa snažnim protivupalnim i antialergijskim djelovanjem.', 'Кортикостероид са снажним противупалним и антиалергијским дјеловањем.', 'Глюкокортикоид с сильным противовоспалительным и противоаллергическим действием.', 'Ein Kortikosteroid mit starker entzündungshemmender und antiallergischer Wirkung.', 'Güçlü iltihap ve alerji baskılayıcı etkisi olan bir kortikosteroittir.', 'Used in severe allergic and inflammatory conditions, autoimmune disease and swelling; the drops for inflammation of the eye and outer ear.', 'Primjenjuje se kod teških alergijskih i upalnih stanja, autoimunih bolesti i otoka, a kapi kod upale oka i spoljašnjeg uha.', 'Примјењује се код тешких алергијских и упалних стања, аутоимуних болести и отока, а капи код упале ока и спољашњег уха.', 'Применяют при тяжёлых аллергических и воспалительных состояниях, аутоиммунных болезнях и отёках, а капли — при воспалении глаз и наружного уха.', 'Wird bei schweren allergischen und entzündlichen Zuständen, Autoimmunkrankheiten und Schwellungen eingesetzt, Tropfen bei Augen- und Ohrentzündungen.', 'Ağır alerjik ve iltihabi durumlarda, otoimmün hastalıklarda ve ödemde; damlaları göz ve dış kulak iltihabında kullanılır.', 'Prescription only. Long use affects blood sugar, blood pressure, bones and immunity. Treatment must not be stopped on your own, the doctor adjusts it.', 'Izdaje se na recept. Duga primjena utiče na šećer u krvi, pritisak, kosti i imunitet. Terapija se ne prekida samostalno, nju mijenja ljekar.', 'Издаје се на рецепт. Дуга примјена утиче на шећер у крви, притисак, кости и имунитет. Терапија се не прекида самостално, њу мијења љекар.', 'Отпускается по рецепту. Длительный приём влияет на сахар крови, давление, кости и иммунитет. Прекращать лечение самостоятельно нельзя, схему меняет врач.', 'Verschreibungspflichtig. Längere Anwendung beeinflusst Blutzucker, Blutdruck, Knochen und Immunsystem. Nicht eigenmächtig absetzen, das regelt der Arzt.', 'Reçeteye tabidir. Uzun kullanım kan şekerini, tansiyonu, kemikleri ve bağışıklığı etkiler. Tedavi kendi başına bırakılmaz, hekim düzenler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dekslansoprazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (172, 'A medicine that reduces stomach acid production, from the proton pump inhibitor group.', 'Lijek koji smanjuje lučenje želudačne kiseline, iz grupe inhibitora protonske pumpe.', 'Лијек који смањује лучење желудачне киселине, из групе инхибитора протонске пумпе.', 'Средство, снижающее выработку кислоты в желудке, из группы ингибиторов протонной помпы.', 'Ein Mittel, das die Magensäureproduktion senkt, aus der Gruppe der Protonenpumpenhemmer.', 'Mide asidi salgısını azaltan, proton pompası inhibitörleri grubundan bir ilaçtır.', 'Used for gastro-oesophageal reflux disease, erosive oesophagitis and persistent heartburn.', 'Primjenjuje se kod refluksne bolesti jednjaka, erozivnog ezofagitisa i uporne gorušice.', 'Примјењује се код рефлуксне болести једњака, ерозивног езофагитиса и упорне горушице.', 'Применяют при гастроэзофагеальной рефлюксной болезни, эрозивном эзофагите и стойкой изжоге.', 'Wird bei Refluxkrankheit, erosiver Speiseröhrenentzündung und anhaltendem Sodbrennen eingesetzt.', 'Reflü hastalığında, eroziv yemek borusu iltihabında ve inatçı mide yanmasında kullanılır.', 'Prescription only. Long-term use is supervised by a doctor because it affects absorption of vitamin B12, magnesium and calcium. It can mask symptoms of other conditions.', 'Izdaje se na recept. Dugotrajna primjena ide uz nadzor ljekara zbog uticaja na usvajanje vitamina B12, magnezijuma i kalcijuma. Može prikriti simptome drugih bolesti.', 'Издаје се на рецепт. Дуготрајна примјена иде уз надзор љекара због утицаја на усвајање витамина B12, магнезијума и калцијума. Може прикрити симптоме других болести.', 'Отпускается по рецепту. Длительный приём — под наблюдением врача из-за влияния на усвоение витамина B12, магния и кальция. Может маскировать симптомы других болезней.', 'Verschreibungspflichtig. Eine Langzeitanwendung erfolgt unter ärztlicher Kontrolle, da sie die Aufnahme von Vitamin B12, Magnesium und Kalzium beeinflusst. Sie kann Symptome verdecken.', 'Yalnızca reçeteyle verilir. B12 vitamini, magnezyum ve kalsiyum emilimini etkilediği için uzun süreli kullanım hekim gözetiminde olur. Başka hastalıkların belirtilerini gizleyebilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dekspantenol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (174, 'Provitamin B5 that supports the repair of skin and mucous membranes.', 'Provitamin B5 koji podržava obnavljanje kože i sluznica.', 'Провитамин B5 који подржава обнављање коже и слузница.', 'Провитамин B5: поддерживает восстановление кожи и слизистых.', 'Provitamin B5, das die Regeneration von Haut und Schleimhäuten unterstützt.', 'Deri ve mukozaların onarımını destekleyen B5 provitaminidir.', 'Applied to dry, irritated or slightly damaged skin; nasal forms for a dry nose. It is also an ingredient of children''s vitamins.', 'Spolja se primjenjuje kod suve i nadražene kože i manjih oštećenja, nazalni oblici kod suvoće u nosu, ulazi i u dječje vitamine.', 'Споља се примјењује код суве и надражене коже и мањих оштећења, назални облици код сувоће у носу, улази и у дјечје витамине.', 'Наружно применяют при сухости, раздражении и мелких повреждениях кожи, назальные формы — при сухости в носу; входит в детские витамины.', 'Wird äußerlich bei trockener, gereizter und leicht verletzter Haut angewendet, Nasenformen bei trockener Nase, es steckt auch in Kindervitaminen.', 'Kuru, tahriş olmuş ve hafif zedelenmiş deride, burun formları burun kuruluğunda kullanılır, çocuk vitaminlerinde de bulunur.', 'Available over the counter and usually well tolerated. Irritation and allergic reactions are possible. On deep or weeping wounds, only on a doctor''s advice.', 'Izdaje se bez recepta i obično se dobro podnosi. Mogući su nadražaj i alergijske reakcije. Na duboke i vlažne rane nanosi se samo po savjetu ljekara.', 'Издаје се без рецепта и обично се добро подноси. Могући су надражај и алергијске реакције. На дубоке и влажне ране наноси се само по савјету љекара.', 'Отпускается без рецепта и обычно хорошо переносится. Возможны раздражение и аллергические реакции. На глубокие и мокнущие раны наносят по назначению врача.', 'Rezeptfrei und meist gut verträglich. Reizungen und allergische Reaktionen sind möglich. Auf tiefe oder nässende Wunden nur nach ärztlicher Anweisung.', 'Reçetesiz satılır ve genellikle iyi tolere edilir. Tahriş ve alerjik tepki görülebilir. Derin ve sızıntılı yaralara yalnızca hekim önerisiyle sürülür.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dekstrometorfan
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (175, 'A centrally acting cough suppressant that damps the cough reflex. In Montenegro it comes as part of combined cold remedies.', 'Lijek protiv kašlja sa centralnim djelovanjem koji potiskuje refleks kašlja. U Crnoj Gori dolazi u kombinovanim preparatima protiv prehlade.', 'Лијек против кашља са централним дјеловањем који потискује рефлекс кашља. У Црној Гори долази у комбинованим препаратима против прехладе.', 'Противокашлевое средство центрального действия: подавляет кашлевой рефлекс. В Черногории входит в комбинированные средства от простуды.', 'Ein zentral wirkendes Hustenmittel, das den Hustenreiz dämpft. In Montenegro ist es Bestandteil von Kombipräparaten gegen Erkältung.', 'Öksürük refleksini baskılayan, merkezi etkili bir öksürük kesicidir. Karadağ''da soğuk algınlığı kombinasyonlarının içinde bulunur.', 'Used for a dry, hacking cough without mucus during colds and flu, usually alongside a fever-reducing component.', 'Primjenjuje se kod suvog, nadražajnog kašlja bez sekreta uz prehladu i grip, obično uz komponentu protiv temperature.', 'Примјењује се код сувог, надражајног кашља без секрета уз прехладу и грип, обично уз компоненту против температуре.', 'Применяют при сухом надсадном кашле без мокроты при простуде и гриппе, обычно вместе с жаропонижающим компонентом.', 'Wird bei trockenem Reizhusten ohne Schleim bei Erkältung und Grippe angewendet, meist zusammen mit einem fiebersenkenden Wirkstoff.', 'Soğuk algınlığı ve gripte balgamsız, kuru ve rahatsız edici öksürükte, genellikle ateş düşürücü bileşenle birlikte kullanılır.', 'Combined forms are over the counter but contain paracetamol, so doses add up. Not combined with mucolytics or antidepressants; in children only as advised.', 'Kombinovani oblici su bez recepta, ali sadrže paracetamol, pa se doze lako saberu. Ne kombinuje se sa mukoliticima i antidepresivima, djeci po savjetu ljekara.', 'Комбиновани облици су без рецепта, али садрже парацетамол, па се дозе лако саберу. Не комбинује се са муколитицима и антидепресивима, дјеци по савјету љекара.', 'Комбинированные формы безрецептурные, но содержат парацетамол, дозы легко сложить. Не сочетают с муколитиками и антидепрессантами, детям — по назначению врача.', 'Die Kombipräparate sind rezeptfrei, enthalten aber Paracetamol, Dosen summieren sich. Nicht mit Schleimlösern und Antidepressiva, bei Kindern nur nach Anweisung.', 'Kombine formları reçetesizdir ancak parasetamol içerir, dozlar toplanabilir. Mukolitik ve antidepresanlarla kullanılmaz, çocuklarda hekim önerisiyle verilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- desloratadin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (178, 'A second-generation antihistamine, the active metabolite of loratadine. It rarely causes drowsiness.', 'Antihistaminik druge generacije, aktivni metabolit loratadina. Rjeđe izaziva pospanost.', 'Антихистаминик друге генерације, активни метаболит лоратадина. Рјеђе изазива поспаност.', 'Антигистаминное средство второго поколения, активный метаболит лоратадина. Реже вызывает сонливость.', 'Ein Antihistaminikum der zweiten Generation, der aktive Metabolit von Loratadin. Es macht selten müde.', 'Loratadinin etkin metaboliti olan ikinci kuşak bir antihistaminiktir. Nadiren uyku hali yapar.', 'Used for seasonal and year-round allergic rhinitis, and for hives with itching and rash.', 'Primjenjuje se kod sezonskog i cjelogodišnjeg alergijskog rinitisa, kao i kod koprivnjače sa svrabom i osipom.', 'Примјењује се код сезонског и цјелогодишњег алергијског ринитиса, као и код копривњаче са сврабом и осипом.', 'Применяют при сезонном и круглогодичном аллергическом рините, а также при крапивнице с зудом и высыпаниями.', 'Wird bei saisonalem und ganzjährigem allergischem Schnupfen sowie bei Nesselsucht mit Juckreiz und Ausschlag angewendet.', 'Mevsimsel ve yıl boyu süren alerjik nezlede, kaşıntı ve döküntüyle seyreden kurdeşende kullanılır.', 'In Montenegro it is prescription only. With kidney or liver disease, in pregnancy and breastfeeding and in children, only on a doctor''s advice.', 'U Crnoj Gori se izdaje na recept. Kod bolesti bubrega i jetre, u trudnoći i dojenju i kod djece samo po savjetu ljekara.', 'У Црној Гори се издаје на рецепт. Код болести бубрега и јетре, у трудноћи и дојењу и код дјеце само по савјету љекара.', 'В Черногории отпускается по рецепту. При болезнях почек и печени, беременности, кормлении грудью и у детей — только по назначению врача.', 'In Montenegro verschreibungspflichtig. Bei Nieren- und Lebererkrankungen, in Schwangerschaft und Stillzeit und bei Kindern nur nach ärztlicher Anweisung.', 'Karadağ''da reçeteye tabidir. Böbrek ve karaciğer hastalığında, gebelik ve emzirme döneminde ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- diklofenak
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (184, 'Diclofenac is a non-steroidal anti-inflammatory drug with strong anti-inflammatory and painkilling action.', 'Diklofenak je nesteroidni antiinflamatorni lijek (NSAIL) sa izraženim protivupalnim i analgetskim djelovanjem.', 'Диклофенак је нестероидни антиинфламаторни лијек (NSAIL) са израженим противупалним и аналгетским дјеловањем.', 'Диклофенак — нестероидное противовоспалительное средство с выраженным противовоспалительным и обезболивающим действием.', 'Diclofenac ist ein nichtsteroidales Antirheumatikum (NSAR) mit starker entzündungshemmender und schmerzstillender Wirkung.', 'Diklofenak, güçlü antiinflamatuar ve ağrı kesici etkili, steroid olmayan bir ilaçtır.', 'Used for pain and inflammation in joints and muscles, after injuries and sprains, and in ophthalmology after eye procedures.', 'Primjenjuje se kod bolova i upale u zglobovima i mišićima, kod povreda i uganuća, te u oftalmologiji nakon zahvata na oku.', 'Примјењује се код болова и упале у зглобовима и мишићима, код повреда и уганућа, те у офталмологији након захвата на оку.', 'Применяют при боли и воспалении в суставах и мышцах, при травмах и растяжениях, а также в офтальмологии после вмешательств на глазу.', 'Wird bei Schmerzen und Entzündungen in Gelenken und Muskeln, nach Verletzungen und Verstauchungen sowie augenärztlich nach Eingriffen eingesetzt.', 'Eklem ve kas ağrısı ile iltihabında, yaralanma ve burkulmalarda, ayrıca göz ameliyatları sonrasında kullanılır.', 'Systemic forms irritate the stomach and affect the heart and kidneys, and most are prescription-only. Contraindicated in the third trimester, for children only as prescribed.', 'Sistemski oblici nadražuju želudac i utiču na srce i bubrege, većina se izdaje na recept. U trećem trimestru trudnoće je kontraindikovan, djeci samo po savjetu ljekara.', 'Системски облици надражују желудац и утичу на срце и бубреге, већина се издаје на рецепт. У трећем триместру трудноће је контраиндикован, дјеци само по савјету љекара.', 'Системные формы раздражают желудок и влияют на сердце и почки, большинство из них рецептурные. В третьем триместре беременности противопоказан, детям — по назначению врача.', 'Systemische Formen reizen den Magen und belasten Herz und Nieren, die meisten sind verschreibungspflichtig. Im letzten Schwangerschaftsdrittel kontraindiziert, Kinder nur ärztlich.', 'Sistemik formlar mideyi tahriş eder, kalp ve böbrekleri etkiler, çoğu reçeteye tabidir. Gebeliğin son üç ayında kontrendikedir, çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dimenhidrinat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (186, 'A first-generation antihistamine with an anti-nausea effect.', 'Antihistaminik prve generacije sa djelovanjem protiv mučnine.', 'Антихистаминик прве генерације са дјеловањем против мучнине.', 'Антигистаминное вещество первого поколения с противорвотным действием.', 'Ein Antihistaminikum der ersten Generation mit Wirkung gegen Übelkeit.', 'Bulantıya karşı etkisi olan birinci kuşak bir antihistaminiktir.', 'Used for motion sickness, nausea and vomiting, and for vertigo caused by inner ear disorders.', 'Primjenjuje se kod bolesti putovanja, mučnine i povraćanja, kao i kod vrtoglavice zbog poremećaja unutrašnjeg uha.', 'Примјењује се код болести путовања, мучнине и повраћања, као и код вртоглавице због поремећаја унутрашњег уха.', 'Применяют при укачивании в транспорте, тошноте и рвоте, а также при головокружении из-за нарушений внутреннего уха.', 'Wird bei Reisekrankheit, Übelkeit und Erbrechen sowie bei Schwindel durch Störungen des Innenohrs angewendet.', 'Taşıt tutmasında, bulantı ve kusmada, ayrıca iç kulak kaynaklı baş dönmesinde kullanılır.', 'Causes drowsiness and reduces attention, does not go with alcohol. For children, in pregnancy and for drivers only on a doctor''s advice.', 'Izaziva pospanost i smanjuje pažnju, ne kombinuje se sa alkoholom. Djeci, trudnicama i vozačima samo po savjetu ljekara.', 'Изазива поспаност и смањује пажњу, не комбинује се са алкохолом. Дјеци, трудницама и возачима само по савјету љекара.', 'Вызывает сонливость и снижает внимание, не сочетается с алкоголем. Детям, беременным и водителям — только по назначению врача.', 'Macht müde und beeinträchtigt die Aufmerksamkeit, nicht mit Alkohol. Für Kinder, Schwangere und Autofahrer nur nach ärztlichem Rat.', 'Uykuya ve dikkat azalmasına yol açar, alkolle birlikte kullanılmaz. Çocuklarda, gebelikte ve araç kullananlarda yalnızca doktor önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dimetilsulfoksid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (189, 'A substance for external use that penetrates the skin, reduces inflammation and helps other gel ingredients get through.', 'Supstanca za spoljnu primjenu koja prolazi kroz kožu, smanjuje upalu i pomaže drugim sastojcima gela da prodru u tkivo.', 'Супстанца за спољну примјену која пролази кроз кожу, смањује упалу и помаже другим састојцима гела да продру у ткиво.', 'Вещество для наружного применения: проникает через кожу, уменьшает воспаление и помогает другим компонентам геля пройти в ткани.', 'Ein Stoff zur äußeren Anwendung, der in die Haut eindringt, Entzündungen mindert und andere Gelbestandteile mitnimmt.', 'Deriden geçen, iltihabı azaltan ve jeldeki diğer bileşenlerin dokuya ulaşmasına yardımcı olan, dıştan kullanılan bir maddedir.', 'As part of combined gels it is used for bruises, swelling, muscle and joint pain and for heavy legs.', 'U sklopu kombinovanih gelova primjenjuje se kod nagnječenja, otoka, bolova u mišićima i zglobovima i kod teških nogu.', 'У склопу комбинованих гелова примјењује се код нагњечења, отока, болова у мишићима и зглобовима и код тешких ногу.', 'В составе комбинированных гелей применяют при ушибах, отёках, боли в мышцах и суставах и при тяжести в ногах.', 'In Kombinationsgelen wird er bei Prellungen, Schwellungen, Muskel- und Gelenkschmerzen sowie bei schweren Beinen verwendet.', 'Kombine jellerin içinde berelenme, şişlik, kas ve eklem ağrısı ile bacak ağırlığında kullanılır.', 'It is part of over-the-counter gels. Skin irritation and a peculiar taste or odour are possible. Not applied to wounds or mucous membranes, in pregnancy ask a doctor.', 'Ulazi u gelove koji se izdaju bez recepta. Mogući su nadražaj kože i specifičan ukus ili miris. Ne nanosi se na rane i sluznice, u trudnoći po savjetu ljekara.', 'Улази у гелове који се издају без рецепта. Могући су надражај коже и специфичан укус или мирис. Не наноси се на ране и слузнице, у трудноћи по савјету љекара.', 'Входит в безрецептурные гели. Возможны раздражение кожи и специфический привкус или запах. На раны и слизистые не наносят, при беременности — по назначению врача.', 'Er steckt in rezeptfreien Gelen. Hautreizungen und ein eigenartiger Geschmack oder Geruch sind möglich. Nicht auf Wunden, in der Schwangerschaft zum Arzt.', 'Reçetesiz jellerin bileşeninde bulunur. Deride tahriş ve tuhaf bir tat ya da koku olabilir. Yara ve mukozaya sürülmez, gebelikte hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- dimetinden
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (190, 'An antihistamine applied externally to the skin.', 'Antihistaminik za spoljnu primjenu na kožu.', 'Антихистаминик за спољну примјену на кожу.', 'Антигистаминное вещество для наружного применения на кожу.', 'Ein Antihistaminikum zur äußerlichen Anwendung auf der Haut.', 'Cilde dıştan uygulanan bir antihistaminiktir.', 'Used for itching after insect bites, for hives, and for mild sunburn and minor skin burns.', 'Primjenjuje se kod svraba poslije uboda insekata, kod koprivnjače, blagih opekotina od sunca i lakših opekotina kože.', 'Примјењује се код свраба послије убода инсеката, код копривњаче, благих опекотина од сунца и лакших опекотина коже.', 'Применяют при зуде после укусов насекомых, при крапивнице, лёгких солнечных и бытовых ожогах кожи.', 'Wird bei Juckreiz nach Insektenstichen, bei Nesselsucht sowie bei leichtem Sonnenbrand und kleinen Verbrennungen angewendet.', 'Böcek ısırığı sonrası kaşıntıda, kurdeşende, hafif güneş yanığı ve küçük cilt yanıklarında kullanılır.', 'Over the counter. Treated skin should be kept out of the sun. Not for large areas or broken skin; for infants, only on a doctor''s advice.', 'Izdaje se bez recepta. Namazana mjesta ne izlagati suncu. Ne nanosi se na velike površine i oštećenu kožu; kod odojčadi samo po savjetu ljekara.', 'Издаје се без рецепта. Намазана мјеста не излагати сунцу. Не наноси се на велике површине и оштећену кожу; код одојчади само по савјету љекара.', 'Отпускается без рецепта. Обработанные участки не подставляют солнцу. Не наносят на большие площади и повреждённую кожу; у грудных детей — по назначению врача.', 'Rezeptfrei. Behandelte Stellen nicht der Sonne aussetzen. Nicht auf große Flächen oder verletzte Haut; bei Säuglingen nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Sürülen bölge güneşe maruz bırakılmaz. Geniş alanlara ve yaralı cilde uygulanmaz; bebeklerde hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- diosmektit
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (191, 'Diosmectite is a natural clay adsorbent taken by mouth', 'Diosmektit je prirodni glineni adsorbens za oralnu primjenu', 'Диосмектит је природни глинени адсорбенс за оралну примјену', 'Диосмектит — природный глинистый адсорбент для приёма внутрь', 'Diosmektit ist ein natürliches Tonmineral als Adsorbens zum Einnehmen', 'Diyosmektit ağızdan alınan doğal kil kaynaklı bir adsorbandır', 'Acute and prolonged diarrhoea, discomfort and bloating in intestinal upsets, including in children', 'Akutna i produžena dijareja, nelagoda i nadutost kod crijevnih tegoba, uključujući i kod djece', 'Акутна и продужена дијареја, нелагода и надутост код цријевних тегоба, укључујући и код дјеце', 'Острая и затяжная диарея, дискомфорт и вздутие при кишечных расстройствах, в том числе у детей', 'Akuter und länger anhaltender Durchfall, Unwohlsein und Blähungen bei Darmbeschwerden, auch bei Kindern', 'Akut ve uzamış ishal, bağırsak şikayetlerinde rahatsızlık ve şişkinlik, çocuklarda da kullanılır', 'It reduces the absorption of other medicines taken at the same time. Fluid replacement is the mainstay in diarrhoea; with blood in stool, high fever or in young children see a doctor.', 'Smanjuje apsorpciju drugih lijekova uzetih istovremeno. Kod proliva je najvažnija nadoknada tečnosti; kod krvi u stolici, visoke temperature i kod male djece obratiti se ljekaru.', 'Смањује апсорпцију других лијекова узетих истовремено. Код пролива је најважнија надокнада течности; код крви у столици, високе температуре и код мале дјеце обратити се љекару.', 'Снижает всасывание других лекарств, принятых одновременно. Основа помощи при диарее — восполнение жидкости; при крови в стуле, высокой температуре и у малышей — к врачу.', 'Vermindert die Aufnahme gleichzeitig eingenommener Arzneimittel. Bei Durchfall steht der Flüssigkeitsersatz im Vordergrund; bei Blut im Stuhl, hohem Fieber und bei Kleinkindern zum Arzt.', 'Aynı anda alınan diğer ilaçların emilimini azaltır. İshalde en önemlisi sıvı kaybının yerine konmasıdır; dışkıda kan, yüksek ateş ve küçük çocuklarda hekime başvurun.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- diosmin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (192, 'Diosmin is a plant flavonoid that acts as a venotonic and protects the walls of the veins.', 'Diosmin je biljni flavonoid koji djeluje kao venotonik i štiti zidove vena.', 'Диосмин је биљни флавоноид који дјелује као венотоник и штити зидове вена.', 'Диосмин — растительный флавоноид, венотонизирующее средство, которое поддерживает тонус вен и защищает их стенки.', 'Diosmin ist ein pflanzliches Flavonoid, das als Venenmittel wirkt und die Venenwand schützt.', 'Diosmin, damar tonusunu artıran ve toplardamar duvarını koruyan bitkisel bir flavonoiddir.', 'Used for chronic venous insufficiency of the legs — heaviness, swelling and pain — and during haemorrhoid flare-ups.', 'Primjenjuje se kod hronične venske insuficijencije nogu — težina, otok i bol — i kod pogoršanja hemoroida.', 'Примјењује се код хроничне венске инсуфицијенције ногу — тежина, оток и бол — и код погоршања хемороида.', 'Применяют при хронической венозной недостаточности ног — тяжести, отёках и боли, а также при обострении геморроя.', 'Wird bei chronischer Venenschwäche der Beine — Schweregefühl, Schwellung, Schmerzen — und bei Hämorrhoidalbeschwerden angewendet.', 'Bacaklarda kronik venöz yetmezlikte — ağırlık hissi, şişlik, ağrı — ve hemoroit alevlenmelerinde kullanılır.', 'Sold without prescription, but persistent swelling, pain or bleeding needs medical assessment. In pregnancy and breastfeeding only as prescribed by a doctor.', 'Izdaje se bez recepta, ali uporan otok, bol ili krvarenje zahtijevaju pregled ljekara. U trudnoći i tokom dojenja samo po savjetu ljekara.', 'Издаје се без рецепта, али упоран оток, бол или крварење захтијевају преглед љекара. У трудноћи и током дојења само по савјету љекара.', 'Отпускается без рецепта, но стойкие отёки, боль или кровотечение требуют осмотра врача. При беременности и кормлении — только по назначению врача.', 'Rezeptfrei erhältlich, doch anhaltende Schwellung, Schmerzen oder Blutungen gehören ärztlich abgeklärt. In Schwangerschaft und Stillzeit nur nach ärztlicher Anweisung.', 'Reçetesiz satılır, ancak geçmeyen şişlik, ağrı veya kanamada hekime başvurulmalıdır. Gebelikte ve emzirme döneminde yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- divlji renac (iberis amara l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (194, 'An extract of bitter candytuft, a herbal component of a combined tincture for the stomach and gut.', 'Ekstrakt divljeg renca, biljni sastojak kombinovane tinkture za želudac i crijeva.', 'Екстракт дивљег ренца, биљни састојак комбиноване тинктуре за желудац и цријева.', 'Экстракт горькой иберийки, растительный компонент комбинированной настойки для желудка и кишечника.', 'Ein Extrakt der Bitteren Schleifenblume, pflanzlicher Bestandteil einer kombinierten Tinktur für Magen und Darm.', 'Acı kandil çiçeği ekstresidir, mide ve bağırsak için hazırlanan bitkisel kombine tentürün bileşenidir.', 'Used as part of a herbal remedy for functional dyspepsia and irritable bowel syndrome: heaviness after meals, bloating and cramps.', 'Primjenjuje se u sastavu biljnog preparata kod funkcionalne dispepsije i sindroma iritabilnog crijeva: težine poslije jela, nadutosti i grčeva.', 'Примјењује се у саставу биљног препарата код функционалне диспепсије и синдрома иритабилног цријева: тежине послије јела, надутости и грчева.', 'Применяют в составе растительного средства при функциональной диспепсии и синдроме раздражённого кишечника: тяжести после еды, вздутии, спазмах.', 'Wird als Teil eines pflanzlichen Mittels bei funktioneller Dyspepsie und Reizdarm eingesetzt: Völlegefühl nach dem Essen, Blähungen, Krämpfe.', 'Bitkisel preparatın parçası olarak fonksiyonel dispepside ve huzursuz bağırsak sendromunda, yemek sonrası dolgunluk, şişkinlik ve krampta kullanılır.', 'Over the counter, the tincture contains alcohol. Rare liver reactions have been reported. Lasting symptoms, blood in the stool or weight loss need a doctor.', 'Izdaje se bez recepta, tinktura sadrži alkohol. Opisane su rijetke reakcije jetre. Uporne tegobe, krv u stolici i gubitak težine traže ljekara.', 'Издаје се без рецепта, тинктура садржи алкохол. Описане су ријетке реакције јетре. Упорне тегобе, крв у столици и губитак тежине траже љекара.', 'Отпускается без рецепта, настойка содержит спирт. Описаны редкие поражения печени. При стойких жалобах, крови в стуле и потере веса нужен врач.', 'Rezeptfrei, die Tinktur enthält Alkohol. Selten wurden Leberreaktionen berichtet. Anhaltende Beschwerden, Blut im Stuhl und Gewichtsverlust gehören zum Arzt.', 'Reçetesiz satılır, tentür alkol içerir. Nadiren karaciğer reaksiyonları bildirilmiştir. Geçmeyen şikayet, dışkıda kan ve kilo kaybı hekim gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- drospirenon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (205, 'A progestogen, a synthetic analogue of progesterone used in hormonal contraceptives, with a mild diuretic effect.', 'Gestagen, sintetski analog progesterona koji ulazi u hormonske kontraceptive, ima blago diuretsko dejstvo.', 'Гестаген, синтетски аналог прогестерона који улази у хормонске контрацептиве, има благо диуретско дејство.', 'Гестаген, синтетический аналог прогестерона, компонент гормональных контрацептивов, обладает слабым мочегонным действием.', 'Ein Gestagen, ein synthetisches Progesteron-Analogon in hormonellen Verhütungsmitteln, mit leicht entwässernder Wirkung.', 'Hormonal doğum kontrol haplarında bulunan, progesteronun sentetik benzeri bir progestajendir, hafif idrar söktürücü etkisi vardır.', 'Used as part of contraceptives, and for marked premenstrual syndrome when a doctor decides so.', 'Primjenjuje se u sastavu kontraceptiva, a po odluci ljekara i kod izraženog predmenstrualnog sindroma.', 'Примјењује се у саставу контрацептива, а по одлуци љекара и код израженог предменструалног синдрома.', 'Применяют в составе противозачаточных средств, а по решению врача — при выраженном предменструальном синдроме.', 'Wird als Bestandteil von Verhütungsmitteln und nach ärztlicher Entscheidung bei ausgeprägtem prämenstruellem Syndrom eingesetzt.', 'Doğum kontrol haplarının bileşeni olarak, hekim kararıyla belirgin adet öncesi sendromda da kullanılır.', 'Prescription only. It can raise potassium levels, so it is used with care in kidney, liver and adrenal disease. Follow-up is done by a gynaecologist.', 'Izdaje se samo na recept. Može zadržavati kalijum, pa se kod bolesti bubrega, jetre i nadbubrežne žlijezde daje uz oprez. Kontrole vodi ginekolog.', 'Издаје се само на рецепт. Може задржавати калијум, па се код болести бубрега, јетре и надбубрежне жлијезде даје уз опрез. Контроле води гинеколог.', 'Только по рецепту. Может задерживать калий, поэтому при болезнях почек, печени и надпочечников назначается с осторожностью. Наблюдение ведёт гинеколог.', 'Verschreibungspflichtig. Kann den Kaliumspiegel erhöhen, daher Vorsicht bei Nieren-, Leber- und Nebennierenerkrankungen. Die Kontrolle übernimmt der Arzt.', 'Yalnızca reçeteyle verilir. Potasyumu tutabildiği için böbrek, karaciğer ve böbrek üstü bezi hastalıklarında dikkatle verilir. Takibi hekim yapar.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- empagliflozin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (218, 'A glucose-lowering SGLT2 inhibitor that makes the kidneys remove more glucose with urine. Also comes combined with metformin.', 'Lijek za snižavanje šećera, SGLT2 inhibitor koji pojačava izlučivanje glukoze mokraćom. Postoje i kombinacije sa metforminom.', 'Лијек за снижавање шећера, SGLT2 инхибитор који појачава излучивање глукозе мокраћом. Постоје и комбинације са метформином.', 'Сахароснижающее средство, ингибитор SGLT2: усиливает выведение глюкозы с мочой. Есть комбинации с метформином.', 'Ein blutzuckersenkender SGLT2-Hemmer, der die Ausscheidung von Glukose über den Urin steigert. Auch als Kombination mit Metformin.', 'Böbreklerden glukoz atılımını artıran, kan şekerini düşüren bir SGLT2 inhibitörüdür. Metforminli kombinasyonları da vardır.', 'Used in type 2 diabetes and also in chronic heart failure and chronic kidney disease.', 'Primjenjuje se kod dijabetesa tipa 2, kao i kod hronične srčane slabosti i hronične bolesti bubrega.', 'Примјењује се код дијабетеса типа 2, као и код хроничне срчане слабости и хроничне болести бубрега.', 'Применяют при сахарном диабете 2 типа, а также при хронической сердечной недостаточности и хронической болезни почек.', 'Wird bei Typ-2-Diabetes sowie bei chronischer Herzschwäche und chronischer Nierenkrankheit eingesetzt.', 'Tip 2 diyabette, ayrıca kronik kalp yetmezliği ve kronik böbrek hastalığında kullanılır.', 'Prescription only. It increases urine output, so dehydration and genital fungal infections are possible. During acute illness or surgery a doctor adjusts treatment.', 'Izdaje se samo na recept. Povećava količinu mokraće, mogući su dehidracija i gljivične infekcije genitalija. Kod akutnih bolesti i operacija terapiju mijenja ljekar.', 'Издаје се само на рецепт. Повећава количину мокраће, могући су дехидрација и гљивичне инфекције гениталија. Код акутних болести и операција терапију мијења љекар.', 'Только по рецепту. Увеличивает объём мочи, возможны обезвоживание и грибковые инфекции половых органов. При острых болезнях и операциях лечение меняет врач.', 'Verschreibungspflichtig. Die Urinmenge steigt, Austrocknung und Pilzinfektionen im Genitalbereich sind möglich. Bei akuten Erkrankungen entscheidet der Arzt.', 'Yalnızca reçeteyle verilir. İdrar miktarını artırır, susuz kalma ve genital mantar enfeksiyonları görülebilir. Akut hastalıkta tedaviyi hekim düzenler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- enalapril
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (220, 'A blood pressure medicine from the ACE inhibitor group that relaxes blood vessels. Also comes combined with a diuretic.', 'Lijek za povišen pritisak iz grupe ACE inhibitora koji opušta krvne sudove. Postoje i kombinacije sa diuretikom.', 'Лијек за повишен притисак из групе ACE инхибитора који опушта крвне судове. Постоје и комбинације са диуретиком.', 'Средство от повышенного давления из группы ингибиторов АПФ: расслабляет сосуды. Есть комбинации с мочегонным.', 'Ein Blutdruckmittel aus der Gruppe der ACE-Hemmer, das die Gefäße entspannt. Es gibt Kombinationen mit einem Entwässerungsmittel.', 'Damarları gevşeten, ACE inhibitörü grubundan bir tansiyon ilacıdır. İdrar söktürücüyle kombinasyonları da vardır.', 'Used for high blood pressure and chronic heart failure, and to protect the heart after a heart attack.', 'Primjenjuje se kod povišenog pritiska i hronične srčane slabosti, kao i radi zaštite srca poslije infarkta.', 'Примјењује се код повишеног притиска и хроничне срчане слабости, као и ради заштите срца послије инфаркта.', 'Применяют при артериальной гипертензии и хронической сердечной недостаточности, а также для защиты сердца после инфаркта.', 'Wird bei Bluthochdruck und chronischer Herzschwäche sowie zum Schutz des Herzens nach einem Infarkt eingesetzt.', 'Yüksek tansiyonda ve kronik kalp yetmezliğinde, ayrıca kalp krizi sonrası kalbi korumak için kullanılır.', 'Prescription only. A dry cough is a common side effect. It is not stopped on your own, blood pressure and blood tests are monitored. It is not used in pregnancy.', 'Izdaje se samo na recept. Čest neželjeni efekat je suv kašalj. Terapija se ne prekida samostalno, prate se pritisak i nalazi. U trudnoći se ne primjenjuje.', 'Издаје се само на рецепт. Чест нежељени ефекат је сув кашаљ. Терапија се не прекида самостално, прате се притисак и налази. У трудноћи се не примјењује.', 'Только по рецепту. Частый побочный эффект — сухой кашель. Приём не прекращают самостоятельно, нужен контроль давления и анализов. При беременности не применяют.', 'Verschreibungspflichtig. Ein trockener Reizhusten ist häufig. Nicht eigenmächtig absetzen, Blutdruck und Laborwerte werden kontrolliert. In der Schwangerschaft nicht.', 'Yalnızca reçeteyle verilir. Kuru öksürük sık görülen yan etkidir. Kendi başına bırakılmaz, tansiyon ve tahliller izlenir. Gebelikte kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- esomeprazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (241, 'A proton pump inhibitor that lowers acid production in the stomach.', 'Inhibitor protonske pumpe koji smanjuje lučenje želudačne kiseline.', 'Инхибитор протонске пумпе који смањује лучење желудачне киселине.', 'Ингибитор протонной помпы: снижает выработку соляной кислоты в желудке.', 'Ein Protonenpumpenhemmer, der die Magensäure verringert.', 'Mide asidi salgısını azaltan bir proton pompası inhibitörüdür.', 'Used for reflux disease, stomach and duodenal ulcers, and to protect the stomach lining during NSAID treatment.', 'Primjenjuje se kod refluksne bolesti, čira želuca i dvanaestopalačnog crijeva, i radi zaštite sluznice uz NSAIL.', 'Примјењује се код рефлуксне болести, чира желуца и дванаестопалачног цријева, и ради заштите слузнице уз NSAIL.', 'Применяют при рефлюксной болезни, язве желудка и двенадцатиперстной кишки, а также для защиты слизистой при лечении НПВС.', 'Wird bei Refluxkrankheit, Magen- und Zwölffingerdarmgeschwüren sowie zum Schutz der Magenschleimhaut unter NSAR eingesetzt.', 'Reflü hastalığında, mide ve onikiparmak bağırsağı ülserinde, NSAİİ tedavisi sırasında mide mukozasını korumak için kullanılır.', 'Prescription only. Long use is supervised by a doctor: vitamin B12 and magnesium may drop and other medicines can be affected. In pregnancy and for children, only on a doctor''s advice.', 'Izdaje se na recept. Dugu primjenu prati ljekar: mogu pasti vitamin B12 i magnezijum, moguće su interakcije. U trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се на рецепт. Дугу примјену прати љекар: могу пасти витамин B12 и магнезијум, могуће су интеракције. У трудноћи и код дјеце само по савјету љекара.', 'Отпускается по рецепту. Длительный приём контролирует врач: возможны снижение витамина B12 и магния, взаимодействие с другими лекарствами. Беременным и детям — по назначению врача.', 'Verschreibungspflichtig. Eine lange Einnahme begleitet der Arzt: Vitamin B12 und Magnesium können sinken, Wechselwirkungen sind möglich. In Schwangerschaft und bei Kindern nur ärztlich.', 'Reçeteyle satılır. Uzun kullanımı hekim izler: B12 vitamini ve magnezyum düşebilir, ilaç etkileşimleri olabilir. Gebelikte ve çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- etarsko ulje
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (246, 'An essential oil is the volatile aromatic fraction of a plant and the active component of over-the-counter herbal preparations.', 'Etarsko ulje je isparljiva aromatična frakcija biljne sirovine i aktivni sastojak biljnih preparata bez recepta.', 'Етарско уље је испарљива ароматична фракција биљне сировине и активни састојак биљних препарата без рецепта.', 'Эфирное масло — летучая ароматическая фракция растительного сырья, действующий компонент безрецептурных растительных препаратов.', 'Ein ätherisches Öl ist der flüchtige Duftanteil einer Pflanze und der Wirkbestandteil rezeptfreier pflanzlicher Zubereitungen.', 'Uçucu yağ, bitkinin uçucu aromatik fraksiyonudur ve reçetesiz bitkisel preparatların etkin bileşenidir.', 'Found in preparations applied to the skin for mild muscle and joint pain.', 'Ulazi u preparate za nanošenje na kožu kod blagih bolova u mišićima i zglobovima.', 'Улази у препарате за наношење на кожу код благих болова у мишићима и зглобовима.', 'Входит в наружные средства, которые применяют при лёгкой мышечной и суставной боли.', 'Steckt in Zubereitungen zum Auftragen auf die Haut bei leichten Muskel- und Gelenkschmerzen.', 'Hafif kas ve eklem ağrılarında deriye sürülen preparatların içinde bulunur.', 'Available without prescription. For unbroken skin only, away from the eyes and mucous membranes; irritation and allergy are possible. In young children and pregnancy, as a doctor advises.', 'Izdaje se bez recepta. Nanosi se samo na neoštećenu kožu, dalje od očiju i sluznica; mogući su nadražaj i alergija. Maloj djeci i trudnicama po savjetu ljekara.', 'Издаје се без рецепта. Наноси се само на неоштећену кожу, даље од очију и слузница; могући су надражај и алергија. Малој дјеци и трудницама по савјету љекара.', 'Отпускается без рецепта. Наносят только на неповреждённую кожу, вдали от глаз и слизистых; возможны раздражение и аллергия. Маленьким детям и беременным — по назначению врача.', 'Rezeptfrei. Nur auf unverletzte Haut auftragen, nicht in Augen und Schleimhäute; Reizungen und Allergien sind möglich. Bei kleinen Kindern und in der Schwangerschaft nach ärztlichem Rat.', 'Reçetesiz satılır. Yalnızca sağlam deriye uygulanır, göz ve mukozalardan uzak tutulur; tahriş ve alerji olabilir. Küçük çocuklarda ve gebelikte hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- etinilestradiol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (247, 'A synthetic estrogen used together with a progestogen in combined hormonal contraceptives.', 'Sintetski estrogen koji ulazi u sastav kombinovanih hormonskih kontraceptiva zajedno sa gestagenom.', 'Синтетски естроген који улази у састав комбинованих хормонских контрацептива заједно са гестагеном.', 'Синтетический эстроген, входит в состав комбинированных гормональных контрацептивов вместе с гестагеном.', 'Ein synthetisches Östrogen, das zusammen mit einem Gestagen in kombinierten hormonellen Verhütungsmitteln enthalten ist.', 'Kombine hormonal doğum kontrol haplarında bir progestajenle birlikte bulunan sentetik östrojendir.', 'Used for contraception, and also for cycle disorders and, at a doctor''s decision, for some forms of acne.', 'Primjenjuje se radi zaštite od trudnoće, kao i kod poremećaja ciklusa i, po odluci ljekara, kod nekih oblika akni.', 'Примјењује се ради заштите од трудноће, као и код поремећаја циклуса и, по одлуци љекара, код неких облика акни.', 'Применяют для предохранения от беременности, а также при нарушениях цикла и по решению врача при некоторых формах акне.', 'Wird zur Verhütung sowie bei Zyklusstörungen und nach ärztlicher Entscheidung bei bestimmten Formen von Akne eingesetzt.', 'Gebelikten korunmada, ayrıca adet düzensizliklerinde ve hekim kararıyla bazı akne biçimlerinde kullanılır.', 'Prescription only. It raises the risk of blood clots, especially in smokers and at older age. A gynaecologist chooses the product, it is not used in pregnancy.', 'Izdaje se samo na recept. Povećava rizik od tromboze, naročito kod pušača i u starijem dobu. Preparat bira ginekolog, u trudnoći i dojenju se ne primjenjuje.', 'Издаје се само на рецепт. Повећава ризик од тромбозе, нарочито код пушача и у старијем добу. Препарат бира гинеколог, у трудноћи и дојењу се не примјењује.', 'Только по рецепту. Повышает риск тромбозов, особенно у курящих и в старшем возрасте. Препарат подбирает гинеколог, при беременности и кормлении не применяют.', 'Verschreibungspflichtig. Erhöht das Thromboserisiko, vor allem bei Raucherinnen und im höheren Alter. Die Auswahl trifft der Arzt, nicht in der Schwangerschaft.', 'Yalnızca reçeteyle verilir. Pıhtı riskini artırır, özellikle sigara içenlerde ve ileri yaşta. Preparatı hekim seçer, gebelik ve emzirmede kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- feksofenadin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (259, 'A second-generation antihistamine that barely reaches the brain and rarely causes drowsiness.', 'Antihistaminik druge generacije koji jedva ulazi u mozak i rjeđe izaziva pospanost.', 'Антихистаминик друге генерације који једва улази у мозак и рјеђе изазива поспаност.', 'Антигистаминное средство второго поколения: почти не проникает в мозг и реже вызывает сонливость.', 'Ein Antihistaminikum der zweiten Generation, das kaum ins Gehirn gelangt und selten müde macht.', 'Beyne neredeyse geçmeyen ve nadiren uyku hali yapan ikinci kuşak bir antihistaminiktir.', 'Used for seasonal and year-round allergic rhinitis, and for hives and allergic itching of the skin.', 'Primjenjuje se kod sezonskog i cjelogodišnjeg alergijskog rinitisa, kao i kod koprivnjače i alergijskog svraba kože.', 'Примјењује се код сезонског и цјелогодишњег алергијског ринитиса, као и код копривњаче и алергијског свраба коже.', 'Применяют при сезонном и круглогодичном аллергическом рините, а также при крапивнице и кожном зуде аллергической природы.', 'Wird bei saisonalem und ganzjährigem allergischem Schnupfen sowie bei Nesselsucht und allergischem Hautjucken angewendet.', 'Mevsimsel ve yıl boyu süren alerjik nezlede, kurdeşende ve alerjik deri kaşıntısında kullanılır.', 'Available over the counter. Fruit juices and antacids reduce its absorption. With kidney disease, in pregnancy and in children, only on a doctor''s advice.', 'Izdaje se bez recepta. Voćni sokovi i antacidi smanjuju njegovu apsorpciju. Kod bolesti bubrega, u trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта. Воћни сокови и антациди смањују његову апсорпцију. Код болести бубрега, у трудноћи и код дјеце само по савјету љекара.', 'Отпускается без рецепта. Фруктовые соки и антациды снижают его усвоение. При болезнях почек, беременности и у детей — по назначению врача.', 'Rezeptfrei erhältlich. Fruchtsäfte und Antazida verringern die Aufnahme. Bei Nierenkrankheiten, in der Schwangerschaft und bei Kindern nur nach Anweisung.', 'Reçetesiz satılır. Meyve suları ve antasitler emilimini azaltır. Böbrek hastalığında, gebelikte ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fenilefrin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (262, 'Phenylephrine is a decongestant that reduces swelling of the nasal lining and is part of combination cold remedies', 'Fenilefrin je dekongestiv koji smanjuje oticanje sluznice nosa; ulazi u kombinovane preparate protiv prehlade', 'Фенилефрин је деконгестив који смањује отицање слузнице носа; улази у комбиноване препарате против прехладе', 'Фенилэфрин — сосудосуживающее средство, которое уменьшает отёк слизистой носа; входит в комбинированные средства от простуды', 'Phenylephrin ist ein abschwellendes Mittel, das die Nasenschleimhaut abschwellen lässt, und Bestandteil von Erkältungskombinationen', 'Fenilefrin burun mukozasındaki şişliği azaltan bir dekonjestandır; kombine soğuk algınlığı ürünlerinde bulunur', 'Blocked nose and swollen nasal lining in colds, flu and rhinitis', 'Začepljen nos i otok sluznice kod prehlade, gripa i rinitisa', 'Зачепљен нос и оток слузнице код прехладе, грипа и ринитиса', 'Заложенность носа и отёк слизистой при простуде, гриппе и рините', 'Verstopfte Nase und geschwollene Nasenschleimhaut bei Erkältung, Grippe und Schnupfen', 'Soğuk algınlığı, grip ve nezlede burun tıkanıklığı ve mukoza ödemi', 'It may raise blood pressure and heart rate. With hypertension, heart or thyroid disease, in children and in pregnancy only as advised by a doctor.', 'Može povisiti krvni pritisak i ubrzati puls. Kod povišenog pritiska, bolesti srca i štitne žlijezde, kod djece i u trudnoći samo po savjetu ljekara.', 'Може повисити крвни притисак и убрзати пулс. Код повишеног притиска, болести срца и штитне жлијезде, код дјеце и у трудноћи само по савјету љекара.', 'Может повышать давление и учащать пульс. При гипертонии, болезнях сердца и щитовидной железы, у детей и беременных — по назначению врача.', 'Kann Blutdruck und Puls erhöhen. Bei Bluthochdruck, Herz- und Schilddrüsenleiden, bei Kindern und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Tansiyonu ve nabzı yükseltebilir. Yüksek tansiyon, kalp ve tiroid hastalığında, çocuklarda ve gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- feniramin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (263, 'Pheniramine is a first-generation antihistamine used within combination cold remedies', 'Feniramin je antihistaminik prve generacije; koristi se u sastavu kombinovanih preparata protiv prehlade', 'Фенирамин је антихистаминик прве генерације; користи се у саставу комбинованих препарата против прехладе', 'Фенирамин — антигистаминное средство первого поколения; применяется в составе комбинированных средств от простуды', 'Pheniramin ist ein Antihistaminikum der ersten Generation und Bestandteil von Erkältungskombinationen', 'Feniramin birinci kuşak bir antihistaminiktir; kombine soğuk algınlığı ürünlerinin bileşeni olarak kullanılır', 'Runny nose, sneezing and watery eyes in colds, and allergy symptoms as part of combination products', 'Curenje iz nosa, kijanje i suzenje očiju kod prehlade, kao i alergijske tegobe u kombinovanim preparatima', 'Цурење из носа, кијање и сузење очију код прехладе, као и алергијске тегобе у комбинованим препаратима', 'Насморк, чихание и слезотечение при простуде, а также аллергические проявления в составе комбинированных средств', 'Laufende Nase, Niesen und tränende Augen bei Erkältung sowie allergische Beschwerden in Kombinationspräparaten', 'Soğuk algınlığında burun akıntısı, hapşırma ve gözlerde sulanma, ayrıca kombine ürünlerde alerji şikayetleri', 'Causes drowsiness and reduces attention, does not go with alcohol; take care when driving. Children''s and adult formulations differ; in pregnancy use only as advised by a doctor.', 'Izaziva pospanost i smanjuje pažnju, ne kombinuje se sa alkoholom; oprez u vožnji. Oblici za djecu i odrasle se razlikuju; u trudnoći samo po savjetu ljekara.', 'Изазива поспаност и смањује пажњу, не комбинује се са алкохолом; опрез у вожњи. Облици за дјецу и одрасле се разликују; у трудноћи само по савјету љекара.', 'Вызывает сонливость и снижает внимание, не сочетается с алкоголем; за рулём — осторожно. Формы для детей и взрослых различаются; при беременности — по назначению врача.', 'Macht müde und mindert die Aufmerksamkeit, verträgt sich nicht mit Alkohol; Vorsicht im Verkehr. Zubereitungen für Kinder und Erwachsene unterscheiden sich; in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Uyku hali yapar ve dikkati azaltır, alkolle birlikte kullanılmaz; araç kullanırken dikkat. Çocuk ve yetişkin formları farklıdır; gebelikte yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fenofibrat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (266, 'A lipid-lowering drug of the fibrate group that lowers blood triglycerides and has a moderate effect on cholesterol.', 'Lijek za snižavanje masnoća iz grupe fibrata: smanjuje trigliceride u krvi i umjereno utiče na holesterol.', 'Лијек за снижавање масноћа из групе фибрата: смањује триглицериде у крви и умјерено утиче на холестерол.', 'Гиполипидемическое средство группы фибратов: снижает уровень триглицеридов в крови и умеренно влияет на холестерин.', 'Ein Lipidsenker aus der Gruppe der Fibrate, der die Triglyceride im Blut senkt und das Cholesterin mäßig beeinflusst.', 'Kandaki trigliseritleri düşüren, kolesterolü orta derecede etkileyen fibrat grubundan bir lipid düşürücüdür.', 'Used for raised triglycerides and mixed lipid disorders when diet alone is not enough, sometimes together with a statin.', 'Primjenjuje se kod povišenih triglicerida i mješovitih poremećaja masnoća kada dijeta nije dovoljna, ponekad uz statin.', 'Примјењује се код повишених триглицерида и мјешовитих поремећаја масноћа када дијета није довољна, понекад уз статин.', 'Применяют при повышенных триглицеридах и смешанных нарушениях липидного обмена, когда одной диеты недостаточно, иногда вместе со статином.', 'Wird bei erhöhten Triglyceriden und gemischten Fettstoffwechselstörungen eingesetzt, wenn die Ernährung allein nicht ausreicht.', 'Beslenme düzeni yeterli olmadığında yüksek trigliserit ve karışık yağ bozukluklarında, bazen statinle birlikte kullanılır.', 'Prescription only. Blood tests are monitored during treatment. Muscle pain should be reported to a doctor. With kidney, liver or gallbladder disease, only as prescribed.', 'Izdaje se na recept. Tokom terapije prate se nalazi krvi. Bol u mišićima treba prijaviti ljekaru. Kod bolesti bubrega, jetre i žučne kese samo po savjetu ljekara.', 'Издаје се на рецепт. Током терапије прате се налази крви. Бол у мишићима треба пријавити љекару. Код болести бубрега, јетре и жучне кесе само по савјету љекара.', 'Отпускается по рецепту. Во время лечения контролируют анализы крови. О боли в мышцах сообщают врачу. При болезнях почек, печени и желчного пузыря — по назначению врача.', 'Verschreibungspflichtig. Blutwerte werden kontrolliert. Muskelschmerzen sind dem Arzt zu melden. Bei Nieren-, Leber- und Gallenerkrankungen nur nach Anweisung.', 'Reçeteye tabidir. Tedavi sırasında kan tetkikleri izlenir. Kas ağrısı hekime bildirilmelidir. Böbrek, karaciğer ve safra kesesi hastalığında hekim kararıyla kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fenoksietanol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (267, 'An antiseptic and preservative. In medicine it is used externally, usually combined with octenidine in ready-made skin products.', 'Antiseptik i konzervans. U medicini se primjenjuje spolja, obično u kombinaciji sa oktenidinom u gotovim preparatima za kožu.', 'Антисептик и конзерванс. У медицини се примјењује споља, обично у комбинацији са октенидином у готовим препаратима за кожу.', 'Антисептик и консервант. В медицине применяется наружно, обычно в комбинации с октенидином в готовых средствах для кожи.', 'Ein Antiseptikum und Konservierungsmittel. Medizinisch wird es äußerlich angewendet, meist mit Octenidin in fertigen Hautpräparaten.', 'Antiseptik ve koruyucu bir maddedir. Tıpta dıştan, genellikle hazır deri ürünlerinde oktenidinle birlikte kullanılır.', 'Used to clean skin, mucous membranes and small wounds, including before procedures and when caring for damaged skin.', 'Koristi se za obradu kože, sluznica i manjih rana, uključujući pripremu prije zahvata i njegu oštećene kože.', 'Користи се за обраду коже, слузница и мањих рана, укључујући припрему прије захвата и његу оштећене коже.', 'Применяют для обработки кожи, слизистых и небольших ран, в том числе перед процедурами и при уходе за повреждённой кожей.', 'Wird zur Reinigung von Haut, Schleimhäuten und kleinen Wunden verwendet, auch vor Eingriffen und bei der Pflege geschädigter Haut.', 'Deri, mukoza ve küçük yaraların temizliğinde, işlem öncesi hazırlıkta ve hasarlı derinin bakımında kullanılır.', 'Available over the counter. For external use only, not to be swallowed. Keep out of the eyes; in small children only on a doctor''s advice.', 'Izdaje se bez recepta. Samo za spoljnu upotrebu, ne guta se. Izbjegavati kontakt sa očima, kod male djece samo po savjetu ljekara.', 'Издаје се без рецепта. Само за спољну употребу, не гута се. Избјегавати контакт са очима, код мале дјеце само по савјету љекара.', 'Отпускается без рецепта. Только для наружного применения, внутрь не принимают. Избегать попадания в глаза, у маленьких детей — по назначению врача.', 'Rezeptfrei erhältlich. Nur zur äußerlichen Anwendung, nicht schlucken. Kontakt mit den Augen vermeiden, bei kleinen Kindern nur nach Anweisung.', 'Reçetesiz satılır. Yalnızca haricen kullanılır, yutulmaz. Gözle temasından kaçınılır, küçük çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fenoterol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (269, 'A short-acting beta-2 agonist that opens the airways quickly. In Montenegro it is available combined with ipratropium bromide.', 'Beta-2 agonist kratkog djelovanja koji brzo širi disajne puteve. U Crnoj Gori je dostupan u kombinaciji sa ipratropijum bromidom.', 'Бета-2 агонист кратког дјеловања који брзо шири дисајне путеве. У Црној Гори је доступан у комбинацији са ипратропијум бромидом.', 'Бета-2-агонист короткого действия, быстро расширяющий бронхи. В Черногории доступен в комбинации с ипратропия бромидом.', 'Ein kurz wirksamer Beta-2-Agonist, der die Atemwege rasch erweitert. In Montenegro gibt es ihn zusammen mit Ipratropiumbromid.', 'Solunum yollarını hızla genişleten kısa etkili bir beta-2 agonistidir. Karadağ''da ipratropiyum bromürle kombine bulunur.', 'Used for quick relief of breathlessness and wheezing in asthma and COPD.', 'Primjenjuje se za brzo olakšanje nedostatka vazduha i sviranja u grudima kod astme i HOBP.', 'Примјењује се за брзо олакшање недостатка ваздуха и свирања у грудима код астме и ХОБП.', 'Применяют для быстрого облегчения одышки и свистящего дыхания при бронхиальной астме и ХОБЛ.', 'Wird zur schnellen Linderung von Atemnot und Pfeifen bei Asthma und COPD eingesetzt.', 'Astım ve KOAH''ta nefes darlığını ve hırıltıyı hızla gidermek için kullanılır.', 'Prescription only. Tremor, palpitations and headache are possible. A growing need for the inhaler means the condition is worsening and calls for a doctor.', 'Izdaje se na recept. Mogući su drhtavica, lupanje srca i glavobolja. Sve češća potreba za inhalacijom znači pogoršanje i traži ljekara.', 'Издаје се на рецепт. Могући су дрхтавица, лупање срца и главобоља. Све чешћа потреба за инхалацијом значи погоршање и тражи љекара.', 'Отпускается по рецепту. Возможны дрожь, сердцебиение и головная боль. Растущая потребность в ингаляциях означает ухудшение и требует врача.', 'Verschreibungspflichtig. Zittern, Herzklopfen und Kopfschmerzen sind möglich. Ein steigender Bedarf zeigt eine Verschlechterung und gehört zum Arzt.', 'Reçeteye tabidir. Titreme, çarpıntı ve baş ağrısı olabilir. İhtiyacın giderek artması durumun kötüleştiğini gösterir ve hekime başvurmayı gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fentikonazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (271, 'An azole antifungal for local use.', 'Antimikotik iz grupe azola za lokalnu primjenu.', 'Антимикотик из групе азола за локалну примјену.', 'Противогрибковое вещество группы азолов для местного применения.', 'Ein Azol-Antimykotikum zur örtlichen Anwendung.', 'Yerel kullanım için azol grubundan bir mantar ilacıdır.', 'Used for vaginal candidiasis and other fungal infections of the mucosa and skin of the external genitals.', 'Primjenjuje se kod vaginalne kandidijaze i drugih gljivičnih infekcija sluznice i kože spoljnih genitalija.', 'Примјењује се код вагиналне кандидијазе и других гљивичних инфекција слузнице и коже спољних гениталија.', 'Применяют при вагинальном кандидозе и других грибковых поражениях слизистой и кожи наружных половых органов.', 'Wird bei Scheidenpilz und anderen Pilzinfektionen der Schleimhaut und Haut im äußeren Genitalbereich angewendet.', 'Vajinal kandidiyazda ve dış genital bölge derisi ile mukozasının diğer mantar enfeksiyonlarında kullanılır.', 'Available without prescription. It can weaken latex condoms and diaphragms. For a first episode, repeated episodes or in pregnancy, see a doctor.', 'Izdaje se bez recepta. Može oslabiti lateks kondome i dijafragme. Kod prve epizode, ponavljanja i u trudnoći potreban je pregled ljekara.', 'Издаје се без рецепта. Може ослабити латекс кондоме и дијафрагме. Код прве епизоде, понављања и у трудноћи потребан је преглед љекара.', 'Отпускается без рецепта. Может снижать надёжность латексных презервативов и диафрагм. При первом эпизоде, повторах и беременности — осмотр врача.', 'Rezeptfrei. Kann Kondome und Diaphragmen aus Latex beeinträchtigen. Bei erster Episode, häufigen Rückfällen und in der Schwangerschaft zum Arzt.', 'Reçetesiz satılır. Lateks prezervatif ve diyaframların güvenilirliğini azaltabilir. İlk atakta, yinelemelerde ve gebelikte doktora başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- flukonazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (280, 'A systemic antifungal from the azole group.', 'Antimikotik iz grupe azola sa sistemskim djelovanjem.', 'Антимикотик из групе азола са системским дјеловањем.', 'Противогрибковое вещество группы азолов системного действия.', 'Ein systemisch wirkendes Antimykotikum aus der Gruppe der Azole.', 'Azol grubundan, tüm vücutta etkili bir mantar ilacıdır.', 'Prescribed for Candida infections of mucous membranes and genitals, fungal infections of skin and nails, and systemic fungal infections.', 'Propisuje se kod kandidijaze sluznica i polnih organa, gljivičnih infekcija kože i noktiju i kod sistemskih gljivičnih infekcija.', 'Прописује се код кандидијазе слузница и полних органа, гљивичних инфекција коже и ноктију и код системских гљивичних инфекција.', 'Назначают при кандидозе слизистых и половых органов, грибковых поражениях кожи и ногтей и при системных грибковых инфекциях.', 'Wird bei Candida-Infektionen von Schleimhäuten und Genitalien, Pilzbefall von Haut und Nägeln sowie systemischen Pilzinfektionen verordnet.', 'Mukoza ve genital bölge kandida enfeksiyonlarında, deri ve tırnak mantarında, ayrıca sistemik mantar enfeksiyonlarında reçete edilir.', 'Prescription only. It interacts with many medicines and can affect the liver. In pregnancy and with heart rhythm disorders, a doctor decides.', 'Izdaje se samo na recept. Stupa u interakcije sa mnogim lijekovima i može uticati na jetru. U trudnoći i kod poremećaja srčanog ritma odlučuje ljekar.', 'Издаје се само на рецепт. Ступа у интеракције са многим лијековима и може утицати на јетру. У трудноћи и код поремећаја срчаног ритма одлучује љекар.', 'Только по рецепту. Взаимодействует со многими лекарствами и может влиять на печень. При беременности и нарушениях сердечного ритма решение принимает врач.', 'Verschreibungspflichtig. Es hat viele Wechselwirkungen und kann die Leber belasten. In der Schwangerschaft und bei Rhythmusstörungen entscheidet der Arzt.', 'Yalnızca reçeteyle verilir. Birçok ilaçla etkileşir ve karaciğeri etkileyebilir. Gebelikte ve kalp ritim bozukluğunda hekim karar verir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- flurbiprofen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (284, 'A non-steroidal anti-inflammatory substance (NSAID) with painkilling and anti-inflammatory action.', 'Nesteroidni antiinflamatorni lijek (NSAIL) sa analgetskim i protivupalnim djelovanjem.', 'Нестероидни антиинфламаторни лијек (NSAIL) са аналгетским и противупалним дјеловањем.', 'Нестероидное противовоспалительное вещество (НПВС) с обезболивающим и противовоспалительным действием.', 'Ein nichtsteroidales Antirheumatikum (NSAR) mit schmerzstillender und entzündungshemmender Wirkung.', 'Ağrı kesici ve iltihap giderici etkili, steroid yapıda olmayan bir antiinflamatuar maddedir (NSAİİ).', 'Used for joint and muscle pain and inflammation, for sore throat, and in ophthalmology after eye surgery.', 'Primjenjuje se kod bola i upale zglobova i mišića, kod upale grla i u oftalmologiji poslije operacije oka.', 'Примјењује се код бола и упале зглобова и мишића, код упале грла и у офталмологији послије операције ока.', 'Применяют при боли и воспалении в суставах и мышцах, при боли в горле, а также в офтальмологии после операций на глазу.', 'Wird bei Schmerzen und Entzündungen in Gelenken und Muskeln, bei Halsschmerzen und in der Augenheilkunde nach Operationen angewendet.', 'Eklem ve kas ağrısı ile iltihabında, boğaz ağrısında ve göz ameliyatı sonrası iltihapta kullanılır.', 'Like all NSAIDs it can irritate the stomach and affect the kidneys. Systemic forms are prescription only, care is needed with ulcers, asthma and in pregnancy.', 'Kao svi NSAIL može nadražiti želudac i uticati na bubrege. Sistemski oblici se izdaju na recept, oprez kod čira, astme i u trudnoći.', 'Као сви NSAIL може надражити желудац и утицати на бубреге. Системски облици се издају на рецепт, опрез код чира, астме и у трудноћи.', 'Как все НПВС может раздражать желудок и влиять на почки. Системные формы — по назначению врача, нужна осторожность при язве, астме и беременности.', 'Wie alle NSAR kann es den Magen reizen und die Nieren belasten. Systemische Formen sind verschreibungspflichtig, Vorsicht bei Geschwüren, Asthma und in der Schwangerschaft.', 'Tüm NSAİİ ilaçları gibi mideyi tahriş edebilir ve böbrekleri etkileyebilir. Sistemik formları reçeteyle verilir, ülser, astım ve gebelikte dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- flutikazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (285, 'A corticosteroid applied locally in the airways and in the nose, including in combination products.', 'Kortikosteroid za lokalnu primjenu u disajnim putevima i u nosu, uključujući i kombinovane preparate.', 'Кортикостероид за локалну примјену у дисајним путевима и у носу, укључујући и комбиноване препарате.', 'Глюкокортикоид для местного применения в дыхательных путях и в полости носа, в том числе в комбинированных препаратах.', 'Ein Kortison zur örtlichen Anwendung in den Atemwegen und in der Nase, auch in Kombinationspräparaten.', 'Solunum yollarında ve burunda bölgesel etki gösteren bir kortikosteroittir, kombine preparatları da vardır.', 'Inhaled forms are used in asthma, nasal sprays in allergic rhinitis and a blocked nose.', 'Inhalacioni oblici primjenjuju se kod astme, a nazalni sprejevi kod alergijskog rinitisa i zapušenog nosa.', 'Инхалациони облици примјењују се код астме, а назални спрејеви код алергијског ринитиса и запушеног носа.', 'Ингаляционные формы применяют при бронхиальной астме, назальные спреи — при аллергическом рините и заложенности носа.', 'Inhalative Formen werden bei Asthma eingesetzt, Nasensprays bei allergischem Schnupfen und verstopfter Nase.', 'İnhaler formları astımda, burun spreyleri alerjik nezle ve burun tıkanıklığında kullanılır.', 'Prescription only. Dryness and irritation in the nose are possible, and with inhalers hoarseness and oral thrush. The length of treatment is set by a doctor.', 'Izdaje se na recept. Mogući su suvoća i nadražaj u nosu, a uz inhalacije promuklost i gljivice u ustima. Trajanje terapije određuje ljekar.', 'Издаје се на рецепт. Могући су сувоћа и надражај у носу, а уз инхалације промуклост и гљивице у устима. Трајање терапије одређује љекар.', 'Отпускается по рецепту. Возможны сухость и раздражение в носу, при ингаляциях — осиплость и молочница во рту. Длительность лечения определяет врач.', 'Verschreibungspflichtig. Trockenheit und Reizung in der Nase sind möglich, bei Inhalation Heiserkeit und Mundsoor. Die Dauer bestimmt der Arzt.', 'Reçeteye tabidir. Burunda kuruluk ve tahriş, inhalasyonda ses kısıklığı ve ağızda pamukçuk görülebilir. Tedavi süresini hekim belirler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- folna kiselina
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (289, 'Vitamin B9, a water-soluble vitamin involved in blood formation and cell division. It is also part of vitamin supplements.', 'Folna kiselina je vitamin rastvorljiv u vodi koji učestvuje u stvaranju krvi i dijeljenju ćelija. Ulazi i u vitaminske preparate.', 'Фолна киселина је витамин растворљив у води који учествује у стварању крви и дијељењу ћелија. Улази и у витаминске препарате.', 'Витамин B9, водорастворимый витамин: участвует в кроветворении и делении клеток. Входит в витаминные комплексы.', 'Vitamin B9, ein wasserlösliches Vitamin für Blutbildung und Zellteilung, auch Bestandteil von Vitaminpräparaten.', 'Kan yapımında ve hücre bölünmesinde rol alan, suda çözünen B9 vitaminidir. Vitamin preparatlarında da bulunur.', 'Used when planning and during pregnancy to lower the risk of neural tube defects, and for anaemia caused by folate deficiency.', 'Primjenjuje se u pripremi za trudnoću i tokom nje radi smanjenja rizika od defekata nervne cijevi, kao i kod anemije zbog nedostatka folata.', 'Примјењује се у припреми за трудноћу и током ње ради смањења ризика од дефеката нервне цијеви, као и код анемије због недостатка фолата.', 'Применяют при планировании беременности и во время неё для снижения риска пороков нервной трубки, а также при анемии из-за нехватки фолатов.', 'Wird bei Kinderwunsch und in der Schwangerschaft zur Senkung des Risikos für Neuralrohrdefekte sowie bei Blutarmut durch Folatmangel eingesetzt.', 'Gebelik hazırlığında ve gebelikte nöral tüp defekti riskini azaltmak için, ayrıca folat eksikliğine bağlı kansızlıkta kullanılır.', 'Some forms are prescription only. It can mask vitamin B12 deficiency, so in anaemia a doctor decides, as with use alongside methotrexate.', 'Dio oblika izdaje se na recept. Može prikriti nedostatak vitamina B12, pa kod anemije terapiju određuje ljekar, kao i primjenu uz metotreksat.', 'Дио облика издаје се на рецепт. Може прикрити недостатак витамина B12, па код анемије терапију одређује љекар, као и примјену уз метотрексат.', 'Часть форм по рецепту. Может маскировать дефицит витамина B12, поэтому при анемии лечение назначает врач, как и приём вместе с метотрексатом.', 'Ein Teil der Formen ist verschreibungspflichtig. Es kann einen Vitamin-B12-Mangel verdecken, daher entscheidet bei Blutarmut der Arzt, ebenso bei Methotrexat.', 'Bazı formları reçeteye tabidir. B12 vitamini eksikliğini gizleyebilir, bu nedenle kansızlıkta ve metotreksatla birlikte kullanımına hekim karar verir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- formoterol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (291, 'A long-acting beta-2 agonist that widens the airways. In Montenegro it is available only combined with an inhaled steroid.', 'Beta-2 agonist dugog djelovanja koji širi disajne puteve. U Crnoj Gori je dostupan samo uz inhalacioni kortikosteroid.', 'Бета-2 агонист дугог дјеловања који шири дисајне путеве. У Црној Гори је доступан само уз инхалациони кортикостероид.', 'Бета-2-агонист длительного действия, расширяющий бронхи. В Черногории доступен только в комбинации с ингаляционным гормоном.', 'Ein lang wirksamer Beta-2-Agonist, der die Atemwege erweitert. In Montenegro gibt es ihn nur zusammen mit einem inhalativen Kortison.', 'Solunum yollarını genişleten uzun etkili bir beta-2 agonistidir. Karadağ''da yalnızca inhale kortikosteroitle kombine bulunur.', 'Used for long-term control of asthma and COPD: the combined inhalers reduce breathlessness and the number of flare-ups.', 'Primjenjuje se za dugotrajnu kontrolu astme i HOBP: kombinovani inhalatori smanjuju nedostatak vazduha i broj pogoršanja.', 'Примјењује се за дуготрајну контролу астме и ХОБП: комбиновани инхалатори смањују недостатак ваздуха и број погоршања.', 'Применяют для длительного контроля бронхиальной астмы и ХОБЛ: комбинированные ингаляторы уменьшают одышку и частоту обострений.', 'Wird zur Langzeitkontrolle von Asthma und COPD eingesetzt: Die Kombinationsinhalatoren mindern Atemnot und die Zahl der Verschlechterungen.', 'Astım ve KOAH''ın uzun süreli kontrolünde kullanılır: kombine inhalerler nefes darlığını ve alevlenme sayısını azaltır.', 'Prescription only. In asthma it is not used without an inhaled steroid. Tremor and palpitations are possible. The inhaler regimen is set by a doctor.', 'Izdaje se na recept. Kod astme se ne koristi bez inhalacionog kortikosteroida. Mogući su drhtavica i lupanje srca. Primjenu određuje ljekar.', 'Издаје се на рецепт. Код астме се не користи без инхалационог кортикостероида. Могући су дрхтавица и лупање срца. Примјену одређује љекар.', 'Отпускается по рецепту. При астме не применяют без ингаляционного гормона. Возможны дрожь и сердцебиение. Режим ингаляций определяет врач.', 'Verschreibungspflichtig. Bei Asthma nicht ohne inhalatives Kortison. Zittern und Herzklopfen sind möglich. Die Anwendung legt der Arzt fest.', 'Reçeteye tabidir. Astımda inhale kortikosteroit olmadan kullanılmaz. Titreme ve çarpıntı görülebilir. Kullanım düzenini hekim belirler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fosfolipidi sjemena soje
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (294, 'Essential phospholipids from soybean seeds, a supportive agent for liver cells.', 'Esencijalni fosfolipidi iz sjemena soje, preparat za podršku ćelijama jetre.', 'Есенцијални фосфолипиди из сјемена соје, препарат за подршку ћелијама јетре.', 'Эссенциальные фосфолипиды из семян сои, средство для поддержки клеток печени.', 'Essenzielle Phospholipide aus Sojabohnen, ein Mittel zur Unterstützung der Leberzellen.', 'Soya tohumundan elde edilen, karaciğer hücrelerini desteklemek için kullanılan esansiyel fosfolipitlerdir.', 'Used as a supportive treatment in fatty liver disease, toxic liver damage and chronic hepatitis.', 'Primjenjuje se kao pomoćna terapija kod masne jetre, toksičnih oštećenja jetre i hroničnih hepatitisa.', 'Примјењује се као помоћна терапија код масне јетре, токсичних оштећења јетре и хроничних хепатитиса.', 'Применяют как вспомогательное средство при жировой болезни печени, токсических поражениях печени и при хронических гепатитах.', 'Wird unterstützend bei Fettleber, toxischen Leberschäden und chronischer Hepatitis eingesetzt.', 'Karaciğer yağlanmasında, toksik karaciğer hasarında ve kronik hepatitte destekleyici olarak kullanılır.', 'Available over the counter. Evidence for its effect is limited and it does not replace treatment of the underlying disease. Not used in soy allergy.', 'Izdaje se bez recepta. Dokazi o djelovanju su ograničeni i ne zamjenjuje liječenje osnovne bolesti. Ne primjenjuje se kod alergije na soju.', 'Издаје се без рецепта. Докази о дјеловању су ограничени и не замјењује лијечење основне болести. Не примјењује се код алергије на соју.', 'Отпускается без рецепта. Доказательная база ограничена, средство не заменяет лечение основной болезни. При аллергии на сою не применяют.', 'Rezeptfrei erhältlich. Die Studienlage ist begrenzt, es ersetzt die Behandlung der Grunderkrankung nicht. Bei Sojaallergie nicht anwenden.', 'Reçetesiz satılır. Etkisine dair kanıtlar sınırlıdır, altta yatan hastalığın tedavisinin yerini tutmaz. Soya alerjisinde kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- fosfor
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (296, 'A mineral found in bones and teeth and involved in energy metabolism. In medicines it appears as part of vitamin and mineral supplements.', 'Mineral koji ulazi u kosti i zube i učestvuje u energetskom metabolizmu. U lijekovima se javlja u vitaminsko-mineralnim preparatima.', 'Минерал који улази у кости и зубе и учествује у енергетском метаболизму. У лијековима се јавља у витаминско-минералним препаратима.', 'Минерал, входящий в состав костей и зубов и участвующий в обмене энергии. В лекарствах встречается в витаминно-минеральных комплексах.', 'Ein Mineralstoff in Knochen und Zähnen, beteiligt am Energiestoffwechsel. In Arzneimitteln kommt er als Teil von Vitamin-Mineral-Präparaten vor.', 'Kemik ve dişlerde bulunan, enerji metabolizmasında rol alan bir mineraldir. İlaçlarda vitamin-mineral preparatlarının içinde yer alır.', 'It is included in multivitamin supplements used with a limited diet and increased demands, including in children.', 'Ulazi u multivitaminske preparate koji se koriste kod jednolične ishrane i pojačanih napora, i kod djece.', 'Улази у мултивитаминске препарате који се користе код једноличне исхране и појачаних напора, и код дјеце.', 'Входит в поливитаминные комплексы, которые применяют при однообразном питании и повышенных нагрузках, в том числе у детей.', 'Er ist Bestandteil von Multivitaminpräparaten, die bei einseitiger Ernährung und erhöhtem Bedarf, auch bei Kindern, verwendet werden.', 'Tek düze beslenmede ve artmış gereksinimlerde, çocuklarda da kullanılan multivitamin preparatlarının bileşenidir.', 'Such supplements are over the counter. Food usually supplies enough phosphorus, so extra intake is rarely needed. With kidney disease, only as advised.', 'Ti preparati izdaju se bez recepta. Hranom se obično unese dovoljno fosfora, pa poseban unos rijetko treba. Kod bolesti bubrega samo po savjetu ljekara.', 'Ти препарати издају се без рецепта. Храном се обично унесе довољно фосфора, па посебан унос ријетко треба. Код болести бубрега само по савјету љекара.', 'Такие комплексы безрецептурные. С пищей фосфора обычно достаточно, отдельный приём нужен редко. При болезнях почек — только по назначению врача.', 'Diese Präparate sind rezeptfrei. Über die Nahrung wird meist genug Phosphor aufgenommen. Bei Nierenkrankheiten nur nach ärztlicher Anweisung.', 'Bu preparatlar reçetesizdir. Fosfor genellikle besinlerle yeterince alınır, ayrıca alım nadiren gerekir. Böbrek hastalığında hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- gabapentin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (303, 'An anticonvulsant that also reduces nerve pain.', 'Antiepileptik koji smanjuje i neuropatski bol.', 'Антиепилептик који смањује и неуропатски бол.', 'Противосудорожное средство, которое также уменьшает нейропатическую боль.', 'Ein Antiepileptikum, das auch Nervenschmerzen lindert.', 'Sinir ağrısını da azaltan bir antiepileptik ilaçtır.', 'Used as part of epilepsy treatment and for neuropathic pain, including after shingles and in diabetes.', 'Primjenjuje se u sklopu liječenja epilepsije i kod neuropatskog bola, uključujući bol poslije herpes zostera i kod dijabetesa.', 'Примјењује се у склопу лијечења епилепсије и код неуропатског бола, укључујући бол послије херпес зостера и код дијабетеса.', 'Применяют при эпилепсии в составе комплексной терапии и при нейропатической боли, в том числе после опоясывающего лишая и при диабете.', 'Wird als Teil der Epilepsiebehandlung und bei Nervenschmerzen eingesetzt, unter anderem nach Gürtelrose und bei Diabetes.', 'Epilepsi tedavisinin bir parçası olarak ve zona sonrası ile diyabete bağlı sinir ağrılarında kullanılır.', 'Prescription only. It causes drowsiness and dizziness and affects driving, alcohol increases the effect. Stopping abruptly is dangerous, only a doctor changes treatment.', 'Izdaje se samo na recept. Izaziva pospanost i vrtoglavicu, utiče na vožnju, a alkohol pojačava dejstvo. Naglo prekidanje je opasno, terapiju mijenja ljekar.', 'Издаје се само на рецепт. Изазива поспаност и вртоглавицу, утиче на вожњу, а алкохол појачава дејство. Нагло прекидање је опасно, терапију мијења љекар.', 'Только по рецепту. Вызывает сонливость и головокружение, влияет на вождение, алкоголь усиливает эффект. Резкая отмена опасна, лечение меняет только врач.', 'Verschreibungspflichtig. Macht müde und schwindelig, beeinflusst das Fahren, Alkohol verstärkt die Wirkung. Abruptes Absetzen ist gefährlich, Änderungen nur beim Arzt.', 'Yalnızca reçeteyle verilir. Uyku hali ve baş dönmesi yapar, araç kullanımını etkiler, alkol etkisini artırır. Aniden kesilmesi tehlikelidir, tedaviyi hekim değiştirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- glicerol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (317, 'Glycerol is a mild osmotic laxative that draws water into the bowel.', 'Glicerol je blago osmotsko laksativno sredstvo koje privlači vodu u crijevo.', 'Глицерол је благо осмотско лаксативно средство које привлачи воду у цријево.', 'Глицерол — осмотическое слабительное мягкого действия, которое притягивает воду в кишечнике.', 'Glycerol ist ein mild wirkendes osmotisches Abführmittel, das Wasser in den Darm zieht.', 'Gliserol, bağırsağa su çeken hafif etkili ozmotik bir müshildir.', 'Used for occasional constipation to soften the stool and make bowel emptying easier, including in children.', 'Primjenjuje se kod povremenog zatvora da omekša stolicu i olakša pražnjenje crijeva, uključujući i kod djece.', 'Примјењује се код повременог затвора да омекша столицу и олакша пражњење цријева, укључујући и код дјеце.', 'Применяют при эпизодических запорах, чтобы размягчить стул и облегчить опорожнение кишечника, в том числе у детей.', 'Wird bei gelegentlicher Verstopfung eingesetzt, um den Stuhl weicher zu machen und die Entleerung zu erleichtern, auch bei Kindern.', 'Ara sıra görülen kabızlıkta dışkıyı yumuşatmak ve bağırsak boşalmasını kolaylaştırmak için, çocuklarda da kullanılır.', 'Intended for short-term use, as constant use disturbs the natural bowel rhythm. Chronic constipation, abdominal pain or blood in the stool needs a doctor.', 'Namijenjen je kratkotrajnoj primjeni, stalna upotreba remeti prirodni ritam crijeva. Hronični zatvor, bol u trbuhu ili krv u stolici traže pregled ljekara.', 'Намијењен је краткотрајној примјени, стална употреба ремети природни ритам цријева. Хронични затвор, бол у трбуху или крв у столици траже преглед љекара.', 'Средство для короткого применения, постоянное использование нарушает естественный ритм кишечника. При хроническом запоре, боли в животе или крови в стуле нужен врач.', 'Nur zur kurzzeitigen Anwendung, ständiger Gebrauch stört den natürlichen Darmrhythmus. Chronische Verstopfung, Bauchschmerzen oder Blut im Stuhl gehören ärztlich abgeklärt.', 'Kısa süreli kullanım içindir, sürekli kullanım bağırsağın doğal ritmini bozar. Kronik kabızlık, karın ağrısı veya dışkıda kan varsa hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- glikopironijum bromid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (320, 'A long-acting inhaled anticholinergic that relaxes the muscles of the airways. It comes in combination products.', 'Inhalacioni antiholinergik dugog djelovanja koji opušta mišiće disajnih puteva. Dolazi u kombinovanim preparatima.', 'Инхалациони антихолинергик дугог дјеловања који опушта мишиће дисајних путева. Долази у комбинованим препаратима.', 'Ингаляционное холинолитическое вещество длительного действия, расслабляющее мышцы бронхов. Входит в состав комбинированных препаратов.', 'Ein lang wirksames inhalatives Anticholinergikum, das die Atemwegsmuskulatur entspannt. Es steckt in Kombinationspräparaten.', 'Solunum yolu kaslarını gevşeten uzun etkili inhale bir antikolinerjiktir. Kombine preparatlarda bulunur.', 'Used for long-term treatment of COPD, reducing breathlessness and flare-ups; some combinations are also used in asthma.', 'Primjenjuje se u dugotrajnom liječenju HOBP, smanjuje nedostatak vazduha i pogoršanja, a neke kombinacije se koriste i kod astme.', 'Примјењује се у дуготрајном лијечењу ХОБП, смањује недостатак ваздуха и погоршања, а неке комбинације се користе и код астме.', 'Применяют для длительного лечения ХОБЛ: уменьшает одышку и число обострений, в некоторых комбинациях применяется и при астме.', 'Wird zur Langzeitbehandlung der COPD eingesetzt und mindert Atemnot und Verschlechterungen; manche Kombinationen auch bei Asthma.', 'KOAH''ın uzun süreli tedavisinde nefes darlığını ve alevlenmeleri azaltmak için, bazı kombinasyonlarda astımda da kullanılır.', 'Prescription only. It is not used to relieve an attack. Dry mouth is possible; with glaucoma or difficulty passing urine the doctor weighs the risk.', 'Izdaje se na recept. Ne koristi se za prekid napada. Moguća je suvoća usta, a kod glaukoma i otežanog mokrenja rizik procjenjuje ljekar.', 'Издаје се на рецепт. Не користи се за прекид напада. Могућа је сувоћа уста, а код глаукома и отежаног мокрења ризик процјењује љекар.', 'Отпускается по рецепту. Не используется для снятия приступа. Возможна сухость во рту; при глаукоме и затруднённом мочеиспускании риск оценивает врач.', 'Verschreibungspflichtig. Nicht zur Behandlung eines akuten Anfalls. Mundtrockenheit ist möglich; bei Glaukom und Blasenproblemen wägt der Arzt ab.', 'Reçeteye tabidir. Atağı geçirmek için kullanılmaz. Ağız kuruluğu olabilir; glokom ve idrar yapma güçlüğünde hekim riski değerlendirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- glukozamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (325, 'An amino sugar that occurs naturally in cartilage, used as a joint remedy.', 'Amino šećer koji se prirodno nalazi u hrskavici, koristi se kao preparat za zglobove.', 'Амино шећер који се природно налази у хрскавици, користи се као препарат за зглобове.', 'Аминосахар, естественный компонент хряща, применяется как средство для суставов.', 'Ein Aminozucker, natürlicher Bestandteil des Knorpels, wird als Mittel für die Gelenke verwendet.', 'Kıkırdakta doğal olarak bulunan bir amino şeker, eklemlere yönelik preparatlarda kullanılır.', 'Used for osteoarthritis, most often of the knee, with joint pain and stiffness.', 'Primjenjuje se kod osteoartroze, najčešće koljena, uz bol i ukočenost zglobova.', 'Примјењује се код остеоартрозе, најчешће кољена, уз бол и укоченост зглобова.', 'Применяют при остеоартрозе, чаще всего коленного сустава, при боли и скованности в суставах.', 'Wird bei Arthrose, meist des Knies, bei Gelenkschmerzen und Steifigkeit angewendet.', 'Çoğunlukla diz olmak üzere osteoartrozda, eklem ağrısı ve tutuklukta kullanılır.', 'Available without prescription. The effect builds slowly and is not seen in everyone. Care with shellfish allergy, diabetes and blood thinners.', 'Izdaje se bez recepta. Djelovanje nastupa sporo i nije kod svih. Oprez kod alergije na morske plodove, dijabetesa i lijekova protiv zgrušavanja.', 'Издаје се без рецепта. Дјеловање наступа споро и није код свих. Опрез код алергије на морске плодове, дијабетеса и лијекова против згрушавања.', 'Отпускается без рецепта. Действие развивается медленно и заметно не у всех. Осторожно при аллергии на морепродукты, диабете и приёме антикоагулянтов.', 'Rezeptfrei erhältlich. Die Wirkung setzt langsam ein und tritt nicht bei allen auf. Vorsicht bei Meeresfrüchteallergie, Diabetes und Blutverdünnern.', 'Reçetesiz satılır. Etkisi yavaş başlar ve herkeste görülmez. Deniz ürünü alerjisi, diyabet ve kan sulandırıcı kullanımında dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- haloperidol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (338, 'A first-generation antipsychotic from the butyrophenone group.', 'Antipsihotik prve generacije iz grupe butirofenona.', 'Антипсихотик прве генерације из групе бутирофенона.', 'Антипсихотическое средство первого поколения из группы бутирофенонов.', 'Ein Antipsychotikum der ersten Generation aus der Gruppe der Butyrophenone.', 'Bütirofenon grubundan birinci kuşak bir antipsikotiktir.', 'Used in schizophrenia and other psychotic states, in severe agitation, and in certain movement disorders.', 'Primjenjuje se kod šizofrenije i drugih psihotičnih stanja, kod izražene uznemirenosti i kod pojedinih poremećaja pokreta.', 'Примјењује се код шизофреније и других психотичних стања, код изражене узнемирености и код појединих поремећаја покрета.', 'Применяют при шизофрении и других психотических состояниях, при выраженном возбуждении, а также при некоторых двигательных расстройствах.', 'Wird bei Schizophrenie und anderen psychotischen Zuständen, bei starker Unruhe und bei bestimmten Bewegungsstörungen eingesetzt.', 'Şizofreni ve diğer psikotik durumlarda, belirgin huzursuzlukta ve bazı hareket bozukluklarında kullanılır.', 'Prescription only and supervised by a psychiatrist. Movement side effects and drowsiness are possible and affect driving. It must not be stopped on your own.', 'Izdaje se na recept, terapiju vodi psihijatar. Mogući su poremećaji pokreta i pospanost, što utiče na vožnju. Terapija se ne prekida samostalno.', 'Издаје се на рецепт, терапију води психијатар. Могући су поремећаји покрета и поспаност, што утиче на вожњу. Терапија се не прекида самостално.', 'Отпускается по рецепту, лечение ведёт психиатр. Возможны двигательные нарушения и сонливость, влияет на вождение. Прекращать приём самостоятельно нельзя.', 'Verschreibungspflichtig, die Behandlung führt ein Psychiater. Bewegungsstörungen und Müdigkeit sind möglich und beeinflussen das Fahren. Nicht eigenmächtig absetzen.', 'Reçeteye tabidir, tedaviyi psikiyatri hekimi yürütür. Hareket bozuklukları ve uyku hali görülebilir, araç kullanımını etkiler. Kendi başına bırakılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- heksetidin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (339, 'An antiseptic for local use in the mouth and throat.', 'Antiseptik za lokalnu primjenu u usnoj duplji i grlu.', 'Антисептик за локалну примјену у усној дупљи и грлу.', 'Антисептик для местного применения в полости рта и горле.', 'Ein Antiseptikum zur örtlichen Anwendung in Mund und Rachen.', 'Ağız ve boğazda bölgesel kullanılan bir antiseptiktir.', 'Used for inflamed gums and mouth lining, sore throat, after dental procedures and for bad breath.', 'Primjenjuje se kod upale desni i sluznice usta, bola u grlu, poslije stomatoloških zahvata i kod neprijatnog zadaha.', 'Примјењује се код упале десни и слузнице уста, бола у грлу, послије стоматолошких захвата и код непријатног задаха.', 'Применяют при воспалении дёсен и слизистой рта, боли в горле, после стоматологических вмешательств, при неприятном запахе изо рта.', 'Wird bei Zahnfleisch- und Mundschleimhautentzündung, Halsschmerzen, nach zahnärztlichen Eingriffen und bei Mundgeruch angewendet.', 'Diş eti ve ağız mukozası iltihabında, boğaz ağrısında, diş işlemlerinden sonra ve ağız kokusunda kullanılır.', 'Over the counter. The solution is not swallowed. Temporary burning and taste changes are possible. Not given to small children who cannot rinse and spit.', 'Izdaje se bez recepta. Rastvor se ne guta. Mogući su prolazno peckanje i promjena ukusa. Ne daje se maloj djeci koja ne umiju da ispljunu.', 'Издаје се без рецепта. Раствор се не гута. Могући су пролазно пецкање и промјена укуса. Не даје се малој дјеци која не умију да испљуну.', 'Отпускается без рецепта. Раствор не проглатывают. Возможны временное жжение и изменение вкуса. Маленьким детям, которые не умеют выплёвывать, не дают.', 'Rezeptfrei. Die Lösung wird nicht geschluckt. Vorübergehendes Brennen und Geschmacksveränderungen sind möglich. Nicht für kleine Kinder, die nicht ausspucken können.', 'Reçetesiz satılır. Çözelti yutulmaz. Geçici yanma ve tat değişikliği olabilir. Gargarayı tükürmeyi beceremeyen küçük çocuklara verilmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- heparin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (341, 'An anticoagulant that slows blood clotting.', 'Antikoagulans koji usporava zgrušavanje krvi.', 'Антикоагуланс који успорава згрушавање крви.', 'Антикоагулянт, который препятствует свёртыванию крови.', 'Ein Antikoagulans, das die Blutgerinnung hemmt.', 'Kanın pıhtılaşmasını yavaşlatan bir antikoagülandır.', 'Injectable forms are used to prevent and treat thrombosis, external forms for bruises, haematomas and heavy legs with varicose veins.', 'Injekcioni oblici koriste se za prevenciju i liječenje tromboze, spoljni kod nagnječenja, hematoma i teških nogu sa proširenim venama.', 'Ињекциони облици користе се за превенцију и лијечење тромбозе, спољни код нагњечења, хематома и тешких ногу са проширеним венама.', 'Инъекционные формы применяют для профилактики и лечения тромбозов, наружные — при ушибах, гематомах и тяжести в ногах при варикозе.', 'Injektionsformen dienen der Vorbeugung und Behandlung von Thrombosen, äußere Formen bei Prellungen, Blutergüssen und schweren Beinen.', 'Enjeksiyon formları tromboz önleme ve tedavisinde, dıştan kullanılanlar berelenme, hematom ve varise bağlı bacak ağırlığında kullanılır.', 'External forms are over the counter, injections only on a doctor''s orders. Not applied to open wounds or mucous membranes. With clotting disorders, see a doctor.', 'Spoljni oblici izdaju se bez recepta, injekcije samo po nalogu ljekara. Ne nanose se na otvorene rane i sluznice. Kod poremećaja zgrušavanja potreban je pregled.', 'Спољни облици издају се без рецепта, ињекције само по налогу љекара. Не наносе се на отворене ране и слузнице. Код поремећаја згрушавања потребан је преглед.', 'Наружные формы безрецептурные, инъекционные — только по назначению врача. Не наносят на открытые раны и слизистые. При нарушениях свёртывания крови нужен осмотр врача.', 'Äußere Formen sind rezeptfrei, Injektionen nur auf ärztliche Anordnung. Nicht auf offene Wunden und Schleimhäute auftragen. Bei Gerinnungsstörungen zum Arzt.', 'Dıştan kullanılan formlar reçetesizdir, enjeksiyonlar yalnızca hekim kararıyla uygulanır. Açık yara ve mukozaya sürülmez. Pıhtılaşma bozukluğunda hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- heparin natrijum
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (342, 'Heparin sodium is an anticoagulant; in products sold over the counter it is used only on the skin.', 'Heparin natrijum je antikoagulans; u lijekovima bez recepta koristi se samo spolja, na koži.', 'Хепарин натријум је антикоагуланс; у лијековима без рецепта користи се само споља, на кожи.', 'Гепарин натрия — антикоагулянт; в аптечных безрецептурных препаратах применяется только наружно.', 'Heparin-Natrium ist ein Gerinnungshemmer; rezeptfrei wird es nur äußerlich auf der Haut angewendet.', 'Heparin sodyum bir pıhtılaşma önleyicidir; reçetesiz ürünlerde yalnızca deri üzerine uygulanır.', 'Applied to the skin for bruises and haematomas, superficial thrombophlebitis and heavy, swollen legs in varicose disease.', 'Spolja se primjenjuje kod nagnječenja i hematoma, površinskog tromboflebitisa i kod težine i otoka nogu sa proširenim venama.', 'Споља се примјењује код нагњечења и хематома, површинског тромбофлебитиса и код тежине и отока ногу са проширеним венама.', 'Наружно применяют при ушибах и гематомах, поверхностном тромбофлебите, тяжести и отёках в ногах при варикозе.', 'Äußerlich bei Prellungen und Blutergüssen, oberflächlicher Venenentzündung sowie schweren, geschwollenen Beinen bei Krampfadern.', 'Cilde uygulandığında morluk ve hematomlarda, yüzeyel tromboflebitte, varise bağlı bacak ağırlığı ve şişliğinde kullanılır.', 'Not for open wounds or mucous membranes. With bleeding disorders, blood-thinning medicines or in pregnancy, use only as directed by a doctor.', 'Ne nanosi se na otvorene rane i sluznice. Kod poremećaja zgrušavanja krvi, uz lijekove za razrjeđivanje krvi i u trudnoći samo po savjetu ljekara.', 'Не наноси се на отворене ране и слузнице. Код поремећаја згрушавања крви, уз лијекове за разрјеђивање крви и у трудноћи само по савјету љекара.', 'Не наносят на открытые раны и слизистые. При нарушениях свёртывания крови, приёме разжижающих кровь препаратов и при беременности — только по назначению врача.', 'Nicht auf offene Wunden oder Schleimhäute auftragen. Bei Gerinnungsstörungen, blutverdünnenden Medikamenten und in der Schwangerschaft nur ärztlich verordnet.', 'Açık yaralara ve mukozaya sürülmez. Kanama bozukluğu, kan sulandırıcı ilaç kullanımı ve gebelikte yalnızca hekim önerisiyle uygulanır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hesperidin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (343, 'Hesperidin is a citrus flavonoid with venotonic action, used mainly in combination with diosmin.', 'Hesperidin je flavonoid iz citrusa sa venotonskim djelovanjem, koristi se uglavnom u kombinaciji sa diosminom.', 'Хесперидин је флавоноид из цитруса са венотонским дјеловањем, користи се углавном у комбинацији са диосмином.', 'Гесперидин — цитрусовый флавоноид с венотонизирующим действием, применяется в основном в комбинации с диосмином.', 'Hesperidin ist ein Zitrusflavonoid mit venentonisierender Wirkung, meist kombiniert mit Diosmin.', 'Hesperidin, narenciyeden elde edilen ve diosminle birlikte kullanılan, damar tonusunu artıran bir flavonoiddir.', 'Part of combination products used for chronic venous insufficiency of the legs and for haemorrhoids.', 'Ulazi u kombinovane lijekove koji se primjenjuju kod hronične venske insuficijencije nogu i kod hemoroida.', 'Улази у комбиноване лијекове који се примјењују код хроничне венске инсуфицијенције ногу и код хемороида.', 'Входит в комбинированные препараты, которые применяют при хронической венозной недостаточности ног и при геморрое.', 'Bestandteil von Kombinationspräparaten bei chronischer Venenschwäche der Beine und bei Hämorrhoiden.', 'Bacaklarda kronik venöz yetmezlik ve hemoroit için kullanılan kombine ürünlerin bileşenidir.', 'Available without prescription, but persistent swelling, pain or bleeding needs medical assessment. In pregnancy and breastfeeding only as prescribed.', 'Izdaje se bez recepta, ali uporan otok, bol ili krvarenje traže pregled ljekara. U trudnoći i tokom dojenja samo po savjetu ljekara.', 'Издаје се без рецепта, али упоран оток, бол или крварење траже преглед љекара. У трудноћи и током дојења само по савјету љекара.', 'Безрецептурное средство, но при стойких отёках, боли или кровотечении нужен осмотр врача. При беременности и кормлении — только по назначению врача.', 'Rezeptfrei, doch anhaltende Schwellung, Schmerzen oder Blutungen ärztlich abklären lassen. In Schwangerschaft und Stillzeit nur nach ärztlicher Anweisung.', 'Reçetesiz satılır, ancak geçmeyen şişlik, ağrı veya kanamada hekim değerlendirmesi gerekir. Gebelikte ve emzirmede yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hidrohlortiazid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (344, 'A thiazide diuretic. It is most often part of combination products for high blood pressure together with other agents.', 'Tiazidni diuretik. Najčešće je dio kombinovanih lijekova za povišen pritisak, zajedno sa drugim supstancama.', 'Тиазидни диуретик. Најчешће је дио комбинованих лијекова за повишен притисак, заједно са другим супстанцама.', 'Тиазидный мочегонный препарат. Чаще всего входит в комбинированные средства от повышенного давления вместе с другими веществами.', 'Ein Thiaziddiuretikum. Meist ist es Bestandteil von Kombinationspräparaten gegen Bluthochdruck zusammen mit anderen Wirkstoffen.', 'Tiyazid grubu bir idrar söktürücüdür. Çoğunlukla yüksek tansiyon için hazırlanan kombine ilaçların bileşenidir.', 'Used for arterial hypertension and for oedema related to heart failure or kidney disease.', 'Primjenjuje se kod povišenog krvnog pritiska i kod otoka uz srčanu slabost ili bolesti bubrega.', 'Примјењује се код повишеног крвног притиска и код отока уз срчану слабост или болести бубрега.', 'Применяют при артериальной гипертензии и при отёках, связанных с сердечной недостаточностью или болезнями почек.', 'Wird bei Bluthochdruck und bei Ödemen im Rahmen von Herzschwäche oder Nierenerkrankungen eingesetzt.', 'Yüksek tansiyonda ve kalp yetmezliği ya da böbrek hastalığına bağlı ödemde kullanılır.', 'Prescription only. It removes potassium and sodium, so the doctor monitors blood tests. It increases sun sensitivity and can affect blood sugar and uric acid.', 'Izdaje se na recept. Izbacuje kalijum i natrijum, pa ljekar prati nalaze krvi. Povećava osjetljivost na sunce i može uticati na šećer i mokraćnu kiselinu.', 'Издаје се на рецепт. Избацује калијум и натријум, па љекар прати налазе крви. Повећава осјетљивост на сунце и може утицати на шећер и мокраћну киселину.', 'Отпускается по рецепту. Выводит калий и натрий, поэтому врач контролирует анализы крови. Повышает чувствительность к солнцу, влияет на уровень сахара и мочевой кислоты.', 'Verschreibungspflichtig. Es schwemmt Kalium und Natrium aus, daher kontrolliert der Arzt die Blutwerte. Es erhöht die Lichtempfindlichkeit und beeinflusst Blutzucker und Harnsäure.', 'Yalnızca reçeteyle verilir. Potasyum ve sodyum kaybına yol açtığı için hekim kan değerlerini izler. Güneşe duyarlılığı artırır, kan şekerini ve ürik asidi etkileyebilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hidrotalcit
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (350, 'An antacid based on aluminium and magnesium that binds excess stomach acid.', 'Antacid na bazi aluminijuma i magnezijuma koji vezuje višak želudačne kiseline.', 'Антацид на бази алуминијума и магнезијума који везује вишак желудачне киселине.', 'Антацид на основе алюминия и магния: связывает избыток соляной кислоты в желудке.', 'Ein Antazidum aus Aluminium und Magnesium, das überschüssige Magensäure bindet.', 'Fazla mide asidini bağlayan, alüminyum ve magnezyum içeren bir antasittir.', 'Used for heartburn, acid reflux and stomach discomfort, including after a large or spicy meal.', 'Primjenjuje se kod žgaravice, kiselog podrigivanja i nelagode u želucu, i poslije obilnog ili začinjenog obroka.', 'Примјењује се код жгаравице, киселог подригивања и нелагоде у желуцу, и послије обилног или зачињеног оброка.', 'Применяют при изжоге, кислой отрыжке и дискомфорте в желудке, в том числе после обильной или острой еды.', 'Wird bei Sodbrennen, saurem Aufstoßen und Magenbeschwerden angewendet, auch nach einer üppigen oder scharfen Mahlzeit.', 'Mide yanmasında, ekşi geğirmede ve mide rahatsızlığında, ağır ya da baharatlı yemek sonrasında da kullanılır.', 'Available over the counter and meant for short use. It hinders the absorption of other medicines, so they are taken at a different time. With kidney disease, see a doctor.', 'Izdaje se bez recepta i namijenjen je kratkotrajnoj upotrebi. Ometa apsorpciju drugih lijekova, pa se oni uzimaju u drugo vrijeme. Kod bolesti bubrega po savjetu ljekara.', 'Издаје се без рецепта и намијењен је краткотрајној употреби. Омета апсорпцију других лијекова, па се они узимају у друго вријеме. Код болести бубрега по савјету љекара.', 'Отпускается без рецепта и предназначен для короткого применения. Мешает усвоению других лекарств, их принимают отдельно по времени. При болезнях почек — по назначению врача.', 'Rezeptfrei und nur für kurze Anwendung gedacht. Es behindert die Aufnahme anderer Arzneimittel, diese zeitlich versetzt einnehmen. Bei Nierenkrankheiten zum Arzt.', 'Reçetesiz satılır ve kısa süreli kullanım içindir. Diğer ilaçların emilimini engeller, bu yüzden onlar ayrı saatte alınır. Böbrek hastalığında hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- himekromon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (351, 'A choleretic with an antispasmodic action that relaxes the bile ducts and eases bile flow.', 'Sredstvo koje pojačava otjecanje žuči i opušta žučne puteve, sa spazmolitičkim djelovanjem.', 'Средство које појачава отјецање жучи и опушта жучне путеве, са спазмолитичким дјеловањем.', 'Желчегонное вещество со спазмолитическим действием: расслабляет желчные пути и облегчает отток желчи.', 'Ein gallenwirksames, krampflösendes Mittel, das die Gallenwege entspannt und den Gallenfluss erleichtert.', 'Safra yollarını gevşetip safra akışını kolaylaştıran, antispazmodik etkili bir maddedir.', 'Used for spasm of the bile ducts and the pain it causes, for biliary dyskinesia and after gallbladder surgery.', 'Primjenjuje se kod grčeva žučnih puteva i bolova koje oni izazivaju, kod diskinezije žučnih puteva i poslije operacije žučne kese.', 'Примјењује се код грчева жучних путева и болова које они изазивају, код дискинезије жучних путева и послије операције жучне кесе.', 'Применяют при спазмах желчных путей и связанной с ними боли, при дискинезии желчевыводящих путей и после операций на желчном пузыре.', 'Wird bei Krämpfen der Gallenwege und den dadurch bedingten Schmerzen, bei Gallenwegsdyskinesie und nach Gallenblasenoperationen eingesetzt.', 'Safra yolu spazmlarında ve buna bağlı ağrıda, safra yolu diskinezisinde ve safra kesesi ameliyatı sonrasında kullanılır.', 'Available over the counter. Not used when the bile ducts are blocked. Lasting pain in the right upper abdomen needs a doctor, in pregnancy only as prescribed.', 'Izdaje se bez recepta. Ne primjenjuje se kod zapušenja žučnih puteva. Uporan bol pod desnim rebrima traži pregled, u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта. Не примјењује се код запушења жучних путева. Упоран бол под десним ребрима тражи преглед, у трудноћи само по савјету љекара.', 'Отпускается без рецепта. При закупорке желчных путей не применяют. Стойкая боль в правом подреберье требует осмотра врача, при беременности — по назначению.', 'Rezeptfrei erhältlich. Bei verschlossenen Gallenwegen nicht anwenden. Anhaltende Schmerzen im rechten Oberbauch gehören zum Arzt, in der Schwangerschaft nur nach Anweisung.', 'Reçetesiz satılır. Safra yolları tıkalıysa kullanılmaz. Sağ üst karında geçmeyen ağrı hekim muayenesi gerektirir, gebelikte hekim önerisi gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hioscin butilbromid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (352, 'An antispasmodic with an anticholinergic action that relaxes smooth muscle in the abdomen.', 'Spazmolitik sa antiholinergičkim djelovanjem koji opušta glatke mišiće trbušnih organa.', 'Спазмолитик са антихолинергичким дјеловањем који опушта глатке мишиће трбушних органа.', 'Спазмолитик с холиноблокирующим действием: расслабляет гладкие мышцы органов брюшной полости.', 'Ein krampflösendes Mittel mit anticholinerger Wirkung, das die glatte Muskulatur im Bauchraum entspannt.', 'Karın organlarındaki düz kasları gevşeten, antikolinerjik etkili bir antispazmodiktir.', 'Used for cramping abdominal pain, intestinal and biliary colic, painful periods, and in preparation for some examinations.', 'Primjenjuje se kod grčevitih bolova u trbuhu, crijevnih i žučnih kolika, bolnih menstruacija i u pripremi za pojedine preglede.', 'Примјењује се код грчевитих болова у трбуху, цријевних и жучних колика, болних менструација и у припреми за поједине прегледе.', 'Применяют при спастической боли в животе, кишечной и желчной колике, болезненных менструациях, а также при подготовке к обследованиям.', 'Wird bei krampfartigen Bauchschmerzen, Darm- und Gallenkoliken, schmerzhafter Regel und zur Vorbereitung auf Untersuchungen eingesetzt.', 'Kramp tarzı karın ağrısında, bağırsak ve safra koliğinde, ağrılı adet dönemlerinde ve bazı tetkiklerin hazırlığında kullanılır.', 'Tablets are over the counter, the injection is prescription only. With glaucoma, an enlarged prostate or lasting abdominal pain, see a doctor.', 'Tablete se izdaju bez recepta, injekcije samo po savjetu ljekara. Kod glaukoma, uvećane prostate i upornog bola u trbuhu potreban je pregled.', 'Таблете се издају без рецепта, ињекције само по савјету љекара. Код глаукома, увећане простате и упорног бола у трбуху потребан је преглед.', 'Таблетки безрецептурные, инъекции — только по назначению врача. При глаукоме, аденоме простаты и стойкой боли в животе нужна консультация врача.', 'Tabletten sind rezeptfrei, die Injektion ist verschreibungspflichtig. Bei Glaukom, vergrößerter Prostata und anhaltenden Bauchschmerzen zum Arzt.', 'Tabletleri reçetesizdir, enjeksiyon formu reçeteye tabidir. Glokom, prostat büyümesi ve geçmeyen karın ağrısında hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hipromeloza
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (353, 'A polymer that holds moisture on the eye surface, the base of artificial tears.', 'Polimer koji zadržava vlagu na površini oka, osnova vještačkih suza.', 'Полимер који задржава влагу на површини ока, основа вјештачких суза.', 'Полимер, удерживающий влагу на поверхности глаза; основа искусственных слёз.', 'Ein Polymer, das Feuchtigkeit auf der Augenoberfläche hält, Grundlage künstlicher Tränen.', 'Göz yüzeyinde nemi tutan bir polimerdir, suni gözyaşlarının temelini oluşturur.', 'Used for dryness and a gritty feeling in the eyes, during long screen work, with contact lenses and after an eye examination.', 'Primjenjuje se kod suvoće i osjećaja pijeska u očima, uz dug rad za ekranom, nošenje sočiva i poslije pregleda oka.', 'Примјењује се код сувоће и осјећаја пијеска у очима, уз дуг рад за екраном, ношење сочива и послије прегледа ока.', 'Применяют при сухости и ощущении песка в глазах, при долгой работе за экраном, ношении контактных линз и после осмотра глаза.', 'Wird bei Trockenheit und Sandkorngefühl im Auge, bei langer Bildschirmarbeit, beim Tragen von Kontaktlinsen und nach Augenuntersuchungen angewendet.', 'Göz kuruluğunda ve batma hissinde, uzun ekran çalışmasında, lens kullanımında ve göz muayenesi sonrasında kullanılır.', 'Available without prescription. It relieves dryness but does not remove its cause. With pain, persistent redness or worsening vision see an ophthalmologist.', 'Izdaje se bez recepta. Ublažava suvoću, ali ne uklanja njen uzrok. Uz bol, uporno crvenilo i slabljenje vida potreban je pregled oftalmologa.', 'Издаје се без рецепта. Ублажава сувоћу, али не уклања њен узрок. Уз бол, упорно црвенило и слабљење вида потребан је преглед офталмолога.', 'Отпускается без рецепта. Снимает сухость, но не устраняет её причину. При боли, стойком покраснении и ухудшении зрения нужен осмотр офтальмолога.', 'Rezeptfrei. Lindert die Trockenheit, beseitigt aber nicht deren Ursache. Bei Schmerzen, anhaltender Rötung und schlechterem Sehen zum Augenarzt.', 'Reçetesiz satılır. Kuruluğu giderir ancak nedenini ortadan kaldırmaz. Ağrı, geçmeyen kızarıklık ve görme azalmasında göz doktoruna başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hlorfenamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (356, 'Chlorphenamine is a first-generation antihistamine, most often found in combination cold remedies', 'Hlorfenamin je antihistaminik prve generacije; najčešće se nalazi u kombinovanim preparatima protiv prehlade', 'Хлорфенамин је антихистаминик прве генерације; најчешће се налази у комбинованим препаратима против прехладе', 'Хлорфенамин — антигистаминное средство первого поколения; чаще всего встречается в комбинированных средствах от простуды', 'Chlorphenamin ist ein Antihistaminikum der ersten Generation und vor allem in Erkältungskombinationen enthalten', 'Klorfenamin birinci kuşak bir antihistaminiktir; çoğunlukla kombine soğuk algınlığı ürünlerinde bulunur', 'Runny nose, sneezing, watery eyes and itching in colds and allergic reactions', 'Curenje iz nosa, kijanje, suzenje očiju i svrab kod prehlade i alergijskih reakcija', 'Цурење из носа, кијање, сузење очију и свраб код прехладе и алергијских реакција', 'Насморк, чихание, слезотечение и зуд при простуде и аллергических реакциях', 'Laufende Nase, Niesen, tränende Augen und Juckreiz bei Erkältung und allergischen Reaktionen', 'Soğuk algınlığı ve alerjik tepkilerde burun akıntısı, hapşırma, gözlerde sulanma ve kaşıntı', 'Causes drowsiness, slows reactions and does not go with alcohol; take care when driving. With glaucoma, prostate enlargement, in children and in pregnancy only as advised by a doctor.', 'Izaziva pospanost, usporava reakcije i ne kombinuje se sa alkoholom; oprez u vožnji. Kod glaukoma, uvećane prostate, kod djece i u trudnoći samo po savjetu ljekara.', 'Изазива поспаност, успорава реакције и не комбинује се са алкохолом; опрез у вожњи. Код глаукома, увећане простате, код дјеце и у трудноћи само по савјету љекара.', 'Вызывает сонливость, замедляет реакцию и не сочетается с алкоголем; за рулём — осторожно. При глаукоме, аденоме простаты, у детей и беременных — по назначению врача.', 'Macht müde, verlangsamt die Reaktion und verträgt sich nicht mit Alkohol; Vorsicht im Verkehr. Bei Glaukom, Prostatavergrößerung, bei Kindern und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Uyku hali yapar, tepkileri yavaşlatır ve alkolle birlikte kullanılmaz; araç kullanırken dikkat. Glokom, prostat büyümesi, çocuklar ve gebelikte yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- hloropiramin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (357, 'A first-generation antihistamine that blocks histamine in allergic reactions and often causes drowsiness.', 'Antihistaminik prve generacije koji blokira dejstvo histamina kod alergije i često izaziva pospanost.', 'Антихистаминик прве генерације који блокира дејство хистамина код алергије и често изазива поспаност.', 'Антигистаминное средство первого поколения: блокирует действие гистамина при аллергии, часто вызывает сонливость.', 'Ein Antihistaminikum der ersten Generation, das die Histaminwirkung bei Allergien hemmt und oft müde macht.', 'Alerjide histaminin etkisini engelleyen, sıklıkla uyku hali yapan birinci kuşak bir antihistaminiktir.', 'Used for hives, allergic rhinitis and conjunctivitis, itchy skin, reactions to insect bites and drug allergy.', 'Primjenjuje se kod koprivnjače, alergijskog rinitisa i konjunktivitisa, svraba kože, reakcija na ubode insekata i alergije na lijekove.', 'Примјењује се код копривњаче, алергијског ринитиса и коњунктивитиса, свраба коже, реакција на убоде инсеката и алергије на лијекове.', 'Применяют при крапивнице, аллергическом рините и конъюнктивите, кожном зуде, реакциях на укусы насекомых и лекарственной аллергии.', 'Wird bei Nesselsucht, allergischem Schnupfen und Bindehautentzündung, Hautjucken, Insektenstichen und Arzneimittelallergie angewendet.', 'Kurdeşende, alerjik nezle ve konjonktivitte, deri kaşıntısında, böcek sokması tepkilerinde ve ilaç alerjisinde kullanılır.', 'The topical form is over the counter, the injection is prescription only. It makes you drowsy, so avoid driving and alcohol. In children and pregnancy, only as advised.', 'Spoljni oblik je bez recepta, injekcije samo po savjetu ljekara. Izaziva pospanost, pa se ne kombinuje sa vožnjom i alkoholom. Djeci i trudnicama po savjetu ljekara.', 'Спољни облик је без рецепта, ињекције само по савјету љекара. Изазива поспаност, па се не комбинује са вожњом и алкохолом. Дјеци и трудницама по савјету љекара.', 'Наружная форма безрецептурная, инъекции — только по назначению врача. Вызывает сонливость, поэтому несовместимо с вождением и алкоголем. Детям — по назначению врача.', 'Die äußerliche Form ist rezeptfrei, die Injektion ist verschreibungspflichtig. Es macht müde, daher kein Autofahren und kein Alkohol. Bei Kindern nur nach Anweisung.', 'Dıştan kullanılan formu reçetesizdir, enjeksiyon formu reçeteye tabidir. Uyku hali yapar, araç kullanımı ve alkolle birleştirilmez. Çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- holekalciferol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (359, 'Vitamin D3, a fat-soluble vitamin that helps the body take up calcium and phosphorus. It also comes in combinations with calcium.', 'Vitamin D3, vitamin rastvorljiv u mastima, pomaže usvajanje kalcijuma i fosfora i potreban je za kosti. Ima i kombinacija sa kalcijumom.', 'Витамин D3, витамин растворљив у мастима, помаже усвајање калцијума и фосфора и потребан је за кости. Има и комбинација са калцијумом.', 'Витамин D3, жирорастворимый витамин: помогает усвоению кальция и фосфора и нужен для костей. Входит и в комбинации с кальцием.', 'Vitamin D3, ein fettlösliches Vitamin für die Aufnahme von Kalzium und Phosphor und für die Knochen, auch in Kombination mit Kalzium.', 'Kalsiyum ve fosforun emilimine yardımcı olan, kemikler için gerekli yağda çözünen D3 vitaminidir. Kalsiyumlu kombinasyonları da vardır.', 'Used for vitamin D deficiency, to prevent rickets in children, in osteoporosis and as part of vitamin and mineral supplements.', 'Primjenjuje se kod nedostatka vitamina D, za prevenciju rahitisa kod djece, kod osteoporoze i u vitaminsko-mineralnim preparatima.', 'Примјењује се код недостатка витамина Д, за превенцију рахитиса код дјеце, код остеопорозе и у витаминско-минералним препаратима.', 'Применяют при недостатке витамина D, для профилактики рахита у детей, при остеопорозе и в составе витаминно-минеральных комплексов.', 'Wird bei Vitamin-D-Mangel, zur Rachitisvorbeugung bei Kindern, bei Osteoporose und in Vitamin-Mineral-Präparaten eingesetzt.', 'D vitamini eksikliğinde, çocuklarda raşitizmden korunmada, osteoporozda ve vitamin-mineral preparatlarında kullanılır.', 'Some forms are over the counter, combinations with osteoporosis medicines are prescription only. The vitamin builds up in the body, so a doctor sets the course.', 'Dio oblika izdaje se bez recepta, kombinacije sa lijekovima za osteoporozu na recept. Vitamin se nakuplja u organizmu, pa trajanje određuje ljekar.', 'Дио облика издаје се без рецепта, комбинације са лијековима за остеопорозу на рецепт. Витамин се накупља у организму, па трајање одређује љекар.', 'Часть форм безрецептурная, комбинации с препаратами от остеопороза — по рецепту. Витамин накапливается в организме, поэтому курс определяет врач.', 'Ein Teil der Formen ist rezeptfrei, Kombinationen mit Osteoporosemitteln sind verschreibungspflichtig. Das Vitamin reichert sich an, daher entscheidet der Arzt.', 'Bazı formları reçetesizdir, osteoporoz ilaçlarıyla kombinasyonları reçeteye tabidir. Vücutta biriktiği için kullanım süresine hekim karar verir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ibuprofen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (364, 'A non-steroidal anti-inflammatory drug (NSAID) that relieves pain and lowers fever.', 'Nesteroidni antiinflamatorni lijek (NSAIL) koji smanjuje bol i temperaturu.', 'Нестероидни антиинфламаторни лијек (NSAIL) који смањује бол и температуру.', 'Нестероидное противовоспалительное средство (НПВС) с обезболивающим и жаропонижающим действием.', 'Ein nichtsteroidales Antirheumatikum (NSAR) gegen Schmerzen und Fieber.', 'Ağrıyı ve ateşi azaltan, steroid yapıda olmayan antiinflamatuar bir ilaçtır (NSAİİ).', 'Used for muscle, joint and back pain, headache and toothache, bruises and sprains, and for fever.', 'Primjenjuje se kod bolova u mišićima, zglobovima i leđima, glavobolje i zubobolje, kod nagnječenja i istegnuća i kod temperature.', 'Примјењује се код болова у мишићима, зглобовима и леђима, главобоље и зубобоље, код нагњечења и истегнућа и код температуре.', 'Применяют при боли в мышцах, суставах и спине, головной и зубной боли, при ушибах и растяжениях, при повышенной температуре.', 'Wird bei Muskel-, Gelenk- und Rückenschmerzen, Kopf- und Zahnschmerzen, Prellungen und Zerrungen sowie bei Fieber angewendet.', 'Kas, eklem ve sırt ağrısında, baş ve diş ağrısında, berelenme ve burkulmalarda, ateşte kullanılır.', 'Many forms are over the counter. It irritates the stomach lining. With ulcers, kidney or heart disease and in pregnancy, only on a doctor''s advice.', 'Mnogi oblici izdaju se bez recepta. Nadražuje sluznicu želuca. Kod čira, bolesti bubrega i srca i u trudnoći samo po savjetu ljekara.', 'Многи облици издају се без рецепта. Надражује слузницу желуца. Код чира, болести бубрега и срца и у трудноћи само по савјету љекара.', 'Многие формы безрецептурные. Раздражает слизистую желудка. При язве, болезнях почек и сердца, а также при беременности — только по назначению врача.', 'Viele Formen sind rezeptfrei. Es reizt die Magenschleimhaut. Bei Magengeschwür, Nieren- und Herzkrankheiten und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Birçok formu reçetesizdir. Mide mukozasını tahriş eder. Ülser, böbrek ve kalp hastalıklarında ve gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- indakaterol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (376, 'A long-acting beta-2 agonist for inhalation. In Montenegro it is available only combined with an anticholinergic.', 'Beta-2 agonist dugog djelovanja za inhalaciju. U Crnoj Gori je dostupan samo u kombinaciji sa antiholinergikom.', 'Бета-2 агонист дугог дјеловања за инхалацију. У Црној Гори је доступан само у комбинацији са антихолинергиком.', 'Бета-2-агонист длительного действия для ингаляций. В Черногории доступен только в комбинации с холинолитиком.', 'Ein lang wirksamer Beta-2-Agonist zum Inhalieren. In Montenegro gibt es ihn nur in Kombination mit einem Anticholinergikum.', 'İnhalasyon yoluyla kullanılan uzun etkili bir beta-2 agonistidir. Karadağ''da yalnızca antikolinerjikle kombine bulunur.', 'Used for long-term treatment of COPD: it eases breathlessness, improves exercise tolerance and reduces flare-ups.', 'Primjenjuje se u dugotrajnom liječenju HOBP: smanjuje nedostatak vazduha, poboljšava podnošenje napora i smanjuje pogoršanja.', 'Примјењује се у дуготрајном лијечењу ХОБП: смањује недостатак ваздуха, побољшава подношење напора и смањује погоршања.', 'Применяют для длительного лечения ХОБЛ: уменьшает одышку, улучшает переносимость нагрузки и снижает частоту обострений.', 'Wird zur Langzeitbehandlung der COPD eingesetzt: Er lindert Atemnot, verbessert die Belastbarkeit und senkt die Zahl der Verschlechterungen.', 'KOAH''ın uzun süreli tedavisinde kullanılır: nefes darlığını azaltır, efor kapasitesini artırır ve alevlenmeleri seyrekleştirir.', 'Prescription only. It is not used to relieve an attack. Cough after inhaling, tremor and palpitations are possible. The inhaler is used regularly, as prescribed.', 'Izdaje se na recept. Ne koristi se za prekid napada. Mogući su kašalj poslije udisaja, drhtavica i lupanje srca. Inhalator se koristi redovno, po uputstvu ljekara.', 'Издаје се на рецепт. Не користи се за прекид напада. Могући су кашаљ послије удисаја, дрхтавица и лупање срца. Инхалатор се користи редовно, по упутству љекара.', 'Отпускается по рецепту. Не используется для снятия приступа. Возможны кашель после вдоха, дрожь и сердцебиение. Ингалятор применяют регулярно, по назначению врача.', 'Verschreibungspflichtig. Nicht zur Anfallsbehandlung. Husten nach dem Einatmen, Zittern und Herzklopfen sind möglich. Der Inhalator wird regelmäßig angewendet.', 'Reçeteye tabidir. Atağı geçirmek için kullanılmaz. İnhalasyon sonrası öksürük, titreme ve çarpıntı olabilir. İnhaler hekimin belirttiği gibi düzenli kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- insulin aspart
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (383, 'A rapid-acting insulin analogue that starts working soon after injection.', 'Analog insulina brzog djelovanja koji počinje da djeluje ubrzo poslije primjene.', 'Аналог инсулина брзог дјеловања који почиње да дјелује убрзо послије примјене.', 'Аналог инсулина быстрого действия: начинает работать вскоре после введения.', 'Ein schnell wirkendes Insulinanalogon, das kurz nach der Gabe zu wirken beginnt.', 'Uygulamadan kısa süre sonra etkisi başlayan hızlı etkili bir insülin benzeridir.', 'Prescribed in type 1 and type 2 diabetes to control glucose around meals, usually together with a long-acting insulin.', 'Propisuje se kod dijabetesa tipa 1 i tipa 2 za kontrolu glukoze oko obroka, obično uz insulin dugog djelovanja.', 'Прописује се код дијабетеса типа 1 и типа 2 за контролу глукозе око оброка, обично уз инсулин дугог дјеловања.', 'Назначают при сахарном диабете 1 и 2 типа для контроля глюкозы вокруг приёмов пищи, обычно вместе с инсулином длительного действия.', 'Wird bei Typ-1- und Typ-2-Diabetes zur Blutzuckerkontrolle rund um die Mahlzeiten verordnet, meist neben einem Langzeitinsulin.', 'Tip 1 ve tip 2 diyabette öğün çevresinde şeker kontrolü için, genellikle uzun etkili insülinle birlikte reçete edilir.', 'Prescription only, injected under the skin. The main risk is low blood sugar, so its warning signs matter. A doctor sets the regimen, it is not changed on your own.', 'Izdaje se samo na recept, daje se pod kožu. Glavni rizik je nizak šećer, pa je važno prepoznati znake. Režim određuje ljekar i ne mijenja se samovoljno.', 'Издаје се само на рецепт, даје се под кожу. Главни ризик је низак шећер, па је важно препознати знаке. Режим одређује љекар и не мијења се самовољно.', 'Только по рецепту, вводится под кожу. Главный риск — гипогликемия, её признаки нужно знать. Схему определяет врач, менять её самостоятельно нельзя.', 'Verschreibungspflichtig, Gabe unter die Haut. Hauptrisiko ist die Unterzuckerung, deren Anzeichen man kennen sollte. Das Schema legt der Arzt fest.', 'Yalnızca reçeteyle verilir, deri altına uygulanır. Temel risk düşük kan şekeridir, belirtilerini bilmek gerekir. Şemayı hekim belirler, kendiliğinden değiştirilmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ipratropijum bromid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (392, 'A short-acting inhaled anticholinergic that relaxes the muscles of the airways. In Montenegro it is available combined with fenoterol.', 'Antiholinergik kratkog djelovanja za inhalaciju koji opušta mišiće disajnih puteva. U Crnoj Gori dolazi u kombinaciji sa fenoterolom.', 'Антихолинергик кратког дјеловања за инхалацију који опушта мишиће дисајних путева. У Црној Гори долази у комбинацији са фенотеролом.', 'Холинолитик короткого действия для ингаляций, расслабляющий мышцы бронхов. В Черногории доступен в комбинации с фенотеролом.', 'Ein kurz wirksames inhalatives Anticholinergikum, das die Atemwegsmuskulatur entspannt. In Montenegro mit Fenoterol kombiniert erhältlich.', 'Solunum yolu kaslarını gevşeten kısa etkili inhale bir antikolinerjiktir. Karadağ''da fenoterolle kombine bulunur.', 'Used to relieve breathlessness and wheezing in COPD and asthma.', 'Primjenjuje se za olakšanje nedostatka vazduha i sviranja u grudima kod HOBP i astme.', 'Примјењује се за олакшање недостатка ваздуха и свирања у грудима код ХОБП и астме.', 'Применяют для облегчения одышки и свистящего дыхания при ХОБЛ и бронхиальной астме.', 'Wird zur Linderung von Atemnot und Pfeifen bei COPD und Asthma eingesetzt.', 'KOAH ve astımda nefes darlığını ve hırıltıyı gidermek için kullanılır.', 'Prescription only. Dry mouth is possible. The solution must be kept out of the eyes, especially with glaucoma. The regimen is set by a doctor.', 'Izdaje se na recept. Moguća je suvoća usta. Rastvor ne smije dospjeti u oči, naročito kod glaukoma. Primjenu određuje ljekar.', 'Издаје се на рецепт. Могућа је сувоћа уста. Раствор не смије доспјети у очи, нарочито код глаукома. Примјену одређује љекар.', 'Отпускается по рецепту. Возможна сухость во рту. Раствор берегут от попадания в глаза, особенно при глаукоме. Режим применения определяет врач.', 'Verschreibungspflichtig. Mundtrockenheit ist möglich. Die Lösung darf nicht in die Augen gelangen, besonders bei Glaukom. Die Anwendung legt der Arzt fest.', 'Reçeteye tabidir. Ağız kuruluğu olabilir. Solüsyon göze kaçırılmamalıdır, özellikle glokomda. Kullanım düzenini hekim belirler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- islandski lišaj (cetraria islandica (l.) acharius s.l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (395, 'Iceland moss (Cetraria islandica), a lichen whose thallus contains mucilage that soothes the irritated lining of the throat.', 'Islandski lišaj, lišaj čiji talus sadrži sluzi koje umiruju nadraženu sluznicu grla.', 'Исландски лишај, лишај чији талус садржи слузи које умирују надражену слузницу грла.', 'Исландский мох (Cetraria islandica) — лишайник, слоевище которого содержит слизи, смягчающие раздражённую слизистую горла.', 'Isländisch Moos (Cetraria islandica), eine Flechte, deren Thallus Schleimstoffe enthält, die gereizte Schleimhaut im Hals beruhigen.', 'İzlanda likeni (Cetraria islandica), talusundaki müsilaj ile boğazın tahriş olmuş mukozasını yatıştıran bir likendir.', 'The extract is used in cough syrups for dry irritating cough, a scratchy throat and hoarseness during colds.', 'Ekstrakt ulazi u sirupe protiv kašlja koji se koriste kod suvog nadražajnog kašlja, grebanja u grlu i promuklosti uz prehladu.', 'Екстракт улази у сирупе против кашља који се користе код сувог надражајног кашља, гребања у грлу и промуклости уз прехладу.', 'Экстракт входит в сиропы от кашля, которые применяют при сухом раздражающем кашле, першении и охриплости при простуде.', 'Der Extrakt steckt in Hustensäften gegen trockenen Reizhusten, Halskratzen und Heiserkeit bei Erkältung.', 'Ekstresi, soğuk algınlığında kuru tahriş edici öksürük, boğaz kaşıntısı ve ses kısıklığında şuruplarda kullanılır.', 'Available without prescription, and syrups may contain sugar or alcohol. A cough over a week, fever or breathlessness needs a doctor; children, only as advised.', 'Izdaje se bez recepta, sirup može sadržati šećer ili alkohol. Kašalj duži od nedjelju dana, temperatura ili gušenje traže pregled, djeci po preporuci ljekara.', 'Издаје се без рецепта, сируп може садржати шећер или алкохол. Кашаљ дужи од недјељу дана, температура или гушење траже преглед, дјеци по препоруци љекара.', 'Отпускается без рецепта, сироп может содержать сахар или спирт. При кашле дольше недели, температуре или одышке нужен врач, детям — по его назначению.', 'Rezeptfrei, Säfte können Zucker oder Alkohol enthalten. Husten über eine Woche, Fieber oder Atemnot gehören zum Arzt, bei Kindern nur nach ärztlichem Rat.', 'Reçetesiz satılır, şurup şeker veya alkol içerebilir. Bir haftadan uzun öksürük, ateş veya nefes darlığında hekime gidilir; çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- jagorčevina (primula veris l. i/ili primula elatior (l.) hill.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (401, 'Primrose (Primula veris, Primula elatior) is a medicinal plant whose root yields an extract with an expectorant effect.', 'Jagorčevina je ljekovita biljka iz čijeg se korijena dobija ekstrakt sa iskašljavajućim djelovanjem.', 'Јагорчевина је љековита биљка из чијег се коријена добија екстракт са искашљавајућим дјеловањем.', 'Первоцвет (Primula veris, Primula elatior) — лекарственное растение, из корня которого получают экстракт с отхаркивающим действием.', 'Die Schlüsselblume (Primula veris, Primula elatior) ist eine Heilpflanze, aus deren Wurzel ein schleimlösender Extrakt gewonnen wird.', 'Çuha çiçeği (Primula veris, Primula elatior), kökünden balgam söktürücü etkili özüt elde edilen bir şifalı bitkidir.', 'Used for a cough with thick mucus in colds and bronchitis, usually as part of combined herbal syrups.', 'Primjenjuje se kod kašlja sa gustim sekretom uz prehladu i bronhitis, obično u kombinovanim biljnim sirupima.', 'Примјењује се код кашља са густим секретом уз прехладу и бронхитис, обично у комбинованим биљним сирупима.', 'Применяют при кашле с густой мокротой при простуде и бронхите, обычно в составе комбинированных растительных сиропов.', 'Wird bei Husten mit zähem Schleim bei Erkältung und Bronchitis eingesetzt, meist in pflanzlichen Kombinationssäften.', 'Soğuk algınlığı ve bronşitte koyu balgamlı öksürükte, genellikle bitkisel kombine şuruplarda kullanılır.', 'Available over the counter; syrups may contain sugar or alcohol. A cough lasting over a week, fever or breathlessness needs a doctor; in children, as advised.', 'Izdaje se bez recepta, sirupi mogu sadržati šećer ili alkohol. Kod kašlja dužeg od nedjelju dana, temperature i nedostatka vazduha potreban je ljekar.', 'Издаје се без рецепта, сирупи могу садржати шећер или алкохол. Код кашља дужег од недјељу дана, температуре и недостатка ваздуха потребан је љекар.', 'Отпускается без рецепта, сиропы могут содержать сахар или спирт. При кашле дольше недели, температуре и одышке нужен врач, детям — по его назначению.', 'Rezeptfrei erhältlich, Säfte können Zucker oder Alkohol enthalten. Hält der Husten über eine Woche an oder kommen Fieber und Atemnot dazu, ist ein Arzt nötig.', 'Reçetesiz satılır, şuruplar şeker ya da alkol içerebilir. Bir haftadan uzun süren öksürükte, ateş ve nefes darlığında hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kalcijum
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (408, 'A mineral that builds bone and teeth and takes part in muscle work and blood clotting. It is often combined with vitamin D.', 'Mineral koji gradi kosti i zube i učestvuje u radu mišića i zgrušavanju krvi. Često dolazi u kombinaciji sa vitaminom D.', 'Минерал који гради кости и зубе и учествује у раду мишића и згрушавању крви. Често долази у комбинацији са витамином Д.', 'Минерал, основной строительный материал костей и зубов, участвует в работе мышц и свёртывании крови. Часто идёт вместе с витамином D.', 'Ein Mineralstoff, der Knochen und Zähne aufbaut und an Muskelarbeit und Blutgerinnung beteiligt ist. Oft in Kombination mit Vitamin D.', 'Kemik ve dişleri oluşturan, kas çalışmasında ve kanın pıhtılaşmasında rol alan bir mineraldir. Sıklıkla D vitaminiyle birlikte bulunur.', 'Used when the diet is low in calcium, in osteoporosis together with vitamin D, and during growth, pregnancy and breastfeeding.', 'Primjenjuje se kod nedovoljnog unosa kalcijuma hranom, kod osteoporoze uz vitamin D, u periodu rasta, trudnoće i dojenja.', 'Примјењује се код недовољног уноса калцијума храном, код остеопорозе уз витамин Д, у периоду раста, трудноће и дојења.', 'Применяют при недостатке кальция в питании, при остеопорозе вместе с витамином D, в период роста, беременности и кормления грудью.', 'Wird bei zu geringer Kalziumzufuhr, bei Osteoporose zusammen mit Vitamin D sowie in Wachstum, Schwangerschaft und Stillzeit eingesetzt.', 'Beslenmeyle yetersiz kalsiyum alımında, D vitaminiyle birlikte osteoporozda, büyüme, gebelik ve emzirme dönemlerinde kullanılır.', 'Available over the counter. It reduces the absorption of some antibiotics and of thyroid hormones. With kidney stones, only on a doctor''s advice.', 'Izdaje se bez recepta. Smanjuje apsorpciju pojedinih antibiotika i hormona štitne žlijezde. Kod kamena u bubregu samo po savjetu ljekara.', 'Издаје се без рецепта. Смањује апсорпцију појединих антибиотика и хормона штитне жлијезде. Код камена у бубрегу само по савјету љекара.', 'Отпускается без рецепта. Мешает усвоению некоторых антибиотиков и гормонов щитовидной железы. При камнях в почках — только по назначению врача.', 'Rezeptfrei erhältlich. Es vermindert die Aufnahme mancher Antibiotika und von Schilddrüsenhormonen. Bei Nierensteinen nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Bazı antibiyotiklerin ve tiroit hormonlarının emilimini azaltır. Böbrek taşı olanlarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kalcijum karbonat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (411, 'An antacid that neutralises stomach acid. It also serves as a source of calcium and is often combined with magnesium salts.', 'Antacid koji neutrališe želudačnu kiselinu. Služi i kao izvor kalcijuma, često se kombinuje sa solima magnezijuma.', 'Антацид који неутралише желудачну киселину. Служи и као извор калцијума, често се комбинује са солима магнезијума.', 'Антацид: нейтрализует соляную кислоту в желудке. Служит также источником кальция, часто сочетается с солями магния.', 'Ein Antazidum, das Magensäure neutralisiert. Es dient auch als Kalziumquelle und wird oft mit Magnesiumsalzen kombiniert.', 'Mide asidini nötralize eden bir antasittir. Aynı zamanda kalsiyum kaynağıdır, sıklıkla magnezyum tuzlarıyla birlikte bulunur.', 'Used for heartburn, acid regurgitation and stomach discomfort caused by excess acid.', 'Primjenjuje se kod žgaravice, kiselog podrigivanja i nelagode u želucu zbog pojačane kiseline.', 'Примјењује се код жгаравице, киселог подригивања и нелагоде у желуцу због појачане киселине.', 'Применяют при изжоге, кислой отрыжке и дискомфорте в желудке, связанных с повышенной кислотностью.', 'Wird bei Sodbrennen, saurem Aufstoßen und Magenbeschwerden durch zu viel Säure angewendet.', 'Mide yanmasında, ekşi geğirmede ve asit fazlalığına bağlı mide rahatsızlığında kullanılır.', 'Over the counter. It can cause constipation and interfere with the absorption of other medicines. With kidney disease, raised calcium or persistent heartburn, see a doctor.', 'Izdaje se bez recepta. Može izazvati zatvor i ometati apsorpciju drugih lijekova. Kod bolesti bubrega, povišenog kalcijuma i stalne žgaravice javiti se ljekaru.', 'Издаје се без рецепта. Може изазвати затвор и ометати апсорпцију других лијекова. Код болести бубрега, повишеног калцијума и сталне жгаравице јавити се љекару.', 'Отпускается без рецепта. Может вызывать запор и мешать всасыванию других лекарств. При болезнях почек, повышенном кальции и постоянной изжоге нужен врач.', 'Rezeptfrei. Kann Verstopfung verursachen und die Aufnahme anderer Medikamente stören. Bei Nierenerkrankungen, erhöhtem Kalzium und anhaltendem Sodbrennen zum Arzt.', 'Reçetesiz satılır. Kabızlık yapabilir ve diğer ilaçların emilimini bozabilir. Böbrek hastalığında, kalsiyum yüksekliğinde ve sürekli mide yanmasında hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kalcijum pantotenat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (412, 'The calcium salt of pantothenic acid, vitamin B5, involved in metabolism and tissue repair.', 'Kalcijumova so pantotenske kiseline, vitamina B5, učestvuje u razmjeni materija i obnavljanju tkiva.', 'Калцијумова со пантотенске киселине, витамина B5, учествује у размјени материја и обнављању ткива.', 'Кальциевая соль пантотеновой кислоты, витамина B5, участвует в обмене веществ и восстановлении тканей.', 'Das Calciumsalz der Pantothensäure, Vitamin B5, beteiligt am Stoffwechsel und an der Geweberegeneration.', 'Pantotenik asidin (B5 vitamini) kalsiyum tuzudur, metabolizmada ve doku onarımında rol alır.', 'Used for vitamin B5 deficiency and in multivitamin B-complex products, including those for children.', 'Primjenjuje se kod nedostatka vitamina B5 i u multivitaminskim preparatima B grupe, uključujući dječje.', 'Примјењује се код недостатка витамина B5 и у мултивитаминским препаратима Б групе, укључујући дјечје.', 'Применяют при недостатке витамина B5 и в поливитаминных комплексах группы B, в том числе детских.', 'Wird bei Vitamin-B5-Mangel und in Multivitamin-Präparaten der B-Gruppe, auch für Kinder, verwendet.', 'B5 vitamini eksikliğinde ve çocuklara yönelik olanlar dahil B grubu multivitamin preparatlarında kullanılır.', 'Sold over the counter in combined products. Isolated vitamin B5 deficiency is rare. Use in pregnancy is agreed with a doctor.', 'Izdaje se bez recepta u kombinovanim preparatima. Izolovan nedostatak vitamina B5 je rijedak. Primjena u trudnoći dogovara se sa ljekarom.', 'Издаје се без рецепта у комбинованим препаратима. Изолован недостатак витамина B5 је риједак. Примјена у трудноћи договара се са љекаром.', 'Отпускается без рецепта в составе комбинированных препаратов. Изолированный дефицит витамина B5 встречается редко. Приём при беременности согласуют с врачом.', 'Rezeptfrei in Kombinationspräparaten. Ein isolierter Vitamin-B5-Mangel ist selten. Anwendung in der Schwangerschaft mit dem Arzt absprechen.', 'Kombine preparatlarda reçetesiz satılır. Tek başına B5 vitamini eksikliği enderdir. Gebelikte kullanımı doktorla kararlaştırılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kamfor
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (415, 'A natural substance for external use with a counter-irritant, cooling and then warming effect. It is part of topical rubbing products.', 'Prirodna supstanca za spoljnu primjenu sa nadražajnim, rashlađujuće-zagrijavajućim djelovanjem. Ulazi u preparate za utrljavanje.', 'Природна супстанца за спољну примјену са надражајним, расхлађујуће-загријавајућим дјеловањем. Улази у препарате за утрљавање.', 'Природное вещество для наружного применения с раздражающим и охлаждающе-согревающим действием. Входит в средства для растирания.', 'Ein natürlicher Stoff zur äußerlichen Anwendung mit hautreizender, kühlend-wärmender Wirkung. Er steckt in Einreibemitteln.', 'Dıştan kullanılan, deriyi uyaran, önce serinlik sonra sıcaklık hissi veren doğal bir maddedir. Ovma ürünlerinde bulunur.', 'Used in topical products for muscle, joint and back pain and for bruises and sprains.', 'Primjenjuje se u spoljnim preparatima kod bolova u mišićima, zglobovima i leđima, kao i kod nagnječenja i istegnuća.', 'Примјењује се у спољним препаратима код болова у мишићима, зглобовима и леђима, као и код нагњечења и истегнућа.', 'Применяют в составе наружных средств при боли в мышцах, суставах и спине, а также при ушибах и растяжениях.', 'Wird in äußerlichen Mitteln bei Muskel-, Gelenk- und Rückenschmerzen sowie bei Prellungen und Zerrungen angewendet.', 'Dıştan kullanılan ürünlerde kas, eklem ve sırt ağrısında, berelenme ve burkulmalarda kullanılır.', 'Available over the counter. External use only, on unbroken skin, away from eyes and mucous membranes. In small children only on a doctor''s advice.', 'Izdaje se bez recepta. Samo spolja, na neoštećenu kožu, ne na oči i sluznice. Kod male djece samo po savjetu ljekara.', 'Издаје се без рецепта. Само споља, на неоштећену кожу, не на очи и слузнице. Код мале дјеце само по савјету љекара.', 'Отпускается без рецепта. Только наружно, на неповреждённую кожу, в глаза и на слизистые не наносят. Маленьким детям — только по назначению врача.', 'Rezeptfrei erhältlich. Nur äußerlich auf unverletzter Haut, nicht in die Augen und auf Schleimhäute. Bei kleinen Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Yalnızca sağlam deriye haricen uygulanır, göz ve mukozaya sürülmez. Küçük çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- karbocistein
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (422, 'A mucolytic that changes the properties of bronchial mucus and makes coughing it up easier.', 'Mukolitik koji mijenja svojstva bronhijalnog sekreta i olakšava iskašljavanje.', 'Муколитик који мијења својства бронхијалног секрета и олакшава искашљавање.', 'Муколитик: меняет свойства бронхиального секрета и облегчает откашливание.', 'Ein Schleimlöser, der die Eigenschaften des Bronchialschleims verändert und das Abhusten erleichtert.', 'Bronş salgısının özelliklerini değiştirip balgamın atılmasını kolaylaştıran bir mukolitiktir.', 'Used for a cough with thick mucus in bronchitis and other conditions of the airways.', 'Primjenjuje se kod kašlja sa gustim sekretom uz bronhitis i druge bolesti disajnih puteva.', 'Примјењује се код кашља са густим секретом уз бронхитис и друге болести дисајних путева.', 'Применяют при кашле с густой мокротой на фоне бронхита и других болезней дыхательных путей.', 'Wird bei Husten mit zähem Schleim bei Bronchitis und anderen Atemwegserkrankungen angewendet.', 'Bronşit ve diğer solunum yolu hastalıklarında koyu balgamlı öksürükte kullanılır.', 'Available over the counter. It is not combined with cough suppressants. With peptic ulcer disease, in pregnancy and in young children, only on a doctor''s advice.', 'Izdaje se bez recepta. Ne kombinuje se sa lijekovima koji potiskuju kašalj. Kod čira na želucu, u trudnoći i kod male djece samo po savjetu ljekara.', 'Издаје се без рецепта. Не комбинује се са лијековима који потискују кашаљ. Код чира на желуцу, у трудноћи и код мале дјеце само по савјету љекара.', 'Отпускается без рецепта. Не сочетают со средствами, подавляющими кашель. При язвенной болезни, беременности и у детей раннего возраста — по назначению врача.', 'Rezeptfrei erhältlich. Nicht zusammen mit hustenstillenden Mitteln. Bei Magengeschwür, in der Schwangerschaft und bei kleinen Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Öksürüğü baskılayan ilaçlarla birlikte kullanılmaz. Mide ülserinde, gebelikte ve küçük çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ketokonazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (428, 'An azole antifungal for external use.', 'Antimikotik iz grupe azola za spoljnu primjenu.', 'Антимикотик из групе азола за спољну примјену.', 'Противогрибковое вещество группы азолов для наружного применения.', 'Ein Antimykotikum aus der Gruppe der Azole zur äußerlichen Anwendung.', 'Azol grubundan, dıştan uygulanan bir antifungaldir.', 'Used for fungal skin infections, pityriasis versicolor and seborrhoeic dermatitis including dandruff.', 'Primjenjuje se kod gljivičnih infekcija kože, šarene gljivice i seboroičnog dermatitisa, uključujući perut.', 'Примјењује се код гљивичних инфекција коже, шарене гљивице и себороичног дерматитиса, укључујући перут.', 'Применяют при грибковых поражениях кожи, отрубевидном лишае и себорейном дерматите, включая перхоть.', 'Wird bei Pilzinfektionen der Haut, Kleienpilzflechte und seborrhoischem Ekzem einschließlich Schuppen angewendet.', 'Cilt mantar enfeksiyonlarında, tinea versikolorda ve kepek dahil seboreik dermatitte kullanılır.', 'Over the counter. For external use only, avoid contact with the eyes. Widespread or persistent infection needs a doctor''s examination. In pregnancy and for children, only as advised.', 'Izdaje se bez recepta. Samo spolja, izbjegavati kontakt sa očima. Široka ili uporna infekcija traži pregled ljekara. U trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта. Само споља, избјегавати контакт са очима. Широка или упорна инфекција тражи преглед љекара. У трудноћи и код дјеце само по савјету љекара.', 'Отпускается без рецепта. Только наружно, избегать попадания в глаза. При обширном или стойком поражении нужен осмотр врача. Беременным и детям — по назначению врача.', 'Rezeptfrei. Nur äußerlich, Kontakt mit den Augen vermeiden. Ausgedehnter oder anhaltender Befall gehört zum Arzt. In der Schwangerschaft und bei Kindern nur ärztlich.', 'Reçetesiz satılır. Yalnızca dıştan kullanılır, gözle temasından kaçınılır. Yaygın ya da geçmeyen enfeksiyonda hekime başvurulur. Gebelikte ve çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ketoprofen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (429, 'Ketoprofen is a non-steroidal anti-inflammatory drug (NSAID) with a strong painkilling effect', 'Ketoprofen je nesteroidni antiinflamatorni lijek (NSAIL) sa izraženim analgetskim djelovanjem', 'Кетопрофен је нестероидни антиинфламаторни лијек (NSAIL) са израженим аналгетским дјеловањем', 'Кетопрофен — нестероидное противовоспалительное средство (NSAIL) с выраженным обезболивающим действием', 'Ketoprofen ist ein nichtsteroidales Antirheumatikum (NSAR) mit ausgeprägter schmerzstillender Wirkung', 'Ketoprofen, ağrı kesici etkisi belirgin, steroid olmayan bir antiinflamatuar ilaçtır (NSAİİ)', 'Pain and inflammation after injuries, in joint and spine disorders, muscle pain, dental and menstrual pain', 'Bol i upala poslije povreda, kod bolesti zglobova i kičme, mišićni, zubni i menstrualni bol', 'Бол и упала послије повреда, код болести зглобова и кичме, мишићни, зубни и менструални бол', 'Боль и воспаление после травм, при болезнях суставов и позвоночника, мышечная, зубная и менструальная боль', 'Schmerzen und Entzündungen nach Verletzungen, bei Gelenk- und Wirbelsäulenbeschwerden, Muskel-, Zahn- und Regelschmerzen', 'Yaralanma sonrası ağrı ve iltihap, eklem ve omurga hastalıkları, kas ağrısı, diş ve adet ağrısı', 'Almost all forms are prescription-only. It irritates the stomach lining and raises bleeding risk, does not combine with other NSAIDs or alcohol; the gel makes skin sun-sensitive.', 'Gotovo svi oblici izdaju se na recept. Nadražuje sluznicu želuca i povećava rizik od krvarenja, ne kombinuje se sa drugim NSAIL i alkoholom; gel povećava osjetljivost kože na sunce.', 'Готово сви облици издају се на рецепт. Надражује слузницу желуца и повећава ризик од крварења, не комбинује се са другим NSAIL и алкохолом; гел повећава осјетљивост коже на сунце.', 'Почти все формы рецептурные. Раздражает слизистую желудка и повышает риск кровотечения, не сочетается с другими NSAIL и алкоголем; гель повышает чувствительность кожи к солнцу.', 'Fast alle Formen sind rezeptpflichtig. Reizt die Magenschleimhaut und erhöht das Blutungsrisiko, nicht mit anderen NSAR oder Alkohol kombinieren; das Gel macht die Haut lichtempfindlich.', 'Neredeyse tüm formları reçeteye tabidir. Mide mukozasını tahriş eder, kanama riskini artırır, diğer NSAİİ ve alkolle kullanılmaz; jel deriyi güneşe duyarlı hale getirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ketotifen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (431, 'A first-generation antihistamine that also stabilises mast cells.', 'Antihistaminik prve generacije koji uz to stabilizuje mastocite.', 'Антихистаминик прве генерације који уз то стабилизује мастоците.', 'Антигистаминное вещество первого поколения, которое также стабилизирует тучные клетки.', 'Ein Antihistaminikum der ersten Generation, das zusätzlich Mastzellen stabilisiert.', 'Aynı zamanda mast hücrelerini dengeleyen birinci kuşak bir antihistaminiktir.', 'Used as long-term maintenance treatment for allergic rhinitis, conjunctivitis, hives and other allergic conditions.', 'Primjenjuje se kao dugotrajna terapija kod alergijskog rinitisa, konjunktivitisa, koprivnjače i drugih alergijskih stanja.', 'Примјењује се као дуготрајна терапија код алергијског ринитиса, коњунктивитиса, копривњаче и других алергијских стања.', 'Применяют при аллергическом рините, конъюнктивите, крапивнице и других аллергических состояниях как длительную поддерживающую терапию.', 'Wird als Dauertherapie bei allergischem Schnupfen, Bindehautentzündung, Nesselsucht und anderen allergischen Zuständen angewendet.', 'Alerjik nezlede, konjonktivitte, kurdeşende ve diğer alerjik durumlarda uzun süreli sürdürüm tedavisi olarak kullanılır.', 'Prescription only. It often causes drowsiness, especially at the start: this matters when driving, and alcohol adds to the effect. The action builds up gradually.', 'Izdaje se na recept. Često izaziva pospanost, naročito na početku: to se uzima u obzir pri vožnji, a alkohol pojačava efekat. Djelovanje se razvija postepeno.', 'Издаје се на рецепт. Често изазива поспаност, нарочито на почетку: то се узима у обзир при вожњи, а алкохол појачава ефекат. Дјеловање се развија постепено.', 'Отпускается по рецепту. Часто вызывает сонливость, особенно в начале приёма: это учитывают при вождении, алкоголь усиливает эффект. Действие развивается постепенно.', 'Verschreibungspflichtig. Macht oft müde, vor allem am Anfang: beim Autofahren zu bedenken, Alkohol verstärkt die Wirkung. Der Effekt baut sich langsam auf.', 'Reçeteye tabidir. Özellikle başlangıçta sık uyku hali yapar: araç kullanırken dikkate alınır, alkol etkiyi artırır. Etkisi giderek yerleşir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- klotrimazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (440, 'A topical antifungal from the azole group.', 'Antimikotik iz grupe azola za lokalnu primjenu.', 'Антимикотик из групе азола за локалну примјену.', 'Противогрибковое средство группы азолов для местного применения.', 'Ein örtlich anzuwendendes Antimykotikum aus der Gruppe der Azole.', 'Azol grubundan, bölgesel kullanılan bir mantar ilacıdır.', 'Used for fungal infections of the skin and skin folds, for tinea versicolor and for vaginal thrush.', 'Primjenjuje se kod gljivičnih infekcija kože i kožnih nabora, kod pitirijaze i kod vaginalne kandidijaze.', 'Примјењује се код гљивичних инфекција коже и кожних набора, код питиријазе и код вагиналне кандидијазе.', 'Применяют при грибковых поражениях кожи и кожных складок, отрубевидном лишае, а также при вагинальном кандидозе.', 'Wird bei Pilzinfektionen der Haut und der Hautfalten, bei Kleienpilzflechte und bei Scheidenpilz angewendet.', 'Derinin ve deri kıvrımlarının mantar enfeksiyonlarında, renkli mantarda ve vajinal mantarda kullanılır.', 'Available over the counter. If symptoms persist or come back, a doctor''s examination is needed. In pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta. Ako simptomi ne prolaze ili se vraćaju, potreban je pregled ljekara. U trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта. Ако симптоми не пролазе или се враћају, потребан је преглед љекара. У трудноћи само по савјету љекара.', 'Отпускается без рецепта. Если симптомы не проходят или возвращаются, нужен осмотр врача. При беременности — только по назначению врача.', 'Rezeptfrei erhältlich. Bleiben die Beschwerden oder kehren sie zurück, ist eine ärztliche Untersuchung nötig. In der Schwangerschaft nur nach Anweisung.', 'Reçetesiz satılır. Şikayetler geçmez ya da tekrarlarsa hekime başvurmak gerekir. Gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kodein
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (448, 'Codeine is an opioid with painkilling and cough-suppressing action; in Montenegro it appears as part of a combination painkiller.', 'Kodein je opioid sa analgetskim i antitusičnim djelovanjem; u Crnoj Gori se nalazi u sastavu kombinovanog analgetika.', 'Кодеин је опиоид са аналгетским и антитусичним дјеловањем; у Црној Гори се налази у саставу комбинованог аналгетика.', 'Кодеин — опиоид с обезболивающим и противокашлевым действием; в Черногории встречается в составе комбинированного обезболивающего.', 'Codein ist ein Opioid mit schmerzstillender und hustendämpfender Wirkung; in Montenegro ist es Teil eines Kombinationsschmerzmittels.', 'Kodein, ağrı kesici ve öksürük baskılayıcı etkisi olan bir opioiddir; Karadağ kayıtlarında kombine bir ağrı kesicinin bileşenidir.', 'In combination products it strengthens the effect of other painkillers, and on its own it is used to suppress a dry cough.', 'U kombinovanim lijekovima pojačava djelovanje drugih analgetika, a samostalno se koristi za smirivanje suvog kašlja.', 'У комбинованим лијековима појачава дјеловање других аналгетика, а самостално се користи за смиривање сувог кашља.', 'В комбинированных средствах усиливает действие других обезболивающих, самостоятельно применяется для подавления сухого кашля.', 'In Kombinationspräparaten verstärkt es die Wirkung anderer Schmerzmittel, allein wird es gegen trockenen Husten eingesetzt.', 'Kombine ürünlerde diğer ağrı kesicilerin etkisini artırır, tek başına kuru öksürüğü baskılamak için kullanılır.', 'Causes drowsiness and constipation, and prolonged use can lead to dependence. Not compatible with alcohol or driving. For children, in pregnancy and breastfeeding only as prescribed.', 'Izaziva pospanost i zatvor, a duža primjena može dovesti do zavisnosti. Ne kombinuje se sa alkoholom i vožnjom. Djeci, trudnicama i dojiljama samo po savjetu ljekara.', 'Изазива поспаност и затвор, а дужа примјена може довести до зависности. Не комбинује се са алкохолом и вожњом. Дјеци, трудницама и дојиљама само по савјету љекара.', 'Вызывает сонливость и запор, при длительном приёме возможна зависимость. Несовместим с алкоголем и вождением. Детям, беременным и кормящим — по назначению врача.', 'Macht müde und verstopft, längere Anwendung kann abhängig machen. Nicht mit Alkohol oder Autofahren vereinbar. Für Kinder, Schwangere und Stillende nur ärztlich verordnet.', 'Uyku hali ve kabızlık yapar, uzun kullanımda bağımlılık gelişebilir. Alkol ve araç kullanımıyla bağdaşmaz. Çocuklarda, gebelikte ve emzirmede yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kofein
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (450, 'Caffeine is a central nervous system stimulant; in medicines it is most often part of combination painkillers', 'Kofein je stimulans centralnog nervnog sistema; u lijekovima je najčešće dio kombinovanih analgetika', 'Кофеин је стимуланс централног нервног система; у лијековима је најчешће дио комбинованих аналгетика', 'Кофеин — стимулятор центральной нервной системы; в лекарствах чаще всего входит в состав комбинированных обезболивающих', 'Koffein ist ein Stimulans des zentralen Nervensystems und in Arzneimitteln meist Bestandteil von Kombinationsschmerzmitteln', 'Kafein merkezi sinir sistemini uyaran bir maddedir; ilaçlarda çoğunlukla kombine ağrı kesicilerin bileşeni olarak bulunur', 'Combination products for headache, migraine and colds, where caffeine enhances the effect of the pain-relieving component', 'Kombinovani preparati kod glavobolje, migrene i prehlade, gdje kofein pojačava dejstvo analgetske komponente', 'Комбиновани препарати код главобоље, мигрене и прехладе, гдје кофеин појачава дејство аналгетске компоненте', 'Комбинированные средства при головной боли, мигрени и простуде, где кофеин усиливает действие обезболивающего компонента', 'Kombinationspräparate bei Kopfschmerzen, Migräne und Erkältung, in denen Koffein die Wirkung der schmerzstillenden Komponente verstärkt', 'Baş ağrısı, migren ve soğuk algınlığında kullanılan kombine preparatlarda kafein ağrı kesici bileşenin etkisini artırır', 'May cause insomnia, palpitations and restlessness; it counts together with coffee and tea. In heart disease, pregnancy and in children only as advised by a doctor.', 'Može izazvati nesanicu, lupanje srca i nervozu; računa se zajedno sa kafom i čajem. Kod srčanih bolesti, u trudnoći i kod djece samo po savjetu ljekara.', 'Може изазвати несаницу, лупање срца и нервозу; рачуна се заједно са кафом и чајем. Код срчаних болести, у трудноћи и код дјеце само по савјету љекара.', 'Может вызывать бессонницу, сердцебиение и нервозность; учитывается вместе с кофе и чаем. При болезнях сердца, беременности и у детей — по назначению врача.', 'Kann Schlaflosigkeit, Herzklopfen und Unruhe auslösen; zählt zusammen mit Kaffee und Tee. Bei Herzerkrankungen, in der Schwangerschaft und bei Kindern nur nach ärztlicher Anweisung.', 'Uykusuzluk, çarpıntı ve huzursuzluk yapabilir; kahve ve çayla birlikte hesaba katılır. Kalp hastalığı, gebelik ve çocuklarda yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- kombinacije
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (452, 'A registry label for products with several active ingredients; in Montenegro these are skin and vein gels and combined probiotics.', 'Oznaka iz registra za preparate sa više aktivnih supstanci, u Crnoj Gori su to gelovi za kožu i vene i kombinovani probiotici.', 'Ознака из регистра за препарате са више активних супстанци, у Црној Гори су то гелови за кожу и вене и комбиновани пробиотици.', 'Обозначение из реестра для средств с несколькими действующими веществами: в Черногории это гели для кожи и вен и комбинированные пробиотики.', 'Eine Registerbezeichnung für Präparate mit mehreren Wirkstoffen, in Montenegro sind das Haut- und Venengele sowie kombinierte Probiotika.', 'Birden çok etken madde içeren preparatlar için kayıttaki ortak addır; Karadağ''da bunlar deri ve damar jelleri ile kombine probiyotiklerdir.', 'Such gels are used for scars and heavy legs, while combined probiotics support the gut flora.', 'Takvi gelovi primjenjuju se kod ožiljaka i teških nogu, a kombinovani probiotici podržavaju crijevnu floru.', 'Такви гелови примјењују се код ожиљака и тешких ногу, а комбиновани пробиотици подржавају цријевну флору.', 'Такие гели применяют при рубцах и тяжести в ногах, а комбинированные пробиотики — для поддержки микрофлоры кишечника.', 'Solche Gele werden bei Narben und schweren Beinen verwendet, kombinierte Probiotika unterstützen die Darmflora.', 'Bu jeller yara izlerinde ve bacak ağırlığında, kombine probiyotikler bağırsak florasını desteklemek için kullanılır.', 'These products are over the counter but their composition differs. The exact ingredients and limits are in each product''s leaflet. For children and in pregnancy, ask a doctor.', 'Preparati se izdaju bez recepta, ali im se sastav razlikuje. Tačne supstance i ograničenja stoje u uputstvu konkretnog preparata. Djeci i trudnicama po savjetu ljekara.', 'Препарати се издају без рецепта, али им се састав разликује. Тачне супстанце и ограничења стоје у упутству конкретног препарата. Дјеци и трудницама по савјету љекара.', 'Препараты безрецептурные, но состав у них разный. Точные вещества и ограничения указаны в инструкции конкретного средства. Детям и беременным — по назначению врача.', 'Die Präparate sind rezeptfrei, ihre Zusammensetzung ist aber unterschiedlich. Die genauen Stoffe stehen in der Packungsbeilage. Für Kinder und Schwangere nach ärztlichem Rat.', 'Preparatlar reçetesizdir ancak bileşimleri farklıdır. Kesin içerik ve kısıtlamalar her ürünün prospektüsünde yazar. Çocuklarda ve gebelikte hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ksilometazolin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (456, 'Xylometazoline is a nasal decongestant (alpha-adrenergic agonist) sold over the counter', 'Ksilometazolin je nazalni dekongestiv (alfa-adrenergički agonist), izdaje se bez recepta', 'Ксилометазолин је назални деконгестив (алфа-адренергички агонист), издаје се без рецепта', 'Ксилометазолин — сосудосуживающее средство для носа (альфа-адреномиметик), отпускается без рецепта', 'Xylometazolin ist ein abschwellendes Nasenmittel (Alpha-Sympathomimetikum) und rezeptfrei erhältlich', 'Ksilometazolin burun tıkanıklığını açan bir maddedir (alfa-adrenerjik agonist), reçetesiz bulunur', 'Nasal congestion in colds, allergic rhinitis, sinusitis and ear inflammation, and before an examination of the nose', 'Začepljen nos kod prehlade, alergijskog rinitisa, sinuzitisa i upale uha, kao i prije pregleda nosa', 'Зачепљен нос код прехладе, алергијског ринитиса, синузитиса и упале уха, као и прије прегледа носа', 'Заложенность носа при простуде, аллергическом рините, синусите и отите, а также перед осмотром полости носа', 'Verstopfte Nase bei Erkältung, allergischem Schnupfen, Nebenhöhlen- und Mittelohrentzündung sowie vor einer Untersuchung der Nase', 'Soğuk algınlığı, alerjik nezle, sinüzit ve orta kulak iltihabında burun tıkanıklığı, ayrıca burun muayenesi öncesi', 'Prolonged use leads to tolerance and rebound congestion. Children have separate formulations; in pregnancy, hypertension and glaucoma use only as advised by a doctor.', 'Duža primjena dovodi do navikavanja i medikamentoznog rinitisa. Za djecu postoje posebni oblici; u trudnoći, kod povišenog pritiska i glaukoma samo po savjetu ljekara.', 'Дужа примјена доводи до навикавања и медикаментозног ринитиса. За дјецу постоје посебни облици; у трудноћи, код повишеног притиска и глаукома само по савјету љекара.', 'Длительное применение вызывает привыкание и медикаментозный ринит. Для детей есть отдельные формы; при беременности, гипертонии и глаукоме — по назначению врача.', 'Längere Anwendung führt zu Gewöhnung und erneutem Anschwellen. Für Kinder gibt es eigene Zubereitungen; in der Schwangerschaft, bei Bluthochdruck und Glaukom nur nach ärztlicher Anweisung.', 'Uzun süreli kullanım alışkanlık ve ilaca bağlı nezle yapar. Çocuklar için ayrı formlar vardır; gebelikte, yüksek tansiyon ve glokomda yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- laktuloza
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (460, 'Lactulose is an osmotic laxative, a synthetic disaccharide', 'Laktuloza je osmotski laksativ, sintetički disaharid', 'Лактулоза је осмотски лаксатив, синтетички дисахарид', 'Лактулоза — осмотическое слабительное, синтетический дисахарид', 'Lactulose ist ein osmotisches Abführmittel, ein synthetisches Disaccharid', 'Laktüloz ozmotik etkili bir müshildir, sentetik bir disakkarittir', 'Constipation and the need to soften stool, and also liver-related conditions when a doctor prescribes it', 'Zatvor i potreba da se stolica omekša, a kod bolesti jetre po odluci ljekara', 'Затвор и потреба да се столица омекша, а код болести јетре по одлуци љекара', 'Запор и необходимость размягчить стул, а также состояния при болезнях печени, когда препарат назначает врач', 'Verstopfung und weichere Stuhlkonsistenz, bei Lebererkrankungen zudem nach ärztlicher Verordnung', 'Kabızlık ve dışkının yumuşatılması gereken durumlar, ayrıca karaciğer hastalıklarında hekim kararıyla', 'Bloating and gas are possible at the start. With abdominal pain of unclear cause, in children and in pregnancy only as prescribed; some forms require a prescription.', 'Na početku primjene mogući su nadutost i gasovi. Kod bolova u trbuhu nejasnog uzroka, kod djece i u trudnoći samo po savjetu ljekara; dio oblika izdaje se na recept.', 'На почетку примјене могући су надутост и гасови. Код болова у трбуху нејасног узрока, код дјеце и у трудноћи само по савјету љекара; дио облика издаје се на рецепт.', 'В начале приёма возможны вздутие и газы. При болях в животе неясной причины, у детей и при беременности — только по назначению врача; часть форм рецептурная.', 'Zu Beginn sind Blähungen und Völlegefühl möglich. Bei Bauchschmerzen unklarer Ursache, bei Kindern und in der Schwangerschaft nur nach ärztlicher Anweisung; einige Formen sind rezeptpflichtig.', 'Başlangıçta şişkinlik ve gaz görülebilir. Nedeni belirsiz karın ağrısında, çocuklarda ve gebelikte yalnızca hekim önerisiyle; bazı formları reçeteye tabidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- levetiracetam
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (477, 'An antiepileptic substance that affects the transmission of nerve signals in the brain.', 'Antiepileptik koji utiče na prenos nervnih signala u mozgu.', 'Антиепилептик који утиче на пренос нервних сигнала у мозгу.', 'Противоэпилептическое вещество, влияет на передачу нервных сигналов в мозге.', 'Ein Antiepileptikum, das die Übertragung von Nervensignalen im Gehirn beeinflusst.', 'Beyinde sinir sinyallerinin iletimini etkileyen bir antiepileptiktir.', 'Prescribed in epilepsy to control various seizure types, alone or together with other antiepileptic medicines.', 'Propisuje se kod epilepsije radi kontrole različitih tipova napada, sam ili uz druge antiepileptike.', 'Прописује се код епилепсије ради контроле различитих типова напада, сам или уз друге антиепилептике.', 'Назначают при эпилепсии для контроля разных типов приступов, отдельно или вместе с другими противоэпилептическими лекарствами.', 'Wird bei Epilepsie zur Kontrolle verschiedener Anfallsformen verordnet, allein oder zusammen mit anderen Antiepileptika.', 'Epilepside farklı nöbet tiplerinin kontrolü için tek başına veya diğer antiepileptiklerle birlikte reçete edilir.', 'Prescription only. Drowsiness, irritability and mood swings are possible. It must not be stopped abruptly, as that triggers seizures, so a doctor plans withdrawal.', 'Izdaje se samo na recept. Mogući su pospanost, razdražljivost i promjene raspoloženja. Nagli prekid izaziva napade, pa ukidanje planira ljekar.', 'Издаје се само на рецепт. Могући су поспаност, раздражљивост и промјене расположења. Нагли прекид изазива нападе, па укидање планира љекар.', 'Только по рецепту. Возможны сонливость, раздражительность и перепады настроения. Резко прекращать приём нельзя: это провоцирует приступы, отмену планирует врач.', 'Verschreibungspflichtig. Müdigkeit, Reizbarkeit und Stimmungsschwankungen sind möglich. Plötzliches Absetzen löst Anfälle aus, daher plant der Arzt das Ausschleichen.', 'Yalnızca reçeteyle verilir. Uyku hali, sinirlilik ve ruh hali değişimleri olabilir. Aniden bırakmak nöbet tetikler, bırakma planını doktor yapar.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- levofloksacin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (480, 'A fluoroquinolone antibiotic active against a wide range of bacteria.', 'Antibiotik iz grupe fluorohinolona koji djeluje na veliki broj bakterija.', 'Антибиотик из групе флуорохинолона који дјелује на велики број бактерија.', 'Антибиотик из группы фторхинолонов, действует на широкий круг бактерий.', 'Ein Fluorchinolon-Antibiotikum gegen ein breites Bakterienspektrum.', 'Geniş bakteri yelpazesine etkili, florokinolon grubundan bir antibiyotiktir.', 'Used for pneumonia and bronchitis, urinary tract and kidney infections, sinusitis and skin infections, and the drops for eye infections.', 'Primjenjuje se kod upale pluća i bronhitisa, infekcija mokraćnih puteva i bubrega, sinuzitisa i infekcija kože, a kapi kod infekcija oka.', 'Примјењује се код упале плућа и бронхитиса, инфекција мокраћних путева и бубрега, синузитиса и инфекција коже, а капи код инфекција ока.', 'Применяют при пневмонии и бронхите, инфекциях мочевых путей и почек, при синусите и инфекциях кожи, капли — при инфекциях глаза.', 'Wird bei Lungenentzündung und Bronchitis, Harnwegs- und Niereninfektionen, Nebenhöhlenentzündung und Hautinfektionen eingesetzt, Tropfen am Auge.', 'Zatürre ve bronşitte, idrar yolu ve böbrek enfeksiyonlarında, sinüzit ve deri enfeksiyonlarında kullanılır, damlası göz enfeksiyonlarında.', 'Prescription only. Tendon inflammation or rupture and nerve and sleep problems are possible. It increases sun sensitivity. The course is not stopped on your own.', 'Izdaje se samo na recept. Mogući su upala i pucanje tetiva, smetnje nerava i sna. Povećava osjetljivost na sunce. Terapija se ne prekida bez ljekara.', 'Издаје се само на рецепт. Могући су упала и пуцање тетива, сметње нерава и сна. Повећава осјетљивост на сунце. Терапија се не прекида без љекара.', 'Только по рецепту. Возможны воспаление и разрыв сухожилий, нарушения со стороны нервов и сна. Повышает чувствительность к солнцу. Курс не прерывают сами.', 'Verschreibungspflichtig. Sehnenentzündung und -riss sowie Nerven- und Schlafstörungen sind möglich. Erhöht die Lichtempfindlichkeit. Nicht eigenmächtig absetzen.', 'Yalnızca reçeteyle verilir. Tendon iltihabı ve yırtığı, sinir ve uyku sorunları görülebilir. Güneşe duyarlılığı artırır. Tedavi hekime danışmadan kesilmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- levomentol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (481, 'Levomenthol is a mint-derived substance with a cooling and mildly pain-relieving effect.', 'Levomentol je supstanca iz mente sa rashlađujućim i blagim analgetskim djelovanjem.', 'Левоментол је супстанца из менте са расхлађујућим и благим аналгетским дјеловањем.', 'Левоментол — вещество из мяты с охлаждающим и лёгким обезболивающим действием.', 'Levomenthol ist ein Stoff aus der Minze mit kühlender und leicht schmerzlindernder Wirkung.', 'Levomentol, naneden elde edilen, serinletici ve hafif ağrı kesici etkili bir maddedir.', 'Applied to the skin for muscle and joint pain, and included in remedies for sore throat and a blocked nose.', 'Spolja se primjenjuje kod bolova u mišićima i zglobovima, a ulazi i u preparate za grlobolju i začepljen nos.', 'Споља се примјењује код болова у мишићима и зглобовима, а улази и у препарате за грлобољу и зачепљен нос.', 'Применяют наружно при мышечной и суставной боли, а также в средствах от боли в горле и заложенности носа.', 'Äußerlich bei Muskel- und Gelenkschmerzen sowie in Mitteln gegen Halsschmerzen und verstopfte Nase.', 'Kas ve eklem ağrısında haricen uygulanır, boğaz ağrısı ve burun tıkanıklığı ürünlerinde de yer alır.', 'Keep away from the eyes, mucous membranes and broken skin. For infants and small children, menthol products only as directed by a doctor.', 'Ne nanosi se na oči, sluznice i oštećenu kožu. Maloj djeci se preparati sa mentolom daju samo po savjetu ljekara.', 'Не наноси се на очи, слузнице и оштећену кожу. Малој дјеци се препарати са ментолом дају само по савјету љекара.', 'Не наносят на глаза, слизистые и повреждённую кожу. Детям раннего возраста средства с ментолом дают только по назначению врача.', 'Nicht an Augen, Schleimhäute oder verletzte Haut bringen. Bei Säuglingen und Kleinkindern nur nach ärztlicher Anweisung anwenden.', 'Göze, mukozaya ve zedelenmiş cilde uygulanmaz. Bebeklerde ve küçük çocuklarda mentollü ürünler yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- levonorgestrel
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (483, 'Levonorgestrel is a synthetic progestogen used in contraceptives, including emergency contraception.', 'Levonorgestrel je sintetski gestagen koji se koristi u kontraceptivnim sredstvima, uključujući i hitnu kontracepciju.', 'Левоноргестрел је синтетски гестаген који се користи у контрацептивним средствима, укључујући и хитну контрацепцију.', 'Левоноргестрел — синтетический гестаген, который применяют в противозачаточных средствах, включая экстренную контрацепцию.', 'Levonorgestrel ist ein synthetisches Gestagen, das in Verhütungsmitteln einschließlich der Notfallverhütung eingesetzt wird.', 'Levonorgestrel, acil korunma dahil olmak üzere doğum kontrol ürünlerinde kullanılan sentetik bir progestindir.', 'Part of regular contraceptives, while separate products are used for emergency contraception after unprotected intercourse.', 'Ulazi u redovne kontraceptive, a pojedini oblici se koriste za hitnu kontracepciju nakon nezaštićenog odnosa.', 'Улази у редовне контрацептиве, а поједини облици се користе за хитну контрацепцију након незаштићеног односа.', 'Входит в состав плановых контрацептивов, а отдельные формы применяют для экстренной контрацепции после незащищённого контакта.', 'Bestandteil regulärer Verhütungsmittel, einzelne Präparate dienen der Notfallverhütung nach ungeschütztem Geschlechtsverkehr.', 'Düzenli doğum kontrol ürünlerinin bileşenidir, bazı formları korunmasız ilişki sonrası acil korunmada kullanılır.', 'Emergency contraception does not replace a regular method and gives no protection against infections. Regular contraception is chosen by a doctor, a missed period needs a check-up.', 'Hitna kontracepcija ne zamjenjuje redovnu metodu i ne štiti od infekcija. Redovnu kontracepciju bira ljekar, a izostanak menstruacije traži pregled.', 'Хитна контрацепција не замјењује редовну методу и не штити од инфекција. Редовну контрацепцију бира љекар, а изостанак менструације тражи преглед.', 'Экстренная контрацепция не заменяет постоянный метод и не защищает от инфекций. Плановую контрацепцию подбирает врач, при задержке менструации нужен осмотр.', 'Notfallverhütung ersetzt keine reguläre Methode und schützt nicht vor Infektionen. Reguläre Verhütung wird ärztlich ausgewählt, bleibt die Regel aus, ist eine Untersuchung nötig.', 'Acil korunma düzenli bir yöntemin yerini tutmaz ve enfeksiyonlardan korumaz. Düzenli korunma yöntemini hekim seçer, adet gecikirse muayene gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- levotiroksin natrijum
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (485, 'A synthetic form of the thyroid hormone thyroxine that replaces what the gland does not produce.', 'Sintetski oblik hormona štitne žlijezde tiroksina koji nadoknađuje ono što žlijezda ne stvara.', 'Синтетски облик хормона штитне жлијезде тироксина који надокнађује оно што жлијезда не ствара.', 'Синтетический аналог гормона щитовидной железы тироксина, восполняющий его недостаток в организме.', 'Eine synthetische Form des Schilddrüsenhormons Thyroxin, die fehlendes eigenes Hormon ersetzt.', 'Tiroit bezinin üretemediği tiroksin hormonunun yerini alan sentetik bir hormondur.', 'Used for an underactive thyroid, after removal of the gland and for some forms of goitre, as replacement therapy under specialist care.', 'Primjenjuje se kod smanjene funkcije štitne žlijezde, poslije njenog uklanjanja i kod nekih oblika gušavosti, kao nadoknadna terapija.', 'Примјењује се код смањене функције штитне жлијезде, послије њеног уклањања и код неких облика гушавости, као надокнадна терапија.', 'Применяют при сниженной функции щитовидной железы, после её удаления и при некоторых формах зоба как заместительную терапию.', 'Wird bei Schilddrüsenunterfunktion, nach Entfernung der Schilddrüse und bei manchen Kropfformen als Ersatztherapie eingesetzt.', 'Tiroit bezinin az çalışmasında, bezin alınmasından sonra ve bazı guatr biçimlerinde yerine koyma tedavisi olarak kullanılır.', 'Prescription only; the dose is set by a doctor from blood tests. Calcium and iron preparations reduce absorption. Changing or stopping it on your own is dangerous.', 'Izdaje se na recept, dozu određuje ljekar prema nalazima krvi. Preparati kalcijuma i gvožđa smanjuju apsorpciju. Samostalna promjena ili prekid su opasni.', 'Издаје се на рецепт, дозу одређује љекар према налазима крви. Препарати калцијума и гвожђа смањују апсорпцију. Самостална промјена или прекид су опасни.', 'Отпускается по рецепту, дозу подбирает врач по анализам крови. Препараты кальция и железа снижают усвоение. Самостоятельно менять или прекращать приём опасно.', 'Verschreibungspflichtig, die Dosis legt der Arzt anhand der Blutwerte fest. Kalzium und Eisen mindern die Aufnahme. Eigenmächtiges Absetzen ist gefährlich.', 'Reçeteye tabidir, dozu hekim kan tetkiklerine göre belirler. Kalsiyum ve demir ilaçları emilimi azaltır. Kendi başına değiştirmek ya da bırakmak tehlikelidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- lidokain
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (486, 'Lidocaine is an amide-type local anaesthetic that temporarily blocks the transmission of pain', 'Lidokain je lokalni anestetik amidnog tipa koji privremeno blokira prenos bola', 'Лидокаин је локални анестетик амидног типа који привремено блокира пренос бола', 'Лидокаин — местный анестетик амидного типа, который временно блокирует передачу боли', 'Lidocain ist ein Lokalanästhetikum vom Amidtyp, das die Schmerzweiterleitung vorübergehend blockiert', 'Lidokain, ağrı iletimini geçici olarak engelleyen amid yapılı bir lokal anesteziktir', 'Pain relief during medical and dental procedures, numbing of skin and mucous membranes, sore throat', 'Ublažavanje bola tokom medicinskih i stomatoloških zahvata, obamrljivanje kože i sluzokože, bol u grlu', 'Ублажавање бола током медицинских и стоматолошких захвата, обамрљивање коже и слузокоже, бол у грлу', 'Обезболивание при медицинских и стоматологических процедурах, местное обезболивание кожи и слизистых, боль в горле', 'Schmerzausschaltung bei medizinischen und zahnärztlichen Eingriffen, örtliche Betäubung von Haut und Schleimhaut, Halsschmerzen', 'Tıbbi ve diş hekimliği işlemlerinde ağrının giderilmesi, deri ve mukozanın uyuşturulması, boğaz ağrısı', 'Injectable and concentrated forms are used by health professionals on a doctor''s orders. Allergic reactions are possible; it is not applied to large or damaged areas of skin.', 'Injekcione i koncentrovane oblike primjenjuje zdravstveni radnik po nalogu ljekara. Moguće su alergijske reakcije; ne nanosi se na velike i oštećene površine kože.', 'Ињекционе и концентроване облике примјењује здравствени радник по налогу љекара. Могуће су алергијске реакције; не наноси се на велике и оштећене површине коже.', 'Инъекционные и концентрированные формы применяет медработник по назначению врача. Возможны аллергические реакции; средство не наносят на большие и повреждённые участки кожи.', 'Injektions- und hochkonzentrierte Formen wenden medizinische Fachkräfte auf ärztliche Anordnung an. Allergische Reaktionen sind möglich; nicht auf große oder verletzte Hautflächen auftragen.', 'Enjeksiyonluk ve yüksek yoğunluklu formlar hekim talimatıyla sağlık personeli tarafından uygulanır. Alerjik tepki olabilir; geniş ve yaralı deriye uygulanmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- liraglutid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (491, 'A GLP-1 hormone analogue given as an injection under the skin, it slows stomach emptying and reduces appetite.', 'Analog crijevnog hormona koji se daje injekcijom pod kožu, usporava pražnjenje želuca i smanjuje apetit.', 'Аналог цријевног хормона који се даје ињекцијом под кожу, успорава пражњење желуца и смањује апетит.', 'Аналог гормона ГПП-1 для подкожных инъекций: замедляет опорожнение желудка, снижает сахар после еды и уменьшает аппетит.', 'Ein GLP-1-Analogon zur Injektion unter die Haut, es verzögert die Magenentleerung und dämpft den Appetit.', 'Deri altına enjeksiyonla uygulanan bir GLP-1 analoğudur, mide boşalmasını yavaşlatır ve iştahı azaltır.', 'Used in type 2 diabetes, while separate products are used for obesity together with changes in diet and activity.', 'Primjenjuje se kod dijabetesa tipa 2, a posebni preparati kod gojaznosti uz promjenu ishrane i fizičku aktivnost.', 'Примјењује се код дијабетеса типа 2, а посебни препарати код гојазности уз промјену исхране и физичку активност.', 'Применяют при сахарном диабете 2 типа, отдельные препараты — при ожирении вместе с изменением питания и физической активностью.', 'Wird bei Typ-2-Diabetes eingesetzt, eigene Präparate bei Adipositas zusammen mit Ernährungsumstellung und Bewegung.', 'Tip 2 diyabette kullanılır, ayrı preparatları beslenme ve hareket değişikliğiyle birlikte obezitede tercih edilir.', 'Prescription only, given by injection under the skin. Nausea is common at the start. It is not used in type 1 diabetes. Thyroid disease is discussed with a doctor.', 'Izdaje se samo na recept i daje se pod kožu. Na početku je česta mučnina. Ne primjenjuje se kod dijabetesa tipa 1. Bolesti štitaste žlijezde javiti ljekaru.', 'Издаје се само на рецепт и даје се под кожу. На почетку је честа мучнина. Не примјењује се код дијабетеса типа 1. Болести штитасте жлијезде јавити љекару.', 'Только по рецепту, вводится под кожу. В начале лечения часто бывает тошнота. При диабете 1 типа не применяется. Болезни щитовидной железы обсуждают с врачом.', 'Verschreibungspflichtig, wird unter die Haut gespritzt. Zu Beginn ist Übelkeit häufig. Nicht bei Typ-1-Diabetes. Schilddrüsenerkrankungen mit dem Arzt besprechen.', 'Yalnızca reçeteyle verilir, deri altına uygulanır. Başlangıçta bulantı sıktır. Tip 1 diyabette kullanılmaz. Tiroit hastalıkları hekime bildirilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- list ginka
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (492, 'Ginkgo biloba leaf is the plant material for a standardised extract that affects microcirculation.', 'List ginka je biljna sirovina od koje se dobija standardizovani ekstrakt koji utiče na mikrocirkulaciju.', 'Лист гинка је биљна сировина од које се добија стандардизовани екстракт који утиче на микроциркулацију.', 'Листья гинкго двулопастного — растительное сырьё, из которого получают стандартизованный экстракт, влияющий на микроциркуляцию.', 'Ginkgoblätter sind der Pflanzenteil, aus dem ein standardisierter Extrakt mit Wirkung auf die Mikrozirkulation gewonnen wird.', 'Ginkgo biloba yaprağı, mikrodolaşımı etkileyen standart bir ekstrenin elde edildiği bitkisel hammaddedir.', 'Used for age-related decline in memory and attention, dizziness, ringing in the ears and poor circulation in the legs.', 'Primjenjuje se kod slabljenja pamćenja i pažnje u starijem dobu, vrtoglavice, zujanja u ušima i slabe cirkulacije u nogama.', 'Примјењује се код слабљења памћења и пажње у старијем добу, вртоглавице, зујања у ушима и слабе циркулације у ногама.', 'Применяют при снижении памяти и внимания в пожилом возрасте, головокружении, шуме в ушах и нарушениях кровообращения в ногах.', 'Wird bei nachlassendem Gedächtnis und nachlassender Konzentration im Alter, Schwindel, Ohrgeräuschen und Durchblutungsstörungen der Beine angewendet.', 'İleri yaşta bellek ve dikkat azalmasında, baş dönmesinde, kulak çınlamasında ve bacaklarda dolaşım bozukluğunda kullanılır.', 'May increase the effect of blood-thinning medicines and the risk of bleeding. Alongside such medicines and before surgery, use only as directed by a doctor.', 'Može pojačati djelovanje lijekova za razrjeđivanje krvi i povećati rizik od krvarenja. Uz takve lijekove i prije operacija samo po savjetu ljekara.', 'Може појачати дјеловање лијекова за разрјеђивање крви и повећати ризик од крварења. Уз такве лијекове и прије операција само по савјету љекара.', 'Может усиливать действие препаратов, разжижающих кровь, и повышать риск кровотечения. При таких препаратах и перед операциями — только по назначению врача.', 'Kann die Wirkung blutverdünnender Medikamente verstärken und das Blutungsrisiko erhöhen. Zusammen mit ihnen und vor Operationen nur nach ärztlicher Anweisung.', 'Kan sulandırıcı ilaçların etkisini ve kanama riskini artırabilir. Bu ilaçlarla birlikte ve ameliyat öncesinde yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- lizozim
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (495, 'A natural enzyme with an antiseptic action, used locally in the throat and mouth, often together with vitamin B6.', 'Prirodni enzim sa antiseptičkim djelovanjem za lokalnu primjenu u grlu i ustima, često u kombinaciji sa vitaminom B6.', 'Природни ензим са антисептичким дјеловањем за локалну примјену у грлу и устима, често у комбинацији са витамином B6.', 'Природный фермент с антисептическим действием для местного применения в горле и полости рта, часто в сочетании с витамином B6.', 'Ein natürliches Enzym mit antiseptischer Wirkung zur örtlichen Anwendung in Hals und Mund, oft zusammen mit Vitamin B6.', 'Boğaz ve ağızda bölgesel kullanılan, antiseptik etkili doğal bir enzimdir, sıklıkla B6 vitamini ile birlikte bulunur.', 'Used for a sore and irritated throat, inflammation of the mouth lining and gums, and for hoarseness.', 'Primjenjuje se kod bola i nadražaja u grlu, zapaljenja sluznice usta i desni, kao i kod promuklosti.', 'Примјењује се код бола и надражаја у грлу, запаљења слузнице уста и десни, као и код промуклости.', 'Применяют при боли и раздражении в горле, воспалении слизистой рта и дёсен, а также при охриплости.', 'Wird bei Halsschmerzen und Reizungen, Entzündungen der Mundschleimhaut und des Zahnfleischs sowie bei Heiserkeit angewendet.', 'Boğaz ağrısı ve tahrişinde, ağız mukozası ve diş eti iltihabında, ses kısıklığında kullanılır.', 'Available over the counter. High fever, coating on the tonsils or a sore throat that does not pass need a doctor''s examination. In children, on a doctor''s advice.', 'Izdaje se bez recepta. Visoka temperatura, naslage na krajnicima i bol u grlu koji ne prolazi traže pregled ljekara. Kod djece po savjetu ljekara.', 'Издаје се без рецепта. Висока температура, наслаге на крајницима и бол у грлу који не пролази траже преглед љекара. Код дјеце по савјету љекара.', 'Отпускается без рецепта. При высокой температуре, налётах на миндалинах и долго не проходящей боли в горле нужен осмотр врача. Детям — по назначению врача.', 'Rezeptfrei erhältlich. Hohes Fieber, Beläge auf den Mandeln und anhaltende Halsschmerzen erfordern eine ärztliche Untersuchung. Bei Kindern nach ärztlichem Rat.', 'Reçetesiz satılır. Yüksek ateş, bademciklerde plak ve geçmeyen boğaz ağrısı hekim muayenesi gerektirir. Çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- loratadin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (498, 'A second-generation antihistamine that causes drowsiness less often than older ones.', 'Antihistaminik druge generacije koji rjeđe izaziva pospanost od starijih lijekova.', 'Антихистаминик друге генерације који рјеђе изазива поспаност од старијих лијекова.', 'Антигистаминное средство второго поколения, которое реже вызывает сонливость, чем старые препараты.', 'Ein Antihistaminikum der zweiten Generation, das seltener müde macht als ältere Mittel.', 'Eski ilaçlara göre daha az uyku hali yapan ikinci kuşak bir antihistaminiktir.', 'Used for seasonal and year-round allergic rhinitis, hives and allergic itching of the skin.', 'Primjenjuje se kod sezonskog i cjelogodišnjeg alergijskog rinitisa, koprivnjače i alergijskog svraba kože.', 'Примјењује се код сезонског и цјелогодишњег алергијског ринитиса, копривњаче и алергијског свраба коже.', 'Применяют при сезонном и круглогодичном аллергическом рините, крапивнице и кожном зуде аллергической природы.', 'Wird bei saisonalem und ganzjährigem allergischem Schnupfen, Nesselsucht und allergischem Hautjucken angewendet.', 'Mevsimsel ve yıl boyu süren alerjik nezlede, kurdeşende ve alerjik deri kaşıntısında kullanılır.', 'Available over the counter. Drowsiness is rare but worth keeping in mind when driving. With liver disease, in pregnancy and in children, on a doctor''s advice.', 'Izdaje se bez recepta. Pospanost je rijetka, ali se uzima u obzir pri vožnji. Kod bolesti jetre, u trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта. Поспаност је ријетка, али се узима у обзир при вожњи. Код болести јетре, у трудноћи и код дјеце само по савјету љекара.', 'Отпускается без рецепта. Сонливость бывает редко, но при вождении это учитывают. При болезнях печени, беременности и у детей — по назначению врача.', 'Rezeptfrei erhältlich. Müdigkeit ist selten, beim Autofahren aber zu bedenken. Bei Lebererkrankungen, in der Schwangerschaft und bei Kindern nach ärztlichem Rat.', 'Reçetesiz satılır. Uyku hali nadirdir ama araç kullanırken dikkate alınmalıdır. Karaciğer hastalığında, gebelikte ve çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- magaldrat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (505, 'An antacid, a compound of aluminium and magnesium that neutralises stomach acid.', 'Antacid, jedinjenje aluminijuma i magnezijuma koje neutrališe želudačnu kiselinu.', 'Антацид, једињење алуминијума и магнезијума које неутралише желудачну киселину.', 'Антацид — соединение алюминия и магния, нейтрализует соляную кислоту в желудке.', 'Ein Antazidum, eine Aluminium-Magnesium-Verbindung, die Magensäure neutralisiert.', 'Mide asidini nötralize eden alüminyum ve magnezyum bileşiği, yani bir antasittir.', 'Used for heartburn, acid belching and discomfort in the upper abdomen, including with reflux and gastritis.', 'Primjenjuje se kod žgaravice, kiselog podrigivanja i nelagode u gornjem dijelu stomaka, uključujući refluks i gastritis.', 'Примјењује се код жгаравице, киселог подригивања и нелагоде у горњем дијелу стомака, укључујући рефлукс и гастритис.', 'Применяют при изжоге, кислой отрыжке и дискомфорте в верхней части живота, в том числе при рефлюксе и гастрите.', 'Wird bei Sodbrennen, saurem Aufstoßen und Beschwerden im Oberbauch angewendet, auch bei Reflux und Gastritis.', 'Mide yanmasında, ekşi geğirmede ve reflü ile gastrit dahil üst karın bölgesindeki rahatsızlıkta kullanılır.', 'Available without prescription. It reduces absorption of other medicines, so they are spaced apart in time. In kidney disease, in children and in pregnancy only as prescribed.', 'Izdaje se bez recepta. Smanjuje apsorpciju drugih lijekova, pa se oni uzimaju vremenski odvojeno. Kod bolesti bubrega, kod djece i u trudnoći po savjetu ljekara.', 'Издаје се без рецепта. Смањује апсорпцију других лијекова, па се они узимају временски одвојено. Код болести бубрега, код дјеце и у трудноћи по савјету љекара.', 'Отпускается без рецепта. Мешает всасыванию других лекарств, поэтому их разносят по времени. При болезнях почек, у детей и при беременности — по назначению врача.', 'Rezeptfrei. Die Aufnahme anderer Medikamente wird verringert, daher werden diese zeitlich versetzt genommen. Bei Nierenerkrankungen, Kindern und Schwangerschaft ärztlich abklären.', 'Reçetesiz satılır. Diğer ilaçların emilimini azaltır, bu yüzden aralarına zaman konur. Böbrek hastalığında, çocuklarda ve gebelikte doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- magnezijum karbonat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (510, 'An antacid magnesium salt that neutralises stomach acid, often combined with calcium salts.', 'Antacid na bazi soli magnezijuma, neutrališe želudačnu kiselinu, često u kombinaciji sa solima kalcijuma.', 'Антацид на бази соли магнезијума, неутралише желудачну киселину, често у комбинацији са солима калцијума.', 'Антацид на основе соли магния: нейтрализует желудочную кислоту, часто в сочетании с солями кальция.', 'Ein Antazidum auf Magnesiumbasis, das Magensäure neutralisiert, oft zusammen mit Kalziumsalzen.', 'Mide asidini nötralize eden magnezyum tuzu esaslı bir antasittir, sıklıkla kalsiyum tuzlarıyla birlikte kullanılır.', 'Used for heartburn, acid regurgitation and stomach discomfort caused by excess acid.', 'Primjenjuje se kod žgaravice, kiselog podrigivanja i nelagode u želucu zbog pojačane kiseline.', 'Примјењује се код жгаравице, киселог подригивања и нелагоде у желуцу због појачане киселине.', 'Применяют при изжоге, кислой отрыжке и дискомфорте в желудке, связанных с повышенной кислотностью.', 'Wird bei Sodbrennen, saurem Aufstoßen und Magenbeschwerden durch zu viel Säure angewendet.', 'Mide yanmasında, ekşi geğirmede ve asit fazlalığına bağlı mide rahatsızlığında kullanılır.', 'Over the counter. It can loosen the stools and interfere with the absorption of other medicines. With kidney disease or persistent heartburn, see a doctor.', 'Izdaje se bez recepta. Može omekšati stolicu i ometati apsorpciju drugih lijekova. Kod bolesti bubrega i stalne žgaravice javiti se ljekaru.', 'Издаје се без рецепта. Може омекшати столицу и ометати апсорпцију других лијекова. Код болести бубрега и сталне жгаравице јавити се љекару.', 'Отпускается без рецепта. Может послаблять стул и мешать всасыванию других лекарств. При болезнях почек и постоянной изжоге нужен врач.', 'Rezeptfrei. Kann den Stuhl weich machen und die Aufnahme anderer Medikamente stören. Bei Nierenerkrankungen und anhaltendem Sodbrennen zum Arzt.', 'Reçetesiz satılır. Dışkıyı yumuşatabilir ve diğer ilaçların emilimini bozabilir. Böbrek hastalığında ve sürekli mide yanmasında hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- makrogol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (514, 'An osmotic laxative that holds water in the bowel and softens stool without being absorbed.', 'Osmotski laksativ koji zadržava vodu u crijevu i omekšava stolicu, a sam se ne resorbuje.', 'Осмотски лаксатив који задржава воду у цријеву и омекшава столицу, а сам се не ресорбује.', 'Осмотическое слабительное: удерживает воду в кишечнике и размягчает стул, само не всасывается.', 'Ein osmotisches Abführmittel, das Wasser im Darm bindet und den Stuhl weich macht, ohne aufgenommen zu werden.', 'Bağırsakta suyu tutarak dışkıyı yumuşatan, emilmeyen osmotik bir müshildir.', 'Used for constipation, including long-standing constipation, and to empty the bowel before colonoscopy and surgery.', 'Primjenjuje se kod zatvora, i dugotrajnog, i za potpuno pražnjenje crijeva prije kolonoskopije i operacija.', 'Примјењује се код затвора, и дуготрајног, и за потпуно пражњење цријева прије колоноскопије и операција.', 'Применяют при запоре, в том числе длительном, и для полного очищения кишечника перед колоноскопией и операциями.', 'Wird bei Verstopfung, auch bei anhaltender, und zur vollständigen Darmentleerung vor Koloskopie und Operationen eingesetzt.', 'Kabızlıkta, uzun süren kabızlık dahil, ayrıca kolonoskopi ve ameliyat öncesi bağırsağın tamamen boşaltılmasında kullanılır.', 'Some forms are over the counter, bowel-prep solutions are used as prescribed. It must not be taken with abdominal pain or suspected bowel obstruction.', 'Dio oblika je bez recepta, rastvori za pripremu za kolonoskopiju po savjetu ljekara. Ne uzima se kod bolova u trbuhu i sumnje na opstrukciju crijeva.', 'Дио облика је без рецепта, раствори за припрему за колоноскопију по савјету љекара. Не узима се код болова у трбуху и сумње на опструкцију цријева.', 'Часть форм безрецептурная, растворы для подготовки к колоноскопии — по назначению врача. При боли в животе и подозрении на непроходимость приём недопустим.', 'Ein Teil ist rezeptfrei, Lösungen zur Darmvorbereitung nur nach ärztlicher Anweisung. Bei Bauchschmerzen und Verdacht auf Darmverschluss nicht anwenden.', 'Bazı formları reçetesizdir, kolonoskopi hazırlık çözeltileri hekim önerisiyle kullanılır. Karın ağrısında ve bağırsak tıkanıklığı şüphesinde kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- matičnjak (melissa officinalis)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (520, 'Lemon balm (Melissa officinalis) is a medicinal plant whose leaf extract has a mild calming effect. It is used in combined herbal remedies.', 'Matičnjak je ljekovita biljka čiji ekstrakt lista ima blago umirujuće djelovanje. Ulazi u kombinovane biljne preparate.', 'Матичњак је љековита биљка чији екстракт листа има благо умирујуће дјеловање. Улази у комбиноване биљне препарате.', 'Мелисса лекарственная — растение, из листьев которого получают экстракт с мягким успокаивающим действием. Входит в растительные комбинации.', 'Melisse (Melissa officinalis) ist eine Heilpflanze, deren Blattextrakt leicht beruhigend wirkt. Sie steckt in pflanzlichen Kombipräparaten.', 'Oğulotu (Melissa officinalis), yaprak ekstresi hafif sakinleştirici etki gösteren tıbbi bir bitkidir. Kombine bitkisel preparatlarda bulunur.', 'Used for nervous tension, irritability and trouble falling asleep, usually together with valerian and peppermint.', 'Primjenjuje se kod nervne napetosti, razdražljivosti i teškog uspavljivanja, obično uz valerijanu i nanu.', 'Примјењује се код нервне напетости, раздражљивости и тешког успављивања, обично уз валеријану и нану.', 'Применяют при нервном напряжении, раздражительности и трудностях с засыпанием, обычно в сочетании с валерианой и мятой.', 'Wird bei nervöser Anspannung, Reizbarkeit und Einschlafproblemen eingesetzt, meist zusammen mit Baldrian und Pfefferminze.', 'Sinirsel gerginlikte, huzursuzlukta ve uykuya dalma güçlüğünde, genellikle kediotu ve naneyle birlikte kullanılır.', 'Available over the counter. Drowsiness is possible, so avoid alcohol and sleeping pills. Lasting anxiety or insomnia, and use in children, need a doctor.', 'Izdaje se bez recepta. Moguća je pospanost, pa se ne kombinuje sa alkoholom i lijekovima za spavanje. Uporna nesanica i primjena kod djece traže ljekara.', 'Издаје се без рецепта. Могућа је поспаност, па се не комбинује са алкохолом и лијековима за спавање. Упорна несаница и примјена код дјеце траже љекара.', 'Отпускается без рецепта. Возможна сонливость, с алкоголем и снотворными не сочетают. При стойкой тревоге и бессоннице, а также детям — нужен врач.', 'Rezeptfrei erhältlich. Müdigkeit ist möglich, kein Alkohol und keine Schlafmittel dazu. Anhaltende Schlaflosigkeit und Anwendung bei Kindern gehören zum Arzt.', 'Reçetesiz satılır. Uyku hali görülebilir, alkol ve uyku ilaçlarıyla birlikte kullanılmaz. Süregelen uykusuzlukta ve çocuklarda hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- medicinski ugalj
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (523, 'Activated charcoal, an adsorbent that binds substances and gas in the gut and leaves the body without being absorbed.', 'Medicinski ugalj je adsorbens koji veže materije i gasove u crijevima i izlučuje se bez ulaska u krvotok.', 'Медицински угаљ је адсорбенс који веже материје и гасове у цријевима и излучује се без уласка у крвоток.', 'Активированный уголь, сорбент: связывает вещества и газы в кишечнике и выводится, не всасываясь в кровь.', 'Medizinische Kohle, ein Adsorbens, das Stoffe und Gase im Darm bindet und unverändert ausgeschieden wird.', 'Bağırsakta maddeleri ve gazı bağlayan, kana geçmeden atılan bir adsorbandır.', 'Used for bloating, diarrhoea and digestive upsets, and in some poisonings, where the decision is a doctor''s.', 'Primjenjuje se kod nadutosti, proljeva i probavnih smetnji, a kod pojedinih trovanja po odluci ljekara.', 'Примјењује се код надутости, прољева и пробавних сметњи, а код појединих тровања по одлуци љекара.', 'Применяют при вздутии, диарее и пищевых расстройствах, а также при некоторых отравлениях — в этом случае по решению врача.', 'Wird bei Blähungen, Durchfall und Verdauungsbeschwerden eingesetzt, bei manchen Vergiftungen nach ärztlicher Entscheidung.', 'Şişkinlik, ishal ve sindirim şikayetlerinde, bazı zehirlenmelerde ise hekim kararıyla kullanılır.', 'Available over the counter. It reduces the absorption of other medicines, so it is not taken together with them. It turns stools black.', 'Izdaje se bez recepta. Smanjuje apsorpciju drugih lijekova, pa se ne uzima zajedno sa njima. Boji stolicu u crno.', 'Издаје се без рецепта. Смањује апсорпцију других лијекова, па се не узима заједно са њима. Боји столицу у црно.', 'Отпускается без рецепта. Снижает всасывание других лекарств, поэтому одновременно с ними не принимают. Окрашивает стул в чёрный цвет.', 'Rezeptfrei erhältlich. Es verringert die Aufnahme anderer Medikamente und wird daher nicht zusammen mit ihnen eingenommen. Der Stuhl färbt sich schwarz.', 'Reçetesiz satılır. Diğer ilaçların emilimini azalttığı için onlarla birlikte alınmaz. Dışkıyı siyaha boyar.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- meki ekstrakt ploda
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (524, 'A soft extract of saw palmetto fruit, a plant-based ingredient of preparations used in urology.', 'Meki ekstrakt ploda testeraste palme, biljna sirovina preparata koji se koriste u urologiji.', 'Меки екстракт плода тестерасте палме, биљна сировина препарата који се користе у урологији.', 'Мягкий экстракт плодов пальмы сабаль — растительное сырьё препаратов, которые применяют в урологии.', 'Ein Weichextrakt aus Sägepalmenfrüchten, pflanzlicher Bestandteil von Mitteln für urologische Beschwerden.', 'Cüce palmiye meyvesinin yumuşak ekstresidir, ürolojide kullanılan preparatların bitkisel içeriğidir.', 'Used for urinary complaints linked to benign enlargement of the prostate.', 'Primjenjuje se kod tegoba sa mokrenjem koje prate benigno uvećanje prostate.', 'Примјењује се код тегоба са мокрењем које прате бенигно увећање простате.', 'Применяют при жалобах на мочеиспускание, связанных с доброкачественным увеличением предстательной железы.', 'Wird bei Beschwerden beim Wasserlassen im Rahmen einer gutartigen Vergrößerung der Prostata angewendet.', 'İyi huylu prostat büyümesine bağlı idrar yapma şikayetlerinde kullanılır.', 'Available without prescription, but it does not replace a check-up: similar complaints occur in other prostate conditions. The effect builds slowly and is judged by a doctor.', 'Izdaje se bez recepta, ali ne zamjenjuje pregled: slične tegobe daju i druge bolesti prostate. Djelovanje nastupa sporo, a učinak procjenjuje ljekar.', 'Издаје се без рецепта, али не замјењује преглед: сличне тегобе дају и друге болести простате. Дјеловање наступа споро, а учинак процјењује љекар.', 'Отпускается без рецепта, но обследование не заменяет: похожие жалобы бывают и при других болезнях простаты. Действие развивается медленно, эффект оценивает врач.', 'Rezeptfrei, ersetzt aber keine Untersuchung: ähnliche Beschwerden haben auch andere Prostataerkrankungen. Die Wirkung setzt langsam ein, den Verlauf beurteilt der Arzt.', 'Reçetesiz satılır ancak muayenenin yerini tutmaz: benzer şikayetler başka prostat hastalıklarında da görülür. Etkisi yavaş gelişir, sonucu doktor değerlendirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- meki ekstrakt talusa
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (525, 'Soft thallus extract is a herbal active-substance heading; in the Montenegrin registry it stands for Iceland moss thallus in a cough syrup.', 'Meki ekstrakt talusa, oznaka biljne aktivne supstance; u crnogorskom registru to je talus islandskog lišaja u sirupu protiv kašlja.', 'Меки екстракт талуса, ознака биљне активне супстанце; у црногорском регистру то је талус исландског лишаја у сирупу против кашља.', 'Мягкий экстракт слоевища — обозначение растительного действующего вещества; в реестре Черногории это слоевище исландского мха в сиропе от кашля.', 'Weicher Thallusextrakt ist die Bezeichnung eines pflanzlichen Wirkstoffs, im montenegrinischen Register der Isländisch-Moos-Thallus im Hustensaft.', 'Yumuşak talus ekstresi bitkisel bir etkin madde tanımıdır; Karadağ kayıtlarında öksürük şurubundaki İzlanda likeni talusunu gösterir.', 'Such extracts go into herbal cough syrups: they coat the lining of the throat and ease a dry cough and a scratchy throat.', 'Takvi ekstrakti ulaze u biljne sirupe protiv kašlja: oblažu sluznicu i ublažavaju suv kašalj i grebanje u grlu.', 'Такви екстракти улазе у биљне сирупе против кашља: облажу слузницу и ублажавају сув кашаљ и гребање у грлу.', 'Такие экстракты входят в растительные сиропы от кашля: они обволакивают слизистую и смягчают сухой кашель и першение в горле.', 'Solche Extrakte stecken in pflanzlichen Hustensäften: Sie legen sich über die Schleimhaut und lindern trockenen Husten und Halskratzen.', 'Bu tür ekstreler bitkisel öksürük şuruplarında bulunur, boğaz mukozasını kaplayarak kuru öksürüğü ve boğaz kaşıntısını hafifletir.', 'Sold without prescription, and syrups may contain sugar. For children and in pregnancy, only as a doctor advises. A lasting cough with fever needs examination.', 'Preparati se izdaju bez recepta, sirup može sadržati šećer. Djeci i trudnicama po preporuci ljekara. Dugotrajan kašalj sa temperaturom traži pregled.', 'Препарати се издају без рецепта, сируп може садржати шећер. Дјеци и трудницама по препоруци љекара. Дуготрајан кашаљ са температуром тражи преглед.', 'Средства безрецептурные, сироп может содержать сахар. Детям и беременным — по назначению врача. Затяжной кашель с температурой требует осмотра.', 'Rezeptfrei, der Saft kann Zucker enthalten. Für Kinder und in der Schwangerschaft nur nach ärztlichem Rat. Anhaltender Husten mit Fieber gehört untersucht.', 'Reçetesiz satılır, şurup şeker içerebilir. Çocuklarda ve gebelikte hekim önerisiyle kullanılır. Ateşle birlikte süren öksürük muayene gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- mentol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (530, 'A substance from mint with a cooling and mild pain-relieving effect. In Montenegro it is part of topical rubbing products.', 'Supstanca iz nane sa rashlađujućim i blagim analgetskim djelovanjem. U Crnoj Gori ulazi u spoljne preparate za utrljavanje.', 'Супстанца из нане са расхлађујућим и благим аналгетским дјеловањем. У Црној Гори улази у спољне препарате за утрљавање.', 'Вещество из мяты с охлаждающим и слабым обезболивающим действием. В Черногории входит в наружные средства для растирания.', 'Ein Stoff aus der Minze mit kühlender und leicht schmerzlindernder Wirkung. In Montenegro Bestandteil von Einreibemitteln.', 'Naneden elde edilen, serinletici ve hafif ağrı kesici etkili bir maddedir. Karadağ''da ovma ürünlerinde bulunur.', 'Used in topical products for muscle and joint pain, bruises and sprains, and for itchy skin.', 'Primjenjuje se u spoljnim preparatima kod bolova u mišićima i zglobovima, kod nagnječenja i istegnuća i kod svraba kože.', 'Примјењује се у спољним препаратима код болова у мишићима и зглобовима, код нагњечења и истегнућа и код свраба коже.', 'Применяют в составе наружных средств при боли в мышцах и суставах, при ушибах и растяжениях, а также при кожном зуде.', 'Wird in äußerlichen Mitteln bei Muskel- und Gelenkschmerzen, Prellungen und Zerrungen sowie bei Juckreiz angewendet.', 'Dıştan kullanılan ürünlerde kas ve eklem ağrısında, berelenme ve burkulmalarda, deri kaşıntısında kullanılır.', 'Available over the counter. External use only, skin irritation is possible. Not applied to the face of babies and small children because of the risk of airway spasm.', 'Izdaje se bez recepta. Samo spolja, moguć je nadražaj kože. Odojčadi i maloj djeci se ne nanosi na lice zbog rizika od grča disajnih puteva.', 'Издаје се без рецепта. Само споља, могућ је надражај коже. Одојчади и малој дјеци се не наноси на лице због ризика од грча дисајних путева.', 'Отпускается без рецепта. Только наружно, возможно раздражение кожи. Младенцам и маленьким детям на лицо не наносят из-за риска спазма дыхания.', 'Rezeptfrei erhältlich. Nur äußerlich, Hautreizungen sind möglich. Bei Säuglingen und kleinen Kindern nicht im Gesicht anwenden, es droht ein Atemwegskrampf.', 'Reçetesiz satılır. Yalnızca haricen kullanılır, ciltte tahriş olabilir. Solunum yolu spazmı riski nedeniyle bebek ve küçük çocukların yüzüne sürülmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- meropenem
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (531, 'A broad-spectrum antibiotic from the carbapenem group. It is given intravenously in hospital.', 'Antibiotik iz grupe karbapenema širokog spektra djelovanja. Daje se intravenski u bolnici.', 'Антибиотик из групе карбапенема широког спектра дјеловања. Даје се интравенски у болници.', 'Антибиотик группы карбапенемов с широким спектром действия. Вводят внутривенно в стационаре.', 'Ein Breitbandantibiotikum aus der Gruppe der Carbapeneme. Es wird im Krankenhaus intravenös gegeben.', 'Karbapenem grubundan geniş spektrumlu bir antibiyotiktir. Hastanede damar yoluyla uygulanır.', 'Used in hospital for severe infections such as pneumonia, abdominal and urinary tract infections, meningitis and sepsis.', 'Primjenjuje se u bolnici kod teških infekcija, kao što su upala pluća, infekcije trbuha i mokraćnih puteva, meningitis i sepsa.', 'Примјењује се у болници код тешких инфекција, као што су упала плућа, инфекције трбуха и мокраћних путева, менингитис и сепса.', 'Применяют в больнице при тяжёлых инфекциях — пневмонии, инфекциях брюшной полости и мочевых путей, менингите и сепсисе.', 'Wird im Krankenhaus bei schweren Infektionen wie Lungenentzündung, Bauch- und Harnwegsinfektionen, Meningitis und Sepsis eingesetzt.', 'Zatürre, karın içi ve idrar yolu enfeksiyonları, menenjit ve sepsis gibi ağır enfeksiyonlarda hastanede kullanılır.', 'Prescription only and given by medical staff in hospital. It is a reserve antibiotic used when others no longer work. Tell the doctor about allergy to penicillins or beta-lactams.', 'Izdaje se samo na recept, daje ga zdravstveno osoblje u bolnici. Rezervni je antibiotik. Važno je reći ljekaru za alergiju na peniciline i druge beta-laktame.', 'Издаје се само на рецепт, даје га здравствено особље у болници. Резервни је антибиотик. Важно је рећи љекару за алергију на пеницилине и друге бета-лактаме.', 'Только по рецепту, вводит медработник в стационаре. Резервный антибиотик, назначают при устойчивости к другим. Важно сообщить об аллергии на пенициллины и бета-лактамы.', 'Verschreibungspflichtig und wird von medizinischem Personal im Krankenhaus verabreicht. Reserveantibiotikum. Allergien gegen Penicilline und Beta-Lactame unbedingt melden.', 'Yalnızca reçeteyle verilir ve hastanede sağlık personeli tarafından uygulanır. Yedek antibiyotiktir. Penisilin ve beta-laktam alerjisi hekime bildirilmelidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- mesalazin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (532, 'An anti-inflammatory medicine that acts inside the bowel (an aminosalicylate).', 'Protivupalni lijek koji djeluje u crijevima (aminosalicilat).', 'Противупални лијек који дјелује у цријевима (аминосалицилат).', 'Противовоспалительное средство, действующее в кишечнике (аминосалицилат).', 'Ein entzündungshemmendes Mittel, das im Darm wirkt (ein Aminosalicylat).', 'Bağırsak içinde etki gösteren yangı giderici bir ilaçtır (aminosalisilat).', 'Used in ulcerative colitis and Crohn''s disease, both during flare-ups and to keep the disease in remission.', 'Primjenjuje se kod ulceroznog kolitisa i Crohnove bolesti, u pogoršanju i za održavanje remisije.', 'Примјењује се код улцерозног колитиса и Црохнове болести, у погоршању и за одржавање ремисије.', 'Применяют при язвенном колите и болезни Крона — при обострении и для поддержания ремиссии.', 'Wird bei Colitis ulcerosa und Morbus Crohn eingesetzt, im Schub und zum Erhalt der Remission.', 'Ülseratif kolit ve Crohn hastalığında, alevlenme dönemlerinde ve remisyonun sürdürülmesinde kullanılır.', 'Prescription only, the regimen is set by the doctor. Nausea and headache are possible and kidney function is monitored. Not used with allergy to salicylates.', 'Izdaje se na recept, terapiju određuje ljekar. Mogući su mučnina i glavobolja, prati se rad bubrega. Ne primjenjuje se kod alergije na salicilate.', 'Издаје се на рецепт, терапију одређује љекар. Могући су мучнина и главобоља, прати се рад бубрега. Не примјењује се код алергије на салицилате.', 'Отпускается по рецепту, схему определяет врач. Возможны тошнота и головная боль, нужен контроль работы почек. При аллергии на салицилаты не применяют.', 'Verschreibungspflichtig, die Therapie legt der Arzt fest. Übelkeit und Kopfschmerzen sind möglich, die Nierenfunktion wird kontrolliert. Nicht bei Salicylatallergie.', 'Yalnızca reçeteyle verilir, tedaviyi hekim belirler. Bulantı ve baş ağrısı olabilir, böbrek işlevi izlenir. Salisilat alerjisinde kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- metamizol natrijum
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (534, 'A painkiller and fever reducer of the pyrazolone group.', 'Lijek protiv bola i povišene temperature iz grupe pirazolona.', 'Лијек против бола и повишене температуре из групе пиразолона.', 'Обезболивающее и жаропонижающее вещество из группы пиразолонов.', 'Ein Schmerz- und Fiebermittel aus der Gruppe der Pyrazolone.', 'Pirazolon grubundan bir ağrı kesici ve ateş düşürücü maddedir.', 'Used for severe pain, including cramping pain, and for high fever when other medicines have not helped.', 'Primjenjuje se kod jakog bola, uključujući grčeviti, i kod visoke temperature kada drugi lijekovi nijesu pomogli.', 'Примјењује се код јаког бола, укључујући грчевити, и код високе температуре када други лијекови нијесу помогли.', 'Применяют при сильной боли, в том числе спазматической, и при высокой температуре, когда другие средства не помогли.', 'Wird bei starken, auch krampfartigen Schmerzen und bei hohem Fieber angewendet, wenn andere Mittel nicht geholfen haben.', 'Diğer ilaçların yetmediği şiddetli ağrıda, kramp tarzı ağrılarda ve yüksek ateşte kullanılır.', 'It can rarely cause a dangerous drop in white blood cells (agranulocytosis) and is banned in some countries, injections are given only on a doctor''s order.', 'Rijetko izaziva opasan pad broja bijelih krvnih zrnaca (agranulocitozu), zbog čega je u nekim državama zabranjen, injekcije se daju samo po nalogu ljekara.', 'Ријетко изазива опасан пад броја бијелих крвних зрнаца (агранулоцитозу), због чега је у неким државама забрањен, ињекције се дају само по налогу љекара.', 'Редко вызывает опасное падение уровня лейкоцитов (агранулоцитоз), из-за чего запрещён в ряде стран, инъекции применяют только по назначению врача.', 'Kann selten einen gefährlichen Abfall der weißen Blutkörperchen (Agranulozytose) auslösen und ist in einigen Ländern verboten, Injektionen nur auf ärztliche Anordnung.', 'Ender olarak akyuvarlarda tehlikeli düşüşe (agranülositoz) yol açabilir, bu nedenle bazı ülkelerde yasaktır, iğneleri yalnızca doktor kararıyla uygulanır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- metformin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (535, 'A glucose-lowering biguanide that reduces glucose production by the liver and improves the body''s sensitivity to insulin.', 'Lijek za snižavanje šećera iz grupe bigvanida, smanjuje stvaranje glukoze u jetri i povećava osjetljivost na insulin.', 'Лијек за снижавање шећера из групе бигванида, смањује стварање глукозе у јетри и повећава осјетљивост на инсулин.', 'Сахароснижающее вещество группы бигуанидов: уменьшает выработку глюкозы печенью и повышает чувствительность к инсулину.', 'Ein blutzuckersenkendes Biguanid, das die Zuckerbildung in der Leber senkt und die Insulinempfindlichkeit verbessert.', 'Karaciğerde şeker üretimini azaltan ve insüline duyarlılığı artıran, biguanid grubundan kan şekeri düşürücü bir maddedir.', 'Prescribed for type 2 diabetes, alone or in fixed combinations with other glucose-lowering substances.', 'Propisuje se kod dijabetesa tipa 2, sam ili u fiksnim kombinacijama sa drugim lijekovima za snižavanje šećera.', 'Прописује се код дијабетеса типа 2, сам или у фиксним комбинацијама са другим лијековима за снижавање шећера.', 'Назначают при сахарном диабете 2 типа, отдельно или в фиксированных комбинациях с другими сахароснижающими веществами.', 'Wird bei Typ-2-Diabetes verordnet, allein oder in festen Kombinationen mit anderen blutzuckersenkenden Wirkstoffen.', 'Tip 2 diyabette tek başına ya da diğer kan şekeri düşürücülerle sabit kombinasyonlar içinde reçete edilir.', 'Prescription only. Nausea and loose stools are common at the start. With kidney disease, dehydration or before contrast imaging, a doctor adjusts the treatment.', 'Izdaje se samo na recept. Na početku su mogući mučnina i proljev. Kod bolesti bubrega, dehidracije i prije snimanja sa kontrastom terapiju mijenja ljekar.', 'Издаје се само на рецепт. На почетку су могући мучнина и прољев. Код болести бубрега, дехидрације и прије снимања са контрастом терапију мијења љекар.', 'Только по рецепту. В начале приёма возможны тошнота и расстройство стула. При болезнях почек, обезвоживании и перед исследованиями с контрастом лечение меняет врач.', 'Verschreibungspflichtig. Zu Beginn sind Übelkeit und weicher Stuhl möglich. Bei Nierenkrankheiten, Flüssigkeitsmangel und vor Kontrastmitteluntersuchungen entscheidet der Arzt.', 'Yalnızca reçeteyle verilir. Başlangıçta bulantı ve yumuşak dışkı görülebilir. Böbrek hastalığı, sıvı kaybı ve kontrastlı tetkik öncesinde tedaviyi hekim düzenler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- metil salicilat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (537, 'A salicylate for external use with a pain-relieving and anti-inflammatory effect. It is part of warming topical products.', 'Salicilat za spoljnu primjenu sa analgetskim i protivupalnim djelovanjem. Ulazi u zagrijavajuće preparate za utrljavanje.', 'Салицилат за спољну примјену са аналгетским и противупалним дјеловањем. Улази у загријавајуће препарате за утрљавање.', 'Салицилат для наружного применения с обезболивающим и противовоспалительным действием. Входит в согревающие средства для растирания.', 'Ein Salicylat zur äußerlichen Anwendung mit schmerzlindernder und entzündungshemmender Wirkung. Bestandteil wärmender Einreibemittel.', 'Ağrı kesici ve iltihap giderici etkili, dıştan kullanılan bir salisilattır. Isıtıcı ovma ürünlerinin içinde bulunur.', 'Used in topical products for muscle, joint and back pain, for sprains and for strain after physical activity.', 'Primjenjuje se u spoljnim preparatima kod bolova u mišićima, zglobovima i leđima, kod istegnuća i preopterećenja poslije napora.', 'Примјењује се у спољним препаратима код болова у мишићима, зглобовима и леђима, код истегнућа и преоптерећења послије напора.', 'Применяют в составе наружных средств при боли в мышцах, суставах и спине, при растяжениях и перегрузке после физической нагрузки.', 'Wird in äußerlichen Mitteln bei Muskel-, Gelenk- und Rückenschmerzen, bei Zerrungen und Überlastung nach Sport angewendet.', 'Dıştan kullanılan ürünlerde kas, eklem ve sırt ağrısında, burkulmalarda ve fiziksel zorlanma sonrası ağrılarda kullanılır.', 'Available over the counter. Only on unbroken skin and not under tight dressings. With aspirin allergy, in children and in pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta. Samo na neoštećenu kožu i bez čvrstih zavoja. Kod alergije na aspirin, kod djece i u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта. Само на неоштећену кожу и без чврстих завоја. Код алергије на аспирин, код дјеце и у трудноћи само по савјету љекара.', 'Отпускается без рецепта. Только на неповреждённую кожу и без плотных повязок. При аллергии на аспирин, у детей и при беременности — по назначению врача.', 'Rezeptfrei erhältlich. Nur auf unverletzte Haut und nicht unter festen Verbänden. Bei Aspirinallergie, bei Kindern und in der Schwangerschaft nur nach ärztlichem Rat.', 'Reçetesiz satılır. Yalnızca sağlam deriye, sıkı sargı altına uygulanmadan kullanılır. Aspirin alerjisinde, çocuklarda ve gebelikte hekim önerisi gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- metilprednizolon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (540, 'A glucocorticoid with a strong anti-inflammatory and anti-allergic action.', 'Glukokortikoid sa snažnim protivupalnim i antialergijskim djelovanjem.', 'Глукокортикоид са снажним противупалним и антиалергијским дјеловањем.', 'Глюкокортикоид с сильным противовоспалительным и противоаллергическим действием.', 'Ein Glukokortikoid mit starker entzündungshemmender und antiallergischer Wirkung.', 'Güçlü iltihap ve alerji giderici etkisi olan bir glukokortikoittir.', 'Prescribed for severe allergic reactions, autoimmune and rheumatic diseases, asthma flare-ups and in emergency situations.', 'Propisuje se kod teških alergijskih reakcija, autoimunih i reumatskih bolesti, pogoršanja astme i u hitnim stanjima.', 'Прописује се код тешких алергијских реакција, аутоимуних и реуматских болести, погоршања астме и у хитним стањима.', 'Назначают при тяжёлых аллергических реакциях, аутоиммунных и ревматических болезнях, обострениях астмы и в неотложных ситуациях.', 'Wird bei schweren allergischen Reaktionen, Autoimmun- und rheumatischen Erkrankungen, Asthmaanfällen und in Notfällen verordnet.', 'Ağır alerjik tepkilerde, otoimmün ve romatizmal hastalıklarda, astım ataklarında ve acil durumlarda reçete edilir.', 'Prescription only. Long use affects blood pressure, blood sugar, bones and weight. It must not be stopped abruptly, a doctor tapers it gradually.', 'Izdaje se samo na recept. Duga primjena utiče na pritisak, šećer u krvi, kosti i tjelesnu težinu. Nagli prekid nije dozvoljen, ukidanje ljekar vodi postepeno.', 'Издаје се само на рецепт. Дуга примјена утиче на притисак, шећер у крви, кости и тјелесну тежину. Нагли прекид није дозвољен, укидање љекар води постепено.', 'Только по рецепту. Длительный приём влияет на давление, уровень сахара, кости и вес. Резко прекращать нельзя, отмену врач проводит постепенно.', 'Verschreibungspflichtig. Längere Einnahme beeinflusst Blutdruck, Blutzucker, Knochen und Gewicht. Kein plötzliches Absetzen, der Arzt schleicht es aus.', 'Yalnızca reçeteyle verilir. Uzun kullanım tansiyonu, kan şekerini, kemikleri ve kiloyu etkiler. Aniden bırakılmaz, hekim kademeli olarak azaltır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- minoksidil
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (552, 'A substance applied to the scalp that stimulates hair growth, originally developed as a blood pressure medicine.', 'Sredstvo koje se nanosi na kožu glave i podstiče rast kose, prvobitno razvijeno kao lijek za pritisak.', 'Средство које се наноси на кожу главе и подстиче раст косе, првобитно развијено као лијек за притисак.', 'Вещество для нанесения на кожу головы, стимулирующее рост волос, изначально созданное как средство от давления.', 'Ein Wirkstoff zum Auftragen auf die Kopfhaut, der das Haarwachstum anregt, ursprünglich ein Blutdruckmittel.', 'Saç derisine sürülen ve saç çıkışını uyaran bir madde, başlangıçta tansiyon ilacı olarak geliştirilmiştir.', 'Used for androgenetic alopecia, the most common type of hair loss, in men and women.', 'Primjenjuje se kod androgene alopecije, najčešćeg oblika opadanja kose, kod muškaraca i žena.', 'Примјењује се код андрогене алопеције, најчешћег облика опадања косе, код мушкараца и жена.', 'Применяют при андрогенной алопеции, самом частом типе выпадения волос, у мужчин и женщин.', 'Wird bei androgenetischer Alopezie angewendet, der häufigsten Form von Haarausfall, bei Männern und Frauen.', 'Saç dökülmesinin en sık türü olan androgenetik alopeside, kadın ve erkeklerde kullanılır.', 'For the scalp only, not to be taken by mouth. The effect lasts only while it is used. Skin irritation is possible, with heart disease use on a doctor''s advice.', 'Samo za kožu glave, ne uzima se na usta. Djelovanje traje dok se preparat koristi. Moguće je nadraženje kože, kod bolesti srca po savjetu ljekara.', 'Само за кожу главе, не узима се на уста. Дјеловање траје док се препарат користи. Могуће је надражење коже, код болести срца по савјету љекара.', 'Наносится только на кожу головы, внутрь не принимается. Эффект сохраняется, пока средство применяют. Возможно раздражение кожи, при болезнях сердца — по совету врача.', 'Nur für die Kopfhaut, nicht einnehmen. Die Wirkung hält nur an, solange es angewendet wird. Hautreizungen sind möglich, bei Herzerkrankungen ärztlichen Rat einholen.', 'Yalnızca saç derisine uygulanır, ağızdan alınmaz. Etkisi kullanıldığı sürece devam eder. Ciltte tahriş olabilir, kalp hastalığında doktora danışılmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- mliječnokiselinske bakterije
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (554, 'A probiotic with live lactic acid bacteria that support the natural microflora.', 'Probiotik sa živim mliječnokiselinskim bakterijama koje podržavaju prirodnu floru.', 'Пробиотик са живим млијечнокиселинским бактеријама које подржавају природну флору.', 'Пробиотик: живые молочнокислые бактерии, поддерживающие естественную микрофлору.', 'Ein Probiotikum mit lebenden Milchsäurebakterien, die die natürliche Flora unterstützen.', 'Doğal florayı destekleyen canlı laktik asit bakterileri içeren bir probiyotiktir.', 'Used for diarrhoea and disturbed gut flora, including during antibiotic treatment; vaginal forms help restore the flora of the vagina.', 'Primjenjuje se kod proliva i poremećaja crijevne flore, i uz terapiju antibioticima, a vaginalni oblici za obnovu vaginalne flore.', 'Примјењује се код пролива и поремећаја цријевне флоре, и уз терапију антибиотицима, а вагинални облици за обнову вагиналне флоре.', 'Применяют при диарее и нарушении микрофлоры кишечника, в том числе на фоне антибиотиков; вагинальные формы — для восстановления флоры влагалища.', 'Wird bei Durchfall und gestörter Darmflora, auch während einer Antibiotikatherapie, eingesetzt; Vaginalformen bauen die Scheidenflora wieder auf.', 'İshalde ve bağırsak florasının bozulmasında, antibiyotik tedavisi sırasında da kullanılır; vajinal formlar vajina florasını onarmaya yardımcı olur.', 'Available over the counter. Diarrhoea with high fever, blood or dehydration needs a doctor. In severe illness and weakened immunity, only as advised.', 'Izdaje se bez recepta. Proliv sa visokom temperaturom, krvlju ili dehidracijom traži ljekara. Kod teških bolesti i oslabljenog imuniteta isto važi.', 'Издаје се без рецепта. Пролив са високом температуром, крвљу или дехидрацијом тражи љекара. Код тешких болести и ослабљеног имунитета исто важи.', 'Отпускается без рецепта. При диарее с высокой температурой, кровью или обезвоживанием нужен врач. При тяжёлых болезнях и сниженном иммунитете — тоже.', 'Rezeptfrei erhältlich. Durchfall mit hohem Fieber, Blut oder Austrocknung gehört zum Arzt. Bei schweren Krankheiten und geschwächter Abwehr ebenso.', 'Reçetesiz satılır. Yüksek ateş, kan veya sıvı kaybının eşlik ettiği ishalde hekime gidilir. Ağır hastalık ve bağışıklık zayıflığında da aynısı geçerlidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- moksifloksacin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (556, 'A broad-spectrum antibiotic from the fluoroquinolone group.', 'Antibiotik širokog spektra iz grupe fluorohinolona.', 'Антибиотик широког спектра из групе флуорохинолона.', 'Антибиотик широкого спектра из группы фторхинолонов.', 'Ein Breitbandantibiotikum aus der Gruppe der Fluorchinolone.', 'Florokinolon grubundan geniş spektrumlu bir antibiyotiktir.', 'Used for bacterial infections of the airways and sinuses, skin infections and pelvic infections, while the drops are used for conjunctivitis.', 'Primjenjuje se kod bakterijskih infekcija disajnih puteva i sinusa, infekcija kože i male karlice, a kapi kod konjunktivitisa.', 'Примјењује се код бактеријских инфекција дисајних путева и синуса, инфекција коже и мале карлице, а капи код коњунктивитиса.', 'Применяют при бактериальных инфекциях дыхательных путей и придаточных пазух, при инфекциях кожи и органов малого таза, капли — при конъюнктивите.', 'Wird bei bakteriellen Infektionen der Atemwege und Nebenhöhlen, bei Haut- und Beckeninfektionen eingesetzt, die Tropfen bei Bindehautentzündung.', 'Solunum yolu ve sinüs enfeksiyonlarında, deri ve pelvis enfeksiyonlarında kullanılır, damlası konjonktivitte tercih edilir.', 'Prescription only. Tendon and nerve damage are possible, more often in older people. It increases sun sensitivity. Systemic forms are usually not given to children.', 'Izdaje se samo na recept. Moguća su oštećenja tetiva i nerava, rizik je veći u starijem dobu. Povećava osjetljivost na sunce. Djeci se sistemski oblici ne daju.', 'Издаје се само на рецепт. Могућа су оштећења тетива и нерава, ризик је већи у старијем добу. Повећава осјетљивост на сунце. Дјеци се системски облици не дају.', 'Только по рецепту. Возможны повреждения сухожилий и нервов, риск выше в пожилом возрасте. Повышает чувствительность к солнцу. Детям системные формы не назначают.', 'Verschreibungspflichtig. Sehnen- und Nervenschäden sind möglich, im Alter häufiger. Erhöht die Lichtempfindlichkeit. Bei Kindern werden systemische Formen gemieden.', 'Yalnızca reçeteyle verilir. Tendon ve sinir hasarı görülebilir, risk ileri yaşta artar. Güneşe duyarlılığı artırır. Çocuklara sistemik formları genelde verilmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- mometazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (558, 'A corticosteroid for local use in the nose: it reduces inflammation and swelling of the nasal lining.', 'Kortikosteroid za lokalnu primjenu u nosu: smanjuje upalu i otok sluznice nosa.', 'Кортикостероид за локалну примјену у носу: смањује упалу и оток слузнице носа.', 'Глюкокортикоид для местного применения в полости носа: уменьшает воспаление и отёк слизистой.', 'Ein Kortison zur örtlichen Anwendung in der Nase: Es mindert Entzündung und Schwellung der Nasenschleimhaut.', 'Burunda bölgesel olarak kullanılan bir kortikosteroittir: burun mukozasındaki iltihabı ve şişliği azaltır.', 'Used for seasonal and year-round allergic rhinitis, a blocked nose and for nasal polyps.', 'Primjenjuje se kod sezonskog i cjelogodišnjeg alergijskog rinitisa, zapušenog nosa i kod nosnih polipa.', 'Примјењује се код сезонског и цјелогодишњег алергијског ринитиса, запушеног носа и код носних полипа.', 'Применяют при сезонном и круглогодичном аллергическом рините, заложенности носа и при полипах в носу.', 'Wird bei saisonalem und ganzjährigem allergischem Schnupfen, verstopfter Nase und bei Nasenpolypen angewendet.', 'Mevsimsel ve yıl boyu süren alerjik nezlede, burun tıkanıklığında ve burun poliplerinde kullanılır.', 'Prescription only. The effect builds up gradually rather than at once. Dryness, irritation and nosebleeds are possible. In children and pregnancy, only as a doctor advises.', 'Izdaje se na recept. Djelovanje se razvija postepeno, a ne odmah. Mogući su suvoća, nadražaj i krvarenje iz nosa. Djeci i trudnicama samo po savjetu ljekara.', 'Издаје се на рецепт. Дјеловање се развија постепено, а не одмах. Могући су сувоћа, надражај и крварење из носа. Дјеци и трудницама само по савјету љекара.', 'Отпускается по рецепту. Действие развивается постепенно, а не сразу. Возможны сухость, раздражение и носовые кровотечения. Детям и беременным — по назначению врача.', 'Verschreibungspflichtig. Die Wirkung baut sich allmählich auf. Trockenheit, Reizung und Nasenbluten sind möglich. Bei Kindern und in der Schwangerschaft nur nach ärztlichem Rat.', 'Reçeteye tabidir. Etkisi hemen değil, giderek ortaya çıkar. Kuruluk, tahriş ve burun kanaması görülebilir. Çocuklarda ve gebelikte hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- montelukast
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (559, 'An anti-asthma medicine that blocks leukotrienes and reduces airway inflammation.', 'Lijek protiv astme koji blokira leukotrijene i smanjuje zapaljenje u disajnim putevima.', 'Лијек против астме који блокира леукотријене и смањује запаљење у дисајним путевима.', 'Противоастматическое средство: блокирует действие лейкотриенов и уменьшает воспаление в дыхательных путях.', 'Ein Asthmamittel, das Leukotriene blockiert und die Entzündung der Atemwege dämpft.', 'Lökotrienleri bloke ederek hava yollarındaki iltihabı azaltan bir astım ilacıdır.', 'Used for long-term control of asthma, for exercise-induced asthma and for seasonal allergic rhinitis.', 'Primjenjuje se za dugotrajnu kontrolu astme, kod astme izazvane naporom i kod sezonskog alergijskog rinitisa.', 'Примјењује се за дуготрајну контролу астме, код астме изазване напором и код сезонског алергијског ринитиса.', 'Применяют для длительного контроля бронхиальной астмы, при астме физического усилия и при сезонном аллергическом рините.', 'Wird zur Dauerbehandlung von Asthma, bei Anstrengungsasthma und bei saisonaler allergischer Rhinitis eingesetzt.', 'Astımın uzun süreli kontrolünde, eforla tetiklenen astımda ve mevsimsel alerjik rinitte kullanılır.', 'Prescription only. It does not relieve an attack that has already started. Changes in mood, sleep and behaviour, especially in children, are reported to a doctor.', 'Izdaje se samo na recept. Ne prekida napad koji je već počeo. Promjene raspoloženja, sna i ponašanja, naročito kod djece, odmah se javljaju ljekaru.', 'Издаје се само на рецепт. Не прекида напад који је већ почео. Промјене расположења, сна и понашања, нарочито код дјеце, одмах се јављају љекару.', 'Только по рецепту. Не снимает уже начавшийся приступ. Описаны изменения настроения, сна и поведения, особенно у детей: о них сразу сообщают врачу.', 'Verschreibungspflichtig. Ein bereits begonnener Anfall wird damit nicht gelöst. Änderungen von Stimmung, Schlaf und Verhalten, vor allem bei Kindern, dem Arzt melden.', 'Yalnızca reçeteyle verilir. Başlamış bir atağı geçirmez. Özellikle çocuklarda ruh hali, uyku ve davranış değişiklikleri görülürse hekime bildirilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nafazolin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (564, 'A vasoconstrictor of the alpha agonist group for local use in the nose and eyes.', 'Vazokonstriktor iz grupe alfa agonista za lokalnu primjenu u nosu i očima.', 'Вазоконстриктор из групе алфа агониста за локалну примјену у носу и очима.', 'Сосудосуживающее вещество из группы альфа-адреномиметиков для местного применения в носу и глазах.', 'Ein gefäßverengender Wirkstoff aus der Gruppe der Alpha-Agonisten zur örtlichen Anwendung in Nase und Augen.', 'Alfa agonist grubundan, burunda ve gözde bölgesel kullanılan damar büzücü bir maddedir.', 'Used for a blocked nose during colds and allergy, and for redness and irritation of the eyes.', 'Primjenjuje se kod zapušenog nosa uz prehladu i alergiju, kao i kod crvenila i nadraženosti očiju.', 'Примјењује се код запушеног носа уз прехладу и алергију, као и код црвенила и надражености очију.', 'Применяют при заложенности носа во время простуды и аллергии, а также при покраснении и раздражении глаз.', 'Wird bei verstopfter Nase durch Erkältung oder Allergie sowie bei geröteten und gereizten Augen angewendet.', 'Soğuk algınlığı ve alerjide burun tıkanıklığında, gözlerde kızarıklık ve tahrişte kullanılır.', 'Over the counter. Prolonged use leads to dependence and rebound congestion. For small children, in pregnancy and with glaucoma, only on a doctor''s advice.', 'Izdaje se bez recepta. Duža primjena stvara naviku i vraća zapušenost nosa. Kod male djece, u trudnoći i kod glaukoma samo po savjetu ljekara.', 'Издаје се без рецепта. Дужа примјена ствара навику и враћа запушеност носа. Код мале дјеце, у трудноћи и код глаукома само по савјету љекара.', 'Отпускается без рецепта. Длительное применение вызывает привыкание и возврат заложенности. Детям раннего возраста, беременным и при глаукоме — только по назначению врача.', 'Rezeptfrei. Längere Anwendung macht abhängig und die Nase verstopft erneut. Bei kleinen Kindern, in der Schwangerschaft und bei Glaukom nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Uzun süreli kullanım alışkanlık yapar ve tıkanıklığı geri getirir. Küçük çocuklarda, gebelikte ve glokomda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- naftifin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (565, 'Naftifine is an allylamine antifungal for external use.', 'Naftifin je antimikotik iz grupe alilamina za spoljašnju primjenu.', 'Нафтифин је антимикотик из групе алиламина за спољашњу примјену.', 'Нафтифин — противогрибковое средство из группы аллиламинов для наружного применения.', 'Naftifin ist ein Antimykotikum aus der Gruppe der Allylamine zur äußeren Anwendung.', 'Naftifin, haricen kullanılan alilamin grubu bir mantar ilacıdır.', 'Used for fungal infections of the skin, skin folds and feet, for nail fungus and for pityriasis versicolor.', 'Primjenjuje se kod gljivičnih infekcija kože, kožnih nabora i stopala, kod gljivica noktiju i kod pitirijaze verzikolor.', 'Примјењује се код гљивичних инфекција коже, кожних набора и стопала, код гљивица ноктију и код питиријазе верзиколор.', 'Применяют при грибковых поражениях кожи, кожных складок и стоп, при грибке ногтей и отрубевидном лишае.', 'Wird bei Pilzinfektionen der Haut, der Hautfalten und der Füße, bei Nagelpilz und bei Kleienpilzflechte angewendet.', 'Cilt, cilt kıvrımları ve ayak mantarında, tırnak mantarında ve pitiriyazis versikolor enfeksiyonunda kullanılır.', 'For external use only, avoid contact with the eyes. The length of treatment is decided by a doctor, and nail infections take a long course.', 'Samo za spoljašnju primjenu, izbjegavati kontakt sa očima. Dužinu primjene određuje ljekar, a kod zahvaćenih noktiju liječenje je dugotrajno.', 'Само за спољашњу примјену, избјегавати контакт са очима. Дужину примјене одређује љекар, а код захваћених ноктију лијечење је дуготрајно.', 'Только для наружного применения, избегать попадания в глаза. Продолжительность применения определяет врач, при поражении ногтей лечение длительное.', 'Nur zur äußeren Anwendung, Kontakt mit den Augen vermeiden. Die Anwendungsdauer legt der Arzt fest, bei Nagelbefall dauert die Behandlung lange.', 'Yalnızca haricen kullanılır, gözle teması önlenir. Kullanım süresini hekim belirler, tırnak tutulumunda tedavi uzun sürer.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nana (mentha piperita)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (568, 'Peppermint (Mentha piperita) is a plant rich in essential oil and menthol. In medicines it acts as a calming and antispasmodic component.', 'Nana je biljka bogata etarskim uljem i mentolom. U lijekovima djeluje kao umirujuća i spazmolitička biljna komponenta.', 'Нана је биљка богата етарским уљем и ментолом. У лијековима дјелује као умирујућа и спазмолитичка биљна компонента.', 'Мята перечная — растение с эфирным маслом и ментолом. В лекарствах используется как успокаивающий и спазмолитический компонент.', 'Pfefferminze (Mentha piperita) ist eine Pflanze mit ätherischem Öl und Menthol. In Arzneimitteln wirkt sie beruhigend und krampflösend.', 'Nane (Mentha piperita), uçucu yağ ve mentol içeren bir bitkidir. İlaçlarda sakinleştirici ve kramp çözücü bitkisel bileşen olarak yer alır.', 'Part of herbal calming remedies, and also used for cramps and discomfort in the abdomen and in cold remedies.', 'Ulazi u biljne umirujuće preparate, a koristi se i kod grčeva i tegoba u trbuhu, kao i u preparatima protiv prehlade.', 'Улази у биљне умирујуће препарате, а користи се и код грчева и тегоба у трбуху, као и у препаратима против прехладе.', 'Входит в растительные успокаивающие средства, а также применяется при спазмах и дискомфорте в животе и в средствах от простуды.', 'Sie steckt in pflanzlichen Beruhigungsmitteln und wird bei Krämpfen und Beschwerden im Bauch sowie in Erkältungsmitteln verwendet.', 'Bitkisel sakinleştirici preparatlarda bulunur, ayrıca karındaki kramp ve rahatsızlıkta ve soğuk algınlığı ürünlerinde kullanılır.', 'Available over the counter. With reflux and heartburn it may make symptoms worse. For small children, menthol products only on a doctor''s advice.', 'Izdaje se bez recepta. Kod refluksa i gorušice može pojačati tegobe. Maloj djeci se preparati sa mentolom daju samo po savjetu ljekara.', 'Издаје се без рецепта. Код рефлукса и горушице може појачати тегобе. Малој дјеци се препарати са ментолом дају само по савјету љекара.', 'Отпускается без рецепта. При рефлюксе и изжоге может усиливать симптомы. Маленьким детям средства с ментолом дают только по назначению врача.', 'Rezeptfrei erhältlich. Bei Reflux und Sodbrennen kann sie die Beschwerden verstärken. Bei kleinen Kindern nur nach ärztlicher Anweisung anwenden.', 'Reçetesiz satılır. Reflü ve mide yanmasında şikayetleri artırabilir. Küçük çocuklarda mentollü ürünler yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- naproksen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (569, 'Naproxen is a long-acting non-steroidal anti-inflammatory drug (NSAID) derived from propionic acid', 'Naproksen je nesteroidni antiinflamatorni lijek (NSAIL) dugog dejstva, derivat propionske kiseline', 'Напроксен је нестероидни антиинфламаторни лијек (NSAIL) дугог дејства, дериват пропионске киселине', 'Напроксен — нестероидное противовоспалительное средство (NSAIL) длительного действия, производное пропионовой кислоты', 'Naproxen ist ein lang wirkendes nichtsteroidales Antirheumatikum (NSAR) aus der Gruppe der Propionsäurederivate', 'Naproksen uzun etkili, propiyonik asit türevi steroid olmayan bir antiinflamatuar ilaçtır (NSAİİ)', 'Pain and inflammation in joint and spine disorders, muscle pain, headache and menstrual pain', 'Bol i upala kod bolesti zglobova i kičme, mišićni bol, glavobolja i menstrualni bol', 'Бол и упала код болести зглобова и кичме, мишићни бол, главобоља и менструални бол', 'Боль и воспаление при болезнях суставов и позвоночника, мышечная, головная и менструальная боль', 'Schmerzen und Entzündungen bei Gelenk- und Wirbelsäulenbeschwerden, Muskelschmerzen, Kopfschmerzen und Regelschmerzen', 'Eklem ve omurga hastalıklarında ağrı ve iltihap, kas ağrısı, baş ağrısı ve adet ağrısı', 'Most forms are prescription-only. It affects the stomach, kidneys and blood clotting and does not combine with other NSAIDs. With ulcers, heart disease or pregnancy only as prescribed.', 'Većina oblika izdaje se na recept. Utiče na želudac, bubrege i zgrušavanje krvi i ne kombinuje se sa drugim NSAIL. Kod čira, bolesti srca i u trudnoći samo po savjetu ljekara.', 'Већина облика издаје се на рецепт. Утиче на желудац, бубреге и згрушавање крви и не комбинује се са другим NSAIL. Код чира, болести срца и у трудноћи само по савјету љекара.', 'Большинство форм отпускается по рецепту. Влияет на желудок, почки и свёртывание крови, не сочетается с другими NSAIL. При язве, болезнях сердца и беременности — по назначению врача.', 'Die meisten Formen sind rezeptpflichtig. Wirkt auf Magen, Nieren und Blutgerinnung, nicht mit anderen NSAR kombinieren. Bei Magengeschwür, Herzkrankheit und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Çoğu formu reçeteye tabidir. Mide, böbrekler ve kan pıhtılaşmasını etkiler, diğer NSAİİ ile birlikte kullanılmaz. Ülser, kalp hastalığı ve gebelikte yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- natrijum askorbat
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (572, 'The sodium salt of ascorbic acid, a form of vitamin C.', 'Natrijumova so askorbinske kiseline, oblik vitamina C.', 'Натријумова со аскорбинске киселине, облик витамина Ц.', 'Натриевая соль аскорбиновой кислоты, форма витамина C.', 'Das Natriumsalz der Ascorbinsäure, eine Form von Vitamin C.', 'Askorbik asidin sodyum tuzudur, bir C vitamini formudur.', 'Lozenges are used for a sore and scratchy throat, the solutions for cleansing the bowel before colonoscopy.', 'Pastile se koriste kod bola i grebanja u grlu, a rastvori za čišćenje crijeva prije kolonoskopije.', 'Пастиле се користе код бола и гребања у грлу, а раствори за чишћење цријева прије колоноскопије.', 'Пастилки применяют при боли и першении в горле, растворы — для очищения кишечника перед колоноскопией.', 'Pastillen werden bei Halsschmerzen und Kratzen im Hals verwendet, die Lösungen zur Darmreinigung vor einer Koloskopie.', 'Pastiller boğaz ağrısı ve gıcıkta, çözeltiler ise kolonoskopi öncesi bağırsağın temizlenmesinde kullanılır.', 'Lozenges are sold over the counter, bowel preparation solutions are used as directed by a doctor. It contains sodium, which matters on a low-salt diet.', 'Pastile se izdaju bez recepta, rastvori za pripremu za kolonoskopiju po savjetu ljekara. Sadrži natrijum, što se računa uz dijetu sa manje soli.', 'Пастиле се издају без рецепта, раствори за припрему за колоноскопију по савјету љекара. Садржи натријум, што се рачуна уз дијету са мање соли.', 'Пастилки отпускаются без рецепта, растворы для подготовки к колоноскопии — по назначению врача. Содержит натрий, что учитывают при диете с ограничением соли.', 'Pastillen sind rezeptfrei, Lösungen zur Darmvorbereitung nur nach ärztlicher Anweisung. Sie enthalten Natrium, was bei salzarmer Kost zu beachten ist.', 'Pastiller reçetesizdir, bağırsak hazırlık çözeltileri hekim önerisiyle kullanılır. Sodyum içerir, tuz kısıtlı beslenmede dikkate alınır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nebivolol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (583, 'A cardioselective beta blocker with an additional blood vessel widening effect.', 'Kardioselektivni beta-blokator sa dodatnim širenjem krvnih sudova.', 'Кардиоселективни бета-блокатор са додатним ширењем крвних судова.', 'Кардиоселективный бета-блокатор с дополнительным сосудорасширяющим действием.', 'Ein kardioselektiver Betablocker mit zusätzlich gefäßerweiternder Wirkung.', 'Damarları da genişleten kardiyoselektif bir beta blokerdir.', 'Used for arterial hypertension and for chronic heart failure, including in older patients.', 'Primjenjuje se kod povišenog krvnog pritiska i kod hronične srčane slabosti, i kod starijih osoba.', 'Примјењује се код повишеног крвног притиска и код хроничне срчане слабости, и код старијих особа.', 'Применяют при артериальной гипертензии и при хронической сердечной недостаточности, в том числе у пожилых людей.', 'Wird bei Bluthochdruck und bei chronischer Herzschwäche eingesetzt, auch bei älteren Menschen.', 'Yüksek tansiyonda ve kronik kalp yetmezliğinde, yaşlı hastalar dahil kullanılır.', 'Prescription only. It slows the pulse and lowers blood pressure. It must not be stopped abruptly. In asthma, a slow pulse and pregnancy only as directed by a doctor.', 'Izdaje se na recept. Usporava puls i snižava pritisak. Ne smije se naglo prekinuti. Kod astme, usporenog pulsa i u trudnoći samo po savjetu ljekara.', 'Издаје се на рецепт. Успорава пулс и снижава притисак. Не смије се нагло прекинути. Код астме, успореног пулса и у трудноћи само по савјету љекара.', 'Отпускается по рецепту. Урежает пульс и снижает давление. Резко прекращать приём нельзя. При астме, замедленном пульсе и во время беременности — по назначению врача.', 'Verschreibungspflichtig. Es senkt Puls und Blutdruck. Es darf nicht abrupt abgesetzt werden. Bei Asthma, langsamem Puls und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Yalnızca reçeteyle verilir. Nabzı yavaşlatır ve tansiyonu düşürür. Aniden bırakılmamalıdır. Astım, yavaş nabız ve gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nikotin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (589, 'The active substance of nicotine replacement therapy, which eases craving when quitting smoking.', 'Aktivna supstanca nikotinske zamjenske terapije koja ublažava želju za cigaretom.', 'Активна супстанца никотинске замјенске терапије која ублажава жељу за цигаретом.', 'Действующее вещество никотинзаместительной терапии, ослабляющее тягу при отказе от курения.', 'Der Wirkstoff der Nikotinersatztherapie, der das Verlangen beim Rauchstopp mildert.', 'Sigarayı bırakırken isteği azaltan nikotin replasman tedavisinin etken maddesidir.', 'Used when quitting smoking to ease withdrawal symptoms, including in situations where smoking is temporarily not possible.', 'Koristi se pri prestanku pušenja radi ublažavanja simptoma apstinencije, i u situacijama kada pušenje privremeno nije moguće.', 'Користи се при престанку пушења ради ублажавања симптома апстиненције, и у ситуацијама када пушење привремено није могуће.', 'Применяют при отказе от курения для облегчения симптомов отмены, в том числе в ситуациях, когда курить временно нельзя.', 'Wird beim Rauchstopp zur Linderung von Entzugsbeschwerden eingesetzt, auch wenn Rauchen vorübergehend nicht möglich ist.', 'Sigarayı bırakırken yoksunluk belirtilerini hafifletmek için, sigara içmenin geçici olarak mümkün olmadığı durumlarda da kullanılır.', 'Over the counter, but it is not combined with smoking. After a recent heart attack, with arrhythmia or ulcer, in pregnancy and breastfeeding, only as advised.', 'Izdaje se bez recepta, ali se ne kombinuje sa pušenjem. Poslije skorašnjeg infarkta, kod aritmije i čira, u trudnoći i dojenju po savjetu ljekara.', 'Издаје се без рецепта, али се не комбинује са пушењем. Послије скорашњег инфаркта, код аритмије и чира, у трудноћи и дојењу по савјету љекара.', 'Отпускается без рецепта, но курить одновременно с ним не следует. При недавнем инфаркте, аритмии, язве, беременности и кормлении — по назначению врача.', 'Rezeptfrei, aber nicht zusammen mit dem Rauchen anwenden. Nach frischem Herzinfarkt, bei Rhythmusstörungen, Magengeschwür, in Schwangerschaft und Stillzeit nur nach Anweisung.', 'Reçetesiz satılır ama sigarayla birlikte kullanılmaz. Yakın zamanda kalp krizi geçirenlerde, aritmi ve ülserde, gebelik ve emzirmede hekim önerisi gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nikotinamid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (590, 'A form of vitamin B3 (niacin) that takes part in metabolism and cell respiration.', 'Oblik vitamina B3 (nikotinske kiseline), učestvuje u razmjeni materija i ćelijskom disanju.', 'Облик витамина Б3 (никотинске киселине), учествује у размјени материја и ћелијском дисању.', 'Форма витамина B3 (никотиновой кислоты), участвует в обмене веществ и клеточном дыхании.', 'Eine Form von Vitamin B3 (Niacin), beteiligt am Stoffwechsel und an der Zellatmung.', 'B3 vitamininin (niasin) bir formudur, metabolizmada ve hücre solunumunda rol alır.', 'Used for vitamin B3 deficiency and in multivitamin B-complex products, including those for children.', 'Primjenjuje se kod nedostatka vitamina B3 i u multivitaminskim preparatima B grupe, uključujući dječje.', 'Примјењује се код недостатка витамина Б3 и у мултивитаминским препаратима Б групе, укључујући дјечје.', 'Применяют при недостатке витамина B3 и в поливитаминных комплексах группы B, в том числе детских.', 'Wird bei Vitamin-B3-Mangel und in Multivitamin-Präparaten der B-Gruppe, auch für Kinder, verwendet.', 'B3 vitamini eksikliğinde ve çocuklara yönelik olanlar dahil B grubu multivitamin preparatlarında kullanılır.', 'Sold over the counter as part of combined products. Unlike niacin it usually does not cause skin flushing. With liver disease, use on a doctor''s advice.', 'Izdaje se bez recepta u kombinovanim preparatima. Za razliku od nikotinske kiseline obično ne izaziva crvenilo kože. Kod bolesti jetre po savjetu ljekara.', 'Издаје се без рецепта у комбинованим препаратима. За разлику од никотинске киселине обично не изазива црвенило коже. Код болести јетре по савјету љекара.', 'Отпускается без рецепта в составе комбинированных препаратов. В отличие от никотиновой кислоты обычно не вызывает покраснения кожи. При болезнях печени — по совету врача.', 'Rezeptfrei in Kombinationspräparaten. Anders als Niacin verursacht es meist keine Hautrötung. Bei Lebererkrankungen nach ärztlichem Rat anwenden.', 'Kombine preparatlarda reçetesiz satılır. Niasinden farklı olarak genelde ciltte kızarma yapmaz. Karaciğer hastalığında doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- nistatin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (595, 'Nystatin is an antifungal from the polyene antibiotic group, active mainly against Candida yeasts', 'Nistatin je antimikotik iz grupe polienskih antibiotika, djeluje prije svega na gljivice roda kandida', 'Нистатин је антимикотик из групе полиенских антибиотика, дјелује прије свега на гљивице рода кандида', 'Нистатин — противогрибковое средство из группы полиеновых антибиотиков, действует прежде всего на грибы рода Candida', 'Nystatin ist ein Antimykotikum aus der Gruppe der Polyen-Antibiotika und wirkt vor allem gegen Hefepilze der Gattung Candida', 'Nistatin polien grubu bir antifungaldir; başlıca Candida mayalarına etki eder', 'Candida infections of the mouth, intestine, skin and vagina, often as part of combination products', 'Kandidijaza usne duplje i crijeva, kože i vaginalna kandidijaza, često u sastavu kombinovanih preparata', 'Кандидијаза усне дупље и цријева, коже и вагинална кандидијаза, често у саставу комбинованих препарата', 'Кандидоз рта и кишечника, кожи и вагинальный кандидоз, часто в составе комбинированных препаратов', 'Candida-Befall von Mund, Darm, Haut und Scheide, oft in Kombinationspräparaten', 'Ağız, bağırsak, deri ve vajina kandidiyazı, sıklıkla kombine preparatlar içinde', 'It is barely absorbed from the gut and acts locally. Most forms are prescription-only; during pregnancy and in children use only as prescribed by a doctor.', 'Gotovo se ne apsorbuje iz crijeva i djeluje lokalno. Većina oblika izdaje se na recept; u trudnoći i kod djece samo po savjetu ljekara.', 'Готово се не апсорбује из цријева и дјелује локално. Већина облика издаје се на рецепт; у трудноћи и код дјеце само по савјету љекара.', 'Практически не всасывается из кишечника и работает местно. Большинство форм отпускается по рецепту; при беременности и у детей — только по назначению врача.', 'Wird aus dem Darm kaum aufgenommen und wirkt örtlich. Die meisten Formen sind rezeptpflichtig; in der Schwangerschaft und bei Kindern nur nach ärztlicher Anweisung.', 'Bağırsaktan neredeyse emilmez, yerel etki gösterir. Çoğu formu reçeteyle verilir; gebelikte ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- oksimetazolin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (608, 'A nasal decongestant of the alpha-adrenergic agonist group.', 'Dekongestiv za nos iz grupe alfa-adrenergičkih agonista.', 'Деконгестив за нос из групе алфа-адренергичких агониста.', 'Сосудосуживающее средство для носа из группы альфа-адреномиметиков.', 'Ein abschwellendes Nasenmittel aus der Gruppe der Alpha-Sympathomimetika.', 'Alfa-adrenerjik agonist grubundan burun tıkanıklığını açan bir maddedir.', 'Used for a blocked nose during colds, allergic rhinitis and sinusitis, and as support in ear inflammation.', 'Primjenjuje se kod zapušenog nosa uz prehladu, alergijski rinitis i sinuzitis, kao i kod upale uha.', 'Примјењује се код запушеног носа уз прехладу, алергијски ринитис и синузитис, као и код упале уха.', 'Применяют при заложенности носа во время простуды, аллергического ринита и синусита, а также при воспалении уха.', 'Wird bei verstopfter Nase bei Erkältung, allergischem Schnupfen und Nebenhöhlenentzündung sowie bei Mittelohrentzündung angewendet.', 'Soğuk algınlığı, alerjik nezle ve sinüzite bağlı burun tıkanıklığında, ayrıca orta kulak iltihabında kullanılır.', 'Available without prescription. Not for continuous long use, as rebound congestion develops. In pregnancy, high blood pressure and in children only as prescribed.', 'Izdaje se bez recepta. Ne koristi se dugo bez prekida jer nastaje medikamentozni rinitis. U trudnoći, kod povišenog pritiska i kod djece po savjetu ljekara.', 'Издаје се без рецепта. Не користи се дуго без прекида јер настаје медикаментозни ринитис. У трудноћи, код повишеног притиска и код дјеце по савјету љекара.', 'Отпускается без рецепта. Долго подряд не применяют — развивается медикаментозный ринит. При беременности, гипертонии и у детей — по назначению врача.', 'Rezeptfrei. Nicht über längere Zeit ohne Pause anwenden, sonst entsteht ein Arzneimittelschnupfen. In Schwangerschaft, bei Bluthochdruck und bei Kindern ärztlich abklären.', 'Reçetesiz satılır. Ara vermeden uzun süre kullanılmaz, ilaca bağlı nezle gelişir. Gebelikte, yüksek tansiyonda ve çocuklarda doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- oktenidin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (611, 'An external antiseptic active against bacteria and fungi, for skin and mucous membranes.', 'Spoljni antiseptik širokog spektra protiv bakterija i gljivica, za kožu i sluznice.', 'Спољни антисептик широког спектра против бактерија и гљивица, за кожу и слузнице.', 'Наружный антисептик широкого спектра против бактерий и грибов для кожи и слизистых.', 'Ein äußerliches Antiseptikum gegen Bakterien und Pilze für Haut und Schleimhäute.', 'Deri ve mukozada kullanılan, bakteri ve mantarlara karşı etkili bir antiseptiktir.', 'Used to clean small wounds and grazes, mucous membranes and skin before procedures, and when caring for damaged skin.', 'Koristi se za obradu manjih rana i ogrebotina, sluznica i kože prije zahvata, kao i za njegu oštećene kože.', 'Користи се за обраду мањих рана и огреботина, слузница и коже прије захвата, као и за његу оштећене коже.', 'Применяют для обработки небольших ран и ссадин, слизистых, а также кожи перед процедурами и при уходе за повреждённой кожей.', 'Wird zur Reinigung kleiner Wunden und Schürfungen, von Schleimhäuten und der Haut vor Eingriffen sowie zur Wundpflege verwendet.', 'Küçük yara ve sıyrıkların, mukozaların ve işlem öncesi derinin temizliğinde, hasarlı derinin bakımında kullanılır.', 'Available over the counter. External use only, not to be swallowed. It must not be flushed into wounds under pressure or get into the eyes.', 'Izdaje se bez recepta. Samo za spoljnu upotrebu, ne guta se. Ne smije se uštrcavati u ranu pod pritiskom niti dospjeti u oči.', 'Издаје се без рецепта. Само за спољну употребу, не гута се. Не смије се уштрцавати у рану под притиском нити доспјети у очи.', 'Отпускается без рецепта. Только наружно, внутрь не принимают. Нельзя вводить в раны под давлением и допускать попадания в глаза.', 'Rezeptfrei erhältlich. Nur äußerlich, nicht schlucken. Es darf nicht unter Druck in Wunden eingebracht werden und nicht in die Augen gelangen.', 'Reçetesiz satılır. Yalnızca haricen kullanılır, yutulmaz. Basınçla yara içine verilmemeli ve gözle temas ettirilmemelidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- olodaterol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (616, 'A long-acting beta-2 agonist that widens the airways. In Montenegro it is available only in combination with an anticholinergic.', 'Dugodjelujući beta-2 agonist koji širi disajne puteve. U Crnoj Gori je dostupan samo u kombinaciji sa antiholinergikom.', 'Дугодјелујући бета-2 агонист који шири дисајне путеве. У Црној Гори је доступан само у комбинацији са антихолинергиком.', 'Бета-2-агонист длительного действия, расширяющий бронхи. В Черногории доступен только в комбинации с антихолинергическим веществом.', 'Ein lang wirkendes Beta-2-Sympathomimetikum zur Erweiterung der Bronchien. In Montenegro nur in Kombination mit einem Anticholinergikum erhältlich.', 'Hava yollarını genişleten uzun etkili beta-2 agonistidir. Karadağ''da yalnızca antikolinerjik bir maddeyle kombine bulunur.', 'Used for long-term treatment of chronic obstructive pulmonary disease, easing breathlessness and making activity easier.', 'Koristi se u dugotrajnom liječenju hronične opstruktivne bolesti pluća, smanjuje nedostatak vazduha i olakšava napor.', 'Користи се у дуготрајном лијечењу хроничне опструктивне болести плућа, смањује недостатак ваздуха и олакшава напор.', 'Применяют для длительного лечения хронической обструктивной болезни лёгких: уменьшает одышку и облегчает переносимость нагрузки.', 'Wird zur Langzeitbehandlung der chronisch obstruktiven Lungenerkrankung eingesetzt, lindert Atemnot und erleichtert Belastung.', 'Kronik obstrüktif akciğer hastalığının uzun süreli tedavisinde kullanılır, nefes darlığını azaltır ve hareketi kolaylaştırır.', 'Prescription only. Not suitable for relieving an attack. Palpitations and tremor are possible. In asthma such inhalers are used only as prescribed by a doctor.', 'Samo na recept. Nije za prekid napada. Mogući su lupanje srca i drhtanje. Kod astme se ovakvi inhalatori koriste isključivo po preporuci ljekara.', 'Само на рецепт. Није за прекид напада. Могући су лупање срца и дрхтање. Код астме се овакви инхалатори користе искључиво по препоруци љекара.', 'Только по рецепту. Не подходит для снятия приступа. Возможны сердцебиение и дрожь. При бронхиальной астме такие ингаляторы применяют только по назначению врача.', 'Nur auf Rezept. Nicht zur Behandlung eines Anfalls geeignet. Herzklopfen und Zittern sind möglich. Bei Asthma nur nach ärztlicher Verordnung anwenden.', 'Yalnızca reçeteyle verilir. Krizi geçirmek için uygun değildir. Çarpıntı ve titreme olabilir. Astımda bu tür inhalerler ancak hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- olopatadin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (617, 'An antihistamine for local use in the eye.', 'Antihistaminik za lokalnu primjenu u oku.', 'Антихистаминик за локалну примјену у оку.', 'Антигистаминное вещество для местного применения в офтальмологии.', 'Ein Antihistaminikum zur örtlichen Anwendung am Auge.', 'Gözde bölgesel olarak kullanılan bir antihistaminiktir.', 'Used in allergic conjunctivitis for itching, redness and watering of the eyes, including during seasonal allergy.', 'Primjenjuje se kod alergijskog konjunktivitisa: svrab, crvenilo i suzenje očiju, uključujući sezonsku alergiju.', 'Примјењује се код алергијског коњунктивитиса: свраб, црвенило и сузење очију, укључујући сезонску алергију.', 'Применяют при аллергическом конъюнктивите: зуде, покраснении и слезотечении, в том числе при сезонной аллергии.', 'Wird bei allergischer Bindehautentzündung mit Juckreiz, Rötung und tränenden Augen angewendet, auch bei Heuschnupfen.', 'Alerjik konjonktivitte gözlerde kaşıntı, kızarıklık ve sulanmada, mevsimsel alerji dahil kullanılır.', 'Prescription only. Brief stinging and blurred vision are possible. Contact lenses are removed before instilling. In children, only as a doctor advises.', 'Izdaje se na recept. Mogući su kratkotrajno peckanje i zamućen vid. Kontaktna sočiva se skidaju prije ukapavanja. Djeci samo po savjetu ljekara.', 'Издаје се на рецепт. Могући су краткотрајно пецкање и замућен вид. Контактна сочива се скидају прије укапавања. Дјеци само по савјету љекара.', 'Отпускается по рецепту. Возможны кратковременное жжение и затуманивание зрения. Контактные линзы снимают перед закапыванием. Детям — по назначению врача.', 'Verschreibungspflichtig. Kurzes Brennen und verschwommenes Sehen sind möglich. Kontaktlinsen vor dem Eintropfen herausnehmen. Bei Kindern nach ärztlichem Rat.', 'Reçeteye tabidir. Kısa süreli yanma ve bulanık görme olabilir. Damlatmadan önce kontakt lensler çıkarılır. Çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- omalizumab
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (618, 'A monoclonal antibody against immunoglobulin E that damps down the allergic response. It is injected under the skin in a medical setting.', 'Monoklonsko antitijelo protiv imunoglobulina E koje smiruje alergijsku reakciju. Daje se injekcijom pod kožu u zdravstvenoj ustanovi.', 'Моноклонско антитијело против имуноглобулина Е које смирује алергијску реакцију. Даје се ињекцијом под кожу у здравственој установи.', 'Моноклональное антитело против иммуноглобулина E, подавляющее аллергическую реакцию. Вводится подкожно в медицинском учреждении.', 'Ein monoklonaler Antikörper gegen Immunglobulin E, der die allergische Reaktion dämpft. Er wird in der Praxis unter die Haut gespritzt.', 'İmmünoglobulin E''ye karşı geliştirilmiş, alerjik yanıtı baskılayan monoklonal bir antikordur. Sağlık kuruluşunda deri altına uygulanır.', 'Prescribed for severe allergic asthma, chronic hives and nasal polyps when the usual treatment does not give control.', 'Propisuje se kod teške alergijske astme, hronične koprivnjače i nosne polipoze, kada uobičajena terapija ne daje kontrolu.', 'Прописује се код тешке алергијске астме, хроничне копривњаче и носне полипозе, када уобичајена терапија не даје контролу.', 'Назначают при тяжёлой аллергической астме, хронической крапивнице и полипозе носа, когда обычная терапия не даёт контроля.', 'Wird bei schwerem allergischem Asthma, chronischer Nesselsucht und Nasenpolypen verordnet, wenn die übliche Therapie nicht ausreicht.', 'Ağır alerjik astımda, kronik kurdeşende ve burun polipozunda, olağan tedavi yeterli kontrol sağlamadığında reçete edilir.', 'Prescription only, and a specialist starts and supervises the treatment. Because of the risk of an allergic reaction, injections are given under medical supervision.', 'Izdaje se samo na recept, terapiju vodi specijalista. Zbog rizika od alergijske reakcije primjena se sprovodi uz medicinski nadzor.', 'Издаје се само на рецепт, терапију води специјалиста. Због ризика од алергијске реакције примјена се спроводи уз медицински надзор.', 'Только по рецепту, терапию назначает и ведёт специалист. Из-за риска аллергической реакции введения проводят под медицинским наблюдением.', 'Verschreibungspflichtig, die Therapie steuert ein Facharzt. Wegen des Risikos einer allergischen Reaktion erfolgt die Gabe unter ärztlicher Aufsicht.', 'Yalnızca reçeteyle verilir, tedaviyi uzman hekim yürütür. Alerjik tepki riski nedeniyle uygulama tıbbi gözetim altında yapılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- pankreatin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (633, 'Pancreatic enzymes that help digest fats, proteins and carbohydrates when the body''s own enzymes are lacking.', 'Enzimi pankreasa koji pomažu varenje masti, bjelančevina i ugljenih hidrata kada sopstvenih enzima nema dovoljno.', 'Ензими панкреаса који помажу варење масти, бјеланчевина и угљених хидрата када сопствених ензима нема довољно.', 'Ферменты поджелудочной железы: помогают переваривать жиры, белки и углеводы, когда своих ферментов не хватает.', 'Bauchspeicheldrüsenenzyme, die Fette, Eiweiße und Kohlenhydrate verdauen helfen, wenn eigene Enzyme fehlen.', 'Kendi enzimleri yetersiz kaldığında yağ, protein ve karbonhidratların sindirimine yardımcı olan pankreas enzimleridir.', 'Used for pancreatic enzyme insufficiency: in chronic pancreatitis, after pancreatic surgery and in cystic fibrosis.', 'Primjenjuje se kod slabosti pankreasa: kod hroničnog pankreatitisa, poslije operacija pankreasa i kod cistične fibroze.', 'Примјењује се код слабости панкреаса: код хроничног панкреатитиса, послије операција панкреаса и код цистичне фиброзе.', 'Применяют при недостаточности поджелудочной железы: при хроническом панкреатите, после операций на поджелудочной, при муковисцидозе.', 'Wird bei ungenügender Enzymbildung der Bauchspeicheldrüse eingesetzt: bei chronischer Pankreatitis, nach Operationen und bei Mukoviszidose.', 'Pankreas enzim yetersizliğinde kullanılır: kronik pankreatitte, pankreas ameliyatlarından sonra ve kistik fibrozda.', 'In Montenegro it is prescription only. The enzymes come from pig pancreas, which matters in case of intolerance. It is not used in acute pancreatitis.', 'U Crnoj Gori se izdaje na recept. Enzimi se dobijaju iz svinjskog pankreasa, što je važno kod nepodnošljivosti. Ne primjenjuje se kod akutnog pankreatitisa.', 'У Црној Гори се издаје на рецепт. Ензими се добијају из свињског панкреаса, што је важно код неподношљивости. Не примјењује се код акутног панкреатитиса.', 'В Черногории отпускается по рецепту. Ферменты получают из поджелудочной железы свиней, о непереносимости важно сказать врачу. При остром панкреатите не применяют.', 'In Montenegro verschreibungspflichtig. Die Enzyme stammen aus Schweinepankreas, was bei Unverträglichkeit wichtig ist. Nicht bei akuter Pankreatitis.', 'Karadağ''da reçeteyle verilir. Enzimler domuz pankreasından elde edilir, bu duyarlılığı olanlar için önemlidir. Akut pankreatitte kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- pantoprazol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (634, 'A proton pump inhibitor that reduces stomach acid production.', 'Inhibitor protonske pumpe koji smanjuje lučenje želudačne kiseline.', 'Инхибитор протонске пумпе који смањује лучење желудачне киселине.', 'Ингибитор протонной помпы: снижает выработку соляной кислоты в желудке.', 'Ein Protonenpumpenhemmer, der die Magensäureproduktion senkt.', 'Mide asidi üretimini azaltan bir proton pompası inhibitörüdür.', 'Used for reflux disease, stomach and duodenal ulcers, and to protect the stomach during long-term NSAID treatment.', 'Primjenjuje se kod refluksne bolesti, čira želuca i dvanaestopalačnog crijeva, kao i radi zaštite želuca uz dugotrajnu terapiju NSAIL.', 'Примјењује се код рефлуксне болести, чира желуца и дванаестопалачног цријева, као и ради заштите желуца уз дуготрајну терапију NSAIL.', 'Применяют при рефлюксной болезни, язве желудка и двенадцатиперстной кишки, а также для защиты желудка при длительном приёме НПВС.', 'Wird bei Refluxkrankheit, Magen- und Zwölffingerdarmgeschwüren sowie zum Magenschutz bei längerer NSAR-Therapie eingesetzt.', 'Reflü hastalığında, mide ve onikiparmak bağırsağı ülserinde, ayrıca uzun süreli NSAİİ tedavisinde mideyi korumak için kullanılır.', 'Almost all forms are prescription only, and long-term use is a doctor''s decision. It can mask the symptoms of more serious stomach disease.', 'Skoro svi oblici izdaju se na recept, a dugotrajnu primjenu određuje ljekar. Može prikriti simptome ozbiljnijih bolesti želuca.', 'Скоро сви облици издају се на рецепт, а дуготрајну примјену одређује љекар. Може прикрити симптоме озбиљнијих болести желуца.', 'Почти все формы рецептурные, длительный приём — только по назначению врача. Может маскировать симптомы более серьёзных болезней желудка.', 'Fast alle Formen sind verschreibungspflichtig, eine längere Einnahme entscheidet der Arzt. Es kann Beschwerden ernsterer Magenerkrankungen verdecken.', 'Formlarının neredeyse tamamı reçeteye tabidir, uzun süreli kullanıma hekim karar verir. Daha ciddi mide hastalıklarının belirtilerini gizleyebilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- paracetamol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (635, 'A painkiller and fever reducer, not an NSAID. It is also part of combined cold remedies.', 'Lijek protiv bolova i povišene temperature, ne spada u NSAIL. Ulazi i u kombinovane preparate protiv prehlade.', 'Лијек против болова и повишене температуре, не спада у NSAIL. Улази и у комбиноване препарате против прехладе.', 'Обезболивающее и жаропонижающее средство, не относится к НПВС. Входит также в состав комбинированных средств от простуды.', 'Ein Schmerz- und Fiebermittel, das nicht zu den NSAR gehört. Es steckt auch in Kombipräparaten gegen Erkältung.', 'NSAİİ grubunda yer almayan bir ağrı kesici ve ateş düşürücüdür. Soğuk algınlığı kombinasyonlarında da bulunur.', 'Used for headache and toothache, muscle and joint pain, and for fever during colds and flu.', 'Primjenjuje se kod glavobolje i zubobolje, bolova u mišićima i zglobovima, kao i kod povišene temperature uz prehladu i grip.', 'Примјењује се код главобоље и зубобоље, болова у мишићима и зглобовима, као и код повишене температуре уз прехладу и грип.', 'Применяют при головной и зубной боли, боли в мышцах и суставах, при повышенной температуре на фоне простуды и гриппа.', 'Wird bei Kopf- und Zahnschmerzen, Muskel- und Gelenkschmerzen sowie bei Fieber im Rahmen von Erkältung und Grippe angewendet.', 'Baş ve diş ağrısında, kas ve eklem ağrılarında, soğuk algınlığı ve gripte görülen ateşte kullanılır.', 'Most forms are over the counter. Exceeding the dose is dangerous for the liver, more so with alcohol. It is in many cold remedies, so doses add up unnoticed.', 'Većina oblika izdaje se bez recepta. Prekoračenje doze opasno je za jetru, rizik je veći uz alkohol. Ima ga u mnogim preparatima protiv prehlade, pa se doze lako saberu.', 'Већина облика издаје се без рецепта. Прекорачење дозе опасно је за јетру, ризик је већи уз алкохол. Има га у многим препаратима против прехладе, па се дозе лако саберу.', 'Большинство форм безрецептурные. Превышение дозы опасно для печени, риск выше вместе с алкоголем. Входит во многие средства от простуды, дозы легко сложить случайно.', 'Die meisten Formen sind rezeptfrei. Eine zu hohe Dosis schädigt die Leber, mit Alkohol steigt das Risiko. Es steckt in vielen Erkältungsmitteln, Dosen summieren sich leicht.', 'Çoğu formu reçetesizdir. Dozun aşılması karaciğer için tehlikelidir, alkolle risk artar. Birçok soğuk algınlığı ilacında bulunur, dozlar fark edilmeden toplanır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- piridoksin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (658, 'Vitamin B6, a water-soluble B vitamin involved in protein metabolism and nerve function.', 'Vitamin B6, vitamin B grupe rastvorljiv u vodi, učestvuje u razmjeni bjelančevina i radu nerava.', 'Витамин B6, витамин Б групе растворљив у води, учествује у размјени бјеланчевина и раду нерава.', 'Витамин B6, водорастворимый витамин группы B, участвует в обмене белков и работе нервной системы.', 'Vitamin B6, ein wasserlösliches B-Vitamin, wichtig für den Eiweißstoffwechsel und die Nervenfunktion.', 'B6 vitamini, suda çözünen bir B grubu vitamini, protein metabolizmasında ve sinir işlevinde rol alır.', 'Used for vitamin B6 deficiency, in B-complex products for nerve disorders, and in remedies for the mouth and throat.', 'Primjenjuje se kod nedostatka vitamina B6, u preparatima B grupe kod oboljenja nerava i u preparatima za usta i grlo.', 'Примјењује се код недостатка витамина B6, у препаратима Б групе код обољења нерава и у препаратима за уста и грло.', 'Применяют при недостатке витамина B6, в составе комплексов группы B при заболеваниях нервов, а также в средствах для рта и горла.', 'Wird bei Vitamin-B6-Mangel, in B-Komplex-Präparaten bei Nervenerkrankungen und in Mitteln für Mund und Rachen verwendet.', 'B6 vitamini eksikliğinde, sinir hastalıklarında B grubu preparatlarda ve ağız ile boğaz ürünlerinde kullanılır.', 'Some forms are sold over the counter, injections are prescription only. Prolonged unsupervised use can harm nerves, so the course is set by a doctor.', 'Neki oblici se izdaju bez recepta, injekcije samo na recept. Dugotrajno uzimanje bez nadzora može oštetiti nerve, pa trajanje određuje ljekar.', 'Неки облици се издају без рецепта, ињекције само на рецепт. Дуготрајно узимање без надзора може оштетити нерве, па трајање одређује љекар.', 'Часть форм отпускается без рецепта, инъекции — только по назначению врача. Длительный бесконтрольный приём может навредить нервам, поэтому курс определяет врач.', 'Manche Formen sind rezeptfrei, Injektionen verschreibungspflichtig. Längere unkontrollierte Einnahme kann Nerven schädigen, die Dauer legt der Arzt fest.', 'Bazı formları reçetesiz, iğneleri reçeteyle verilir. Uzun süreli kontrolsüz kullanım sinirlere zarar verebilir, süreyi doktor belirler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- polidokanol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (663, 'A local anaesthetic that is also used as a sclerosing agent for veins. In Montenegro it is part of haemorrhoid products together with heparin.', 'Lokalni anestetik koji se koristi i za sklerozaciju vena. U Crnoj Gori ulazi u preparate za hemoroide zajedno sa heparinom.', 'Локални анестетик који се користи и за склерозацију вена. У Црној Гори улази у препарате за хемороиде заједно са хепарином.', 'Местноанестезирующее вещество, которое применяют и для склерозирования вен. В Черногории входит в средства от геморроя вместе с гепарином.', 'Ein örtliches Betäubungsmittel, das auch zur Venenverödung dient. In Montenegro ist es mit Heparin in Hämorrhoidenmitteln enthalten.', 'Lokal anestezik etkili, damar sertleştirme işlemlerinde de kullanılan bir maddedir. Karadağ''da heparinli hemoroit ürünlerinde bulunur.', 'Used for pain, itching and burning from haemorrhoids.', 'Primjenjuje se kod bola, svraba i žarenja zbog hemoroida.', 'Примјењује се код бола, свраба и жарења због хемороида.', 'Применяют при боли, зуде и жжении при геморрое.', 'Wird bei Schmerz, Juckreiz und Brennen durch Hämorrhoiden angewendet.', 'Hemoroide bağlı ağrı, kaşıntı ve yanmada kullanılır.', 'Available over the counter. Local allergic reactions are possible. Blood during bowel movements needs examination, and in pregnancy use only as directed by a doctor.', 'Izdaje se bez recepta. Moguće su lokalne alergijske reakcije. Krv pri pražnjenju crijeva zahtijeva pregled, u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта. Могуће су локалне алергијске реакције. Крв при пражњењу цријева захтијева преглед, у трудноћи само по савјету љекара.', 'Отпускается без рецепта. Возможны местные аллергические реакции. Кровь при дефекации требует обследования, при беременности — по назначению врача.', 'Rezeptfrei erhältlich. Örtliche allergische Reaktionen sind möglich. Blut beim Stuhlgang muss abgeklärt werden, in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Bölgesel alerjik tepkiler görülebilir. Dışkılamada kan görülmesi araştırılmalıdır, gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- polikrezulen
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (664, 'An astringent antiseptic for local use. In Montenegro it is part of combined haemorrhoid products together with a local anaesthetic.', 'Adstringentno i antiseptično sredstvo za lokalnu primjenu. U Crnoj Gori ulazi u kombinovane preparate za hemoroide zajedno sa lokalnim anestetikom.', 'Адстрингентно и антисептично средство за локалну примјену. У Црној Гори улази у комбиноване препарате за хемороиде заједно са локалним анестетиком.', 'Вяжущее и антисептическое вещество для местного применения. В Черногории входит в комбинированные средства от геморроя вместе с местным анестетиком.', 'Ein adstringierendes, antiseptisches Mittel zur örtlichen Anwendung, in Montenegro in Kombipräparaten gegen Hämorrhoiden mit einem Betäubungsmittel.', 'Bölgesel kullanılan büzücü ve antiseptik bir maddedir. Karadağ''da lokal anestezikle birlikte hemoroit ürünlerinde bulunur.', 'Used for haemorrhoids and anal fissures, for itching, burning and minor bleeding of the mucous membrane.', 'Primjenjuje se kod hemoroida i analnih fisura, kod svraba, žarenja i manjih krvarenja sluznice.', 'Примјењује се код хемороида и аналних фисура, код свраба, жарења и мањих крварења слузнице.', 'Применяют при геморрое и трещинах заднего прохода, при зуде, жжении и небольших кровотечениях слизистой.', 'Wird bei Hämorrhoiden und Analfissuren sowie bei Juckreiz, Brennen und leichten Blutungen der Schleimhaut angewendet.', 'Hemoroit ve anal fissürde, kaşıntı, yanma ve mukozadan gelen hafif kanamalarda kullanılır.', 'Available over the counter. Burning on application is possible. Bleeding during bowel movements needs to be examined, in pregnancy only on a doctor''s advice.', 'Izdaje se bez recepta. Moguće je žarenje pri nanošenju. Krv pri pražnjenju crijeva zahtijeva pregled, u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта. Могуће је жарење при наношењу. Крв при пражњењу цријева захтијева преглед, у трудноћи само по савјету љекара.', 'Отпускается без рецепта. Возможно жжение при нанесении. Кровь при дефекации требует обследования, при беременности — только по назначению врача.', 'Rezeptfrei erhältlich. Brennen beim Auftragen ist möglich. Blut beim Stuhlgang muss abgeklärt werden, in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Uygulama sırasında yanma olabilir. Dışkılamada kan görülmesi araştırılmalıdır, gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- polirezistentne spore bacillus clausii
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (666, 'Spores of the Bacillus clausii bacterium, resistant to several antibiotics, used as an oral probiotic.', 'Spore bakterije Bacillus clausii otporne na više antibiotika, koriste se kao probiotik za uzimanje na usta.', 'Споре бактерије Bacillus clausii отпорне на више антибиотика, користе се као пробиотик за узимање на уста.', 'Споры бактерии Bacillus clausii, устойчивые к ряду антибиотиков, — пробиотик для приёма внутрь.', 'Sporen des Bakteriums Bacillus clausii, gegen mehrere Antibiotika resistent, als Probiotikum zum Einnehmen.', 'Birçok antibiyotiğe dirençli Bacillus clausii bakterisinin sporları, ağızdan alınan bir probiyotiktir.', 'Used for disturbed gut flora, including during antibiotic treatment, and for diarrhoea.', 'Primjenjuje se kod poremećaja crijevne flore, uključujući tokom terapije antibioticima, i kod proljeva.', 'Примјењује се код поремећаја цријевне флоре, укључујући током терапије антибиотицима, и код прољева.', 'Применяют при нарушении микрофлоры кишечника, в том числе на фоне приёма антибиотиков, и при диарее.', 'Wird bei gestörter Darmflora, auch während einer Antibiotikatherapie, und bei Durchfall angewendet.', 'Bağırsak florasının bozulmasında, antibiyotik tedavisi sırasında ve ishalde kullanılır.', 'Available without prescription. See a doctor if there is fever, blood in the stool, or diarrhoea lasting more than a few days. Care is needed with weak immunity.', 'Izdaje se bez recepta. Uz povišenu temperaturu, krv u stolici ili proljev duži od nekoliko dana potreban je ljekar. Oprez kod oslabljenog imuniteta.', 'Издаје се без рецепта. Уз повишену температуру, крв у столици или прољев дужи од неколико дана потребан је љекар. Опрез код ослабљеног имунитета.', 'Отпускается без рецепта. При высокой температуре, крови в стуле или диарее дольше нескольких дней нужен врач. Осторожно при ослабленном иммунитете.', 'Rezeptfrei erhältlich. Bei Fieber, Blut im Stuhl oder mehrtägigem Durchfall zum Arzt. Vorsicht bei geschwächtem Immunsystem.', 'Reçetesiz satılır. Ateş, dışkıda kan veya birkaç günden uzun süren ishalde doktora başvurulmalıdır. Bağışıklığı zayıf kişilerde dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- povidon jod
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (670, 'A broad-spectrum iodine-based antiseptic used on skin and mucous membranes.', 'Antiseptik širokog spektra na bazi joda, primjenjuje se na koži i sluznicama.', 'Антисептик широког спектра на бази јода, примјењује се на кожи и слузницама.', 'Антисептик широкого спектра на основе йода, применяется на коже и слизистых.', 'Ein jodhaltiges Antiseptikum mit breitem Wirkspektrum für Haut und Schleimhäute.', 'Deri ve mukozalarda kullanılan, iyot içeren geniş etkili bir antiseptiktir.', 'Used to clean wounds and burns and to prepare skin before procedures, and for mucous membrane infections as prescribed.', 'Koristi se za obradu rana i opekotina i pripremu kože prije zahvata, a kod infekcija sluznica po savjetu ljekara.', 'Користи се за обраду рана и опекотина и припрему коже прије захвата, а код инфекција слузница по савјету љекара.', 'Применяют для обработки ран, ожогов и кожи перед процедурами, а также при инфекциях слизистых по назначению врача.', 'Wird zur Reinigung von Wunden und Verbrennungen, zur Hautvorbereitung vor Eingriffen und bei Schleimhautinfektionen eingesetzt.', 'Yara ve yanıkların temizlenmesinde, işlem öncesi deri hazırlığında, mukoza enfeksiyonlarında hekim önerisiyle kullanılır.', 'Some forms are prescription only. With thyroid disease, in pregnancy and breastfeeding and in newborns, only on a doctor''s advice.', 'Dio oblika izdaje se na recept. Kod bolesti štitne žlijezde, u trudnoći i dojenju i kod novorođenčadi samo po savjetu ljekara.', 'Дио облика издаје се на рецепт. Код болести штитне жлијезде, у трудноћи и дојењу и код новорођенчади само по савјету љекара.', 'Часть форм отпускается по рецепту. При болезнях щитовидной железы, беременности, кормлении грудью и у новорождённых — только по назначению врача.', 'Ein Teil der Formen ist verschreibungspflichtig. Bei Schilddrüsenkrankheiten, in Schwangerschaft und Stillzeit und bei Neugeborenen nur nach Anweisung.', 'Bazı formları reçeteye tabidir. Tiroit hastalığında, gebelik ve emzirme döneminde ve yenidoğanlarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- prednizolon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (677, 'A glucocorticoid, a hormonal anti-inflammatory substance. In Montenegro it is registered only for local use.', 'Glukokortikoid, hormonska protivupalna supstanca. U Crnoj Gori je registrovan samo za lokalnu primjenu.', 'Глукокортикоид, хормонска противупална супстанца. У Црној Гори је регистрован само за локалну примјену.', 'Глюкокортикоид — гормональное противовоспалительное вещество. В Черногории зарегистрирован только для местного применения.', 'Ein Glukokortikoid, ein hormoneller Entzündungshemmer. In Montenegro ist es nur zur örtlichen Anwendung zugelassen.', 'Hormonal yapıda yangı giderici bir glukokortikoiddir. Karadağ''da yalnızca yerel kullanım için ruhsatlıdır.', 'Used for inflammation, itching and swelling around the anus, and for inflammatory eye conditions as directed by a doctor.', 'Primjenjuje se kod upale, svraba i otoka u predjelu čmara, kao i kod upalnih bolesti oka po savjetu ljekara.', 'Примјењује се код упале, свраба и отока у предјелу чмара, као и код упалних болести ока по савјету љекара.', 'Применяют при воспалении, зуде и отёке в области заднего прохода, а также при воспалительных заболеваниях глаз по назначению врача.', 'Wird bei Entzündung, Juckreiz und Schwellung im Analbereich sowie bei entzündlichen Augenerkrankungen nach ärztlicher Anweisung angewendet.', 'Makat çevresindeki iltihap, kaşıntı ve şişlikte, ayrıca hekim önerisiyle iltihaplı göz hastalıklarında kullanılır.', 'Some forms are over the counter, eye drops are used as directed by a doctor. Prolonged use is not advisable, and in an eye infection a steroid can make the condition worse.', 'Dio oblika izdaje se bez recepta, kapi za oči se koriste po savjetu ljekara. Duga primjena nije poželjna, a kod infekcije oka kortikosteroid može pogoršati bolest.', 'Дио облика издаје се без рецепта, капи за очи се користе по савјету љекара. Дуга примјена није пожељна, а код инфекције ока кортикостероид може погоршати болест.', 'Часть форм отпускается без рецепта, глазные капли применяют по назначению врача. Долгое применение нежелательно, при инфекции глаза гормон может ухудшить течение болезни.', 'Ein Teil der Formen ist rezeptfrei, Augentropfen nur nach ärztlicher Anweisung. Eine lange Anwendung ist nicht ratsam, bei einer Augeninfektion kann Kortison schaden.', 'Bazı formları reçetesizdir, göz damlaları hekim önerisiyle kullanılır. Uzun süreli kullanım uygun değildir, göz enfeksiyonunda kortizon hastalığı ağırlaştırabilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- prednizon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (678, 'A systemic glucocorticoid: the liver converts it to prednisolone, which damps inflammation and the immune response.', 'Sistemski glukokortikoid: u jetri prelazi u prednizolon, smiruje upalu i potiskuje imuni odgovor.', 'Системски глукокортикоид: у јетри прелази у преднизолон, смирује упалу и потискује имуни одговор.', 'Системный глюкокортикоид: в печени превращается в преднизолон, снимает воспаление и подавляет иммунный ответ.', 'Ein systemisches Glukokortikoid: Die Leber wandelt es in Prednisolon um, das Entzündung und Immunantwort dämpft.', 'Sistemik bir glukokortikoittir: karaciğerde prednizolona dönüşür, iltihabı ve bağışıklık yanıtını baskılar.', 'Prescribed for autoimmune and rheumatic diseases, severe allergic reactions and flare-ups of asthma and bowel disease.', 'Propisuje se kod autoimunih i reumatskih bolesti, teških alergijskih reakcija, pogoršanja astme i bolesti crijeva.', 'Прописује се код аутоимуних и реуматских болести, тешких алергијских реакција, погоршања астме и болести цријева.', 'Назначают при аутоиммунных и ревматических болезнях, тяжёлых аллергических реакциях, обострениях астмы и болезней кишечника.', 'Wird bei Autoimmun- und rheumatischen Erkrankungen, schweren allergischen Reaktionen sowie Schüben von Asthma und Darmerkrankungen verordnet.', 'Otoimmün ve romatizmal hastalıklarda, ağır alerjik tepkilerde, astım ve bağırsak hastalığı alevlenmelerinde reçete edilir.', 'Prescription only. Long use affects blood pressure, blood sugar, bones and weight and raises the risk of infections. A doctor tapers it gradually.', 'Izdaje se samo na recept. Duga primjena utiče na pritisak, šećer u krvi, kosti i težinu i povećava rizik od infekcija. Ukidanje ljekar vodi postepeno.', 'Издаје се само на рецепт. Дуга примјена утиче на притисак, шећер у крви, кости и тежину и повећава ризик од инфекција. Укидање љекар води постепено.', 'Только по рецепту. Длительный приём влияет на давление, сахар крови, кости и вес, повышает риск инфекций. Отмену врач проводит постепенно.', 'Verschreibungspflichtig. Längere Einnahme wirkt auf Blutdruck, Blutzucker, Knochen und Gewicht und erhöht das Infektionsrisiko. Der Arzt schleicht es aus.', 'Yalnızca reçeteyle verilir. Uzun kullanım tansiyonu, kan şekerini, kemikleri ve kiloyu etkiler, enfeksiyon riskini artırır. Hekim kademeli olarak azaltır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- pregabalin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (679, 'A substance that alters nerve signal transmission, classed with antiepileptics.', 'Materija koja mijenja prenos nervnih signala, svrstana u antiepileptike.', 'Материја која мијења пренос нервних сигнала, сврстана у антиепилептике.', 'Вещество, влияющее на передачу нервных сигналов; относится к противоэпилептическим средствам.', 'Ein Wirkstoff, der die Übertragung von Nervensignalen beeinflusst, den Antiepileptika zugeordnet.', 'Sinir sinyallerinin iletimini etkileyen, antiepileptikler arasında sayılan bir maddedir.', 'Prescribed for neuropathic pain, as add-on treatment in epilepsy and for generalised anxiety disorder.', 'Propisuje se kod neuropatskog bola, kao dodatak terapiji epilepsije i kod generalizovanog anksioznog poremećaja.', 'Прописује се код неуропатског бола, као додатак терапији епилепсије и код генерализованог анксиозног поремећаја.', 'Назначают при нейропатической боли, при эпилепсии как дополнение к лечению и при генерализованном тревожном расстройстве.', 'Wird bei neuropathischen Schmerzen, als Zusatztherapie bei Epilepsie und bei generalisierter Angststörung verordnet.', 'Nöropatik ağrıda, epilepside ek tedavi olarak ve yaygın anksiyete bozukluğunda reçete edilir.', 'Prescription only and specially controlled because of misuse risk. Causes drowsiness and dizziness, unsafe with alcohol and when driving. A doctor tapers it gradually.', 'Izdaje se samo na recept i pod posebnom je kontrolom zbog rizika od zloupotrebe. Izaziva pospanost i vrtoglavicu, nije bezbjedan uz alkohol i vožnju. Ukidanje ljekar vodi postepeno.', 'Издаје се само на рецепт и под посебном је контролом због ризика од злоупотребе. Изазива поспаност и вртоглавицу, није безбједан уз алкохол и вожњу. Укидање љекар води постепено.', 'Рецептурное вещество под особым контролем из-за риска злоупотребления. Вызывает сонливость и головокружение, опасно с алкоголем и при вождении. Отмену врач проводит постепенно.', 'Verschreibungspflichtig und wegen Missbrauchsgefahr besonders überwacht. Macht müde und schwindelig, unsicher mit Alkohol und beim Fahren. Der Arzt setzt es langsam ab.', 'Yalnızca reçeteyle verilir ve kötüye kullanım riski nedeniyle özel denetime tabidir. Uyku hali ve baş dönmesi yapar, alkolle ve araç kullanırken güvenli değildir. Bırakmayı doktor kademeli planlar.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- propifenazon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (686, 'Propyphenazone is a non-opioid painkiller and antipyretic of the pyrazolone group, used in combination products.', 'Propifenazon je nenarkotični analgetik i antipiretik iz grupe pirazolona, koristi se u kombinovanim preparatima.', 'Пропифеназон је ненаркотични аналгетик и антипиретик из групе пиразолона, користи се у комбинованим препаратима.', 'Пропифеназон — ненаркотическое обезболивающее и жаропонижающее из группы пиразолонов, входит в комбинированные средства.', 'Propyphenazon ist ein nicht-opioides Schmerz- und Fiebermittel aus der Pyrazolon-Gruppe und steckt in Kombipräparaten.', 'Propifenazon, pirazolon grubundan opioid olmayan bir ağrı kesici ve ateş düşürücüdür; kombine ürünlerde bulunur.', 'Used for headache and toothache, muscle and joint pain, menstrual pain, migraine and fever.', 'Primjenjuje se kod glavobolje i zubobolje, bolova u mišićima i zglobovima, menstrualnih bolova, migrene i povišene temperature.', 'Примјењује се код главобоље и зубобоље, болова у мишићима и зглобовима, менструалних болова, мигрене и повишене температуре.', 'Применяют при головной и зубной боли, боли в мышцах и суставах, менструальной боли, при мигрени и повышенной температуре.', 'Wird bei Kopf- und Zahnschmerzen, Muskel- und Gelenkschmerzen, Regelschmerzen, Migräne und Fieber angewendet.', 'Baş ve diş ağrısında, kas ve eklem ağrısında, adet ağrısında, migrende ve ateşte kullanılır.', 'Allergic reactions and rare blood-forming disorders are possible. For children, in pregnancy and with blood disease only as prescribed, without prolonged self-treatment.', 'Moguće su alergijske reakcije i rijetki poremećaji krvne slike. Djeci, trudnicama i osobama sa bolestima krvi samo po savjetu ljekara, bez dugog samoliječenja.', 'Могуће су алергијске реакције и ријетки поремећаји крвне слике. Дјеци, трудницама и особама са болестима крви само по савјету љекара, без дугог самолијечења.', 'Возможны аллергические реакции и редкие нарушения кроветворения. Детям, беременным и при болезнях крови — только по назначению врача, без длительного самолечения.', 'Allergische Reaktionen und selten Blutbildstörungen sind möglich. Für Kinder, Schwangere und bei Blutkrankheiten nur ärztlich verordnet, ohne lange Selbstbehandlung.', 'Alerjik reaksiyonlar ve nadiren kan yapımı bozukluğu görülebilir. Çocuklarda, gebelikte ve kan hastalıklarında yalnızca hekim önerisiyle, uzun süre kendi başına kullanılmadan.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- pseudoefedrin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (693, 'Pseudoephedrine is a systemic decongestant included in combination cold remedies', 'Pseudoefedrin je dekongestiv sistemskog dejstva; ulazi u kombinovane preparate protiv prehlade', 'Псеудоефедрин је деконгестив системског дејства; улази у комбиноване препарате против прехладе', 'Псевдоэфедрин — сосудосуживающее средство системного действия; входит в комбинированные средства от простуды', 'Pseudoephedrin ist ein systemisch wirkendes abschwellendes Mittel und Bestandteil von Erkältungskombinationen', 'Psödoefedrin sistemik etkili bir dekonjestandır; kombine soğuk algınlığı ürünlerinde bulunur', 'Blocked nose and swollen nasal lining in colds, flu, sinusitis and allergic rhinitis', 'Začepljen nos i otok sluznice kod prehlade, gripa, sinuzitisa i alergijskog rinitisa', 'Зачепљен нос и оток слузнице код прехладе, грипа, синузитиса и алергијског ринитиса', 'Заложенность носа и отёк слизистой при простуде, гриппе, синусите и аллергическом рините', 'Verstopfte Nase und geschwollene Nasenschleimhaut bei Erkältung, Grippe, Nebenhöhlenentzündung und allergischem Schnupfen', 'Soğuk algınlığı, grip, sinüzit ve alerjik nezlede burun tıkanıklığı ve mukoza ödemi', 'It raises blood pressure and heart rate and may cause insomnia or agitation. With hypertension, heart or thyroid disease, in children and in pregnancy only as advised by a doctor.', 'Povećava krvni pritisak i puls, mogući su nesanica i uznemirenost. Kod povišenog pritiska, bolesti srca i štitne žlijezde, kod djece i u trudnoći samo po savjetu ljekara.', 'Повећава крвни притисак и пулс, могући су несаница и узнемиреност. Код повишеног притиска, болести срца и штитне жлијезде, код дјеце и у трудноћи само по савјету љекара.', 'Повышает давление и частоту пульса, возможны бессонница и возбуждение. При гипертонии, болезнях сердца и щитовидной железы, у детей и беременных — по назначению врача.', 'Erhöht Blutdruck und Puls, Schlaflosigkeit und Unruhe sind möglich. Bei Bluthochdruck, Herz- und Schilddrüsenleiden, bei Kindern und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Tansiyonu ve nabzı yükseltir, uykusuzluk ve huzursuzluk yapabilir. Yüksek tansiyon, kalp ve tiroid hastalığında, çocuklarda ve gebelikte yalnızca hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ramipril
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (696, 'A blood pressure medicine from the ACE inhibitor group. Often part of combination products with a diuretic or amlodipine.', 'Lijek za povišen pritisak iz grupe ACE inhibitora. Često je dio kombinovanih lijekova sa diuretikom ili amlodipinom.', 'Лијек за повишен притисак из групе ACE инхибитора. Често је дио комбинованих лијекова са диуретиком или амлодипином.', 'Средство от повышенного давления из группы ингибиторов ACE. Часто входит в комбинированные средства с мочегонным или амлодипином.', 'Ein Blutdruckmittel aus der Gruppe der ACE-Hemmer. Häufig Bestandteil von Kombinationspräparaten mit einem Diuretikum oder Amlodipin.', 'ACE inhibitörleri grubundan bir tansiyon ilacıdır. Sıklıkla idrar söktürücü ya da amlodipinli kombine ilaçlarda bulunur.', 'Used for arterial hypertension and heart failure, after a heart attack and to protect the kidneys in diabetes.', 'Primjenjuje se kod povišenog pritiska i srčane slabosti, poslije infarkta i radi zaštite bubrega kod dijabetesa.', 'Примјењује се код повишеног притиска и срчане слабости, послије инфаркта и ради заштите бубрега код дијабетеса.', 'Применяют при артериальной гипертензии, сердечной недостаточности, после инфаркта и для защиты почек при диабете.', 'Wird bei Bluthochdruck und Herzschwäche, nach einem Herzinfarkt und zum Schutz der Nieren bei Diabetes eingesetzt.', 'Yüksek tansiyonda, kalp yetmezliğinde, kalp krizi sonrasında ve diyabette böbrekleri korumak için kullanılır.', 'Prescription only. A dry cough is a common side effect. It is not used in pregnancy. The doctor monitors potassium and kidney function through blood tests.', 'Izdaje se na recept. Čest neželjeni efekat je suv kašalj. U trudnoći se ne primjenjuje. Ljekar prati kalijum i rad bubrega preko nalaza krvi.', 'Издаје се на рецепт. Чест нежељени ефекат је сув кашаљ. У трудноћи се не примјењује. Љекар прати калијум и рад бубрега преко налаза крви.', 'Отпускается по рецепту. Частый побочный эффект — сухой кашель. Во время беременности не применяют. Врач контролирует калий и работу почек по анализам.', 'Verschreibungspflichtig. Trockener Husten ist eine häufige Nebenwirkung. In der Schwangerschaft nicht anwenden. Der Arzt kontrolliert Kalium und Nierenwerte im Blut.', 'Yalnızca reçeteyle verilir. Kuru öksürük sık görülen bir yan etkidir. Gebelikte kullanılmaz. Hekim potasyum ve böbrek değerlerini kan testiyle izler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- retinol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (705, 'Vitamin A, a fat-soluble vitamin needed for vision, skin and mucous membranes. It is part of multivitamins and of combinations with vitamin D.', 'Vitamin A, vitamin rastvorljiv u mastima, potreban za vid, kožu i sluznice. Ulazi u multivitamine i kombinacije sa vitaminom D.', 'Витамин А, витамин растворљив у мастима, потребан за вид, кожу и слузнице. Улази у мултивитамине и комбинације са витамином Д.', 'Витамин A, жирорастворимый витамин: нужен для зрения, кожи и слизистых. Входит в поливитамины и в комбинации с витамином D.', 'Vitamin A, ein fettlösliches Vitamin für Sehkraft, Haut und Schleimhäute. Es steckt in Multivitaminen und in Kombinationen mit Vitamin D.', 'Görme, deri ve mukozalar için gerekli, yağda çözünen A vitaminidir. Multivitaminlerde ve D vitaminli kombinasyonlarda bulunur.', 'Used for vitamin A deficiency, poor vision in dim light and dry mucous membranes, and as part of vitamin supplements.', 'Primjenjuje se kod nedostatka vitamina A, slabijeg vida u sumrak i suvoće sluznica, kao i u sastavu vitaminskih preparata.', 'Примјењује се код недостатка витамина А, слабијег вида у сумрак и сувоће слузница, као и у саставу витаминских препарата.', 'Применяют при недостатке витамина A, при ухудшении сумеречного зрения и сухости слизистых, а также в составе витаминных комплексов.', 'Wird bei Vitamin-A-Mangel, schlechtem Sehen in der Dämmerung und trockenen Schleimhäuten sowie in Vitaminpräparaten eingesetzt.', 'A vitamini eksikliğinde, alacakaranlıkta görmenin azalmasında, mukoza kuruluğunda ve vitamin preparatlarının içinde kullanılır.', 'Some forms are over the counter, but the vitamin builds up in the liver and an excess is harmful. In pregnancy and when planning one, only on a doctor''s advice.', 'Dio oblika izdaje se bez recepta, ali se vitamin nakuplja u jetri i višak je štetan. U trudnoći i pripremi za trudnoću samo po savjetu ljekara.', 'Дио облика издаје се без рецепта, али се витамин накупља у јетри и вишак је штетан. У трудноћи и припреми за трудноћу само по савјету љекара.', 'Часть форм безрецептурная, но витамин накапливается в печени, а избыток опасен. Беременным и планирующим беременность — только по назначению врача.', 'Ein Teil der Formen ist rezeptfrei, doch das Vitamin reichert sich in der Leber an und ein Zuviel schadet. In der Schwangerschaft nur nach ärztlicher Anweisung.', 'Bazı formları reçetesizdir ancak vitamin karaciğerde birikir ve fazlası zararlıdır. Gebelikte ve gebelik hazırlığında yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- riboflavin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (708, 'Vitamin B2, a water-soluble B vitamin involved in energy metabolism and the health of skin and mucous membranes.', 'Vitamin B2, vitamin B grupe rastvorljiv u vodi, učestvuje u razmjeni energije i zdravlju kože i sluzokože.', 'Витамин B2, витамин Б групе растворљив у води, учествује у размјени енергије и здрављу коже и слузокоже.', 'Витамин B2, водорастворимый витамин группы B, участвует в обмене энергии и состоянии кожи и слизистых.', 'Vitamin B2, ein wasserlösliches B-Vitamin, wichtig für den Energiestoffwechsel sowie für Haut und Schleimhäute.', 'B2 vitamini, suda çözünen bir B grubu vitamini, enerji metabolizması ile deri ve mukoza sağlığında rol alır.', 'Used for vitamin B2 deficiency, cracks at the corners of the mouth and inflamed mucous membranes, and in B-complex products.', 'Primjenjuje se kod nedostatka vitamina B2, kod ranica u uglovima usana i upale sluzokože, i u preparatima B grupe.', 'Примјењује се код недостатка витамина B2, код раница у угловима усана и упале слузокоже, и у препаратима Б групе.', 'Применяют при недостатке витамина B2, при трещинках в углах рта и воспалении слизистых, а также в комплексах группы B.', 'Wird bei Vitamin-B2-Mangel, eingerissenen Mundwinkeln und entzündeten Schleimhäuten sowie in B-Komplex-Präparaten verwendet.', 'B2 vitamini eksikliğinde, dudak kenarlarındaki çatlaklarda ve mukoza iltihabında, ayrıca B grubu preparatlarda kullanılır.', 'Sold over the counter in combined products. It harmlessly turns urine bright yellow. Long-term use in pregnancy is agreed with a doctor.', 'Izdaje se bez recepta u kombinovanim preparatima. Bezopasno boji mokraću u jarko žutu boju. Dugotrajno uzimanje u trudnoći dogovara se sa ljekarom.', 'Издаје се без рецепта у комбинованим препаратима. Безопасно боји мокраћу у јарко жуту боју. Дуготрајно узимање у трудноћи договара се са љекаром.', 'Отпускается без рецепта в составе комбинированных препаратов. Безвредно окрашивает мочу в ярко-жёлтый цвет. Длительный приём при беременности согласуют с врачом.', 'Rezeptfrei in Kombinationspräparaten. Färbt den Urin harmlos leuchtend gelb. Längere Einnahme in der Schwangerschaft mit dem Arzt absprechen.', 'Kombine preparatlarda reçetesiz satılır. İdrarı zararsız biçimde parlak sarıya boyar. Gebelikte uzun süreli kullanımı doktorla kararlaştırılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- rivaroksaban
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (719, 'A direct oral anticoagulant that blocks clotting factor Xa.', 'Antikoagulans direktnog djelovanja za uzimanje na usta, blokira faktor zgrušavanja Xa.', 'Антикоагуланс директног дјеловања за узимање на уста, блокира фактор згрушавања Xa.', 'Антикоагулянт прямого действия для приёма внутрь: блокирует фактор свёртывания Xa.', 'Ein direktes orales Antikoagulans, das den Gerinnungsfaktor Xa hemmt.', 'Pıhtılaşma faktörü Xa''yı bloke eden, ağızdan alınan doğrudan etkili bir antikoagülandır.', 'Prescribed to prevent stroke in atrial fibrillation, for deep vein thrombosis and pulmonary embolism, and after some operations.', 'Propisuje se radi prevencije moždanog udara kod atrijalne fibrilacije, kod duboke venske tromboze i plućne embolije i poslije operacija.', 'Прописује се ради превенције можданог удара код атријалне фибрилације, код дубоке венске тромбозе и плућне емболије и послије операција.', 'Назначают для профилактики инсульта при мерцательной аритмии, при тромбозе глубоких вен и тромбоэмболии лёгочной артерии, а также после операций.', 'Wird zur Schlaganfallvorbeugung bei Vorhofflimmern, bei tiefer Venenthrombose und Lungenembolie sowie nach Operationen verordnet.', 'Atriyal fibrilasyonda inme önlemede, derin ven trombozu ve akciğer embolisinde ve ameliyat sonrasında reçete edilir.', 'Prescription only. It raises bleeding risk, and missed doses or stopping on your own are dangerous. Tell any doctor or dentist before procedures.', 'Izdaje se samo na recept. Povećava rizik od krvarenja, propuštanje i samovoljni prekid su opasni. Prije svakog zahvata obavijestiti ljekara i stomatologa.', 'Издаје се само на рецепт. Повећава ризик од крварења, пропуштање и самовољни прекид су опасни. Прије сваког захвата обавијестити љекара и стоматолога.', 'Только по рецепту. Повышает риск кровотечений, пропуск приёма и самостоятельная отмена опасны. Перед любыми вмешательствами предупреждают врача и стоматолога.', 'Verschreibungspflichtig. Erhöht das Blutungsrisiko, vergessene Einnahmen und eigenmächtiges Absetzen sind gefährlich. Vor Eingriffen Arzt und Zahnarzt informieren.', 'Yalnızca reçeteyle verilir. Kanama riskini artırır, doz atlamak ve kendi başına bırakmak tehlikelidir. İşlem öncesi hekim ve diş hekimi bilgilendirilmelidir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- roflumilast
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (721, 'A phosphodiesterase-4 inhibitor: an anti-inflammatory medicine used in chronic obstructive pulmonary disease.', 'Inhibitor fosfodiesteraze-4, protivupalni lijek koji se koristi kod hronične opstruktivne bolesti pluća.', 'Инхибитор фосфодиестеразе-4, противупални лијек који се користи код хроничне опструктивне болести плућа.', 'Ингибитор фосфодиэстеразы-4 — противовоспалительное средство, применяемое при хронической обструктивной болезни лёгких.', 'Ein Phosphodiesterase-4-Hemmer, ein entzündungshemmendes Arzneimittel bei chronisch obstruktiver Lungenerkrankung.', 'Fosfodiesteraz-4 inhibitörüdür, kronik obstrüktif akciğer hastalığında kullanılan iltihap giderici bir ilaçtır.', 'Used in addition to inhalers in severe COPD with chronic bronchitis and frequent exacerbations.', 'Primjenjuje se uz inhalatore kod teške HOBP sa hroničnim bronhitisom i čestim pogoršanjima.', 'Примјењује се уз инхалаторе код тешке ХОБП са хроничним бронхитисом и честим погоршањима.', 'Применяют как дополнение к ингаляторам при тяжёлой ХОБЛ с хроническим бронхитом и частыми обострениями.', 'Wird zusätzlich zu Inhalatoren bei schwerer COPD mit chronischer Bronchitis und häufigen Verschlechterungen angewendet.', 'Ağır KOAH''ta, kronik bronşit ve sık alevlenme durumunda inhalerlere ek olarak kullanılır.', 'Prescription only. It does not widen the airways and does not help during an attack of breathlessness. Weight loss, nausea, diarrhoea, sleep and mood changes are reported to the doctor.', 'Izdaje se samo na recept. Ne širi disajne puteve i ne pomaže kod napada gušenja. Gubitak težine, mučnina, proljev, poremećaji sna i raspoloženja prijavljuju se ljekaru.', 'Издаје се само на рецепт. Не шири дисајне путеве и не помаже код напада гушења. Губитак тежине, мучнина, прољев, поремећаји сна и расположења пријављују се љекару.', 'Только по рецепту. Не расширяет бронхи и не помогает при приступе одышки. О потере веса, тошноте, диарее, нарушениях сна и настроения сообщают врачу.', 'Nur auf Rezept. Es erweitert die Atemwege nicht und hilft nicht bei akuter Atemnot. Gewichtsverlust, Übelkeit, Durchfall, Schlaf- und Stimmungsänderungen dem Arzt melden.', 'Yalnızca reçeteyle verilir. Hava yollarını genişletmez, nefes darlığı krizinde işe yaramaz. Kilo kaybı, bulantı, ishal, uyku ve ruh hali değişiklikleri hekime bildirilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- rosuvastatin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (724, 'A statin that lowers the liver''s cholesterol production and the level of low-density lipoprotein. Also comes combined with ezetimibe and blood pressure drugs.', 'Statin koji smanjuje stvaranje holesterola u jetri i nivo holesterola niske gustine. Postoje i kombinacije sa ezetimibom i lijekovima za pritisak.', 'Статин који смањује стварање холестерола у јетри и ниво холестерола ниске густине. Постоје и комбинације са езетимибом и лијековима за притисак.', 'Статин: снижает выработку холестерина в печени и уровень липопротеинов низкой плотности. Есть комбинации с эзетимибом и средствами от давления.', 'Ein Statin, das die Cholesterinbildung in der Leber und das LDL-Cholesterin senkt. Es gibt Kombinationen mit Ezetimib und Blutdruckmitteln.', 'Karaciğerde kolesterol üretimini ve kandaki düşük yoğunluklu kolesterolü azaltan bir statindir. Ezetimib ve tansiyon ilacı kombinasyonları vardır.', 'Used for raised cholesterol and to reduce the risk of heart attack and stroke in people at high cardiovascular risk.', 'Primjenjuje se kod povišenog holesterola i radi smanjenja rizika od infarkta i moždanog udara kod osoba sa visokim kardiovaskularnim rizikom.', 'Примјењује се код повишеног холестерола и ради смањења ризика од инфаркта и можданог удара код особа са високим кардиоваскуларним ризиком.', 'Применяют при повышенном холестерине и для снижения риска инфаркта и инсульта у людей с высоким сердечно-сосудистым риском.', 'Wird bei erhöhtem Cholesterin und zur Senkung des Herzinfarkt- und Schlaganfallrisikos bei hohem kardiovaskulärem Risiko eingesetzt.', 'Yüksek kolesterolde ve kalp-damar riski yüksek kişilerde kalp krizi ile inme riskini azaltmak için kullanılır.', 'Prescription only, taken long term with regular blood tests. Unexplained muscle pain or weakness should be reported to a doctor. It is not used in pregnancy.', 'Izdaje se samo na recept, terapija je dugotrajna uz kontrolu analiza. Neobjašnjiv bol i slabost u mišićima treba javiti ljekaru. U trudnoći se ne primjenjuje.', 'Издаје се само на рецепт, терапија је дуготрајна уз контролу анализа. Необјашњив бол и слабост у мишићима треба јавити љекару. У трудноћи се не примјењује.', 'Только по рецепту, приём длительный и контролируется анализами. О необъяснимой боли и слабости в мышцах нужно сообщить врачу. При беременности не применяют.', 'Verschreibungspflichtig, die Einnahme läuft langfristig mit Kontrolle der Blutwerte. Unerklärliche Muskelschmerzen dem Arzt melden. In der Schwangerschaft nicht.', 'Yalnızca reçeteyle verilir, tedavi uzun sürelidir ve kan tahlilleriyle izlenir. Açıklanamayan kas ağrısı ve güçsüzlük hekime bildirilir. Gebelikte kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ruzmarin (rosmarinus officinalis l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (726, 'Rosemary (Rosmarinus officinalis) is a medicinal plant, and an essential oil for herbal preparations is obtained from its leaves.', 'Ruzmarin je ljekovita biljka, a iz njegovih listova se dobija etarsko ulje koje ulazi u biljne preparate.', 'Рузмарин је љековита биљка, а из његових листова се добија етарско уље које улази у биљне препарате.', 'Розмарин (Rosmarinus officinalis) — лекарственное растение, из листьев которого получают эфирное масло для растительных препаратов.', 'Rosmarin (Rosmarinus officinalis) ist eine Heilpflanze; aus den Blättern wird ein ätherisches Öl für pflanzliche Zubereitungen gewonnen.', 'Biberiye (Rosmarinus officinalis) tıbbi bir bitkidir; yapraklarından bitkisel preparatlar için uçucu yağ elde edilir.', 'Applied to the skin for mild muscle and joint pain and for mild problems of peripheral circulation.', 'Spolja se primjenjuje kod blagih bolova u mišićima i zglobovima i kod blagih smetnji periferne cirkulacije.', 'Споља се примјењује код благих болова у мишићима и зглобовима и код благих сметњи периферне циркулације.', 'Наружно применяют при лёгкой мышечной и суставной боли и при лёгких нарушениях периферического кровообращения.', 'Wird auf der Haut bei leichten Muskel- und Gelenkschmerzen und bei leichten Durchblutungsstörungen angewendet.', 'Hafif kas ve eklem ağrılarında ve hafif çevresel dolaşım sorunlarında deriye uygulanır.', 'Available without prescription. Apply to unbroken skin and keep away from the eyes; irritation and allergic reaction are possible. In children and pregnancy, as a doctor advises.', 'Izdaje se bez recepta. Nanosi se na neoštećenu kožu, dalje od očiju; mogući su nadražaj i alergijska reakcija. Djeci i trudnicama po savjetu ljekara.', 'Издаје се без рецепта. Наноси се на неоштећену кожу, даље од очију; могући су надражај и алергијска реакција. Дјеци и трудницама по савјету љекара.', 'Отпускается без рецепта. Наносят на неповреждённую кожу, избегая глаз; возможны раздражение и аллергическая реакция. Детям и беременным — по назначению врача.', 'Rezeptfrei. Nur auf unverletzte Haut auftragen, nicht in die Augen; Reizungen und allergische Reaktionen sind möglich. Bei Kindern und in der Schwangerschaft nach ärztlichem Rat.', 'Reçetesiz satılır. Sağlam deriye uygulanır, gözden uzak tutulur; tahriş ve alerjik tepki görülebilir. Çocuklarda ve gebelikte hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- salbutamol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (729, 'A short-acting beta-2 agonist that quickly widens the airways.', 'Kratkodjelujući beta-2 agonist koji brzo širi disajne puteve.', 'Краткодјелујући бета-2 агонист који брзо шири дисајне путеве.', 'Бета-2-агонист короткого действия: быстро расширяет бронхи.', 'Ein kurz wirkendes Beta-2-Sympathomimetikum, das die Atemwege rasch erweitert.', 'Hava yollarını hızla genişleten kısa etkili beta-2 agonistidir.', 'Used to relieve wheezing and breathlessness in asthma and COPD, and before exercise in exercise-induced asthma.', 'Koristi se za prekid napada gušenja i nedostatka vazduha kod astme i HOBP, kao i prije napora kod astme izazvane naporom.', 'Користи се за прекид напада гушења и недостатка ваздуха код астме и ХОБП, као и прије напора код астме изазване напором.', 'Применяют для снятия приступа удушья и одышки при бронхиальной астме и ХОБЛ, а также перед нагрузкой при астме физического усилия.', 'Wird zur raschen Linderung von Atemnot und Pfeifen bei Asthma und COPD sowie vor Belastung bei Anstrengungsasthma angewendet.', 'Astım ve KOAH''ta nefes darlığı ve hırıltı krizini geçirmek için, ayrıca egzersize bağlı astımda hareket öncesi kullanılır.', 'Prescription only. Hand tremor and palpitations are possible. Needing the inhaler more and more means asthma is not controlled and a doctor should review it.', 'Izdaje se na recept. Mogući su drhtanje ruku i lupanje srca. Sve češća potreba za sprejem znači da astma nije pod kontrolom i traži pregled ljekara.', 'Издаје се на рецепт. Могући су дрхтање руку и лупање срца. Све чешћа потреба за спрејем значи да астма није под контролом и тражи преглед љекара.', 'Отпускается по рецепту. Возможны дрожь в руках и сердцебиение. Растущая потребность в ингаляторе означает, что астма не контролируется, нужен осмотр врача.', 'Rezeptpflichtig. Zittern der Hände und Herzklopfen sind möglich. Ein steigender Bedarf am Spray zeigt, dass das Asthma nicht kontrolliert ist, dann zum Arzt.', 'Reçeteyle verilir. El titremesi ve çarpıntı olabilir. İnhalere giderek daha sık ihtiyaç duyulması astımın kontrol altında olmadığını gösterir, hekime başvurulur.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- salmeterol
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (731, 'A long-acting beta-2 agonist that widens the airways. It is available on its own and combined with an inhaled steroid.', 'Beta-2 agonist dugog djelovanja koji širi disajne puteve. Dostupan je samostalno i uz inhalacioni kortikosteroid.', 'Бета-2 агонист дугог дјеловања који шири дисајне путеве. Доступан је самостално и уз инхалациони кортикостероид.', 'Бета-2-агонист длительного действия, расширяющий бронхи. Есть препараты с одним веществом и комбинации с ингаляционным гормоном.', 'Ein lang wirksamer Beta-2-Agonist zur Erweiterung der Atemwege. Erhältlich allein und in Kombination mit inhalativem Kortison.', 'Solunum yollarını genişleten uzun etkili bir beta-2 agonistidir. Tek başına ve inhale kortikosteroitle kombine preparatları vardır.', 'Used for long-term control of asthma and COPD, to reduce breathlessness and night-time symptoms.', 'Primjenjuje se za dugotrajnu kontrolu astme i HOBP, radi smanjenja nedostatka vazduha i noćnih tegoba.', 'Примјењује се за дуготрајну контролу астме и ХОБП, ради смањења недостатка ваздуха и ноћних тегоба.', 'Применяют для длительного контроля бронхиальной астмы и ХОБЛ, чтобы уменьшить одышку и ночные симптомы.', 'Wird zur Langzeitkontrolle von Asthma und COPD eingesetzt, um Atemnot und nächtliche Beschwerden zu verringern.', 'Astım ve KOAH''ın uzun süreli kontrolünde, nefes darlığını ve gece belirtilerini azaltmak için kullanılır.', 'Prescription only. It is not for relieving an attack, as it acts slowly. In asthma it is used only together with an inhaled steroid.', 'Izdaje se na recept. Ne služi za prekid napada jer djeluje sporo. Kod astme se primjenjuje samo uz inhalacioni kortikosteroid.', 'Издаје се на рецепт. Не служи за прекид напада јер дјелује споро. Код астме се примјењује само уз инхалациони кортикостероид.', 'Отпускается по рецепту. Не подходит для снятия приступа: действие развивается медленно. При астме применяют только вместе с ингаляционным гормоном.', 'Verschreibungspflichtig. Nicht zur Behandlung eines akuten Anfalls geeignet, da die Wirkung langsam einsetzt. Bei Asthma nur mit inhalativem Kortison.', 'Reçeteye tabidir. Yavaş etki ettiği için atak sırasında kullanılmaz. Astımda yalnızca inhale kortikosteroitle birlikte kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- semaglutid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (736, 'An analogue of the gut hormone GLP-1 that boosts insulin release after a meal, slows stomach emptying and reduces appetite.', 'Analog crijevnog hormona GLP-1, pojačava lučenje insulina poslije obroka, usporava pražnjenje želuca i smanjuje apetit.', 'Аналог цријевног хормона GLP-1, појачава лучење инсулина послије оброка, успорава пражњење желуца и смањује апетит.', 'Аналог кишечного гормона GLP-1: усиливает выделение инсулина после еды, замедляет опорожнение желудка и снижает аппетит.', 'Ein Analogon des Darmhormons GLP-1, das die Insulinausschüttung nach dem Essen steigert, die Magenentleerung bremst und den Appetit senkt.', 'Yemekten sonra insülin salınımını artıran, mide boşalmasını yavaşlatan ve iştahı azaltan bir bağırsak hormonu analoğudur, GLP-1 benzeridir.', 'Prescribed for type 2 diabetes; separate products are approved for obesity alongside changes in diet and physical activity.', 'Propisuje se kod dijabetesa tipa 2, a pojedini preparati kod gojaznosti uz promjenu ishrane i fizičku aktivnost.', 'Прописује се код дијабетеса типа 2, а поједини препарати код гојазности уз промјену исхране и физичку активност.', 'Назначают при сахарном диабете 2 типа, отдельные препараты — при ожирении вместе с изменением питания и физической активностью.', 'Wird bei Typ-2-Diabetes verordnet, einzelne Präparate bei Adipositas zusammen mit veränderter Ernährung und mehr Bewegung.', 'Tip 2 diyabette reçete edilir, bazı ürünler beslenme değişikliği ve fiziksel etkinlikle birlikte obezitede kullanılır.', 'Prescription only, injected under the skin. Nausea and other digestive problems are common at first. Use for weight loss is a doctor''s decision, not self-treatment.', 'Izdaje se samo na recept, daje se pod kožu. Na početku su česte mučnina i druge tegobe sa varenjem. O primjeni radi mršavljenja odlučuje ljekar, a ne pacijent.', 'Издаје се само на рецепт, даје се под кожу. На почетку су честе мучнина и друге тегобе са варењем. О примјени ради мршављења одлучује љекар, а не пацијент.', 'Только по рецепту, вводится под кожу. В начале лечения часты тошнота и другие нарушения пищеварения. Показания для снижения веса определяет врач, а не сам пациент.', 'Verschreibungspflichtig, Injektion unter die Haut. Anfangs sind Übelkeit und Verdauungsbeschwerden häufig. Über den Einsatz zur Gewichtsabnahme entscheidet der Arzt.', 'Yalnızca reçeteyle verilir, deri altına enjekte edilir. Başlangıçta bulantı ve sindirim sorunları sıktır. Kilo verme amaçlı kullanıma hekim karar verir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- sertralin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (738, 'An antidepressant from the SSRI group that acts on serotonin in the brain.', 'Antidepresiv iz grupe SSRI koji djeluje na serotonin u mozgu.', 'Антидепресив из групе SSRI који дјелује на серотонин у мозгу.', 'Антидепрессант из группы СИОЗС: влияет на обмен серотонина в головном мозге.', 'Ein Antidepressivum aus der Gruppe der SSRI, das auf den Serotoninhaushalt im Gehirn wirkt.', 'Beyindeki serotonin dengesine etki eden, SSRI grubundan bir antidepresandır.', 'Used for depression, anxiety and panic disorders, obsessive-compulsive disorder and post-traumatic stress disorder.', 'Primjenjuje se kod depresije, anksioznih i paničnih poremećaja, opsesivno-kompulzivnog i posttraumatskog stresnog poremećaja.', 'Примјењује се код депресије, анксиозних и паничних поремећаја, опсесивно-компулзивног и посттрауматског стресног поремећаја.', 'Применяют при депрессии, тревожных и панических расстройствах, обсессивно-компульсивном расстройстве и посттравматическом стрессовом расстройстве.', 'Wird bei Depressionen, Angst- und Panikstörungen, Zwangsstörung und posttraumatischer Belastungsstörung eingesetzt.', 'Depresyonda, anksiyete ve panik bozukluğunda, obsesif-kompulsif bozuklukta ve travma sonrası stres bozukluğunda kullanılır.', 'Prescription only. The effect builds up gradually and treatment must not be stopped abruptly. It can cause drowsiness and affect driving, alcohol is best avoided.', 'Izdaje se samo na recept. Djelovanje se razvija postepeno, terapija se ne prekida naglo. Može izazvati pospanost i uticati na vožnju, alkohol se ne preporučuje.', 'Издаје се само на рецепт. Дјеловање се развија постепено, терапија се не прекида нагло. Може изазвати поспаност и утицати на вожњу, алкохол се не препоручује.', 'Только по рецепту. Действие развивается постепенно, резко прекращать приём нельзя. Возможны сонливость и влияние на вождение, алкоголь нежелателен.', 'Verschreibungspflichtig. Die Wirkung setzt langsam ein, die Einnahme darf nicht abrupt beendet werden. Müdigkeit ist möglich, Alkohol wird nicht empfohlen.', 'Yalnızca reçeteyle verilir. Etkisi yavaş yerleşir, tedavi aniden kesilmez. Uyku hali yapabilir ve araç kullanımını etkiler, alkol önerilmez.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- sikavica (silybum marianum (l.) gaertner)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (741, 'Plant material from milk thistle (Silybum marianum), the source of silymarin.', 'Biljna sirovina sikavice (Silybum marianum), izvor silimarina.', 'Биљна сировина сикавице (Silybum marianum), извор силимарина.', 'Растительное сырьё расторопши пятнистой (Silybum marianum), источник силимарина.', 'Pflanzliches Material der Mariendistel (Silybum marianum), Quelle von Silymarin.', 'Deve dikeni (Silybum marianum) bitkisinden elde edilen, silimarin kaynağı bitkisel bir hammaddedir.', 'Used as a supportive remedy in chronic liver disease, fatty liver and after toxic strain on the liver.', 'Primjenjuje se kao pomoćno sredstvo kod hroničnih bolesti jetre, masne jetre i poslije toksičnog opterećenja.', 'Примјењује се као помоћно средство код хроничних болести јетре, масне јетре и послије токсичног оптерећења.', 'Применяют как вспомогательное средство при хронических болезнях печени, жировой болезни печени и после токсических нагрузок.', 'Wird unterstützend bei chronischen Lebererkrankungen, Fettleber und nach Belastung der Leber durch Giftstoffe eingesetzt.', 'Kronik karaciğer hastalıklarında, karaciğer yağlanmasında ve toksik yüklenme sonrasında destekleyici olarak kullanılır.', 'Sold over the counter. Evidence of benefit is limited and it does not replace treatment of the underlying disease. Allergy is possible in people sensitive to daisy family plants.', 'Izdaje se bez recepta. Dokazi o djelovanju su ograničeni i ne zamjenjuje liječenje osnovne bolesti. Moguća je alergija kod osjetljivih na glavočike, a moguće su i interakcije.', 'Издаје се без рецепта. Докази о дјеловању су ограничени и не замјењује лијечење основне болести. Могућа је алергија код осјетљивих на главочике, а могуће су и интеракције.', 'Отпускается без рецепта. Доказательная база ограничена, средство не заменяет лечение основной болезни. Возможна аллергия при чувствительности к астровым, бывают взаимодействия.', 'Rezeptfrei erhältlich. Die Studienlage ist begrenzt, die Behandlung der Grunderkrankung ersetzt es nicht. Bei Empfindlichkeit gegen Korbblütler sind Allergien möglich.', 'Reçetesiz satılır. Etkisine dair kanıtlar sınırlıdır, altta yatan hastalığın tedavisinin yerini tutmaz. Papatyagillere duyarlı kişilerde alerji ve etkileşim olabilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- sildenafil
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (742, 'A medicine that widens blood vessels by blocking phosphodiesterase type 5.', 'Lijek koji širi krvne sudove blokiranjem fosfodiesteraze tipa 5.', 'Лијек који шири крвне судове блокирањем фосфодиестеразе типа 5.', 'Средство, расширяющее сосуды за счёт блокады фосфодиэстеразы 5 типа.', 'Ein Mittel, das die Gefäße erweitert, indem es die Phosphodiesterase Typ 5 hemmt.', 'Fosfodiesteraz tip 5 enzimini bloke ederek damarları genişleten bir ilaçtır.', 'Used for erectile dysfunction, while separate products are used for pulmonary arterial hypertension.', 'Primjenjuje se kod erektilne disfunkcije, a posebni preparati kod plućne arterijske hipertenzije.', 'Примјењује се код еректилне дисфункције, а посебни препарати код плућне артеријске хипертензије.', 'Применяют при эректильной дисфункции, отдельные препараты — при лёгочной артериальной гипертензии.', 'Wird bei erektiler Dysfunktion angewendet, eigene Präparate bei pulmonaler arterieller Hypertonie.', 'Erektil disfonksiyonda kullanılır, ayrı preparatları pulmoner arteriyel hipertansiyonda tercih edilir.', 'Prescription only. It must not be combined with nitrates, as together they drop blood pressure sharply. Headache, flushing and a blocked nose are common.', 'Izdaje se samo na recept. Ne smije se kombinovati sa nitratima jer zajedno naglo snižavaju pritisak. Mogući su glavobolja, crvenilo lica i zapušen nos.', 'Издаје се само на рецепт. Не смије се комбиновати са нитратима јер заједно нагло снижавају притисак. Могући су главобоља, црвенило лица и запушен нос.', 'Только по рецепту. Несовместим с нитратами: вместе они резко снижают давление. Возможны головная боль, приливы и заложенность носа. При болезнях сердца решает врач.', 'Verschreibungspflichtig. Nicht zusammen mit Nitraten, der Blutdruck fällt dann stark ab. Kopfschmerzen, Hitzegefühl und verstopfte Nase kommen häufig vor.', 'Yalnızca reçeteyle verilir. Nitratlarla birlikte kullanılmaz, tansiyon aniden düşer. Baş ağrısı, yüzde kızarma ve burun tıkanıklığı sık görülür.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- simetikon
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (744, 'An antifoaming agent that breaks up gas bubbles in the gut and is not absorbed into the blood.', 'Sredstvo protiv pjene koje razbija mjehuriće gasa u crijevima i ne ulazi u krvotok.', 'Средство против пјене које разбија мјехуриће гаса у цријевима и не улази у крвоток.', 'Пеногаситель: разрушает пузырьки газа в кишечнике и не всасывается в кровь.', 'Ein Entschäumer, der Gasblasen im Darm auflöst und nicht ins Blut übergeht.', 'Bağırsaktaki gaz kabarcıklarını dağıtan, kana geçmeyen bir köpük gidericidir.', 'Used for bloating and excess gas, including in infants, and in preparation for an abdominal ultrasound.', 'Primjenjuje se kod nadutosti i pojačanog stvaranja gasova, i kod odojčadi, kao i u pripremi za ultrazvuk trbuha.', 'Примјењује се код надутости и појачаног стварања гасова, и код одојчади, као и у припреми за ултразвук трбуха.', 'Применяют при вздутии живота и повышенном газообразовании, в том числе у младенцев, а также при подготовке к УЗИ брюшной полости.', 'Wird bei Blähungen und vermehrter Gasbildung, auch bei Säuglingen, sowie zur Vorbereitung auf eine Ultraschalluntersuchung eingesetzt.', 'Şişkinlik ve aşırı gazda, bebeklerde de, ayrıca karın ultrasonu hazırlığında kullanılır.', 'Available over the counter and considered safe. Severe or lasting abdominal pain is not a case for self-treatment and needs a doctor''s examination.', 'Izdaje se bez recepta i smatra se bezbjednim. Kod jakog ili dugotrajnog bola u trbuhu samoliječenje nije prihvatljivo, potreban je pregled.', 'Издаје се без рецепта и сматра се безбједним. Код јаког или дуготрајног бола у трбуху самолијечење није прихватљиво, потребан је преглед.', 'Отпускается без рецепта и считается безопасным. При сильной или длительной боли в животе самолечение недопустимо, нужен осмотр врача.', 'Rezeptfrei und gut verträglich. Bei starken oder anhaltenden Bauchschmerzen ist Selbstbehandlung nicht angebracht, ein Arztbesuch ist nötig.', 'Reçetesiz satılır ve güvenli kabul edilir. Şiddetli ya da uzun süren karın ağrısında kendi kendine tedavi uygun değildir, hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- sitagliptin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (748, 'A glucose-lowering gliptin, a DPP-4 inhibitor, that strengthens the body''s own response to a meal.', 'Lijek za snižavanje šećera iz grupe gliptina, pojačava sopstveni odgovor organizma na obrok.', 'Лијек за снижавање шећера из групе глиптина, појачава сопствени одговор организма на оброк.', 'Сахароснижающее вещество из группы глиптинов, ингибиторов DPP-4: усиливает собственный ответ организма на приём пищи.', 'Ein blutzuckersenkendes Gliptin, das die körpereigene Antwort auf eine Mahlzeit verstärkt.', 'Vücudun öğüne verdiği kendi yanıtını güçlendiren, gliptin grubundan kan şekeri düşürücü bir maddedir.', 'Prescribed for type 2 diabetes, most often added to metformin, including as a fixed combination product.', 'Propisuje se kod dijabetesa tipa 2, najčešće kao dodatak metforminu, i u fiksnim kombinacijama.', 'Прописује се код дијабетеса типа 2, најчешће као додатак метформину, и у фиксним комбинацијама.', 'Назначают при сахарном диабете 2 типа, чаще как дополнение к метформину, в том числе в фиксированных комбинациях.', 'Wird bei Typ-2-Diabetes verordnet, meist zusätzlich zu Metformin, auch als festes Kombinationspräparat.', 'Tip 2 diyabette, çoğunlukla metformine ek olarak ve sabit kombinasyon ürünleri içinde reçete edilir.', 'Prescription only. On its own it rarely causes low blood sugar, but the risk rises with other glucose-lowering medicines. With kidney disease, a doctor decides.', 'Izdaje se samo na recept. Sam rijetko izaziva nizak šećer, ali uz druge lijekove za šećer rizik raste. Kod bolesti bubrega terapiju vodi ljekar.', 'Издаје се само на рецепт. Сам ријетко изазива низак шећер, али уз друге лијекове за шећер ризик расте. Код болести бубрега терапију води љекар.', 'Только по рецепту. Само по себе редко вызывает гипогликемию, но вместе с другими сахароснижающими средствами риск выше. При болезнях почек лечение ведёт врач.', 'Verschreibungspflichtig. Allein löst es selten eine Unterzuckerung aus, zusammen mit anderen Mitteln steigt das Risiko. Bei Nierenkrankheiten führt der Arzt die Therapie.', 'Yalnızca reçeteyle verilir. Tek başına nadiren düşük şekere yol açar, diğer ilaçlarla birlikte risk artar. Böbrek hastalığında tedaviyi hekim yönetir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- suvi ekstrakt korijena
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (768, 'Dry root extract is the label for a herbal active substance; in the Montenegrin register it is valerian root in calming combinations.', 'Suvi ekstrakt korijena je oznaka biljne aktivne supstance, a u crnogorskom registru to je korijen valerijane u umirujućim kombinacijama.', 'Суви екстракт коријена је ознака биљне активне супстанце, а у црногорском регистру то је коријен валеријане у умирујућим комбинацијама.', 'Сухой экстракт корня — обозначение растительного действующего вещества; в реестре Черногории это корень валерианы в успокаивающих сборах.', 'Trockener Wurzelextrakt bezeichnet einen pflanzlichen Wirkstoff, im montenegrinischen Register die Baldrianwurzel in Beruhigungsmitteln.', 'Kuru kök ekstresi, bitkisel bir etkin maddenin adıdır; Karadağ kayıtlarında sakinleştirici kombinasyonlardaki kediotu köküdür.', 'Such extracts go into herbal calming remedies used for nervous tension and trouble falling asleep.', 'Ovakvi ekstrakti ulaze u biljne umirujuće preparate koji se koriste kod nervne napetosti i teškog uspavljivanja.', 'Овакви екстракти улазе у биљне умирујуће препарате који се користе код нервне напетости и тешког успављивања.', 'Такие экстракты входят в растительные успокаивающие средства, которые применяют при нервном напряжении и трудностях с засыпанием.', 'Solche Extrakte stecken in pflanzlichen Beruhigungsmitteln, die bei nervöser Anspannung und Einschlafproblemen verwendet werden.', 'Bu ekstreler, sinirsel gerginlik ve uykuya dalma güçlüğünde kullanılan bitkisel sakinleştirici preparatlarda bulunur.', 'These products need no prescription. Drowsiness is possible, so they are not combined with alcohol or sleeping pills. In children and pregnancy, only as advised.', 'Lijekovi su bez recepta. Moguća je pospanost, pa se ne kombinuju sa alkoholom i lijekovima za spavanje. Djeci i trudnicama samo po savjetu ljekara.', 'Лијекови су без рецепта. Могућа је поспаност, па се не комбинују са алкохолом и лијековима за спавање. Дјеци и трудницама само по савјету љекара.', 'Средства безрецептурные. Возможна сонливость, поэтому с алкоголем и снотворными их не сочетают. Детям и беременным — только по назначению врача.', 'Rezeptfrei erhältlich. Müdigkeit ist möglich, daher kein Alkohol und keine Schlafmittel dazu. Bei Kindern und in der Schwangerschaft nur nach Anweisung.', 'Bu ürünler reçetesizdir. Uyku hali görülebilir, alkol ve uyku ilaçlarıyla birlikte kullanılmaz. Çocuklarda ve gebelikte hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- suvi ekstrakt lista
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (769, 'Dry leaf extract is the label for a herbal active substance; in the Montenegrin register it is mostly ivy leaf extract.', 'Suvi ekstrakt lista je oznaka biljne aktivne supstance, a u crnogorskom registru to je uglavnom list bršljana.', 'Суви екстракт листа је ознака биљне активне супстанце, а у црногорском регистру то је углавном лист бршљана.', 'Сухой экстракт листьев — обозначение растительного действующего вещества; в реестре Черногории это в основном лист плюща.', 'Trockener Blattextrakt bezeichnet einen pflanzlichen Wirkstoff, im montenegrinischen Register meist Efeublattextrakt.', 'Kuru yaprak ekstresi, bitkisel bir etkin maddenin adıdır; Karadağ kayıtlarında çoğunlukla sarmaşık yaprağı ekstresidir.', 'Such extracts go into cough remedies, thinning mucus and making it easier to clear during colds.', 'Ovakvi ekstrakti ulaze u preparate protiv kašlja, razrjeđuju sekret i olakšavaju iskašljavanje kod prehlade.', 'Овакви екстракти улазе у препарате против кашља, разрјеђују секрет и олакшавају искашљавање код прехладе.', 'Такие экстракты входят в средства от кашля, они разжижают мокроту и облегчают её отхождение при простудных заболеваниях.', 'Solche Extrakte stecken in Hustenmitteln, sie verflüssigen den Schleim und erleichtern das Abhusten bei Erkältungen.', 'Bu ekstreler öksürük ürünlerinde bulunur, balgamı sulandırıp soğuk algınlığında atılmasını kolaylaştırır.', 'These products need no prescription, but a cough lasting over a week, with fever, breathlessness or blood in the sputum needs a doctor. For children only as advised.', 'Lijekovi su bez recepta, ali kašalj duži od nedjelju dana, sa temperaturom ili krvlju u ispljuvku traži pregled ljekara. Djeci samo po savjetu ljekara.', 'Лијекови су без рецепта, али кашаљ дужи од недјељу дана, са температуром или крвљу у испљувку тражи преглед љекара. Дјеци само по савјету љекара.', 'Средства безрецептурные, но кашель дольше недели, с температурой, одышкой или кровью в мокроте требует осмотра врача. Детям — по назначению врача.', 'Rezeptfrei, doch Husten über eine Woche, mit Fieber, Atemnot oder Blut im Auswurf gehört ärztlich abgeklärt. Für Kinder nur nach ärztlicher Anweisung.', 'Reçetesiz satılır, ancak bir haftadan uzun süren, ateş, nefes darlığı veya balgamda kan eşlik eden öksürükte hekime gidilir. Çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- suvi ekstrakt ploda
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (770, 'A standardised dry extract of plant fruit. In products registered in Montenegro this is milk thistle fruit extract (Silybum marianum).', 'Standardizovani suvi ekstrakt ploda biljke. U preparatima registrovanim u Crnoj Gori to je ekstrakt ploda sikavice (Silybum marianum).', 'Стандардизовани суви екстракт плода биљке. У препаратима регистрованим у Црној Гори то је екстракт плода сикавице (Silybum marianum).', 'Стандартизированная сухая вытяжка из плодов растения. В зарегистрированных в Черногории препаратах это экстракт плодов расторопши.', 'Ein standardisierter Trockenextrakt aus Pflanzenfrüchten. In den in Montenegro registrierten Präparaten ist es Mariendistelfrucht.', 'Bitki meyvesinden elde edilen standart bir kuru ekstredir. Karadağ''da ruhsatlı ürünlerde deve dikeni meyvesi ekstresidir.', 'Used as a supportive remedy in chronic liver disease and fatty liver, as part of over-the-counter herbal products.', 'Primjenjuje se kao pomoćno sredstvo kod hroničnih bolesti jetre i masne jetre, u sastavu biljnih preparata bez recepta.', 'Примјењује се као помоћно средство код хроничних болести јетре и масне јетре, у саставу биљних препарата без рецепта.', 'Применяют как вспомогательное средство при хронических болезнях печени и жировой болезни печени, в составе растительных препаратов.', 'Wird unterstützend bei chronischen Lebererkrankungen und Fettleber eingesetzt, als Bestandteil rezeptfreier pflanzlicher Präparate.', 'Reçetesiz bitkisel ürünlerin bileşeni olarak kronik karaciğer hastalıklarında ve karaciğer yağlanmasında destekleyici kullanılır.', 'Sold over the counter. The composition depends on the source plant, so the package should be read. Evidence is limited and it does not replace treatment of the underlying disease.', 'Izdaje se bez recepta. Sastav zavisi od biljke iz koje potiče, pa treba pročitati pakovanje. Dokazi o djelovanju su ograničeni i ne zamjenjuju liječenje osnovne bolesti.', 'Издаје се без рецепта. Састав зависи од биљке из које потиче, па треба прочитати паковање. Докази о дјеловању су ограничени и не замјењују лијечење основне болести.', 'Отпускается без рецепта. Состав зависит от растения-источника, поэтому важно читать упаковку. Доказательная база ограничена, средство не заменяет лечение основной болезни.', 'Rezeptfrei erhältlich. Die Zusammensetzung hängt von der Ausgangspflanze ab, daher die Packung lesen. Die Studienlage ist begrenzt, die Grunderkrankung behandelt es nicht.', 'Reçetesiz satılır. İçerik kaynak bitkiye göre değişir, ambalajın okunması gerekir. Etkisine dair kanıtlar sınırlıdır, hastalığın tedavisinin yerini tutmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt cijele svježe biljke; anđelika (angelica archangelica l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (780, 'An extract of the fresh angelica plant, a herbal component of a combined tincture for the stomach and gut.', 'Ekstrakt svježe biljke anđelike, biljni sastojak kombinovane tinkture za želudac i crijeva.', 'Екстракт свјеже биљке анђелике, биљни састојак комбиноване тинктуре за желудац и цријева.', 'Экстракт свежего растения дягиля, растительный компонент комбинированной настойки для желудка и кишечника.', 'Ein Extrakt der frischen Engelwurz, pflanzlicher Bestandteil einer kombinierten Tinktur für Magen und Darm.', 'Taze melekotu bitkisinin ekstresidir, mide ve bağırsak için kombine bitkisel tentürün bileşenidir.', 'Used as part of a herbal remedy for functional digestive complaints: heaviness after meals, bloating and abdominal cramps.', 'Primjenjuje se u sastavu biljnog preparata kod funkcionalnih smetnji probave: težine poslije jela, nadutosti i grčeva u trbuhu.', 'Примјењује се у саставу биљног препарата код функционалних сметњи пробаве: тежине послије јела, надутости и грчева у трбуху.', 'Применяют в составе растительного средства при функциональных нарушениях пищеварения: тяжести после еды, вздутии и спазмах в животе.', 'Wird als Teil eines pflanzlichen Mittels bei funktionellen Verdauungsbeschwerden eingesetzt: Völlegefühl, Blähungen und Bauchkrämpfe.', 'Bitkisel preparatın parçası olarak işlevsel sindirim şikayetlerinde, yemek sonrası dolgunluk, şişkinlik ve karın kramplarında kullanılır.', 'Over the counter, the tincture contains alcohol. Angelica makes the skin more sensitive to sunlight. Lasting complaints need a doctor''s examination.', 'Izdaje se bez recepta, tinktura sadrži alkohol. Anđelika povećava osjetljivost kože na sunce. Uporne tegobe traže pregled ljekara.', 'Издаје се без рецепта, тинктура садржи алкохол. Анђелика повећава осјетљивост коже на сунце. Упорне тегобе траже преглед љекара.', 'Отпускается без рецепта, настойка содержит спирт. Дягиль повышает чувствительность кожи к солнцу. При стойких жалобах нужен осмотр врача.', 'Rezeptfrei, die Tinktur enthält Alkohol. Engelwurz macht die Haut empfindlicher für Sonne. Anhaltende Beschwerden gehören in ärztliche Abklärung.', 'Reçetesiz satılır, tentür alkol içerir. Melekotu cildi güneşe duyarlı hale getirir. Geçmeyen şikayetlerde hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt cvijeta
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (781, 'Liquid flower extract is a herbal active-substance heading; in the Montenegrin registry it stands for mallow flower in a cough syrup.', 'Tečni ekstrakt cvijeta, oznaka biljne aktivne supstance; u crnogorskom registru to je cvijet crnog sljeza u sirupu protiv kašlja.', 'Течни екстракт цвијета, ознака биљне активне супстанце; у црногорском регистру то је цвијет црног сљеза у сирупу против кашља.', 'Жидкий экстракт цветков — обозначение растительного действующего вещества; в реестре Черногории это цветки мальвы в сиропе от кашля.', 'Flüssiger Blütenextrakt ist die Bezeichnung eines pflanzlichen Wirkstoffs, im montenegrinischen Register die Malvenblüte in einem Hustensaft.', 'Sıvı çiçek ekstresi bitkisel bir etkin madde tanımıdır; Karadağ kayıtlarında öksürük şurubundaki ebegümeci çiçeğini gösterir.', 'Such extracts go into herbal cough syrups: they coat the lining of the throat and ease a dry, irritating cough.', 'Takvi ekstrakti ulaze u biljne sirupe protiv kašlja: oblažu sluznicu i ublažavaju suv, nadražajni kašalj.', 'Такви екстракти улазе у биљне сирупе против кашља: облажу слузницу и ублажавају сув, надражајни кашаљ.', 'Такие экстракты входят в растительные сиропы от кашля: они обволакивают слизистую и смягчают сухой раздражающий кашель.', 'Solche Extrakte stecken in pflanzlichen Hustensäften: Sie legen sich über die Schleimhaut und lindern trockenen Reizhusten.', 'Bu tür ekstreler bitkisel öksürük şuruplarında bulunur, boğaz mukozasını kaplayarak kuru ve tahriş edici öksürüğü yatıştırır.', 'These products are sold without prescription and syrups may contain sugar. A cough lasting over a week, fever or breathlessness needs a doctor; children, as advised.', 'Preparati se izdaju bez recepta, sirup može sadržati šećer. Kašalj duži od nedjelju dana, temperatura ili gušenje traže pregled ljekara, djeci po njegovoj preporuci.', 'Препарати се издају без рецепта, сируп може садржати шећер. Кашаљ дужи од недјељу дана, температура или гушење траже преглед љекара, дјеци по његовој препоруци.', 'Средства безрецептурные, сироп может содержать сахар. При кашле дольше недели, температуре или одышке нужен осмотр врача. Детям — по его назначению.', 'Rezeptfrei, der Saft kann Zucker enthalten. Husten über eine Woche, Fieber oder Atemnot gehören zum Arzt. Bei Kindern nur nach ärztlichem Rat.', 'Reçetesiz satılır, şurup şeker içerebilir. Bir haftadan uzun öksürük, ateş veya nefes darlığında hekime gidilir. Çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt cvijeta; nana (mentha piperita l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (782, 'A peppermint extract, a herbal component of a combined tincture for the stomach and gut.', 'Ekstrakt nane, biljni sastojak kombinovane tinkture za želudac i crijeva.', 'Екстракт нане, биљни састојак комбиноване тинктуре за желудац и цријева.', 'Экстракт мяты перечной, растительный компонент комбинированной настойки для желудка и кишечника.', 'Ein Pfefferminzextrakt, pflanzlicher Bestandteil einer kombinierten Tinktur für Magen und Darm.', 'Nane ekstresidir, mide ve bağırsak için hazırlanan kombine bitkisel tentürün bileşenidir.', 'Used as part of a herbal remedy for bloating, cramps and heaviness in the abdomen caused by functional digestive disorders.', 'Primjenjuje se u sastavu biljnog preparata kod nadutosti, grčeva i težine u trbuhu zbog funkcionalnih smetnji probave.', 'Примјењује се у саставу биљног препарата код надутости, грчева и тежине у трбуху због функционалних сметњи пробаве.', 'Применяют в составе растительного средства при вздутии, спазмах и тяжести в животе, связанных с функциональными нарушениями пищеварения.', 'Wird als Teil eines pflanzlichen Mittels bei Blähungen, Krämpfen und Völlegefühl durch funktionelle Verdauungsstörungen eingesetzt.', 'Bitkisel preparatın parçası olarak işlevsel sindirim bozukluğuna bağlı şişkinlik, kramp ve karında dolgunlukta kullanılır.', 'Over the counter, the tincture contains alcohol. It can worsen heartburn and reflux. With gallstones and in children, only on a doctor''s advice.', 'Izdaje se bez recepta, tinktura sadrži alkohol. Može pojačati žgaravicu i refluks. Kod kamena u žuči i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта, тинктура садржи алкохол. Може појачати жгаравицу и рефлукс. Код камена у жучи и код дјеце само по савјету љекара.', 'Отпускается без рецепта, настойка содержит спирт. Может усиливать изжогу и рефлюкс. При камнях в желчном пузыре и у детей — по назначению врача.', 'Rezeptfrei, die Tinktur enthält Alkohol. Sodbrennen und Reflux können sich verstärken. Bei Gallensteinen und bei Kindern nur nach ärztlichem Rat.', 'Reçetesiz satılır, tentür alkol içerir. Mide yanması ve reflüyü artırabilir. Safra taşında ve çocuklarda yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt herbe
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (783, 'Liquid extract of herb is a label for a plant-based active ingredient; in the Montenegrin register it is thyme herb in a cough syrup.', 'Tečni ekstrakt herbe je oznaka biljne aktivne supstance; u crnogorskom registru to je herba timijana u sirupu protiv kašlja.', 'Течни екстракт хербе је ознака биљне активне супстанце; у црногорском регистру то је херба тимијана у сирупу против кашља.', 'Жидкий экстракт травы — обозначение растительного действующего вещества; в реестре Черногории это трава тимьяна в сиропе от кашля.', 'Flüssiger Krautextrakt ist die Bezeichnung eines pflanzlichen Wirkstoffs; im montenegrinischen Register ist es Thymiankraut in einem Hustensaft.', 'Sıvı herba özütü bitkisel bir etken maddenin adıdır; Karadağ kayıtlarında öksürük şurubundaki kekik herbasını belirtir.', 'Such extracts are part of herbal cough syrups: they thin the mucus and soothe a cough during colds.', 'Takvi ekstrakti ulaze u biljne sirupe protiv kašlja: razrjeđuju sekret i ublažavaju kašalj uz prehladu.', 'Такви екстракти улазе у биљне сирупе против кашља: разрјеђују секрет и ублажавају кашаљ уз прехладу.', 'Такие экстракты входят в растительные сиропы от кашля: они разжижают мокроту и смягчают кашель при простудных заболеваниях.', 'Solche Extrakte stecken in pflanzlichen Hustensäften: Sie verflüssigen den Schleim und lindern den Husten bei Erkältungen.', 'Bu tür özütler bitkisel öksürük şuruplarında yer alır: balgamı sulandırır ve soğuk algınlığındaki öksürüğü yumuşatır.', 'These products are over the counter and the syrup may contain sugar. A cough lasting over a week, fever, breathlessness or blood in mucus needs a doctor.', 'Preparati se izdaju bez recepta, sirup može sadržati šećer. Kod kašlja dužeg od nedjelju dana, temperature, nedostatka vazduha ili krvi u sekretu potreban je ljekar.', 'Препарати се издају без рецепта, сируп може садржати шећер. Код кашља дужег од недјељу дана, температуре, недостатка ваздуха или крви у секрету потребан је љекар.', 'Средства безрецептурные, сироп может содержать сахар. При кашле дольше недели, температуре, одышке или крови в мокроте нужен осмотр врача.', 'Die Präparate sind rezeptfrei, der Saft kann Zucker enthalten. Bei Husten über eine Woche, Fieber, Atemnot oder Blut im Auswurf ist ein Arztbesuch nötig.', 'Ürünler reçetesizdir, şurup şeker içerebilir. Bir haftadan uzun süren öksürükte, ateş, nefes darlığı ya da balgamda kan olmasında hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt herbe; sladić (glycyrrhiza glabra l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (784, 'A liquid liquorice extract, a herbal component of combined remedies for the stomach and bowel.', 'Tečni ekstrakt sladića, biljni sastojak kombinovanih preparata za želudac i crijeva.', 'Течни екстракт сладића, биљни састојак комбинованих препарата за желудац и цријева.', 'Жидкий экстракт солодки — растительный компонент комбинированных средств для желудка и кишечника.', 'Ein flüssiger Süßholzextrakt, pflanzlicher Bestandteil von Kombipräparaten für Magen und Darm.', 'Mide ve bağırsağa yönelik kombine bitkisel preparatların bileşeni olan sıvı meyan ekstresidir.', 'Part of herbal preparations used for heaviness and discomfort in the stomach, cramping and bloating.', 'Ulazi u biljne preparate koji se primjenjuju kod težine i nelagode u želucu, grčeva i nadutosti.', 'Улази у биљне препарате који се примјењују код тежине и нелагоде у желуцу, грчева и надутости.', 'Входит в растительные препараты, которые применяют при тяжести и дискомфорте в желудке, спазмах и вздутии.', 'Bestandteil pflanzlicher Mittel, die bei Völlegefühl und Magenbeschwerden, Krämpfen und Blähungen angewendet werden.', 'Midede ağırlık ve rahatsızlık hissinde, kramp ve şişkinlikte kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. Long use of liquorice can raise blood pressure and lower potassium. With hypertension or in pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Duža primjena sladića može podići pritisak i sniziti kalijum. Kod hipertenzije i u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Дужа примјена сладића може подићи притисак и снизити калијум. Код хипертензије и у трудноћи само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Длительный приём солодки может повышать давление и снижать калий. При гипертонии и беременности — по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Längere Anwendung von Süßholz kann den Blutdruck erhöhen und Kalium senken. Bei Bluthochdruck und in der Schwangerschaft nur ärztlich.', 'Kombine preparatların parçası olarak reçetesiz satılır. Uzun süreli meyan kullanımı tansiyonu yükseltip potasyumu düşürebilir. Tansiyon hastalığında ve gebelikte hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt korijena
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (785, 'Liquid extract of root is a label for a plant-based active ingredient; in the Montenegrin register it is primrose root in a cough syrup.', 'Tečni ekstrakt korijena je oznaka biljne aktivne supstance; u crnogorskom registru to je korijen jagorčevine u sirupu protiv kašlja.', 'Течни екстракт коријена је ознака биљне активне супстанце; у црногорском регистру то је коријен јагорчевине у сирупу против кашља.', 'Жидкий экстракт корня — обозначение растительного действующего вещества; в реестре Черногории это корень первоцвета в сиропе от кашля.', 'Flüssiger Wurzelextrakt bezeichnet einen pflanzlichen Wirkstoff; im montenegrinischen Register ist es Schlüsselblumenwurzel im Hustensaft.', 'Sıvı kök özütü bitkisel bir etken maddenin adıdır; Karadağ kayıtlarında öksürük şurubundaki çuha çiçeği kökünü belirtir.', 'Such extracts are part of herbal cough syrups: they make thick mucus easier to bring up in colds and bronchitis.', 'Takvi ekstrakti ulaze u biljne sirupe protiv kašlja: olakšavaju iskašljavanje gustog sekreta uz prehladu i bronhitis.', 'Такви екстракти улазе у биљне сирупе против кашља: олакшавају искашљавање густог секрета уз прехладу и бронхитис.', 'Такие экстракты входят в растительные сиропы от кашля: они облегчают отхождение густой мокроты при простуде и бронхите.', 'Solche Extrakte stecken in pflanzlichen Hustensäften: Sie erleichtern das Abhusten von zähem Schleim bei Erkältung und Bronchitis.', 'Bu tür özütler bitkisel öksürük şuruplarında yer alır: soğuk algınlığı ve bronşitte koyu balgamın atılmasını kolaylaştırır.', 'These products are over the counter and the syrup may contain sugar. In children and in pregnancy, as advised by a doctor. A lasting cough with fever needs a check-up.', 'Preparati se izdaju bez recepta, sirup može sadržati šećer. Kod djece i u trudnoći po savjetu ljekara. Dugotrajan kašalj sa temperaturom traži pregled.', 'Препарати се издају без рецепта, сируп може садржати шећер. Код дјеце и у трудноћи по савјету љекара. Дуготрајан кашаљ са температуром тражи преглед.', 'Средства безрецептурные, сироп может содержать сахар. Детям и беременным — по назначению врача. Затяжной кашель с температурой требует осмотра.', 'Die Präparate sind rezeptfrei, der Saft kann Zucker enthalten. Bei Kindern und in der Schwangerschaft nach ärztlicher Anweisung. Anhaltender Husten mit Fieber gehört zum Arzt.', 'Ürünler reçetesizdir, şurup şeker içerebilir. Çocuklarda ve gebelikte hekim önerisiyle kullanılır. Ateşle süren uzun öksürük muayene gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt korijena; kamilica (matricaria recutita l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (786, 'A liquid chamomile extract, a herbal component of combined remedies for the stomach and bowel.', 'Tečni ekstrakt kamilice, biljni sastojak kombinovanih preparata za želudac i crijeva.', 'Течни екстракт камилице, биљни састојак комбинованих препарата за желудац и цријева.', 'Жидкий экстракт ромашки — растительный компонент комбинированных средств для желудка и кишечника.', 'Ein flüssiger Kamillenextrakt, pflanzlicher Bestandteil von Kombipräparaten für Magen und Darm.', 'Mide ve bağırsağa yönelik kombine bitkisel preparatların bileşeni olan sıvı papatya ekstresidir.', 'Part of herbal preparations used for cramping, bloating and discomfort in the upper abdomen.', 'Ulazi u biljne preparate koji se primjenjuju kod grčeva, nadutosti i nelagode u gornjem dijelu trbuha.', 'Улази у биљне препарате који се примјењују код грчева, надутости и нелагоде у горњем дијелу трбуха.', 'Входит в растительные препараты, которые применяют при спазмах, вздутии и дискомфорте в верхних отделах живота.', 'Bestandteil pflanzlicher Mittel, die bei Krämpfen, Blähungen und Beschwerden im Oberbauch angewendet werden.', 'Karnın üst kısmında kramp, şişkinlik ve rahatsızlık hissinde kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. Allergy is possible in people sensitive to daisy family plants. For children and in pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Moguća je alergija kod osjetljivih na biljke iz porodice glavočika. Za djecu i u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Могућа је алергија код осјетљивих на биљке из породице главочика. За дјецу и у трудноћи само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Возможна аллергия при чувствительности к растениям семейства сложноцветных. Детям и беременным — по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Bei Empfindlichkeit gegen Korbblütler sind Allergien möglich. Für Kinder und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Kombine preparatların parçası olarak reçetesiz satılır. Papatyagillere duyarlı kişilerde alerji görülebilir. Çocuklarda ve gebelikte hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt korijena; matičnjak (melissa officinalis l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (787, 'A liquid lemon balm extract, a herbal component of combined remedies for the stomach and bowel.', 'Tečni ekstrakt matičnjaka, biljni sastojak kombinovanih preparata za želudac i crijeva.', 'Течни екстракт матичњака, биљни састојак комбинованих препарата за желудац и цријева.', 'Жидкий экстракт мелиссы — растительный компонент комбинированных средств для желудка и кишечника.', 'Ein flüssiger Melissenextrakt, pflanzlicher Bestandteil von Kombipräparaten für Magen und Darm.', 'Mide ve bağırsağa yönelik kombine bitkisel preparatların bileşeni olan sıvı oğul otu ekstresidir.', 'Part of herbal preparations used for abdominal cramping and discomfort, including complaints linked to nervous tension.', 'Ulazi u biljne preparate koji se primjenjuju kod grčeva i nelagode u trbuhu, i kod tegoba vezanih za napetost.', 'Улази у биљне препарате који се примјењују код грчева и нелагоде у трбуху, и код тегоба везаних за напетост.', 'Входит в растительные препараты, которые применяют при спазмах и дискомфорте в животе, в том числе на фоне нервного напряжения.', 'Bestandteil pflanzlicher Mittel bei Krämpfen und Bauchbeschwerden, auch wenn diese mit nervöser Anspannung zusammenhängen.', 'Karın kramplarında ve gerginlikle ilişkili sindirim yakınmalarında kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. It may cause mild drowsiness. For children, in pregnancy and while breastfeeding, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Može izazvati blagu pospanost. Za djecu, u trudnoći i tokom dojenja samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Може изазвати благу поспаност. За дјецу, у трудноћи и током дојења само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Может вызывать лёгкую сонливость. Детям, беременным и кормящим — только по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Kann leicht müde machen. Für Kinder, in der Schwangerschaft und Stillzeit nur nach ärztlicher Anweisung.', 'Kombine preparatların parçası olarak reçetesiz satılır. Hafif uyku hali yapabilir. Çocuklarda, gebelikte ve emzirmede hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt lista
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (788, 'Liquid leaf extract is a herbal active-substance heading; in the Montenegrin registry it stands for ribwort plantain leaf in a cough syrup.', 'Tečni ekstrakt lista, oznaka biljne aktivne supstance; u crnogorskom registru to je list bokvice u sirupu protiv kašlja.', 'Течни екстракт листа, ознака биљне активне супстанце; у црногорском регистру то је лист боквице у сирупу против кашља.', 'Жидкий экстракт листьев — обозначение растительного действующего вещества; в реестре Черногории это лист подорожника в сиропе от кашля.', 'Flüssiger Blattextrakt ist die Bezeichnung eines pflanzlichen Wirkstoffs, im montenegrinischen Register das Spitzwegerichblatt in einem Hustensaft.', 'Sıvı yaprak ekstresi bitkisel bir etkin madde tanımıdır; Karadağ kayıtlarında öksürük şurubundaki sinirotu yaprağını gösterir.', 'Such extracts go into herbal cough syrups: they soothe an irritated throat and ease a dry cough during colds.', 'Takvi ekstrakti ulaze u biljne sirupe protiv kašlja: umiruju nadraženo grlo i smanjuju suv kašalj uz prehladu.', 'Такви екстракти улазе у биљне сирупе против кашља: умирују надражено грло и смањују сув кашаљ уз прехладу.', 'Такие экстракты входят в растительные сиропы от кашля: они смягчают раздражённое горло и уменьшают сухой кашель при простуде.', 'Solche Extrakte stecken in pflanzlichen Hustensäften: Sie beruhigen den gereizten Hals und lindern trockenen Husten bei Erkältung.', 'Bu tür ekstreler bitkisel öksürük şuruplarında bulunur, tahriş olmuş boğazı yatıştırır ve soğuk algınlığındaki kuru öksürüğü azaltır.', 'Sold without prescription, and syrups may contain sugar. For children and in pregnancy, only as a doctor advises. A lasting cough with fever needs examination.', 'Preparati se izdaju bez recepta, sirup može sadržati šećer. Djeci i trudnicama po preporuci ljekara. Dugotrajan kašalj sa temperaturom traži pregled.', 'Препарати се издају без рецепта, сируп може садржати шећер. Дјеци и трудницама по препоруци љекара. Дуготрајан кашаљ са температуром тражи преглед.', 'Средства безрецептурные, сироп может содержать сахар. Детям и беременным — по назначению врача. Затяжной кашель с температурой требует осмотра.', 'Rezeptfrei, der Saft kann Zucker enthalten. Für Kinder und in der Schwangerschaft nur nach ärztlichem Rat. Anhaltender Husten mit Fieber gehört untersucht.', 'Reçetesiz satılır, şurup şeker içerebilir. Çocuklarda ve gebelikte hekim önerisiyle kullanılır. Ateşle birlikte süren öksürük muayene gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

