INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (789, 'A liquid milk thistle extract, a herbal component of combined remedies for the stomach and bowel.', 'Tečni ekstrakt gujine trave, biljni sastojak kombinovanih preparata za želudac i crijeva.', 'Течни екстракт гујине траве, биљни састојак комбинованих препарата за желудац и цријева.', 'Жидкий экстракт расторопши — растительный компонент комбинированных средств для желудка и кишечника.', 'Ein flüssiger Mariendistelextrakt, pflanzlicher Bestandteil von Kombipräparaten für Magen und Darm.', 'Mide ve bağırsağa yönelik kombine bitkisel preparatların bileşeni olan sıvı deve dikeni ekstresidir.', 'Part of herbal preparations used for heaviness in the abdomen, bloating and other digestive complaints.', 'Ulazi u biljne preparate koji se primjenjuju kod težine u trbuhu, nadutosti i drugih smetnji u varenju.', 'Улази у биљне препарате који се примјењују код тежине у трбуху, надутости и других сметњи у варењу.', 'Входит в растительные препараты, которые применяют при тяжести в животе, вздутии и других нарушениях пищеварения.', 'Bestandteil pflanzlicher Mittel, die bei Völlegefühl, Blähungen und anderen Verdauungsbeschwerden angewendet werden.', 'Karında ağırlık, şişkinlik ve diğer sindirim yakınmalarında kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. Allergy is possible in people sensitive to daisy family plants. With liver disease, in pregnancy and for children, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Moguća je alergija kod osjetljivih na glavočike. Kod bolesti jetre, u trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Могућа је алергија код осјетљивих на главочике. Код болести јетре, у трудноћи и код дјеце само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Возможна аллергия при чувствительности к сложноцветным. При болезнях печени, беременности и у детей — по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Bei Empfindlichkeit gegen Korbblütler sind Allergien möglich. Bei Lebererkrankungen, in der Schwangerschaft und bei Kindern nur ärztlich.', 'Kombine preparatların parçası olarak reçetesiz satılır. Papatyagillere duyarlı kişilerde alerji olabilir. Karaciğer hastalığında, gebelikte ve çocuklarda hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

