INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (790, 'A liquid caraway extract, a herbal component of combined remedies for the stomach and bowel.', 'Tečni ekstrakt kima, biljni sastojak kombinovanih preparata za želudac i crijeva.', 'Течни екстракт кима, биљни састојак комбинованих препарата за желудац и цријева.', 'Жидкий экстракт тмина — растительный компонент комбинированных средств для желудка и кишечника.', 'Ein flüssiger Kümmelextrakt, pflanzlicher Bestandteil von Kombipräparaten für Magen und Darm.', 'Mide ve bağırsağa yönelik kombine bitkisel preparatların bileşeni olan sıvı karaman kimyonu ekstresidir.', 'Part of herbal preparations used for bloating, trapped gas and cramping in the intestines.', 'Ulazi u biljne preparate koji se primjenjuju kod nadutosti, gasova i grčeva u crijevima.', 'Улази у биљне препарате који се примјењују код надутости, гасова и грчева у цријевима.', 'Входит в растительные препараты, которые применяют при вздутии, скоплении газов и спазмах в кишечнике.', 'Bestandteil pflanzlicher Mittel, die bei Blähungen, Gasansammlung und Krämpfen im Darm angewendet werden.', 'Şişkinlik, gaz birikimi ve bağırsak kramplarında kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. Allergic reactions are possible. For children, in pregnancy and while breastfeeding, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Moguće su alergijske reakcije. Za djecu, u trudnoći i tokom dojenja samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Могуће су алергијске реакције. За дјецу, у трудноћи и током дојења само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Возможны аллергические реакции. Детям, беременным и кормящим — только по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Allergische Reaktionen sind möglich. Für Kinder, in der Schwangerschaft und Stillzeit nur nach ärztlicher Anweisung.', 'Kombine preparatların parçası olarak reçetesiz satılır. Alerjik reaksiyonlar görülebilir. Çocuklarda, gebelikte ve emzirmede hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt ploda
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (791, 'A liquid extract of a medicinal plant fruit, used in multi-herb remedies for digestion.', 'Tečni ekstrakt ploda ljekovite biljke, sastojak višekomponentnih biljnih preparata za varenje.', 'Течни екстракт плода љековите биљке, састојак вишекомпонентних биљних препарата за варење.', 'Жидкий экстракт плодов лекарственного растения — компонент многокомпонентных растительных средств для пищеварения.', 'Ein flüssiger Fruchtextrakt einer Heilpflanze, Bestandteil pflanzlicher Kombipräparate für die Verdauung.', 'Sindirime yönelik çok bileşenli bitkisel preparatlarda yer alan, tıbbi bir bitkinin sıvı meyve ekstresidir.', 'Part of multi-component herbal preparations used for cramping, bloating and discomfort in the abdomen.', 'Ulazi u višekomponentne biljne preparate koji se primjenjuju kod grčeva, nadutosti i nelagode u trbuhu.', 'Улази у вишекомпонентне биљне препарате који се примјењују код грчева, надутости и нелагоде у трбуху.', 'Входит в состав многокомпонентных растительных препаратов, которые применяют при спазмах, вздутии и дискомфорте в животе.', 'Bestandteil mehrteiliger pflanzlicher Mittel, die bei Krämpfen, Blähungen und Bauchbeschwerden angewendet werden.', 'Karında kramp, şişkinlik ve rahatsızlık hissinde kullanılan çok bileşenli bitkisel preparatların içinde bulunur.', 'Sold without prescription within combined products. The exact plant is named in the leaflet of each product. For children and in pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Tačan sastav naveden je u uputstvu konkretnog preparata. Za djecu i u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Тачан састав наведен је у упутству конкретног препарата. За дјецу и у трудноћи само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Точный состав указан в инструкции конкретного препарата. Детям и беременным — по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Die genaue Pflanze steht in der Packungsbeilage des Präparats. Für Kinder und in der Schwangerschaft nur ärztlich.', 'Kombine preparatların parçası olarak reçetesiz satılır. Hangi bitki olduğu ürünün kullanma talimatında belirtilir. Çocuklarda ve gebelikte hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tečni ekstrakt ploda; rusa (chelidonium majus l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (792, 'A liquid greater celandine extract, a herbal component of some combined remedies for the stomach and bowel.', 'Tečni ekstrakt ruse, biljni sastojak nekih kombinovanih preparata za želudac i crijeva.', 'Течни екстракт русе, биљни састојак неких комбинованих препарата за желудац и цријева.', 'Жидкий экстракт чистотела — растительный компонент некоторых комбинированных средств для желудка и кишечника.', 'Ein flüssiger Schöllkrautextrakt, pflanzlicher Bestandteil einiger Kombipräparate für Magen und Darm.', 'Mide ve bağırsağa yönelik bazı kombine bitkisel preparatların bileşeni olan sıvı kırlangıç otu ekstresidir.', 'Part of herbal preparations used for cramping and discomfort in the upper abdomen.', 'Ulazi u biljne preparate koji se primjenjuju kod grčeva i nelagode u gornjem dijelu trbuha.', 'Улази у биљне препарате који се примјењују код грчева и нелагоде у горњем дијелу трбуха.', 'Входит в растительные препараты, которые применяют при спазмах и дискомфорте в верхних отделах живота.', 'Bestandteil pflanzlicher Mittel, die bei Krämpfen und Beschwerden im Oberbauch angewendet werden.', 'Karnın üst kısmında kramp ve rahatsızlık hissinde kullanılan bitkisel preparatların içinde yer alır.', 'Sold without prescription within combined products. Celandine has been linked to rare liver reactions. With liver disease, in pregnancy and for children, only on a doctor''s advice.', 'Izdaje se bez recepta u sklopu kombinovanih preparata. Rusa se dovodi u vezu sa rijetkim oštećenjem jetre. Kod bolesti jetre, u trudnoći i kod djece samo po savjetu ljekara.', 'Издаје се без рецепта у склопу комбинованих препарата. Руса се доводи у везу са ријетким оштећењем јетре. Код болести јетре, у трудноћи и код дјеце само по савјету љекара.', 'Отпускается без рецепта в составе комбинированных средств. Чистотел связывают с редкими поражениями печени. При болезнях печени, беременности и у детей — только по назначению врача.', 'Rezeptfrei als Teil von Kombipräparaten. Schöllkraut wird mit seltenen Leberschäden in Verbindung gebracht. Bei Leberkrankheit, in der Schwangerschaft und bei Kindern nur ärztlich.', 'Kombine preparatların parçası olarak reçetesiz satılır. Kırlangıç otu nadir karaciğer hasarıyla ilişkilendirilmiştir. Karaciğer hastalığında, gebelikte ve çocuklarda hekime danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- teofilin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (797, 'A xanthine that relaxes the airways and eases bronchial spasm.', 'Supstanca iz grupe ksantina koja širi disajne puteve i smanjuje grč bronhija.', 'Супстанца из групе ксантина која шири дисајне путеве и смањује грч бронхија.', 'Вещество из группы ксантинов, расширяющее бронхи и уменьшающее их спазм.', 'Ein Xanthin, das die Bronchien erweitert und Verkrampfungen löst.', 'Bronşları genişleten ve kasılmalarını azaltan ksantin grubundan bir maddedir.', 'Used for long-term treatment of asthma and chronic obstructive pulmonary disease, usually in addition to inhalers.', 'Koristi se u dugotrajnom liječenju astme i hronične opstruktivne bolesti pluća, obično kao dodatak inhalatorima.', 'Користи се у дуготрајном лијечењу астме и хроничне опструктивне болести плућа, обично као додатак инхалаторима.', 'Применяют для длительного лечения бронхиальной астмы и хронической обструктивной болезни лёгких, обычно как дополнение к ингаляторам.', 'Wird zur Langzeitbehandlung von Asthma und chronisch obstruktiver Lungenerkrankung eingesetzt, meist zusätzlich zu Inhalatoren.', 'Astım ve kronik obstrüktif akciğer hastalığının uzun süreli tedavisinde, genellikle inhalerlere ek olarak kullanılır.', 'Prescription only. The gap between an effective and a toxic dose is narrow, so blood levels may be monitored. Coffee, smoking and many medicines change its effect.', 'Samo na recept. Razlika između djelotvorne i toksične doze je mala, pa ljekar može pratiti nivo u krvi. Kafa, pušenje i mnogi lijekovi mijenjaju njegovo djelovanje.', 'Само на рецепт. Разлика између дјелотворне и токсичне дозе је мала, па љекар може пратити ниво у крви. Кафа, пушење и многи лијекови мијењају његово дјеловање.', 'Только по рецепту. Разница между лечебной и токсичной дозой мала, врач может контролировать уровень в крови. Кофе, курение и многие лекарства меняют его действие.', 'Verschreibungspflichtig. Zwischen wirksamer und giftiger Dosis liegt wenig, der Arzt kann den Blutspiegel kontrollieren. Kaffee, Rauchen und viele Arzneimittel verändern die Wirkung.', 'Yalnızca reçeteyle verilir. Etkili doz ile zehirli doz arasındaki fark azdır, hekim kan düzeyini izleyebilir. Kahve, sigara ve birçok ilaç etkisini değiştirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- terbinafin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (799, 'An antifungal of the allylamine group, used both externally and by mouth.', 'Antimikotik iz grupe alilamina, primjenjuje se spolja i na usta.', 'Антимикотик из групе алиламина, примјењује се споља и на уста.', 'Противогрибковое вещество группы аллиламинов, применяется наружно и внутрь.', 'Ein Antimykotikum aus der Gruppe der Allylamine zur äußerlichen und innerlichen Anwendung.', 'Alilamin grubundan, hem dıştan hem ağızdan kullanılan bir mantar ilacıdır.', 'Used for fungal infections of the feet and skin folds, for tinea versicolor and for fungal nail infections.', 'Primjenjuje se kod gljivica stopala i kožnih nabora, kod pityriasis versicolor i kod gljivica na noktima.', 'Примјењује се код гљивица стопала и кожних набора, код питyриасис версицолор и код гљивица на ноктима.', 'Применяют при грибке стоп и складок кожи, отрубевидном лишае, а также при грибковом поражении ногтей.', 'Wird bei Pilzbefall der Füße und der Hautfalten, bei Kleienpilzflechte sowie bei Nagelpilz angewendet.', 'Ayak ve deri kıvrımı mantarlarında, pitiriyazis versikolorda ve tırnak mantarında kullanılır.', 'Topical forms are over the counter, tablets are prescription only and need liver checks. For children and in pregnancy only as prescribed by a doctor.', 'Preparati za kožu izdaju se bez recepta, tablete samo na recept uz praćenje jetre. Kod djece i u trudnoći samo po savjetu ljekara.', 'Препарати за кожу издају се без рецепта, таблете само на рецепт уз праћење јетре. Код дјеце и у трудноћи само по савјету љекара.', 'Наружные формы безрецептурные, таблетки — только по рецепту и с контролем печени. Детям и при беременности — по назначению врача.', 'Äußerliche Formen sind rezeptfrei, Tabletten verschreibungspflichtig und erfordern Leberkontrollen. Bei Kindern und in der Schwangerschaft nur nach ärztlicher Anweisung.', 'Cilde uygulanan formlar reçetesizdir, tabletler reçeteyle verilir ve karaciğer takibi ister. Çocuklarda ve gebelikte yalnızca doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- testerasta palma (serenoa repens (w. bartram) small, fructus)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (803, 'The fruit of saw palmetto (Serenoa repens), a herbal raw material used to make extracts for urological products.', 'Plod testeraste palme (Serenoa repens), biljna sirovina od koje se prave ekstrakti za urološke preparate.', 'Плод тестерасте палме (Serenoa repens), биљна сировина од које се праве екстракти за уролошке препарате.', 'Плоды пальмы сабаль (Serenoa repens) — растительное сырьё, из которого получают экстракты для урологических препаратов.', 'Die Frucht der Sägepalme (Serenoa repens), pflanzlicher Rohstoff für Extrakte in urologischen Präparaten.', 'Cüce palmiye (Serenoa repens) meyvesidir, ürolojik preparatlardaki ekstrelerin elde edildiği bitkisel hammaddedir.', 'Used for a weak stream, difficult urination and frequent urges linked to benign prostatic hyperplasia.', 'Primjenjuje se kod slabog mlaza, otežanog mokrenja i čestih nagona uz benignu hiperplaziju prostate.', 'Примјењује се код слабог млаза, отежаног мокрења и честих нагона уз бенигну хиперплазију простате.', 'Применяют при затруднённом мочеиспускании, слабой струе и частых позывах на фоне доброкачественной гиперплазии простаты.', 'Wird bei schwachem Harnstrahl, erschwertem Wasserlassen und häufigem Harndrang bei gutartiger Prostatavergrößerung angewendet.', 'İyi huylu prostat büyümesine bağlı zayıf idrar akımı, zor idrar yapma ve sık idrara çıkmada kullanılır.', 'A herbal product available without prescription. Stomach discomfort is possible. Prostate symptoms call for a urologist visit rather than long self-treatment.', 'Biljni preparat koji se izdaje bez recepta. Moguće su tegobe u želucu. Simptomi prostate traže pregled urologa, a ne dugo samoliječenje.', 'Биљни препарат који се издаје без рецепта. Могуће су тегобе у желуцу. Симптоми простате траже преглед уролога, а не дуго самолијечење.', 'Безрецептурное растительное средство. Возможен дискомфорт в желудке. Симптомы со стороны простаты требуют осмотра уролога, а не долгого самолечения.', 'Pflanzliches, rezeptfreies Mittel. Magenbeschwerden sind möglich. Prostatabeschwerden gehören zum Urologen und nicht in eine lange Selbstbehandlung.', 'Reçetesiz satılan bitkisel bir üründür. Mide rahatsızlığı görülebilir. Prostat belirtileri uzun süreli kendi kendine tedavi değil, üroloji muayenesi gerektirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tetrizolin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (808, 'A vasoconstrictor (alpha-adrenergic agonist) for local use in the eye that reduces redness of the conjunctiva.', 'Vazokonstriktor (alfa-adrenergički agonist) za lokalnu primjenu u oku, smanjuje crvenilo konjunktive.', 'Вазоконстриктор (алфа-адренергички агонист) за локалну примјену у оку, смањује црвенило коњунктиве.', 'Сосудосуживающее вещество (альфа-адреномиметик) для местного применения в глазах, уменьшает покраснение конъюнктивы.', 'Ein gefäßverengender Wirkstoff (Alpha-Sympathomimetikum) zur örtlichen Anwendung am Auge, der Rötungen der Bindehaut mindert.', 'Gözde bölgesel kullanılan, konjonktivadaki kızarıklığı azaltan damar büzücü (alfa-adrenerjik agonist) bir maddedir.', 'Used for red and irritated eyes caused by dust, smoke, chlorinated water, wind or long screen work.', 'Primjenjuje se kod crvenila i nadraženosti očiju od prašine, dima, hlorisane vode, vjetra i dugog rada za ekranom.', 'Примјењује се код црвенила и надражености очију од прашине, дима, хлорисане воде, вјетра и дугог рада за екраном.', 'Применяют при покраснении и раздражении глаз от пыли, дыма, хлорированной воды, ветра и долгой работы за экраном.', 'Wird bei geröteten und gereizten Augen durch Staub, Rauch, Chlorwasser, Wind oder lange Bildschirmarbeit angewendet.', 'Toz, duman, klorlu su, rüzgar veya uzun ekran çalışmasına bağlı göz kızarıklığı ve tahrişinde kullanılır.', 'Some drops are over the counter. Prolonged use makes redness worse once it is stopped. In glaucoma, eye pain or falling vision only as prescribed by a doctor.', 'Dio kapi izdaje se bez recepta. Duga upotreba pojačava crvenilo poslije prekida. Kod glaukoma, bola u oku i slabljenja vida samo po savjetu ljekara.', 'Дио капи издаје се без рецепта. Дуга употреба појачава црвенило послије прекида. Код глаукома, бола у оку и слабљења вида само по савјету љекара.', 'Часть капель безрецептурная. Долгое применение усиливает покраснение после отмены. При глаукоме, боли в глазу и снижении зрения — только по назначению врача.', 'Ein Teil der Tropfen ist rezeptfrei. Längere Anwendung verstärkt die Rötung nach dem Absetzen. Bei Glaukom, Augenschmerzen und Sehverschlechterung nur ärztlich.', 'Damlaların bir kısmı reçetesizdir. Uzun kullanım bırakınca kızarıklığı artırır. Glokomda, göz ağrısında ve görme azalmasında yalnızca doktor önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tezepelumab
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (809, 'A monoclonal antibody that blocks one of the earliest inflammation signals in the airways. Given as an injection under the skin.', 'Monoklonsko antitijelo koje blokira jedan od najranijih signala upale u disajnim putevima. Daje se injekcijom pod kožu.', 'Моноклонско антитијело које блокира један од најранијих сигнала упале у дисајним путевима. Даје се ињекцијом под кожу.', 'Моноклональное антитело, блокирующее один из ранних сигналов воспаления в дыхательных путях. Вводится подкожно.', 'Ein monoklonaler Antikörper, der eines der frühesten Entzündungssignale in den Atemwegen blockiert. Spritze unter die Haut.', 'Hava yollarındaki en erken iltihap sinyallerinden birini bloke eden monoklonal antikordur. Deri altına enjeksiyonla uygulanır.', 'Used as an add-on to standard therapy in severe asthma that remains uncontrolled despite inhalers.', 'Primjenjuje se kao dodatak osnovnoj terapiji kod teške astme koja ostaje nekontrolisana uprkos inhalatorima.', 'Примјењује се као додатак основној терапији код тешке астме која остаје неконтролисана упркос инхалаторима.', 'Применяют как дополнение к базисной терапии при тяжёлой бронхиальной астме, которая остаётся неконтролируемой на ингаляторах.', 'Wird als Zusatz zur Basistherapie bei schwerem Asthma eingesetzt, das trotz Inhalatoren nicht kontrolliert ist.', 'İnhalerlere rağmen kontrol altına alınamayan ağır astımda temel tedaviye ek olarak kullanılır.', 'Prescription only; a specialist starts and supervises the treatment. Not for attacks, and inhaled therapy is not stopped. Sore throat and injection-site reactions are possible.', 'Samo na recept, terapiju uvodi i prati specijalista. Ne koristi se u napadu, a osnovni inhalatori se ne ukidaju. Mogući su bol u grlu i reakcija na mjestu uboda.', 'Само на рецепт, терапију уводи и прати специјалиста. Не користи се у нападу, а основни инхалатори се не укидају. Могући су бол у грлу и реакција на мјесту убода.', 'Только по рецепту, лечение начинает и контролирует специалист. Не применяется при приступе, базисные ингаляторы не отменяют. Возможны боль в горле и реакция в месте укола.', 'Nur auf Rezept, Beginn und Kontrolle durch einen Facharzt. Nicht im Anfall, die Basisinhalatoren werden nicht abgesetzt. Halsschmerzen und Reaktionen an der Einstichstelle möglich.', 'Yalnızca reçeteyle verilir, tedaviyi uzman hekim başlatır ve izler. Atakta kullanılmaz, temel inhaler tedavi kesilmez. Boğaz ağrısı ve enjeksiyon yerinde tepki olabilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tiamin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (811, 'Vitamin B1, a water-soluble B vitamin involved in carbohydrate metabolism and nerve function.', 'Vitamin B1, vitamin B grupe rastvorljiv u vodi, učestvuje u razmjeni ugljenih hidrata i radu nerava.', 'Витамин B1, витамин Б групе растворљив у води, учествује у размјени угљених хидрата и раду нерава.', 'Витамин B1, водорастворимый витамин группы B, участвует в обмене углеводов и работе нервов.', 'Vitamin B1, ein wasserlösliches B-Vitamin, wichtig für den Kohlenhydratstoffwechsel und die Nerven.', 'B1 vitamini, suda çözünen bir B grubu vitamini, karbonhidrat metabolizmasında ve sinirlerin çalışmasında rol alır.', 'Used for vitamin B1 deficiency, with a poor diet or alcohol misuse, and as part of B-complex products.', 'Primjenjuje se kod nedostatka vitamina B1, kod jednolične ishrane i prekomjernog pijenja alkohola, i u preparatima B grupe.', 'Примјењује се код недостатка витамина B1, код једноличне исхране и прекомјерног пијења алкохола, и у препаратима Б групе.', 'Применяют при недостатке витамина B1, при однообразном питании и злоупотреблении алкоголем, а также в составе комплексов группы B.', 'Wird bei Vitamin-B1-Mangel, bei einseitiger Ernährung und Alkoholmissbrauch sowie in B-Komplex-Präparaten verwendet.', 'B1 vitamini eksikliğinde, tek düze beslenmede ve aşırı alkol kullanımında, ayrıca B grubu preparatlarda kullanılır.', 'Oral forms are sold over the counter, injections are given on a doctor''s order, as allergic reactions are rare but possible.', 'Oblici za uzimanje na usta izdaju se bez recepta, injekcije po nalogu ljekara, jer su rijetko moguće alergijske reakcije.', 'Облици за узимање на уста издају се без рецепта, ињекције по налогу љекара, јер су ријетко могуће алергијске реакције.', 'Формы для приёма внутрь отпускаются без рецепта, инъекции — по назначению врача, так как редко возможны аллергические реакции.', 'Formen zum Einnehmen sind rezeptfrei, Injektionen erfolgen auf ärztliche Anordnung, da selten allergische Reaktionen möglich sind.', 'Ağızdan alınan formları reçetesiz satılır, iğneleri doktor kararıyla uygulanır, çünkü ender de olsa alerjik tepki görülebilir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- timijan (thymus vulgaris l. i/ili thymus zygis l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (816, 'Thyme (Thymus vulgaris, Thymus zygis) is a medicinal plant whose herb yields an extract with an expectorant and soothing effect.', 'Timijan je ljekovita biljka iz čije se herbe dobija ekstrakt sa iskašljavajućim i umirujućim djelovanjem.', 'Тимијан је љековита биљка из чије се хербе добија екстракт са искашљавајућим и умирујућим дјеловањем.', 'Тимьян (Thymus vulgaris, Thymus zygis) — лекарственное растение, из травы которого получают экстракт с отхаркивающим и смягчающим действием.', 'Thymian (Thymus vulgaris, Thymus zygis) ist eine Heilpflanze, aus deren Kraut ein schleimlösender und reizlindernder Extrakt gewonnen wird.', 'Kekik (Thymus vulgaris, Thymus zygis), herbasından balgam söktürücü ve yatıştırıcı özüt elde edilen bir şifalı bitkidir.', 'Used for a cough during colds and bronchitis, usually in herbal syrups, and for irritation in the throat.', 'Primjenjuje se kod kašlja uz prehladu i bronhitis, obično u biljnim sirupima, kao i kod nadražaja u grlu.', 'Примјењује се код кашља уз прехладу и бронхитис, обично у биљним сирупима, као и код надражаја у грлу.', 'Применяют при кашле на фоне простуды и бронхита, обычно в составе растительных сиропов, а также при раздражении в горле.', 'Wird bei Husten im Rahmen von Erkältung und Bronchitis eingesetzt, meist in pflanzlichen Säften, sowie bei Reizgefühl im Hals.', 'Soğuk algınlığı ve bronşite eşlik eden öksürükte, genellikle bitkisel şuruplarda, ayrıca boğaz tahrişinde kullanılır.', 'Available over the counter; syrups may contain sugar or alcohol. Allergy is possible. In young children and in pregnancy, only on a doctor''s advice.', 'Izdaje se bez recepta, sirupi mogu sadržati šećer ili alkohol. Moguća je alergija. Kod male djece i u trudnoći samo po savjetu ljekara.', 'Издаје се без рецепта, сирупи могу садржати шећер или алкохол. Могућа је алергија. Код мале дјеце и у трудноћи само по савјету љекара.', 'Отпускается без рецепта, сиропы могут содержать сахар или спирт. Возможна аллергия. Детям раннего возраста и беременным — только по назначению врача.', 'Rezeptfrei erhältlich, Säfte können Zucker oder Alkohol enthalten. Allergien sind möglich. Bei kleinen Kindern und in der Schwangerschaft nur nach Anweisung.', 'Reçetesiz satılır, şuruplar şeker ya da alkol içerebilir. Alerji görülebilir. Küçük çocuklarda ve gebelikte yalnızca hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tioktinska kiselina
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (818, 'Thioctic, or alpha-lipoic, acid is an antioxidant involved in metabolism.', 'Tioktinska, ili alfa-lipoinska, kiselina je antioksidans uključen u metabolizam.', 'Тиоктинска, или алфа-липоинска, киселина је антиоксиданс укључен у метаболизам.', 'Тиоктовая, или альфа-липоевая, кислота — антиоксидант, участвующий в обмене веществ.', 'Thioktsäure, auch Alpha-Liponsäure, ist ein am Stoffwechsel beteiligtes Antioxidans.', 'Tioktik, diğer adıyla alfa-lipoik asit, metabolizmada rol alan bir antioksidandır.', 'Used in diabetic polyneuropathy — burning, tingling, numbness and pain in the feet and hands.', 'Primjenjuje se kod dijabetesne polineuropatije — pečenje, trnjenje, utrnulost i bol u stopalima i šakama.', 'Примјењује се код дијабетесне полинеуропатије — печење, трњење, утрнулост и бол у стопалима и шакама.', 'Применяют при диабетической полинейропатии — жжении, покалывании, онемении и боли в стопах и кистях.', 'Wird bei diabetischer Polyneuropathie eingesetzt — Brennen, Kribbeln, Taubheitsgefühl und Schmerzen in Füßen und Händen.', 'Diyabetik polinöropatide, yani ayak ve ellerde yanma, karıncalanma, uyuşma ve ağrıda kullanılır.', 'Some forms are prescription-only and injectable forms are given in a medical facility. Use is agreed with a doctor and does not replace blood sugar control.', 'Pojedini oblici se izdaju na recept, a injekcioni oblici se daju u zdravstvenoj ustanovi. Primjena se dogovara sa ljekarom i ne zamjenjuje kontrolu šećera u krvi.', 'Поједини облици се издају на рецепт, а ињекциони облици се дају у здравственој установи. Примјена се договара са љекаром и не замјењује контролу шећера у крви.', 'Часть форм отпускается по рецепту, инъекционные формы вводят в медучреждении. Применение согласуют с врачом, средство не заменяет контроль сахара в крови.', 'Manche Formen sind verschreibungspflichtig, Injektionsformen werden in der Einrichtung gegeben. Die Anwendung wird ärztlich abgestimmt und ersetzt keine Blutzuckerkontrolle.', 'Bazı formları reçeteye tabidir, enjeksiyonluk formlar sağlık kuruluşunda uygulanır. Kullanım hekimle kararlaştırılır ve kan şekeri kontrolünün yerini tutmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tiotropijum bromid
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (820, 'A long-acting anticholinergic bronchodilator. Available on its own and in combination with a beta-2 agonist.', 'Dugodjelujući antiholinergik koji širi disajne puteve. Postoje preparati sa jednom supstancom i kombinacije sa beta-2 agonistom.', 'Дугодјелујући антихолинергик који шири дисајне путеве. Постоје препарати са једном супстанцом и комбинације са бета-2 агонистом.', 'Длительно действующее антихолинергическое средство, расширяющее бронхи. Есть препараты с одним веществом и комбинации с бета-2-агонистом.', 'Ein lang wirkendes Anticholinergikum zur Erweiterung der Bronchien. Es gibt Einzelwirkstoffpräparate und Kombinationen mit einem Beta-2-Agonisten.', 'Bronşları genişleten uzun etkili bir antikolinerjiktir. Tek etkin maddeli preparatları ve beta-2 agonistle kombinasyonları vardır.', 'Used for daily control of chronic obstructive pulmonary disease and as add-on treatment in asthma.', 'Koristi se za svakodnevnu kontrolu hronične opstruktivne bolesti pluća i kao dodatna terapija kod astme.', 'Користи се за свакодневну контролу хроничне опструктивне болести плућа и као додатна терапија код астме.', 'Применяют для ежедневного контроля хронической обструктивной болезни лёгких и как дополнительное лечение при бронхиальной астме.', 'Dient der täglichen Kontrolle der chronisch obstruktiven Lungenerkrankung und als Zusatztherapie bei Asthma.', 'Kronik obstrüktif akciğer hastalığının günlük kontrolünde ve astımda ek tedavi olarak kullanılır.', 'Prescription only. It does not stop an attack that has started, a quick-relief inhaler is used for that. Dry mouth is common. Care is needed in glaucoma and prostate disease.', 'Samo na recept. Ne prekida započeti napad, za to služi brzodjelujući inhalator. Moguća su suva usta. Kod glaukoma i bolesti prostate primjenjuje se oprezno.', 'Само на рецепт. Не прекида започети напад, за то служи брзодјелујући инхалатор. Могућа су сува уста. Код глаукома и болести простате примјењује се опрезно.', 'Только по рецепту. Не снимает начавшийся приступ, для этого нужен ингалятор быстрого действия. Возможна сухость во рту. При глаукоме и болезнях простаты — с осторожностью.', 'Nur auf Rezept. Einen begonnenen Anfall beendet es nicht, dafür dient ein schnell wirkendes Spray. Mundtrockenheit ist häufig. Bei Glaukom und Prostataleiden vorsichtig.', 'Yalnızca reçeteyle verilir. Başlamış krizi durdurmaz, bunun için hızlı etkili inhaler kullanılır. Ağız kuruluğu sıktır. Glokom ve prostat hastalığında dikkat gerekir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tirotricin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (822, 'Tyrothricin is a topical antibacterial polypeptide for external use.', 'Tirotricin je lokalni antibakterijski polipeptid za spoljašnju upotrebu.', 'Тиротрицин је локални антибактеријски полипептид за спољашњу употребу.', 'Тиротрицин — местный антибактериальный полипептид для наружного применения.', 'Tyrothricin ist ein örtlich wirkendes antibakterielles Polypeptid zur äußeren Anwendung.', 'Tirotrisin, cilde uygulanan antibakteriyel bir polipeptittir.', 'Applied to small superficial wounds, grazes and cuts, and to superficial bacterial infections of the skin.', 'Nanosi se na male površinske rane, ogrebotine i posjekotine, kao i kod površinskih bakterijskih infekcija kože.', 'Наноси се на мале површинске ране, огреботине и посјекотине, као и код површинских бактеријских инфекција коже.', 'Наносят на небольшие поверхностные раны, ссадины и порезы, а также при поверхностных бактериальных поражениях кожи.', 'Wird auf kleine oberflächliche Wunden, Schürfungen und Schnitte sowie bei oberflächlichen bakteriellen Hautinfektionen aufgetragen.', 'Küçük yüzeysel yaralara, sıyrıklara ve kesiklere, ayrıca yüzeysel bakteriyel cilt enfeksiyonlarına uygulanır.', 'For external use only, not for the eyes or mucous membranes. A deep wound, spreading inflammation or fever needs medical assessment.', 'Samo za spoljašnju upotrebu, ne nanosi se na oči i sluznice. Duboka rana, širenje upale ili povišena temperatura traže pregled ljekara.', 'Само за спољашњу употребу, не наноси се на очи и слузнице. Дубока рана, ширење упале или повишена температура траже преглед љекара.', 'Только для наружного применения, не наносят на глаза и слизистые. Если рана глубокая, воспаление нарастает или держится температура, нужен осмотр врача.', 'Nur zur äußeren Anwendung, nicht an Augen oder Schleimhäuten. Tiefe Wunden, zunehmende Entzündung oder Fieber gehören ärztlich abgeklärt.', 'Yalnızca haricen kullanılır, göze ve mukozaya sürülmez. Derin yara, yayılan iltihap veya ateş varsa hekime başvurulmalıdır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tolperison
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (827, 'A centrally acting muscle relaxant that lowers increased tone of skeletal muscles.', 'Miorelaksans centralnog djelovanja koji smanjuje povišen tonus skeletnih mišića.', 'Миорелаксанс централног дјеловања који смањује повишен тонус скелетних мишића.', 'Миорелаксант центрального действия: снижает повышенный тонус скелетных мышц.', 'Ein zentral wirkendes Muskelrelaxans, das erhöhte Spannung der Skelettmuskulatur senkt.', 'İskelet kaslarındaki artmış gerginliği azaltan, merkezi etkili bir kas gevşeticidir.', 'Used for muscle spasm caused by spine and joint disorders, and for increased muscle tone after stroke and during rehabilitation.', 'Primjenjuje se kod grčeva mišića uz bolesti kičme i zglobova, kod povišenog tonusa poslije moždanog udara i u rehabilitaciji.', 'Примјењује се код грчева мишића уз болести кичме и зглобова, код повишеног тонуса послије можданог удара и у рехабилитацији.', 'Применяют при мышечных спазмах на фоне болезней позвоночника и суставов, при повышенном тонусе мышц после инсульта и в реабилитации.', 'Wird bei Muskelverspannungen durch Wirbelsäulen- und Gelenkerkrankungen sowie bei erhöhtem Muskeltonus nach Schlaganfall eingesetzt.', 'Omurga ve eklem hastalıklarına bağlı kas spazmlarında, inme sonrası artan kas tonusunda ve rehabilitasyonda kullanılır.', 'Prescription only. Weakness, headache and lower blood pressure are possible. Allergic reactions are described. Ask a doctor about driving.', 'Izdaje se samo na recept. Mogući su slabost, glavobolja i pad pritiska. Opisane su alergijske reakcije. O vožnji odlučuje ljekar.', 'Издаје се само на рецепт. Могући су слабост, главобоља и пад притиска. Описане су алергијске реакције. О вожњи одлучује љекар.', 'Только по рецепту. Возможны слабость, головная боль и снижение давления. Описаны аллергические реакции. О вождении спрашивают врача.', 'Verschreibungspflichtig. Schwäche, Kopfschmerzen und Blutdruckabfall sind möglich. Allergische Reaktionen sind beschrieben.', 'Yalnızca reçeteyle verilir. Halsizlik, baş ağrısı ve tansiyon düşmesi görülebilir. Alerjik tepkiler bildirilmiştir. Araç kullanımını hekim değerlendirir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- tuaminoheptan
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (849, 'A nasal decongestant that narrows blood vessels in the nose. In Montenegro it is only used in a combination with acetylcysteine.', 'Dekongestiv koji sužava krvne sudove u nosu. U Crnoj Gori se koristi samo u kombinaciji sa acetilcisteinom.', 'Деконгестив који сужава крвне судове у носу. У Црној Гори се користи само у комбинацији са ацетилцистеином.', 'Сосудосуживающее средство для носа. В Черногории применяется только в комбинации с ацетилцистеином.', 'Ein abschwellendes Nasenmittel, das die Gefäße in der Nase verengt. In Montenegro nur in Kombination mit Acetylcystein enthalten.', 'Burundaki damarları daraltan bir dekonjestandır. Karadağ''da yalnızca asetilsistein ile kombinasyon halinde bulunur.', 'Used for a runny nose with thick sticky discharge, in acute and chronic rhinitis and sinusitis, to make breathing through the nose easier.', 'Primjenjuje se kod curenja nosa sa gustim sekretom, kod akutnog i hroničnog rinitisa i sinusitisa, radi lakšeg disanja na nos.', 'Примјењује се код цурења носа са густим секретом, код акутног и хроничног ринитиса и синуситиса, ради лакшег дисања на нос.', 'Применяют при насморке с густым вязким отделяемым, при остром и хроническом рините и синусите, чтобы облегчить носовое дыхание.', 'Wird bei Schnupfen mit zähem Sekret, bei akuter und chronischer Rhinitis und Sinusitis angewendet, um die Nasenatmung zu erleichtern.', 'Koyu ve yapışkan akıntılı burun tıkanıklığında, akut ve kronik rinit ile sinüzitte burundan nefes almayı kolaylaştırmak için kullanılır.', 'Over the counter, but prolonged use makes the lining dependent on it. With high blood pressure, heart or thyroid disease and in children, only as advised.', 'Izdaje se bez recepta, ali dugotrajna primjena stvara navikavanje sluznice. Kod povišenog pritiska, bolesti srca i štitne žlijezde po savjetu ljekara.', 'Издаје се без рецепта, али дуготрајна примјена ствара навикавање слузнице. Код повишеног притиска, болести срца и штитне жлијезде по савјету љекара.', 'Отпускается без рецепта, но длительное применение ведёт к привыканию слизистой. При гипертонии, болезнях сердца и щитовидной железы — по назначению врача.', 'Rezeptfrei, doch längere Anwendung macht die Schleimhaut abhängig. Bei Bluthochdruck, Herz- und Schilddrüsenkrankheiten und bei Kindern nur nach Anweisung.', 'Reçetesiz satılır ancak uzun süreli kullanım mukozada alışkanlık yapar. Yüksek tansiyon, kalp ve tiroit hastalığında ve çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- ulipristal
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (851, 'A synthetic progesterone receptor modulator used for emergency contraception.', 'Sintetski modulator progesteronskih receptora za hitnu kontracepciju.', 'Синтетски модулатор прогестеронских рецептора за хитну контрацепцију.', 'Синтетический модулятор рецепторов прогестерона для экстренной контрацепции.', 'Ein synthetischer Progesteronrezeptor-Modulator zur Notfallverhütung.', 'Acil korunmada kullanılan sentetik bir progesteron reseptör modülatörüdür.', 'Used for emergency contraception after unprotected sex or after failure of the usual contraceptive method.', 'Primjenjuje se kao hitna kontracepcija poslije nezaštićenog odnosa ili zakazivanja uobičajene metode zaštite.', 'Примјењује се као хитна контрацепција послије незаштићеног односа или заказивања уобичајене методе заштите.', 'Применяют для экстренной контрацепции после незащищённого полового акта или сбоя привычного метода предохранения.', 'Wird zur Notfallverhütung nach ungeschütztem Verkehr oder nach Versagen der üblichen Verhütungsmethode angewendet.', 'Korunmasız ilişki sonrasında veya alışılmış korunma yönteminin başarısız olduğu durumlarda acil korunma amacıyla kullanılır.', 'Available without prescription, but it is not a regular contraceptive method and gives no protection against infections. While breastfeeding or on other medicines, ask a doctor.', 'Izdaje se bez recepta, ali nije redovna metoda kontracepcije i ne štiti od infekcija. Uz dojenje i uz druge lijekove potreban je savjet ljekara.', 'Издаје се без рецепта, али није редовна метода контрацепције и не штити од инфекција. Уз дојење и уз друге лијекове потребан је савјет љекара.', 'Отпускается без рецепта, но это не постоянный метод контрацепции и не защищает от инфекций. При грудном вскармливании и приёме других лекарств нужен врач.', 'Rezeptfrei erhältlich, aber keine reguläre Verhütung und kein Schutz vor Infektionen. In der Stillzeit und bei anderen Medikamenten ärztlichen Rat einholen.', 'Reçetesiz satılır, ancak düzenli bir korunma yöntemi değildir ve enfeksiyonlardan korumaz. Emzirme döneminde ve başka ilaç kullanımında doktora danışılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- uskolisna bokvica (plantago lanceolata l.)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (857, 'Ribwort plantain (Plantago lanceolata), a medicinal plant whose leaf yields an extract that soothes an irritated throat.', 'Uskolisna bokvica, ljekovita biljka iz čijeg se lista dobija ekstrakt koji umiruje nadraženo grlo.', 'Усколисна боквица, љековита биљка из чијег се листа добија екстракт који умирује надражено грло.', 'Подорожник ланцетолистный (Plantago lanceolata) — лекарственное растение, из листьев которого получают смягчающий горло экстракт.', 'Spitzwegerich (Plantago lanceolata), eine Heilpflanze; der aus dem Blatt gewonnene Extrakt beruhigt den gereizten Hals.', 'Sinirotu (Plantago lanceolata), yaprağından tahriş olmuş boğazı yatıştıran ekstre elde edilen tıbbi bir bitkidir.', 'Used for dry cough and a scratchy throat during colds, usually as part of herbal syrups.', 'Primjenjuje se kod suvog kašlja i grebanja u grlu uz prehladu, obično u biljnim sirupima.', 'Примјењује се код сувог кашља и гребања у грлу уз прехладу, обично у биљним сирупима.', 'Применяют при сухом кашле и першении в горле при простуде, обычно в составе растительных сиропов.', 'Wird bei trockenem Husten und Halskratzen im Rahmen einer Erkältung angewendet, meist in pflanzlichen Säften.', 'Soğuk algınlığında kuru öksürük ve boğaz kaşıntısında, genellikle bitkisel şuruplarda kullanılır.', 'Available without prescription, and syrups may contain sugar or alcohol. Allergy is possible. A cough over a week or breathlessness needs a doctor; children, as advised.', 'Izdaje se bez recepta, sirup može sadržati šećer ili alkohol. Moguća je alergija. Kašalj duži od nedjelju dana ili gušenje traže pregled, djeci po preporuci ljekara.', 'Издаје се без рецепта, сируп може садржати шећер или алкохол. Могућа је алергија. Кашаљ дужи од недјељу дана или гушење траже преглед, дјеци по препоруци љекара.', 'Отпускается без рецепта, сироп может содержать сахар или спирт. Возможна аллергия. При кашле дольше недели или одышке нужен врач, детям — по его назначению.', 'Rezeptfrei, Säfte können Zucker oder Alkohol enthalten. Allergien sind möglich. Husten über eine Woche oder Atemnot gehören zum Arzt, bei Kindern nur nach Rat.', 'Reçetesiz satılır, şurup şeker veya alkol içerebilir. Alerji görülebilir. Bir haftadan uzun öksürükte veya nefes darlığında hekime gidilir; çocuklarda hekim önerisiyle.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- valerijana (valeriana officinalis)
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (879, 'Valerian (Valeriana officinalis) is a plant whose root yields a calming extract. It is used in combined herbal remedies.', 'Valerijana je ljekovita biljka iz čijeg se korijena dobija ekstrakt sa umirujućim djelovanjem. Ulazi u kombinovane biljne preparate.', 'Валеријана је љековита биљка из чијег се коријена добија екстракт са умирујућим дјеловањем. Улази у комбиноване биљне препарате.', 'Валериана лекарственная — растение, из корня которого получают экстракт с успокаивающим действием. Входит в растительные комбинации.', 'Baldrian (Valeriana officinalis) ist eine Heilpflanze, aus deren Wurzel ein beruhigender Extrakt gewonnen wird. Er steckt in Kombipräparaten.', 'Kediotu (Valeriana officinalis), kökünden sakinleştirici ekstre elde edilen tıbbi bir bitkidir. Kombine bitkisel preparatlarda bulunur.', 'Used for nervous tension, restlessness and trouble falling asleep, usually together with lemon balm and peppermint.', 'Primjenjuje se kod nervne napetosti, nemira i teškog uspavljivanja, obično uz matičnjak i nanu.', 'Примјењује се код нервне напетости, немира и тешког успављивања, обично уз матичњак и нану.', 'Применяют при нервном напряжении, беспокойстве и трудностях с засыпанием, обычно вместе с мелиссой и мятой.', 'Wird bei nervöser Anspannung, Unruhe und Einschlafproblemen eingesetzt, meist zusammen mit Melisse und Pfefferminze.', 'Sinirsel gerginlikte, huzursuzlukta ve uykuya dalma güçlüğünde, genellikle oğulotu ve naneyle birlikte kullanılır.', 'Available over the counter. Drowsiness is possible, so take care when driving and avoid alcohol and sleeping pills. In children and pregnancy, only as advised.', 'Izdaje se bez recepta. Moguća je pospanost, pa je potreban oprez u vožnji, a alkohol i lijekovi za spavanje se izbjegavaju. Djeci po savjetu ljekara.', 'Издаје се без рецепта. Могућа је поспаност, па је потребан опрез у вожњи, а алкохол и лијекови за спавање се избјегавају. Дјеци по савјету љекара.', 'Отпускается без рецепта. Возможна сонливость, поэтому нужна осторожность за рулём, а алкоголь и снотворные исключают. Детям — по назначению врача.', 'Rezeptfrei erhältlich. Müdigkeit ist möglich, daher Vorsicht im Straßenverkehr, kein Alkohol und keine Schlafmittel. Bei Kindern nur nach ärztlicher Anweisung.', 'Reçetesiz satılır. Uyku hali görülebilir, araç kullanırken dikkat gerekir, alkol ve uyku ilaçlarından kaçınılır. Çocuklarda hekim önerisiyle kullanılır.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- valsartan
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (883, 'An angiotensin receptor blocker, a sartan, that relaxes blood vessels and lowers blood pressure. Often combined with a diuretic.', 'Blokator angiotenzinskih receptora, sartan, koji opušta krvne sudove i snižava pritisak. Često se kombinuje sa diuretikom.', 'Блокатор ангиотензинских рецептора, сартан, који опушта крвне судове и снижава притисак. Често се комбинује са диуретиком.', 'Блокатор рецепторов ангиотензина, сартан: расслабляет сосуды и снижает давление. Часто входит в комбинации с мочегонным.', 'Ein Angiotensin-Rezeptorblocker, ein Sartan, das die Gefäße entspannt und den Blutdruck senkt. Oft mit einem Diuretikum kombiniert.', 'Damarları gevşetip tansiyonu düşüren bir anjiyotensin reseptör blokeridir, sartandır. İdrar söktürücülü kombinasyonları da vardır.', 'Prescribed for high blood pressure, after a heart attack and in chronic heart failure.', 'Propisuje se kod povišenog krvnog pritiska, poslije infarkta miokarda i kod hronične srčane slabosti.', 'Прописује се код повишеног крвног притиска, послије инфаркта миокарда и код хроничне срчане слабости.', 'Назначают при повышенном артериальном давлении, после инфаркта миокарда и при хронической сердечной недостаточности.', 'Wird bei Bluthochdruck, nach einem Herzinfarkt und bei chronischer Herzschwäche verordnet.', 'Yüksek tansiyonda, kalp krizi sonrasında ve kronik kalp yetmezliğinde reçete edilir.', 'Prescription only. It must not be used in pregnancy. Dizziness is possible at the start, and a doctor monitors potassium and kidney function by blood tests.', 'Izdaje se samo na recept. U trudnoći se ne smije koristiti. Na početku je moguća vrtoglavica, a ljekar prati kalijum i rad bubrega preko analiza.', 'Издаје се само на рецепт. У трудноћи се не смије користити. На почетку је могућа вртоглавица, а љекар прати калијум и рад бубрега преко анализа.', 'Только по рецепту. При беременности противопоказан. В начале приёма возможно головокружение, врач контролирует калий и работу почек по анализам.', 'Verschreibungspflichtig. In der Schwangerschaft darf es nicht angewendet werden. Anfangs ist Schwindel möglich, der Arzt kontrolliert Kalium und Nierenwerte.', 'Yalnızca reçeteyle verilir. Gebelikte kullanılmaz. Başlangıçta baş dönmesi olabilir, hekim potasyum ve böbrek değerlerini tahlille izler.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- vildagliptin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (893, 'A glucose-lowering DPP-4 inhibitor that supports the body''s own insulin release after meals. Often combined with metformin.', 'Lijek za snižavanje šećera, DPP-4 inhibitor koji podržava sopstveno lučenje insulina poslije obroka. Često se kombinuje sa metforminom.', 'Лијек за снижавање шећера, DPP-4 инхибитор који подржава сопствено лучење инсулина послије оброка. Често се комбинује са метформином.', 'Сахароснижающее средство, ингибитор ДПП-4: поддерживает собственную выработку инсулина после еды. Часто в комбинации с метформином.', 'Ein blutzuckersenkender DPP-4-Hemmer, der die körpereigene Insulinausschüttung nach dem Essen unterstützt. Oft mit Metformin kombiniert.', 'Yemek sonrası vücudun kendi insülin salgısını destekleyen, kan şekerini düşüren bir DPP-4 inhibitörüdür. Sıklıkla metforminle birleştirilir.', 'Used in type 2 diabetes when diet and activity are not enough, usually together with other glucose-lowering medicines.', 'Primjenjuje se kod dijabetesa tipa 2 kada ishrana i fizička aktivnost ne daju dovoljan efekat, obično uz druge lijekove za šećer.', 'Примјењује се код дијабетеса типа 2 када исхрана и физичка активност не дају довољан ефекат, обично уз друге лијекове за шећер.', 'Применяют при сахарном диабете 2 типа, когда питания и физической активности недостаточно, обычно вместе с другими сахароснижающими средствами.', 'Wird bei Typ-2-Diabetes eingesetzt, wenn Ernährung und Bewegung nicht ausreichen, meist zusammen mit anderen Diabetesmitteln.', 'Beslenme ve hareketin yeterli olmadığı tip 2 diyabette, genellikle diğer şeker ilaçlarıyla birlikte kullanılır.', 'Prescription only. Blood glucose and liver tests are monitored. Headache and nausea are possible, and rarely inflammation of the pancreas.', 'Izdaje se samo na recept. Prate se šećer u krvi i nalazi jetre. Mogući su glavobolja i mučnina, rijetko zapaljenje pankreasa.', 'Издаје се само на рецепт. Прате се шећер у крви и налази јетре. Могући су главобоља и мучнина, ријетко запаљење панкреаса.', 'Только по рецепту. Нужен контроль глюкозы и печёночных проб. Возможны головная боль и тошнота, редко — воспаление поджелудочной железы.', 'Verschreibungspflichtig. Blutzucker und Leberwerte werden kontrolliert. Kopfschmerzen und Übelkeit sind möglich, selten eine Entzündung der Bauchspeicheldrüse.', 'Yalnızca reçeteyle verilir. Kan şekeri ve karaciğer değerleri izlenir. Baş ağrısı ve bulantı görülebilir, nadiren pankreas iltihabı gelişir.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

-- vinpocetin
INSERT INTO med_substance_reference_info (substance_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, used_for_en, used_for_sr, used_for_sr_cyrl, used_for_ru, used_for_de, used_for_tr, caution_en, caution_sr, caution_sr_cyrl, caution_ru, caution_de, caution_tr)
VALUES (895, 'A vincamine derivative from lesser periwinkle, an agent that affects blood flow in the brain.', 'Derivat vinkamina iz biljke mali zimzelen, sredstvo koje utiče na moždani krvotok.', 'Дериват винкамина из биљке мали зимзелен, средство које утиче на мождани крвоток.', 'Производное винкамина из барвинка малого, средство, влияющее на мозговое кровообращение.', 'Ein Vincamin-Derivat aus dem Kleinen Immergrün, das die Hirndurchblutung beeinflusst.', 'Küçük cezayirmenekşesinden elde edilen vinkamin türevidir, beyin kan akımını etkiler.', 'Used after disturbances of brain circulation, for dizziness and for memory decline of vascular origin.', 'Primjenjuje se kod posljedica poremećaja moždane cirkulacije, kod vrtoglavice i slabljenja pamćenja krvožilnog porijekla.', 'Примјењује се код посљедица поремећаја мождане циркулације, код вртоглавице и слабљења памћења крвожилног поријекла.', 'Применяют при последствиях нарушений мозгового кровообращения, головокружении и снижении памяти сосудистого происхождения.', 'Wird nach Durchblutungsstörungen im Gehirn, bei Schwindel und bei gefäßbedingter Gedächtnisschwäche eingesetzt.', 'Beyin dolaşımı bozukluklarının ardından, baş dönmesinde ve damarsal kökenli bellek zayıflığında kullanılır.', 'Prescription only. Evidence of benefit is limited and in several countries it is not registered as a medicine. It is not used in pregnancy or in children.', 'Izdaje se na recept. Dokazi o djelovanju su ograničeni, u nekim zemljama nije registrovan kao lijek. U trudnoći i kod djece se ne primjenjuje.', 'Издаје се на рецепт. Докази о дјеловању су ограничени, у неким земљама није регистрован као лијек. У трудноћи и код дјеце се не примјењује.', 'Отпускается по рецепту. Доказательная база ограничена, в ряде стран вещество не зарегистрировано как лекарство. При беременности и у детей не применяют.', 'Verschreibungspflichtig. Die Studienlage ist begrenzt, in mehreren Ländern ist es nicht als Arzneimittel zugelassen. In der Schwangerschaft und bei Kindern nicht anwenden.', 'Yalnızca reçeteyle verilir. Etkisine dair kanıtlar sınırlıdır, bazı ülkelerde ilaç olarak ruhsatlı değildir. Gebelikte ve çocuklarda kullanılmaz.')
ON DUPLICATE KEY UPDATE what_en = VALUES(what_en), what_sr = VALUES(what_sr), what_sr_cyrl = VALUES(what_sr_cyrl), what_ru = VALUES(what_ru), what_de = VALUES(what_de), what_tr = VALUES(what_tr), used_for_en = VALUES(used_for_en), used_for_sr = VALUES(used_for_sr), used_for_sr_cyrl = VALUES(used_for_sr_cyrl), used_for_ru = VALUES(used_for_ru), used_for_de = VALUES(used_for_de), used_for_tr = VALUES(used_for_tr), caution_en = VALUES(caution_en), caution_sr = VALUES(caution_sr), caution_sr_cyrl = VALUES(caution_sr_cyrl), caution_ru = VALUES(caution_ru), caution_de = VALUES(caution_de), caution_tr = VALUES(caution_tr);

SELECT COUNT(*) AS substance_reference_rows FROM med_substance_reference_info;
